// Generated by scripts/gen-l10n.mjs (gdetail n1, id) — 不要手改;改翻譯請改 scripts/out/l10n/id/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["id"]=Object.assign(window.GRAMMAR_DETAIL_L10N["id"]||{},{"n1-8":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ならでは」artinya <b>「khas ～, hanya ～ yang punya」「memang pantas ～, hanya ～ yang bisa melakukannya」</b>. Misalnya \"pemandangan khas Kyoto\" atau \"kehangatan khas buatan tangan\". Pakai ini kalau kamu mau menekankan <b>hal ini tidak ada di tempat lain, hanya dia yang punya</b>. Biasanya nadanya memuji.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya langsung <b>kata benda</b>, dan di belakangnya paling sering disambung 「の＋kata benda」.<br><span class='gd-pair'><span class='gd-jp'>職人</span> → <span class='gd-jp'>職人ならではの技術</span></span>（keterampilan khas yang hanya dimiliki pengrajin）<br><span class='gd-pair'><span class='gd-jp'>地元</span> → <span class='gd-jp'>地元ならではの料理</span></span>（masakan yang hanya bisa kamu temukan di daerah itu）<br>Yang ditaruh di depan biasanya <b>orang, tempat, toko, atau cara tertentu</b>, yaitu hal yang punya ciri khasnya sendiri.</div><div class='gd-h'>Bentuk yang paling sering muncul</div><div class='gd-sec'><span class='gd-tag'>ならではの＋kata benda</span>Ini yang paling umum, sekitar sembilan dari sepuluh kali bentuknya begini.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもならではの自由な発想に驚いた。</span>（Aku kaget dengan ide-ide bebas yang hanya bisa datang dari anak-anak）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅館ならではのおもてなしを楽しんだ。</span>（Aku menikmati keramahan khas penginapan tradisional Jepang）</div><div class='gd-sec'><span class='gd-tag'>ならではだ</span>Ditaruh di akhir kalimat, artinya \"inilah yang hanya bisa dilakukan oleh ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>この味は、老舗ならではだ。</span>（Rasa ini hanya bisa dihasilkan oleh toko lama）</div><div class='gd-sec'><span class='gd-tag'>ならでは〜ない</span>Ini ungkapan yang lebih formal dan kuno, artinya \"kalau bukan ～, tidak bisa ～\". Cukup kenali saja.</div><div class='gd-ex-line'>・<span class='gd-jp'>この味は、この店ならでは味わえない。</span>（Rasa ini tidak bisa dinikmati kalau bukan di toko ini）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・「なら」di sini <b>bukan \"kalau\"</b>, jadi jangan diterjemahkan jadi \"kalau itu ～\".<br>・「は」di 「では」dibaca <b>わ</b>, jadi seluruhnya dibaca ならでわ.<br>・Di depannya langsung kata benda, <b>jangan tambah の</b>: yang benar <span class='gd-jp'>日本ならではの</span>, bukan 日本のならではの.<br>・Intinya adalah \"<b>hanya dia yang punya</b>\". Ciri biasa yang dimiliki semua orang tidak bisa dipakai. Misalnya \"minimarket khas Tokyo\" terdengar aneh, karena minimarket ada di mana-mana.<br>・Kebanyakan dipakai untuk memuji. Kadang ada pemakaian netral seperti 「<span class='gd-jp'>都会ならではの悩み</span>」（kegelisahan yang hanya dialami orang kota）, tapi kalau dipakai untuk kekurangan atau kegagalan biasa, kedengarannya sangat aneh.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>らしい</b>＝terasa sangat ～, seperti ～ (tempat lain mungkin juga punya yang mirip):<br><span class='gd-jp'>京都らしい景色だ。</span>（Pemandangan yang terasa sangat Kyoto）<br><b>ならでは</b>＝hanya ada di sana, tidak ada di tempat lain:<br><span class='gd-jp'>京都ならではの景色だ。</span>（Pemandangan yang hanya bisa dilihat di Kyoto）</div><div class='gd-sec'><b>をおいて</b>＝bicara soal <b>pilihan orang</b>: selain dia, tidak ada yang bisa dipilih:<br><span class='gd-jp'>この役ができるのは、彼をおいてほかにいない。</span>（Yang bisa memerankan peran ini, selain dia tidak ada orang lain）<br><b>ならでは</b>＝bicara soal <b>ciri khas</b>: hal seperti ini hanya dia yang bisa melakukannya:<br><span class='gd-jp'>この演技は彼ならではだ。</span>（Akting seperti ini hanya dia yang bisa）</div><div class='gd-warn'>Trik cepat membedakan: \"mirip ～\" pakai らしい; \"ciri khas yang hanya dimiliki ～\" pakai ならでは; \"kalau disuruh memilih, hanya dia\" pakai をおいてほかにない.</div>","n1-33":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜とはいうものの」artinya <b>「memang sih katanya begitu, tapi…」</b>. Di depan kamu mengakui sesuatu itu benar, lalu di belakang kamu menambahkan bahwa kenyataannya tidak berjalan seperti itu. Contohnya \"katanya sudah musim semi, tapi kok masih dingin banget\".<br>Kalau dipecah jadi mudah diingat: <span class='gd-jp'>と</span>（begitu）＋<span class='gd-jp'>いう</span>（berkata）＋<span class='gd-jp'>ものの</span>（meskipun）, gabungannya berarti \"meskipun dikatakan ～\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Di tengah kalimat</span>A とはいうものの、B. A adalah fakta, atau sesuatu yang dikatakan semua orang; B adalah \"seharusnya begitu, tapi ternyata tidak\".</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいうものの、まだ寒い日が続いている。</span>（Katanya sudah musim semi, tapi hari-hari yang dingin masih terus berlanjut）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に十年住んでいるとはいうものの、敬語はまだ苦手だ。</span>（Memang sudah sepuluh tahun tinggal di Jepang, tapi aku masih lemah soal bahasa sopan）</div><div class='gd-ex-line'>・<span class='gd-jp'>便利になったとはいうものの、失われたものも少なくない。</span>（Memang jadi lebih praktis, tapi yang hilang juga tidak sedikit）</div><div class='gd-sec'><span class='gd-tag'>Di awal kalimat</span>Kalau kalimat sebelumnya sudah selesai, kalimat berikutnya dibuka dengan 「<span class='gd-jp'>とはいうものの</span>、」 yang artinya \"meski begitu, …\".</div><div class='gd-ex-line'>・<span class='gd-jp'>今月から節約すると決めた。とはいうものの、コンビニに行くとつい買ってしまう。</span>（Aku memutuskan mulai bulan ini berhemat. Meski begitu, begitu masuk minimarket aku tetap saja kelepasan beli）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya pakai bentuk biasa, yaitu bentuk tanpa です・ます.<br>Kata kerja: <span class='gd-pair'><span class='gd-jp'>習った</span> → <span class='gd-jp'>習ったとはいうものの</span></span><br>Kata sifat-い: <span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとはいうものの</span></span><br>Kata sifat-な: <span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利だとはいうものの</span></span>, だ boleh dihilangkan: <span class='gd-jp'>便利とはいうものの</span><br>Kata benda: <span class='gd-pair'><span class='gd-jp'>春だ</span> → <span class='gd-jp'>春とはいうものの</span></span>, dengan だ tetap dipertahankan juga boleh: <span class='gd-jp'>春だとはいうものの</span></div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di belakang harus ada hal yang \"berbeda dari harapan\". <span class='gd-jp'>春とはいうものの、暖かい。</span> terdengar aneh, karena musim semi memang hangat dan tidak ada pertentangannya sama sekali.<br>・Nuansanya cenderung formal dan tertulis, sering muncul di tulisan, berita, dan pidato. Saat ngobrol dengan teman, 「<span class='gd-jp'>けど</span>」atau 「<span class='gd-jp'>とはいっても</span>」lebih alami; kalau pakai とはいうものの, kedengarannya seperti sedang membaca naskah.<br>・Di belakangnya biasanya menggambarkan keadaan nyata atau perasaanmu sendiri, dan jarang disambung dengan permintaan atau ajakan seperti 「～してください」「～しよう」.<br>・<span class='gd-jp'>いう</span>sebenarnya dibaca 「ゆう」, tapi tulisannya tetap いう, jangan ditulis ゆう.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Situasi yang sama, \"katanya musim semi, tapi masih dingin\":<br><b>とはいえ</b>（N2）：<span class='gd-jp'>春とはいえ、まだ寒い。</span>Artinya hampir sama, lebih pendek, sama-sama bernuansa tertulis, dan bisa ditaruh di awal kalimat.<br><b>とはいうものの</b>：<span class='gd-jp'>春とはいうものの、まだ寒い。</span>Artinya sama dengan とはいえ, hanya lebih panjang.<br><b>とはいっても</b>：<span class='gd-jp'>春とはいっても、まだ寒いね。</span>Versi yang paling sering dipakai saat bicara.<br><b>ものの</b>（N2）：<span class='gd-jp'>春になったものの、まだ寒い。</span>Langsung disambung dengan satu fakta, tanpa lapisan \"katanya ～\".<br><b>とは言い条</b>（N1）：<span class='gd-jp'>春とは言い条、まだ寒い。</span>Artinya sama, tapi sangat klasik, sekarang hampir hanya terlihat di tulisan.</div><div class='gd-warn'>Trik cepat membedakan: saat bicara pakai 「とはいっても」, saat menulis pakai 「とはいえ」「とはいうものの」, sedangkan 「とは言い条」cukup dikenali saja, kamu sendiri hampir tidak perlu memakainya.</div>","n1-15":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜が早いか」setara dengan <b>「begitu ~ langsung …」</b> dalam bahasa Indonesia, dan ini untuk kejadian yang <b>begitu cepat sampai sulit dibedakan mana yang terjadi duluan</b>. Arti harfiahnya kira-kira 「（kejadian pertama）lebih cepat, ya?」: aksi pertama baru saja mulai, tapi aksi kedua sudah terjadi. Seperti bel pulang sekolah baru berbunyi, murid-murid sudah berlarian di koridor.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menggambarkan adegan yang kamu lihat</span>Dipakai untuk hal yang <b>sudah terjadi</b>, jadi akhir kalimatnya kebanyakan berbentuk lampau. Sering muncul di novel, artikel, dan berita, tapi hampir tidak pernah dipakai dalam obrolan sehari-hari.</div><div class='gd-ex-line'>・<span class='gd-jp'>チャイムが鳴るが早いか、子供たちは教室を飛び出した。</span>（Begitu bel berbunyi, anak-anak langsung berlarian keluar kelas）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は家に帰るが早いか、ベッドに倒れ込んだ。</span>（Begitu sampai rumah, dia langsung ambruk di tempat tidur）</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品は発売されるが早いか、売り切れてしまった。</span>（Begitu dirilis, produk baru itu langsung habis terjual）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bentuk kamus kata kerja (bentuk dasar yang kamu temukan di kamus) langsung disambung dengan 「が早いか」, tanpa perubahan bentuk.<br><span class='gd-pair'><span class='gd-jp'>鳴る</span> → <span class='gd-jp'>鳴るが早いか</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るが早いか</span></span><span class='gd-pair'><span class='gd-jp'>発売される</span> → <span class='gd-jp'>発売されるが早いか</span></span><br>Meski kejadiannya sudah lewat, bagian depan tetap memakai bentuk kamus; kala diserahkan ke akhir kalimat. Sesekali kamu juga akan menemukan bentuk た, misalnya <span class='gd-jp'>言ったが早いか</span>, tapi untuk sekarang hafalkan bentuk kamus saja sudah cukup.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Bagian belakang <b>tidak boleh berisi perintah, permintaan, atau niat sendiri</b>: ×<span class='gd-jp'>家に着くが早いか、電話してください。</span> Kalau mau bilang 「begitu sampai rumah, langsung telepon aku」, katakan <span class='gd-jp'>家に着いたら、すぐ電話してください。</span><br>・Pola \"begitu ~ langsung ~\" atau \"kalau ~ pasti ~\" dalam bahasa Indonesia jangkauannya luas. Untuk <b>kebiasaan atau syarat</b> seperti \"kalau musim semi tiba, bunga mekar\", が早いか tidak bisa dipakai. Di situ pakai <span class='gd-jp'>春になると、花が咲く。</span><br>・Nuansanya kaku. Kalau ngobrol dengan teman, \"begitu sampai rumah aku langsung tidur\" cukup katakan <span class='gd-jp'>家に帰って、すぐ寝ちゃった。</span> Kalau pakai が早いか, kamu akan terdengar seperti sedang membacakan novel.<br>・Jangan tambahkan ます di depannya: ×<span class='gd-jp'>鳴りますが早いか</span>。<br>・「早い」dibaca <b>はやい</b>。</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Untuk satu adegan yang sama, ketiga cara ini sama-sama benar:<br><span class='gd-jp'>息子は帰ってくるが早いか、かばんを置いて遊びに行った。</span><br><span class='gd-jp'>息子は帰ってくるなり、かばんを置いて遊びに行った。</span><br><span class='gd-jp'>息子は帰ってくるや否や、かばんを置いて遊びに行った。</span><br>（Begitu anakku pulang, dia langsung menaruh tas dan pergi bermain）</div><div class='gd-sec'><b>なり</b>: aksi di depan dan di belakang pasti dilakukan oleh <b>orang yang sama</b>, dan aksi belakangnya sering berupa tindakan yang agak mengejutkan. Karena itu \"begitu bel berbunyi, murid-murid langsung berlarian keluar\" tidak bisa memakai なり: ×<span class='gd-jp'>チャイムが鳴るなり、生徒が飛び出した。</span><br><b>や否や</b>: depan dan belakang boleh berbeda pelaku atau hal, nuansanya <b>paling tulis dan paling formal</b>, dan sangat disukai berita: <span class='gd-jp'>ドアが開くや否や、客が店内になだれ込んだ。</span>（Begitu pintu dibuka, pelanggan langsung berbondong-bondong masuk ke toko）<br><b>が早いか</b>: subjek depan dan belakang juga boleh berbeda, dan fokusnya pada <b>kecepatan yang membuat urutannya tak terbedakan</b>. Biasanya terbayang adegan orang yang tak sabar atau saling berebut.</div><div class='gd-warn'>Trik menentukan: orang yang sama dan tindakan belakangnya agak di luar dugaan, pakai なり; mau menekankan \"cepat sampai nyaris bersamaan\", pakai が早いか; laporan tulis yang formal, pakai や否や. Ketiganya tidak boleh diikuti perintah, permintaan, atau niat sendiri.</div><div class='gd-h'>Bisa dilanjutkan dengan</div><div class='gd-sec'>「〜そばから」juga tampak seperti \"begitu ~ langsung ~\", tapi artinya <b>terjadi berulang kali</b>, yaitu \"baru saja ~ eh sudah …lagi\": <span class='gd-jp'>覚えるそばから忘れてしまう。</span>（Baru saja dihafal, sudah lupa lagi）. Yang ditekankan adalah \"setiap kali selalu begitu\", bukan kecepatan satu kejadian saja.</div>","n1-16":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜や否や」setara dengan <b>「begitu ~ langsung ~」</b> dalam bahasa Indonesia, yaitu kecepatan ketika <b>satu aksi baru selesai dan hal berikutnya langsung terjadi</b>. Ini <b>ungkapan tulis</b> yang sangat formal, sering muncul di novel, berita, dan artikel. Anggap saja ini versi tulis dari <span class='gd-jp'>〜たとたん</span>.</div><div class='gd-h'>Pahami dulu kata ini</div><div class='gd-sec'>Dibaca <b>やいなや</b>. 「否」artinya \"tidak\". Makna aslinya kira-kira \"jadi tadi sudah dilakukan atau belum pun belum jelas\", yaitu <b>aksi pertama baru saja terjadi, lalu langsung disusul yang berikutnya</b>. Ingat gambaran ini, dan kamu akan tahu bahwa yang ditekankan adalah \"kecepatan\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bentuk kamus kata kerja + や否や<br><span class='gd-pair'><span class='gd-jp'>目を覚ます</span> → <span class='gd-jp'>目を覚ますや否や</span></span>（begitu membuka mata ~）<br><span class='gd-pair'><span class='gd-jp'>ドアが開く</span> → <span class='gd-jp'>ドアが開くや否や</span></span>（begitu pintu terbuka ~）<br>Dalam tulisan, kadang hanya ditulis 「や」, artinya sama: <span class='gd-jp'>家に着くや</span>（begitu sampai rumah ~）。</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menggambarkan hal yang sudah terjadi</span>Dipakai saat bercerita atau melaporkan bahwa \"begitu A terjadi, B langsung terjadi\". Bagian belakang biasanya berbentuk lampau.</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアが開くや否や、子どもたちが飛び出してきた。</span>（Begitu pintu terbuka, anak-anak langsung berlarian keluar）</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品は発売されるや否や、売り切れた。</span>（Begitu dirilis, produk baru itu langsung habis terjual）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長が現れるや否や、会場は静まり返った。</span>（Begitu direktur muncul, ruangan langsung hening）</div><div class='gd-sec'>Bagian depan dan belakang boleh berupa <b>orang atau benda yang berbeda</b>: pada contoh di atas, \"pintu terbuka\" dan \"anak-anak berlarian keluar\" adalah dua pelaku berbeda, dan ini tidak masalah.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Bagian depan harus memakai <b>bentuk kamus</b>, bukan bentuk た: yang benar <span class='gd-jp'>帰るや否や</span>, bukan 「帰ったや否や」. Banyak orang terbawa pikiran \"sudah pulang\" lalu otomatis memakai bentuk lampau.<br>・「否」dibaca <b>いな</b>, bukan ひ.<br>・Bagian belakang tidak boleh berisi permintaan atau niat seperti \"aku akan ~\", \"tolong ~\", atau \"ayo ~\".<br>　× 駅に着くや否や、電話してください。<br>　○ <span class='gd-jp'>駅に着いたら、すぐ電話してください。</span>（Begitu sampai stasiun, tolong segera telepon aku）<br>・Nuansanya kaku dan sangat tulis. Saat ngobrol dengan teman, \"begitu sampai rumah aku langsung tidur\" cukup katakan <span class='gd-jp'>家に着いたとたん、寝ちゃった</span> atau <span class='gd-jp'>帰ってすぐ寝た</span>。</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Situasi yang sama, \"Begitu masuk kamar, dia langsung menangis\":<br><span class='gd-tag'>や否や</span><span class='gd-jp'>彼は部屋に入るや否や、泣き出した。</span><br>Paling formal dan paling tulis; depan dan belakang boleh berbeda pelaku.<br><span class='gd-tag'>なり</span><span class='gd-jp'>彼は部屋に入るなり、泣き出した。</span><br>Depan dan belakang pasti <b>orang yang sama</b>, sering bernuansa kaget seperti \"kok tiba-tiba begitu?\".<br><span class='gd-tag'>が早いか</span><span class='gd-jp'>彼は部屋に入るが早いか、泣き出した。</span><br>Lebih menekankan \"cepat sampai nyaris bersamaan\", terasa sangat seperti novel; bagian depannya juga boleh memakai bentuk た.<br><span class='gd-tag'>たとたん</span><span class='gd-jp'>彼は部屋に入ったとたん、泣き出した。</span><br>Versi sehari-hari, bisa dipakai untuk bicara maupun menulis; bagian depannya bentuk た.</div><div class='gd-sec'>Dua pola lain ini juga sering tertukar:<br><b>次第</b> bisa diikuti permintaan atau niat: <span class='gd-jp'>着き次第、連絡します。</span>（Begitu sampai, aku akan menghubungimu）. Kalau diganti や否や, kalimat ini tidak bisa dipakai.<br><b>そばから</b> artinya \"baru dikerjakan, langsung dibatalkan lagi, dan terus berulang\": <span class='gd-jp'>覚えるそばから忘れてしまう。</span>（Baru saja diingat, langsung lupa lagi, terus begitu）. Ini bukan \"begitu ~ langsung ~\" untuk satu kejadian.</div><div class='gd-warn'>Trik menentukan: mau meminta lawan bicara melakukan sesuatu, pakai 「次第」; kerja sia-sia yang berulang terus, pakai 「そばから」; menggambarkan satu kejadian yang sudah terjadi, pakai 「たとたん」 untuk obrolan dan 「や否や」 untuk tulisan.</div><div class='gd-h'>Bisa dilanjutkan dengan</div><div class='gd-sec'>Lihat <span class='gd-jp'>〜なり</span>, <span class='gd-jp'>〜が早いか</span>, dan <span class='gd-jp'>〜そばから</span> sekaligus. Kelompok \"begitu ~ langsung ~\" ini sering muncul bersamaan untuk dibandingkan dalam ujian N1.</div>","n1-40":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜にひきかえ」mirip dengan <b>「sebaliknya ～」「berbeda dengan ～」</b>. Kamu menyebut satu sisi dulu, lalu sisi lain yang bertolak belakang. Biasanya satu sisi bagus dan satu sisi kurang bagus, dan pembicara punya perasaan tertentu tentangnya. Contohnya: 「Kakaknya rajin banget, <b>sebaliknya</b> adiknya……」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata benda</b> langsung disambung: <span class='gd-pair'><span class='gd-jp'>去年</span> → <span class='gd-jp'>去年にひきかえ</span></span><br><b>Satu kalimat</b> harus diberi 「の」 dulu supaya jadi kata benda, baru disambung にひきかえ:<br><span class='gd-pair'><span class='gd-jp'>兄はよく勉強する</span> → <span class='gd-jp'>兄がよく勉強するのにひきかえ</span></span><br><span class='gd-pair'><span class='gd-jp'>姉は明るい</span> → <span class='gd-jp'>姉が明るいのにひきかえ</span></span><br>Kata seperti 「社交的」 harus diberi な dulu baru bisa disambung の: <span class='gd-pair'><span class='gd-jp'>社交的</span> → <span class='gd-jp'>社交的なのにひきかえ</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kedua sisi sangat berbeda</span>Dipakai untuk membandingkan dua orang, dua masa, atau dua tempat, dengan menekankan bahwa bedanya jauh.</div><div class='gd-ex-line'>・<span class='gd-jp'>去年の猛暑にひきかえ、今年の夏は過ごしやすい。</span>(Dibandingkan panas terik tahun lalu, musim panas tahun ini jauh lebih nyaman.)</div><div class='gd-ex-line'>・<span class='gd-jp'>前の部長にひきかえ、今度の部長はとても話しやすい。</span>(Dibandingkan kepala bagian yang dulu, kepala bagian yang sekarang jauh lebih enak diajak bicara.)</div><div class='gd-ex-line'>・<span class='gd-jp'>兄が社交的なのにひきかえ、弟は人見知りだ。</span>(Kakaknya supel, sebaliknya adiknya pemalu pada orang baru.)</div><div class='gd-sec'><span class='gd-tag'>それにひきかえ</span>Diletakkan di awal kalimat, artinya 「sebaliknya ～」. Bagian depan menyebut betapa baiknya orang lain, lalu bagian belakang membahas diri sendiri atau keluarga sendiri. Sering bernada mengeluh atau menyindir diri sendiri.</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の子は毎日勉強している。それにひきかえ、うちの子はゲームばかりだ。</span>(Anak tetangga belajar setiap hari. Sebaliknya, anak kita kerjanya main game melulu.)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Saat menyambung kalimat, 「の」 di tengah tidak boleh hilang. Yang benar <span class='gd-jp'>社交的なのにひきかえ</span>, bukan 社交的にひきかえ. 「のに」 di sini adalah 「の＋に」, bukan のに yang berarti 「padahal ～」.<br>・Pola ini membawa penilaian pembicara, jadi <b>tidak cocok untuk membandingkan data semata</b>. Kalimat yang hanya menyebut angka, misalnya 「pria 30%, wanita 50%」, akan terasa aneh kalau memakai にひきかえ.<br>・Nuansanya cenderung tertulis dan formal. Dalam obrolan sehari-hari, yang lebih sering terdengar adalah <span class='gd-jp'>それにひきかえ</span> di awal kalimat.<br>・Jangan tertukar dengan <span class='gd-jp'>〜と引き換えに</span>. Itu artinya 「menukar dengan ～」: <span class='gd-jp'>代金と引き換えに商品を渡す。</span>(Barang diserahkan bersamaan dengan pembayaran.) Artinya sama sekali berbeda.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama bicara soal kakak yang supel dan adik yang tertutup:<br><b>に対して</b> = menyebut perbedaan kedua sisi secara objektif, tanpa emosi: <span class='gd-jp'>兄は社交的なのに対して、弟は内向的だ。</span>(Kakaknya supel, sedangkan adiknya introver.)<br><b>にひきかえ</b> = membawa perasaan 「kok bedanya jauh banget」 atau rasa tidak puas: <span class='gd-jp'>兄が社交的なのにひきかえ、弟は内向的だ。</span>(Kakaknya supel banget, tapi adiknya malah introver begini.)<br><b>に比べて</b> = sekadar membandingkan tingkat tinggi-rendahnya: <span class='gd-jp'>去年に比べて、今年は暑い。</span>(Tahun ini lebih panas daripada tahun lalu.)</div><div class='gd-warn'>Tips menentukan: kalau kamu merasa 「sebaliknya ～」 atau 「orang lain sudah begitu, kamu malah begini…」, pakai にひきかえ. Kalau hanya menyatakan dua sisi berbeda secara objektif, pakai に対して. Kalau hanya membandingkan mana yang lebih banyak atau sedikit, pakai に比べて.</div>","n1-2":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜をもって」mirip dengan <b>「dengan ～」</b> dalam bahasa surat resmi. Satu artinya <b>「melakukan dengan ～」</b> (memberi tahu secara tertulis, menangani dengan sepenuh hati). Artinya yang lain <b>「berbatas pada ～」</b> (berlaku sampai hari ini, berakhir hari ini). Kamu paling sering menemukannya di pengumuman, surat pemberitahuan, dan ucapan pembawa acara upacara. Dalam obrolan biasa hampir tidak dipakai.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Letakkan kata benda di depan, lalu tambahkan をもって: <span class='gd-pair'><span class='gd-jp'>書面</span> → <span class='gd-jp'>書面をもって</span></span><br>Yang disambung biasanya kata benda formal atau abstrak, misalnya 書面, 誠意, 拍手, atau kata waktu seperti 本日 dan 3月.<br>Kalau mau terdengar lebih sopan saat berbicara, bentuknya jadi <span class='gd-jp'>をもちまして</span>, artinya sama.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Dengan cara apa</span>「Melakukan sesuatu dengan ～」, seperti 「で」 dalam situasi formal.</div><div class='gd-ex-line'>・<span class='gd-jp'>合否は書面をもってお知らせします。</span>(Hasil lulus atau tidaknya akan diberitahukan secara tertulis.)</div><div class='gd-ex-line'>・<span class='gd-jp'>誠意をもって対応いたします。</span>(Kami akan menanganinya dengan sepenuh hati.)</div><div class='gd-ex-line'>・<span class='gd-jp'>盛大な拍手をもってお迎えください。</span>(Mari sambut dengan tepuk tangan yang meriah.)</div><div class='gd-sec'><span class='gd-tag'>Batas waktu</span>Menjadikan satu titik waktu sebagai batas. Biasanya artinya 「sampai hari ini, lalu selesai」, tapi bisa juga 「mulai hari ini berlaku」.</div><div class='gd-ex-line'>・<span class='gd-jp'>本日をもって、閉店いたします。</span>(Toko kami beroperasi sampai hari ini, lalu tutup.)</div><div class='gd-ex-line'>・<span class='gd-jp'>以上をもちまして、本日の会議を終了いたします。</span>(Sekian, rapat hari ini kami akhiri.)</div><div class='gd-ex-line'>・<span class='gd-jp'>4月1日をもって、社名を変更いたします。</span>(Mulai 1 April, nama perusahaan kami diubah.)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<span class='gd-jp'>本日をもって閉店</span> berarti <b>hari ini toko masih buka dan hari ini adalah hari terakhir</b>, bukan berarti hari ini sudah tidak buka. Kalau diterjemahkan jadi 「mulai hari ini tutup」, gampang disalahpahami.<br>・Ini ungkapan tulis yang kaku, jadi jangan dipakai sembarangan dalam kehidupan sehari-hari. Kalau bilang ke teman 「menulis pakai pulpen」, ucapkan <span class='gd-jp'>ペンで書く</span>. Kalau bilang ペンをもって書く, terdengar aneh.<br>・Ini berbeda dengan <span class='gd-jp'>持って</span> yang berarti 「membawa」. <span class='gd-jp'>傘を持って出かける</span> benar-benar berarti pergi sambil memegang payung di tangan. Sedangkan <span class='gd-jp'>書面をもって</span> artinya 「dengan cara tertulis」, tidak ada orang yang memegang sesuatu. Karena itu, sebagai pola tata bahasa, sering ditulis dengan hiragana.<br>・<span class='gd-jp'>以上をもちまして</span> adalah ungkapan baku untuk menutup acara atau upacara. Begitu mendengarnya, kamu tahu acaranya akan selesai.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>で</b> = 「dengan ～」 dalam ungkapan sehari-hari: <span class='gd-jp'>結果はメールで知らせるね。</span>(Hasilnya nanti kukabari lewat email ya.)<br><b>をもって</b> = 「dengan ～」 dalam pengumuman resmi: <span class='gd-jp'>結果は書面をもってお知らせします。</span>(Hasilnya akan diberitahukan secara tertulis.)<br>Artinya hampir sama, bedanya ada di situasi pemakaian. Yang satu untuk bicara santai dengan orang, yang satu untuk pemberitahuan resmi dari perusahaan atau sekolah.</div><div class='gd-sec'><b>を限りに</b> juga bisa berarti 「sampai ～」, tapi menekankan <b>「ini yang terakhir kalinya, setelah ini tidak dilakukan lagi」</b>. Sering terasa seperti tekad pribadi: <span class='gd-jp'>今日を限りにタバコをやめる。</span>(Mulai hari ini aku berhenti merokok.)<br><b>をもって</b> lebih seperti <b>pengumuman resmi</b> dari lembaga atau perusahaan. Pola ini juga bisa berarti 「mulai hari ini berlaku」, yang tidak dimiliki を限りに: <span class='gd-jp'>本日をもって受付を締め切ります。</span>(Pendaftaran ditutup hari ini.)</div><div class='gd-warn'>Tips menentukan: untuk 「dengan ～」 sehari-hari, pakai で. Untuk 「dengan ～」 di pengumuman, pemberitahuan, dan upacara, pakai をもって. Kalau kamu sendiri bertekad 「sampai hari ini saja, setelah ini tidak lagi ～」, pakai を限りに.</div><div class='gd-h'>Bisa dilanjutkan dengan ini</div><div class='gd-sec'><span class='gd-jp'>をもってしても</span> = 「bahkan dengan ～ pun…」, diikuti hal yang tidak bisa dilakukan: <span class='gd-jp'>最新の技術をもってしても、完全には防げない。</span>(Bahkan dengan teknologi terbaru pun, hal ini tidak bisa dicegah sepenuhnya.)</div>","n1-14":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜なり」 setara dengan <b>\"begitu ~ langsung …\"</b>, dengan nuansa kaget \"lho, secepat itu?\". Misalnya kamu bercerita ke teman: \"Begitu masuk pintu, dia langsung lari ke kamar tanpa lepas sepatu.\" Biasanya dipakai untuk menggambarkan <b>orang lain</b> yang baru saja selesai melakukan satu tindakan, lalu langsung melakukan tindakan berikutnya yang agak mengejutkan.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Tambahkan 「なり」 langsung ke bentuk kamus kata kerja (bentuk dasar yang kamu temukan di kamus), tanpa perubahan apa pun.<br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るなり</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くなり</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るなり</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menggambarkan reaksi orang lain</span>Tindakan pertama baru saja selesai, lalu orang yang sama langsung melakukan tindakan berikutnya, dan tindakan itu terasa agak mendadak.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は家に帰るなり、部屋にこもってしまった。</span>（Begitu sampai rumah, dia langsung mengurung diri di kamar）</div><div class='gd-ex-line'>・<span class='gd-jp'>その知らせを聞くなり、彼女は泣き出した。</span>（Begitu mendengar kabar itu, dia langsung menangis）</div><div class='gd-ex-line'>・<span class='gd-jp'>息子は私の顔を見るなり、走って逃げた。</span>（Begitu melihat wajahku, anakku langsung lari kabur）</div><div class='gd-sec'><span class='gd-tag'>Gaya bercerita</span>Kebanyakan muncul di novel, tulisan, atau saat kamu \"menceritakan\" suatu kejadian ke orang lain. Dalam obrolan sehari-hari, untuk \"begitu ~ langsung\" lebih sering dipakai 「〜たとたん」 yang sudah kamu pelajari di N3.</div><div class='gd-h'>Jebakan yang sering terjadi</div><div class='gd-warn'>・<b>Pelaku sebelum dan sesudahnya harus orang yang sama</b>. \"Begitu pulang, <b>dia</b> langsung mengurung diri di kamar\" boleh. Tapi \"Begitu bel berbunyi, murid-murid langsung berlari keluar\" pelakunya berganti, jadi pakai なり terasa janggal.<br>・<b>Biasanya tidak dipakai untuk diri sendiri</b>. なり terasa seperti pengamat yang sedang menceritakan. Untuk \"Begitu pulang aku langsung tidur\", lebih natural bilang <span class='gd-jp'>家に帰ってすぐ寝た。</span><br>・Yang mengikutinya adalah <b>hal yang sudah terjadi</b>. Tidak bisa diikuti perintah, ajakan, atau niat:<br>×<span class='gd-jp'>家に帰るなり、宿題をしなさい。</span>（tidak bisa dipakai untuk menyuruh orang）<br>・Bagian depan harus bentuk kamus. Kalau diganti bentuk た, 「<span class='gd-jp'>〜たなり</span>」 punya arti lain: \"sejak itu terus dalam keadaan begitu\", misalnya <span class='gd-jp'>出かけたなり、帰ってこない。</span>（Sejak pergi, dia tidak pulang-pulang）<br>・「<span class='gd-jp'>〜なり〜なり</span>」（～atau～ boleh） dan 「<span class='gd-jp'>私なりに</span>」（dengan caraku sendiri） bentuknya mirip, tapi tata bahasanya sama sekali berbeda. Jangan dicampur.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Di N1 ada beberapa pola \"begitu ~ langsung\". Semuanya disambung ke bentuk kamus dan diikuti hal yang sudah terjadi. Bedanya ada pada <b>siapa pelakunya, apa yang ditekankan, dan dipakai di mana</b>.<br><br><b>なり</b>: orang yang sama, melakukan tindakan yang agak mengejutkan.<br><span class='gd-jp'>部長は会議室に入るなり、大声で怒鳴り始めた。</span>（Begitu masuk ruang rapat, kepala departemen langsung mulai membentak dengan suara keras）<br><br><b>や否や</b>: sangat bahasa tulis, dan <b>pelaku atau kejadian sebelum dan sesudahnya boleh berbeda</b>.<br><span class='gd-jp'>ベルが鳴るや否や、学生たちは教室を飛び出した。</span>（Begitu bel berbunyi, para murid langsung berhamburan keluar kelas）<br><br><b>が早いか</b>: menekankan <b>kecepatan</b>. Tindakan pertama baru selesai, dan yang berikutnya hampir bersamaan.<br><span class='gd-jp'>子どもたちは「いただきます」と言うが早いか、料理に手を伸ばした。</span>（Anak-anak baru saja selesai bilang 「いただきます」, tangan mereka sudah terulur ke makanan）<br><br><b>たとたん</b>（N3）: bahasa lisan sehari-hari, <b>boleh juga untuk diri sendiri</b>, dan yang mengikuti sering hal yang tak bisa kamu kendalikan.<br><span class='gd-jp'>立ち上がったとたん、めまいがした。</span>（Begitu berdiri, langsung pusing）</div><div class='gd-warn'>Tips menentukan: orang yang sama tiba-tiba melakukan sesuatu → なり; dua hal berbeda terjadi berurutan dan konteksnya tulisan → や否や; ingin menekankan gerakan yang super cepat → が早いか; bicara tentang diri sendiri dalam obrolan biasa → たとたん.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Lanjutkan dengan 「<span class='gd-jp'>〜が早いか</span>」 dan 「<span class='gd-jp'>〜や否や</span>」 dari kelompok yang sama, lalu bandingkan dengan 「<span class='gd-jp'>〜そばから</span>」（baru saja ～ langsung ～ lagi, untuk hal yang terjadi berulang-ulang）. Kalau dihafal bersama-sama, kamu paling kecil kemungkinannya tertukar.</div>","n1-3":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜をものともせず」artinya kira-kira <b>「tidak gentar menghadapi ～」「tidak menganggap ～ sebagai halangan」</b>. Di depannya ada kesulitan, bahaya, atau rintangan, lalu di belakangnya ada hasil bahwa orang itu \"tetap berhasil melakukannya\". Ungkapan ini dipakai untuk memuji seseorang yang berani dan pantang menyerah. Nuansanya seperti berita yang menulis \"tak gentar menghadapi hujan dan angin, tetap setia di pos\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋<span class='gd-jp'>をものともせず</span> (boleh juga ditambah に di belakangnya: <span class='gd-jp'>をものともせずに</span>, artinya sama)<br><span class='gd-pair'><span class='gd-jp'>病気</span> → <span class='gd-jp'>病気をものともせず</span></span> (tak gentar menghadapi penyakit)<br><span class='gd-pair'><span class='gd-jp'>周囲の反対</span> → <span class='gd-jp'>周囲の反対をものともせず</span></span> (tak gentar menghadapi penolakan orang sekitar)<br>Kalau dipecah, <span class='gd-jp'>もの</span> berarti \"benda/hal\" dan <span class='gd-jp'>せず</span> berarti \"tidak melakukan\". Secara harfiah, artinya \"bahkan tidak menganggapnya sebagai masalah\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Di depan: kesulitan</span>Hal-hal yang \"menghadang di depan\", misalnya sakit, cedera, cuaca buruk, bahaya, kegagalan, penolakan, dan tekanan.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は度重なる失敗をものともせず、挑戦し続けた。</span> (Dia tak gentar menghadapi kegagalan yang berulang kali, dan terus mencoba)</div><div class='gd-ex-line'>・<span class='gd-jp'>救助隊は激しい雨をものともせず、山へ向かった。</span> (Tim penyelamat tak gentar menghadapi hujan deras dan berangkat menuju gunung)</div><div class='gd-sec'><span class='gd-tag'>Di belakang: hal yang berhasil dilakukan</span>Biasanya berupa kenyataan yang sudah terjadi, dengan nada kagum dan memuji.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は周囲の反対をものともせず、自分の店を開いた。</span> (Dia tak peduli pada penolakan orang sekitar dan membuka tokonya sendiri)</div><div class='gd-ex-line'>・<span class='gd-jp'>その選手は怪我をものともせず、最後まで走り抜いた。</span> (Atlet itu tak gentar menghadapi cedera dan berlari sampai garis akhir)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Ungkapan ini dipakai untuk <b>memuji orang lain</b>, biasanya tidak dipakai untuk diri sendiri. <span class='gd-jp'>私は寒さをものともせず</span> terdengar seperti membanggakan diri, jadi aneh.<br>・Di belakangnya tidak boleh ada ajakan atau permintaan seperti \"Tolong ～\" atau \"Ayo kita ～\". Kalimat seperti \"Jangan takut pada kesulitan, semangat ya!\" tidak cocok dengan ungkapan ini, karena ungkapan ini dipakai untuk <b>menggambarkan hal yang sudah berhasil dilakukan</b>.<br>・Di depannya harus ada <b>halangan</b>. Hal-hal baik seperti \"dukungan\" atau \"kesempatan\" tidak bisa dipakai, karena tidak ada yang perlu \"ditantang tanpa gentar\".<br>・Partikelnya <b>を</b>, bukan が.<br>・Ini kata kaku untuk bahasa tulis, berita, dan pidato. Hampir tidak pernah dipakai saat mengobrol dengan teman.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>をよそに</b>＝<b>tidak menghiraukan kekhawatiran atau harapan orang lain</b> dan tetap berbuat sesukanya. Di depannya sering ada <span class='gd-jp'>心配</span> atau <span class='gd-jp'>期待</span>, dengan kesan \"tidak mau mendengar nasihat\".<br>・<span class='gd-jp'>親の心配をよそに、彼は一人で海外へ行った。</span> (Tanpa menghiraukan kekhawatiran orang tuanya, dia pergi ke luar negeri sendirian)<br><b>をものともせず</b>＝<b>tidak takut pada kesulitan</b>, berani bertahan sampai berhasil. Ini bentuk pujian.<br>・<span class='gd-jp'>言葉の壁をものともせず、彼は海外で成功した。</span> (Tak gentar menghadapi kendala bahasa, dia sukses di luar negeri)<br>\"Kekhawatiran orang tua\" bukan rintangan yang harus ditaklukkan, jadi <span class='gd-jp'>親の心配をものともせず</span> terdengar tidak wajar.</div><div class='gd-sec'><b>にもかかわらず</b>＝\"meskipun ～ tetap ～\" yang netral, tanpa nada memuji atau mencela. Bisa dipakai untuk hal baik maupun buruk.<br>・<span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span> (Meskipun hujan, banyak orang yang datang)<br>Baru kalau kamu ingin menekankan \"orang-orang ini hebat\", gantilah dengan <span class='gd-jp'>雨をものともせず</span>.</div><div class='gd-warn'>Trik cepat: kalau di depannya \"rintangan\" dan kamu ingin memuji keberanian orang itu, pakai をものともせず. Kalau di depannya \"perasaan orang lain\" yang tidak dihiraukan, pakai をよそに. Kalau cuma bermaksud \"meskipun\", pakai にもかかわらず.</div>","n1-9":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「AはおろかB」artinya kira-kira <b>「jangankan A, B pun ～」</b>. A adalah hal yang \"memang sudah sewajarnya\" sampai malas disebut. B adalah hal yang lebih tak terduga, dipakai untuk menekankan \"keadaannya separah itu\". Urutannya sama dengan bahasa Indonesia, jadi kamu tinggal mengikuti urutan \"jangankan A, B pun ～\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Dasarnya <b>kata benda＋はおろか</b>: <span class='gd-pair'><span class='gd-jp'>漢字</span> → <span class='gd-jp'>漢字はおろか</span></span><br>Kalau A berupa kata kerja, tambahkan「こと」di belakang kata kerja agar jadi kata benda: <span class='gd-pair'><span class='gd-jp'>走る</span> → <span class='gd-jp'>走ることはおろか</span></span><br>Di paruh kedua kalimat biasanya dipasangkan <b>も、さえ、すら、まで</b>. Kata-kata ini setara dengan \"pun\" atau \"bahkan\" dalam bahasa Indonesia.</div><div class='gd-h'>Cara menyusun A dan B</div><div class='gd-sec'>Cara menilainya: letakkan di A hal yang \"memang sewajarnya begitu\", dan di B hal yang lebih ekstrem dan lebih mengejutkan.</div><div class='gd-sec'><span class='gd-tag'>Kalimat negatif (paling umum)</span>A adalah hal yang lebih sulit, B adalah hal yang lebih dasar. Tidak bisa yang sulit itu wajar, tetapi \"yang mudah pun tidak bisa\" baru terasa menekankan.</div><div class='gd-ex-line'>・<span class='gd-jp'>漢字はおろか、ひらがなさえまだ読めない。</span> (Jangankan kanji, hiragana pun belum bisa dibaca)</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、休みはおろか、昼ご飯を食べる時間もない。</span> (Saking sibuknya, jangankan libur, waktu untuk makan siang pun tidak ada)</div><div class='gd-ex-line'>・<span class='gd-jp'>足をけがして、走ることはおろか、歩くこともできない。</span> (Kakiku cedera, jangankan berlari, berjalan pun tidak bisa)</div><div class='gd-sec'><span class='gd-tag'>Kalimat positif</span>Sebaliknya, A adalah hal yang biasa, B adalah hal yang cakupannya lebih luas dan lebih hebat.</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌は国内はおろか、海外でも人気がある。</span> (Lagu ini, jangankan di dalam negeri, di luar negeri pun populer)</div><div class='gd-warn'>Jangan terbalik urutannya: <span class='gd-jp'>ひらがなはおろか、漢字も読めない。</span> tidak masuk akal. Orang yang hiragana saja tidak bisa tentu wajar kalau tidak bisa kanji, jadi tidak perlu ditekankan.<br>Baik kalimat negatif maupun positif, aturannya sama: A adalah \"memang begitu adanya\", B adalah \"bahkan yang ini pun begitu\".</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Paruh kedua kalimat <b>tidak boleh berisi perintah, permintaan, atau niat sendiri</b>. <span class='gd-jp'>漢字はおろか、ひらがなも覚えなさい。</span> itu salah. Dalam kasus ini pakai <span class='gd-jp'>はもちろん</span>.<br>・は sudah termasuk di dalamnya, jadi jangan menambah を atau が di depannya. Kata kerja juga tidak bisa langsung disambung, ingat tambahkan「こと」dulu.<br>・おろか di sini tidak ada hubungannya dengan「愚か」(bodoh), jadi jangan dipahami sebagai \"bodoh\".<br>・Nadanya kaku dan sering membawa rasa tidak puas atau kaget seperti \"keterlaluan banget\" atau \"parah banget\". Dipakai terutama dalam tulisan atau situasi yang cukup formal. Saat mengobrol dengan teman, orang Jepang lebih sering bilang <span class='gd-jp'>どころか</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Coba bandingkan dalam situasi yang sama:<br><b>はおろか</b>＝menekankan \"bahkan B pun\" dengan nada kaget atau tidak puas, dan paruh kedua hanya boleh berupa kalimat pernyataan: <span class='gd-jp'>漢字はおろか、ひらがなも書けない。</span> (Jangankan kanji, hiragana pun tidak bisa menulisnya)<br><b>はもちろん</b>＝\"A tentu saja, B juga\" yang netral, dan di belakangnya boleh ada permintaan: <span class='gd-jp'>漢字はもちろん、ひらがなもちゃんと書いてください。</span> (Kanji tentu harus ditulis dengan benar, hiragana juga tolong tulis dengan benar)<br><b>どころか</b>＝artinya dekat dengan はおろか, tapi lebih lisan. Selain itu, bisa juga berarti \"bukannya A, malah B\": <span class='gd-jp'>安いどころか、すごく高かった。</span> (Bukannya murah, malah mahal sekali). はおろか tidak punya pemakaian \"malah\" ini.</div><div class='gd-warn'>Trik cepat: kalau mau menyuruh orang melakukan sesuatu, pakai はもちろん. Kalau bicara dengan teman, pakai どころか. Kalau menulis dan ingin menekankan rasa kaget \"sampai yang ini pun begitu\", pakai はおろか.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kata <span class='gd-jp'>すら</span> (bahkan ～ pun) yang sering dipasangkan di paruh kedua kalimat, bisa kamu pelajari selanjutnya.</div>","n1-10":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ないまでも」artinya <b>「kalaupun belum sampai ～, setidaknya ～」</b>. Pertama, lepaskan dulu standar tinggi (nilai sempurna, setiap hari, seperti penutur asli), lalu sebutkan target <b>mundur selangkah, batas minimum</b>-nya. Nadanya mirip saat kamu bilang ke diri sendiri, \"Nggak harus olahraga tiap hari, tapi setidaknya seminggu sekali.\"</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bentuk ない kata kerja + までも. Bagian depan berisi \"standar tinggi\", bagian belakang berisi \"tingkat minimal yang harus tercapai\".<br><span class='gd-pair'><span class='gd-jp'>取れない</span> → <span class='gd-jp'>取れないまでも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ネイティブのようには話せないまでも、日常会話はこなしたい。</span>(Kalaupun nggak bisa bicara seperti penutur asli, setidaknya aku ingin bisa mengikuti percakapan sehari-hari)</div><div class='gd-sec'>Dalam praktiknya, dua gabungan tetap di bawah ini lebih sering muncul. Di depannya langsung ditaruh kata benda. Sebaiknya hafalkan satu paket:</div><div class='gd-sec'><span class='gd-tag'>とは言わないまでも</span>\"Nggak sampai menuntut tingkat ～\". Sering dipakai untuk harapan atau permintaan.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日とは言わないまでも、週に一度は運動したい。</span>(Nggak harus tiap hari, tapi setidaknya aku ingin olahraga seminggu sekali)</div><div class='gd-sec'><span class='gd-tag'>とはいかないまでも</span>\"Memang belum sampai ～\". Sering dipakai untuk hasil yang sudah didapat.</div><div class='gd-ex-line'>・<span class='gd-jp'>満点とはいかないまでも、合格点は取れた。</span>(Memang bukan nilai sempurna, tapi setidaknya nilaiku cukup untuk lulus)</div><div class='gd-h'>Seperti apa bagian belakangnya</div><div class='gd-sec'>Bagian belakang biasanya berisi \"ingin ～\", \"seharusnya ～\", \"berharap lawan bicara ～\", atau hasil yang sudah dicapai. Biasanya juga dipasangkan dengan <b>「は」「くらいは」「せめて」</b> untuk menekankan \"setidaknya ini\".</div><div class='gd-ex-line'>・<span class='gd-jp'>謝罪とは言わないまでも、せめて一言説明してほしい。</span>(Nggak minta minta maaf, tapi setidaknya jelaskan sepatah dua kata dong)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Bagian depan dan belakang harus berada <b>di satu penggaris yang sama, hanya beda tinggi-rendahnya</b>: nilai sempurna vs lulus, tiap hari vs seminggu sekali. Depan tinggi, belakang rendah. Kalau belakangnya malah lebih tinggi, atau dua hal itu tidak berhubungan, pola ini tidak bisa dipakai.<br>・Bagian belakang berisi hal <b>positif</b>: \"setidaknya sudah/ingin melakukan ini\". Kalau mau bilang \"standar minimum pun tidak tercapai\", pakai pola lain (lihat はおろか di bawah).<br>・Jangan tertukar dengan「〜までもない」: <span class='gd-jp'>言うまでもない</span> artinya \"tak perlu dikatakan pun sudah jelas\", disambung dengan bentuk kamus, dan maknanya \"tidak perlu melakukannya\". Sedangkan <span class='gd-jp'>言わないまでも</span> artinya \"memang tidak sampai mengatakannya sejauh itu\". Beda satu ない saja, artinya sudah jauh berbeda.<br>・Kesannya agak tulisan dan formal, tapi 「とは言わないまでも」 cukup sering terdengar juga dalam percakapan sehari-hari.</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'>Yang paling gampang tertukar adalah <b>〜はおろか</b>. Keduanya sama-sama berarti \"standar tinggi tidak tercapai\", tapi arah kalimat belakangnya berlawanan. Contohnya sama-sama soal ujian:<br><span class='gd-jp'>満点とはいかないまでも、合格点は取れた。</span>(Memang belum sempurna, tapi setidaknya nilaiku cukup untuk lulus) → standar minimum <b>tercapai</b>, kalimat ditutup ke arah yang baik.<br><span class='gd-jp'>満点はおろか、合格点も取れなかった。</span>(Jangankan nilai sempurna, nilai untuk lulus pun tidak dapat) → standar minimum pun <b>tidak tercapai</b>, penekanannya ke arah yang buruk.</div><div class='gd-warn'>Trik cepat: \"yang tinggi tidak ada, <b>tapi yang rendah ada</b>\" → pakai ないまでも; \"yang tinggi tidak ada, <b>yang rendah pun tidak ada</b>\" → pakai はおろか.</div>","n1-22":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜べく」artinya <b>\"demi/untuk ～\"</b>, tapi ini ungkapan tulisan dan formal, terasa seperti \"guna ～\" atau \"dalam rangka ～\" di berita atau surat resmi bahasa Indonesia. Maknanya hampir sama dengan 「ために」, hanya lebih kaku dan formal, dan hampir tidak pernah dipakai ngobrol sehari-hari.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Berita・Laporan</span>Menjelaskan tujuan seseorang saat mengambil suatu tindakan.</div><div class='gd-ex-line'>・<span class='gd-jp'>真相を確かめるべく、記者は現地へ向かった。</span>(Untuk memastikan kebenarannya, si reporter berangkat ke lokasi)</div><div class='gd-ex-line'>・<span class='gd-jp'>試験に合格すべく、毎日10時間勉強した。</span>(Agar lulus ujian, aku belajar 10 jam setiap hari)</div><div class='gd-sec'><span class='gd-tag'>Menyatakan tekad di acara formal</span>Dalam sambutan, konferensi pers, atau pengumuman perusahaan, untuk mengatakan \"demi ～ kami akan berusaha\".</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご期待に応えるべく、全力を尽くします。</span>(Demi memenuhi harapan Bapak/Ibu sekalian, kami akan berusaha sekuat tenaga)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Tambahkan 「べく」langsung ke <b>bentuk kamus</b> kata kerja (bentuk dasar seperti di kamus):<br><span class='gd-pair'><span class='gd-jp'>確かめる</span> → <span class='gd-jp'>確かめるべく</span></span><br><span class='gd-pair'><span class='gd-jp'>なる</span> → <span class='gd-jp'>なるべく</span></span><br><span class='gd-pair'><span class='gd-jp'>応える</span> → <span class='gd-jp'>応えるべく</span></span></div><div class='gd-sec'><b>する</b> agak istimewa: dua-duanya boleh, tapi <b>すべく</b> lebih umum:<br><span class='gd-pair'><span class='gd-jp'>達成する</span> → <span class='gd-jp'>達成すべく</span></span> (boleh juga <span class='gd-jp'>達成するべく</span>)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Bagian depan <b>tidak bisa berbentuk negatif</b>: tidak ada bentuk 「遅刻しないべく」. Untuk \"supaya tidak ～\", pakai <span class='gd-jp'>遅刻しないように</span>.<br>・Bagian belakang <b>tidak bisa berisi permintaan kepada lawan bicara</b> (permintaan, perintah, ajakan): <span class='gd-jp'>合格すべく、毎日勉強してください</span> itu salah, harus diubah menjadi <span class='gd-jp'>合格するために、毎日勉強してください</span>.<br>・<b>Kata benda tidak bisa langsung disambung</b>: boleh bilang <span class='gd-jp'>健康のために</span>, tapi tidak ada 「健康のべく」. Kalau mau pakai べく, harus sambung dengan kata kerja: <span class='gd-jp'>健康を維持すべく</span>.<br>・Biasanya bagian depan dan belakang berkaitan dengan <b>orang yang sama</b>, dan berupa hal yang <b>dilakukan dengan sengaja</b>. Hal yang tidak bisa dikendalikan manusia seperti \"hujan turun\" tidak bisa ditaruh sebelum べく.<br>・Hati-hati, jangan tertukar dengan adverbia <span class='gd-jp'>なるべく</span> (sebisa mungkin): <span class='gd-jp'>なるべく早く来てください</span> artinya \"Tolong datang secepat mungkin\"; sedangkan <span class='gd-jp'>医者になるべく</span> baru berarti \"untuk menjadi dokter\". Lihat saja ada atau tidaknya kata yang menyambung di depannya.<br>・Kalau dipakai ngobrol dengan teman, 「〜べく」 terdengar seperti membaca surat dinas. Untuk percakapan, pakai ために.</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'>Sama-sama bermakna \"berusaha demi lulus\":<br><b>ために</b> = ungkapan umum, bisa dipakai saat bicara maupun menulis: <span class='gd-jp'>合格するために、毎日勉強している。</span> (Agar lulus, aku belajar setiap hari)<br><b>べく</b> = tulisan, formal: <span class='gd-jp'>合格すべく、毎日勉強した。</span> (Guna lulus ujian, aku belajar keras setiap hari)<br><b>んがため（に）</b> = lebih kuno dan kaku, terasa sangat kuat seperti \"mati-matian pun harus\", dan cara menyambungnya juga berbeda (<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんがため</span></span>): <span class='gd-jp'>合格せんがため、寝る間も惜しんで勉強した。</span> (Demi lulus, aku sampai rela mengorbankan waktu tidur dan belajar mati-matian)</div><div class='gd-warn'>Trik cepat: sehari-hari pakai ために; berita, pidato, dan tulisan formal pakai べく; んがため baru dipakai kalau ingin menekankan \"bagaimanapun caranya harus tercapai\".</div><div class='gd-h'>Setelah ini, bisa lanjut belajar</div><div class='gd-sec'>・<span class='gd-jp'>べくして</span>: \"memang sudah ditakdirkan ～\", artinya berbeda dari \"demi\". <span class='gd-jp'>起こるべくして起こった事故だ。</span> (Ini kecelakaan yang cepat atau lambat memang pasti terjadi)<br>・<span class='gd-jp'>べき</span> (seharusnya) dan <span class='gd-jp'>べからず</span> (dilarang) dari keluarga yang sama, keduanya bukan berarti \"demi\", jadi jangan dicampur.</div>","n1-23":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ゆえ（に）」adalah bentuk bahasa tulis dari <b>「karena」「berhubung」「lantaran」</b>. Artinya sama dengan 「から」「ので」, yaitu \"karena\", hanya saja ia seperti memakai jas dan bicaranya jadi kaku. Kamu sering menemukannya di editorial berita, novel, dan naskah pidato. Dalam obrolan dengan teman, hampir tidak pernah dipakai.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Kata benda</span>Yang paling umum adalah menyambungnya langsung. Di tengahnya boleh juga disisipkan 「の」.<br><span class='gd-pair'><span class='gd-jp'>若さ</span> → <span class='gd-jp'>若さゆえ</span></span><span class='gd-pair'><span class='gd-jp'>貧しさ</span> → <span class='gd-jp'>貧しさのゆえに</span></span></div><div class='gd-sec'><span class='gd-tag'>Kata kerja・kata sifat-い</span>Pakai bentuk biasa (bentuk kamus, tanpa ます). Setelahnya boleh 「がゆえ」 atau 「ゆえ」; 「がゆえ」 terdengar lebih kaku.<br><span class='gd-pair'><span class='gd-jp'>人気がある</span> → <span class='gd-jp'>人気があるがゆえに</span></span><span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若いがゆえに</span></span></div><div class='gd-sec'><span class='gd-tag'>Kata sifat-な・kata benda sebagai kalimat</span>Ganti 「だ」 dengan <b>である</b>, lalu sambungkan.<br><span class='gd-pair'><span class='gd-jp'>真面目だ</span> → <span class='gd-jp'>真面目であるがゆえに</span></span><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生であるがゆえに</span></span></div><div class='gd-h'>Bentuk yang paling sering muncul</div><div class='gd-sec'><span class='gd-tag'>ゆえに、〜</span>Diikuti satu kalimat utuh yang berisi akibatnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>人気があるがゆえに、予約がなかなか取れない。</span>（Karena terlalu populer, reservasinya susah sekali didapat）</div><div class='gd-ex-line'>・<span class='gd-jp'>責任ある立場ゆえに、軽率な発言は許されない。</span>（Karena menduduki posisi penting, tidak boleh asal bicara）</div><div class='gd-sec'><span class='gd-tag'>ゆえの＋kata benda</span>Langsung menerangkan kata benda sesudahnya, artinya \"…yang timbul karena ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>経験不足ゆえの失敗だった。</span>（Itu kegagalan yang disebabkan kurangnya pengalaman）</div><div class='gd-ex-line'>・<span class='gd-jp'>優しさゆえの嘘もある。</span>（Ada juga kebohongan yang lahir dari kelembutan hati）</div><div class='gd-sec'><span class='gd-tag'>ゆえに di awal kalimat</span>Kalau berdiri sendiri di awal kalimat, artinya \"maka, oleh karena itu\". Sering muncul dalam pembuktian matematika dan uraian filsafat.</div><div class='gd-ex-line'>・<span class='gd-jp'>我思う、ゆえに我あり。</span>（Aku berpikir, maka aku ada）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata benda dan kata sifat-な <b>tidak boleh disambung dengan 「だ」</b>: bukan 「学生だがゆえに」, melainkan <span class='gd-jp'>学生であるがゆえに</span>.<br>・Kalau dipakai dalam obrolan sehari-hari, kamu akan terdengar seperti sedang main drama kolosal atau membaca dialog. Untuk bilang \"karena sibuk\" ke teman, cukup <span class='gd-jp'>忙しいから</span>. Kalau bilang 「忙しいがゆえに」, orang bisa tertawa.<br>・Kanjinya ditulis 「故」. Kalau kamu melihat <span class='gd-jp'>若さ故に</span>, jangan kira itu tata bahasa lain; bacanya tetap ゆえに.<br>・Hasil di belakangnya sering bernada negatif, atau berupa \"malah ～\". Ada nuansa \"justru karena ciri inilah jadi begini\", misalnya <span class='gd-jp'>真面目であるがゆえに、かえって批判されることもある。</span>（Justru karena serius, kadang malah dikritik）</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>から／ので</b>＝\"karena\" yang umum, bisa dipakai dalam lisan maupun tulisan: <span class='gd-jp'>子どもを愛しているから、厳しくする。</span>（Karena sayang anak, aku bersikap tegas）<br><b>がゆえに</b>＝artinya sama, tetapi bergaya tulisan dan menyatakan sebab secara objektif: <span class='gd-jp'>子どもを愛するがゆえに、厳しくする。</span>（Berhubung sayang pada anak, ia bersikap tegas）<br><b>ばこそ</b>＝menekankan dengan kuat \"<b>justru</b> karena ini, bukan karena yang lain\". Biasanya pembicara sedang membela caranya sendiri, dan akhir kalimat sering memakai のだ: <span class='gd-jp'>子どもを愛すればこそ、厳しくするのだ。</span>（Justru karena sayang pada anak, aku bersikap tegas）</div><div class='gd-warn'>Trik cepat: kalau hanya ingin bilang \"karena\" dengan gaya formal, pakai ゆえに. Kalau ingin menekankan \"justru karena alasan ini, tolong mengertilah aku\", pakai ばこそ.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Tata bahasa N1 lain yang juga menyatakan sebab adalah <span class='gd-jp'>〜とあって</span> (karena situasinya istimewa seperti ～). Coba hafalkan sambil membandingkannya dengan ゆえに.</div>","n1-27":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜たところで」setara dengan <b>\"biarpun ～ juga percuma\"</b> atau <b>\"～ pun apa gunanya\"</b>. Mirip kalau kita bilang \"nangis sekarang juga percuma\" atau \"sejelas apa pun kamu menjelaskan, dia tetap tidak akan percaya\". Nadanya agak pasrah dan agak menyiram air dingin: apa yang dilakukan di depan itu sia-sia.</div><div class='gd-ex-line'>・<span class='gd-jp'>今さら謝ったところで、関係は戻らないだろう。</span>（Sekarang minta maaf pun, hubungan kita tidak akan kembali seperti dulu）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk た (bentuk lampau), lalu langsung tambahkan 「ところで」.<br><b>Golongan 1 (kata kerja godan)</b>：<br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いだ</span> → <span class='gd-jp'>急いだところで</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったところで</span></span><br><b>Golongan 2 (kata kerja ichidan)</b>：<br><span class='gd-pair'><span class='gd-jp'>慌てる</span> → <span class='gd-jp'>慌てた</span> → <span class='gd-jp'>慌てたところで</span></span><br><b>Golongan 3 (する・来る)</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span> → <span class='gd-jp'>したところで</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たところで</span></span></div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>Dilakukan pun sia-sia</span>Pemakaian yang paling umum. Di depannya sering ada 「<span class='gd-jp'>いくら</span>」「<span class='gd-jp'>どんなに</span>」「<span class='gd-jp'>今さら</span>」, dan di belakangnya hasil yang tidak berguna seperti 「～ない」「無駄だ」「仕方がない」.</div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに急いだところで、最終便には間に合わない。</span>（Secepat apa pun kamu buru-buru, kamu tidak akan keburu naik kereta terakhir）</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら説明したところで、わかってもらえないだろう。</span>（Sebanyak apa pun kamu menjelaskan, dia mungkin tetap tidak akan paham）</div><div class='gd-sec'><span class='gd-tag'>Paling banter cuma ～</span>Diikuti 「<span class='gd-jp'>せいぜい</span>」, artinya \"kalaupun dilakukan, hasilnya tidak akan besar\".</div><div class='gd-ex-line'>・<span class='gd-jp'>今から急いだところで、せいぜい5分早く着くくらいだ。</span>（Kalau buru-buru dari sekarang pun, paling banter cuma sampai 5 menit lebih awal）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Meski memakai bentuk た, yang dibicarakan adalah <b>pengandaian</b>, bukan hal yang sudah terjadi. 「謝ったところで」 artinya \"kalaupun (mau) minta maaf\", bukan \"sudah minta maaf\".<br>・Di belakangnya harus ada hasil yang tidak berguna atau tidak memuaskan. Untuk hasil baik seperti \"kalau berusaha pasti lulus\", kamu tidak bisa bilang 頑張ったところで合格できる. Pakai <span class='gd-jp'>頑張れば合格できる</span>.<br>・Bagian belakang adalah penilaian atau dugaanmu sendiri, sering ditutup dengan 「～だろう」「～わけではない」. Kalimat yang meminta orang lain melakukan sesuatu seperti 「～てください」 tidak dipakai di sini.<br>・「たところで」 yang sama punya makna lain: \"pada saat ～ / ketika sesuatu baru saja selesai\", lalu diikuti tindakan berikutnya: <span class='gd-jp'>話が一段落したところで、休憩しましょう。</span>（Setelah pembicaraan selesai satu tahap, ayo istirahat sebentar）. Lihat bagian belakangnya: kalau hasilnya \"percuma\", itu arti yang kita pelajari di sini; kalau \"lalu melakukan sesuatu\", itu penanda waktu.<br>・Nadanya agak dingin dan pasrah. Mengatakan langsung ke orang \"percuma kamu lakukan\" bisa terasa menyiram air dingin, jadi lihat situasinya.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ても</b>＝\"meskipun\" yang umum dan netral, hasil di belakangnya boleh baik atau buruk: <span class='gd-jp'>彼に説明しても、わかってもらえないだろう。</span>（Dijelaskan ke dia pun, dia mungkin tidak akan paham）<br><b>たところで</b>＝menekankan \"dilakukan pun sia-sia\", lebih pasrah daripada ても: <span class='gd-jp'>彼に説明したところで、わかってもらえないだろう。</span>（Dijelaskan ke dia pun percuma, dia tidak akan paham）<br><b>ようと</b>＝\"apa pun yang terjadi, aku tetap ～\". Intinya, bagian belakang tidak terpengaruh, dan bisa dipakai untuk tekadmu sendiri: <span class='gd-jp'>みんなが反対しようと、私はこの計画を進める。</span>（Sekalipun semua orang menentang, aku tetap menjalankan rencana ini）<br>Untuk menyatakan penentangan yang sama, dengan たところで jadinya: <span class='gd-jp'>みんなが反対したところで、社長の考えは変わらない。</span>（Semua orang menentang pun percuma, pendapat direktur tidak akan berubah）</div><div class='gd-warn'>Trik cepat: untuk \"dilakukan pun sia-sia\" pakai たところで; untuk \"apa pun yang terjadi aku tetap melakukannya\" pakai ようと; untuk \"meskipun\" biasa, pakai ても.</div>","n1-28":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ようが／〜ようと」 artinya <b>「terserah ～, aku tetap ...」</b>. Apa pun yang terjadi di bagian depan, dan bagaimanapun sikap orang lain, kesimpulan di belakang tidak berubah. Nuansanya lebih <b>kaku dan tegas</b> daripada 「〜ても」 biasa, dengan sikap \"aku yang menentukan, aku tidak takut\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Dengan kata tanya</span>Taruh 「何・どこ・誰・どんなに・いくら」 di depan. Artinya \"apa pun / di mana pun / siapa pun / seberapa pun ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>何を言われようが、気にしない。</span>(Apa pun yang dikatakan orang, aku tidak peduli)</div><div class='gd-ex-line'>・<span class='gd-jp'>どこへ行こうと、あなたの自由です。</span>(Kamu mau pergi ke mana pun, itu bebas kamu)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が反対しようと、私はやる。</span>(Siapa pun yang menentang, aku tetap akan melakukannya)</div><div class='gd-sec'><span class='gd-tag'>Dipakai sendiri</span>Kalau tanpa kata tanya, artinya \"walaupun ～ tetap ...\".</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降ろうが行く。</span>(Walaupun hujan, aku tetap pergi)</div><div class='gd-sec'><span class='gd-tag'>Dua berpasangan</span>「AようがBようが」＝baik A maupun B; 「Aようが Aまいが」＝mau dilakukan atau tidak. 「まい」 di sini berarti \"tidak ～\". Untuk kelompok 1 (verba godan), 「まい」 disambung ke bentuk kamus: <span class='gd-jp'>行くまい</span>; sedangkan <span class='gd-jp'>する</span> biasanya menjadi <span class='gd-jp'>しまい</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降ろうが風が吹こうが、試合は行われる。</span>(Mau hujan atau angin kencang, pertandingan tetap digelar)</div><div class='gd-ex-line'>・<span class='gd-jp'>参加しようがしまいが、あなたの自由だ。</span>(Mau ikut atau tidak, terserah kamu)</div><div class='gd-sec'>Di bagian belakang sering muncul 「<span class='gd-jp'>自由だ</span>」「<span class='gd-jp'>関係ない</span>」「<span class='gd-jp'>構わない</span>」「<span class='gd-jp'>気にしない</span>」, atau tekad \"pokoknya aku mau melakukannya\".</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'><b>Verba</b>: ubah dulu ke bentuk volisional (bentuk seperti 「行こう」「食べよう」), lalu tambahkan が atau と.<br>Kelompok 1 (verba godan): <span class='gd-pair'><span class='gd-jp'>行く</span> → ganti く jadi こ → <span class='gd-jp'>行こうが</span></span><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言おうが</span></span><br>Kelompok 2 (verba ichidan): buang る lalu tambahkan よう　<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べようが</span></span>. Bentuk pasif <span class='gd-pair'><span class='gd-jp'>言われる</span> → <span class='gd-jp'>言われようが</span></span> juga berubah dengan cara yang sama<br>Kelompok 3 (する・来る): <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようが</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようが</span></span></div><div class='gd-sec'><b>Kata sifat-い</b>: buang 「い」 di akhir, lalu tambahkan 「かろう」.<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑かろうが</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かろうと</span></span><br>「いい」 berubah lewat 「よい」: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかろうが</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに暑かろうと、毎朝のランニングは欠かさない。</span>(Sepanas apa pun, aku tidak pernah melewatkan lari pagi setiap hari)</div><div class='gd-sec'><b>Kata sifat-な・nomina</b>: tambahkan 「だろう」 atau 「であろう」 yang lebih formal.<br><span class='gd-pair'><span class='gd-jp'>不便だ</span> → <span class='gd-jp'>不便だろうが</span></span><span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どもであろうと</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>相手が子どもだろうが、ルールはルールだ。</span>(Walaupun lawannya anak kecil, aturan tetap aturan)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Bentuk volisional di sini <b>tidak</b> berarti \"ayo ～\" (ajakan). Bentuknya hanya dipinjam untuk menyatakan \"apa pun yang terjadi\".<br>・Verba kelompok 1 tidak bisa langsung disambung: yang benar <span class='gd-jp'>行こうが</span>, bukan 「行くようが」.<br>・<span class='gd-jp'>来ようが</span> dibaca 「こようが」, bukan 「きようが」.<br>・<span class='gd-jp'>降ろうが</span> artinya hanya \"walaupun hujan\"; untuk \"hujan atau tidak, tetap ...\" kamu harus bilang <span class='gd-jp'>降ろうが降るまいが</span>.<br>・「ようが」 dan 「ようと」 pada dasarnya sama artinya dan bisa saling menggantikan.<br>・Nuansanya kaku dan tegas. Dalam obrolan sehari-hari 「<span class='gd-jp'>暑くても</span>」 terdengar lebih natural; bentuk かろう seperti 「<span class='gd-jp'>暑かろうが</span>」 lebih cocok untuk tulisan atau penekanan.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Situasi yang sama: seberapa pun terburu-buru.<br><b>ても</b>＝\"walaupun ～ tetap\" yang umum, paling netral: <span class='gd-jp'>いくら急いでも、間に合わない。</span>(Seberapa pun terburu-buru, tidak akan sempat)<br><b>ようが</b>＝bagian belakangnya \"aku tetap begitu / tidak ada bedanya\", dengan sikap yang kuat: <span class='gd-jp'>いくら急がされようが、手は抜かない。</span>(Seberapa pun aku didesak, aku tidak akan asal-asalan)<br><b>たところで</b>＝bagian belakangnya \"percuma, hasilnya tidak akan bagus\": <span class='gd-jp'>いくら急いだところで、もう間に合わない。</span>(Seberapa pun terburu-buru, sudah tidak sempat lagi)</div><div class='gd-sec'>Selain itu, untuk nomina kamu juga bisa memakai 「<b>であれ</b>」 untuk menyatakan \"apa pun ～\" yang sama: <span class='gd-jp'>理由が何であれ、遅刻はだめだ。</span> dan <span class='gd-jp'>理由が何であろうと、遅刻はだめだ。</span> artinya hampir sama (apa pun alasannya, terlambat tetap tidak boleh).</div><div class='gd-warn'>Trik memilih: kalau bagian belakangnya \"aku tetap melakukannya / terserah kamu / tidak masalah\", pakai ようが; kalau \"dilakukan pun percuma\", pakai たところで; kalau untuk percakapan sehari-hari dan tidak mau terdengar terlalu keras, pakai ても.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Untuk \"baik A maupun B\" yang sama, lanjutkan ke 「<span class='gd-jp'>〜にせよ〜にせよ</span>」: <span class='gd-jp'>行くにせよ行かないにせよ、連絡してください。</span>(Pergi atau tidak, tolong kabari aku)</div>","n1-29":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「AにせよBにせよ」 artinya <b>「entah A entah B, tetap ～」</b>. Kamu melempar dulu dua kemungkinan, lalu bilang: mana pun yang terjadi, hasilnya sama dan kesimpulan tidak berubah. Nuansanya cukup formal, sering muncul di tulisan, berita, dan pidato rapat.</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'><b>Verba, kata sifat-い</b>: langsung disambung ke bentuk biasa (bentuk tanpa ます atau です).<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くにせよ行かないにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いにせよ安いにせよ</span></span></div><div class='gd-sec'><b>Nomina, kata sifat-な</b>: langsung disambung, bentuk sekarang <b>tanpa だ</b>. Kalau mau lebih formal, bisa ditambah 「である」.<br><span class='gd-pair'><span class='gd-jp'>大人</span> → <span class='gd-jp'>大人にせよ子どもにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きにせよ嫌いにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生であるにせよ</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sepasang yang berlawanan</span>Pergi / tidak pergi, setuju / menentang: sisi mana pun hasilnya sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにせよ行かないにせよ、早めに連絡してください。</span>(Pergi atau tidak, tolong kabari lebih awal)</div><div class='gd-ex-line'>・<span class='gd-jp'>好きにせよ嫌いにせよ、この仕事は誰かがやらなければならない。</span>(Suka atau tidak, pekerjaan ini harus ada yang mengerjakan)</div><div class='gd-sec'><span class='gd-tag'>Dua hal sejenis</span>Kamu memberi dua contoh yang mewakili \"semua yang sejenis ini sama saja\".</div><div class='gd-ex-line'>・<span class='gd-jp'>大人にせよ子どもにせよ、ルールは守らなければならない。</span>(Orang dewasa maupun anak-anak, semuanya harus menaati aturan)</div><div class='gd-sec'>Bagian belakang biasanya berupa penilaian yang <b>berlaku untuk kedua sisi</b>, seperti \"seharusnya ～\", \"harus ～\", atau \"tidak ada bedanya\".</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Ungkapan tetap</span>Tanpa memberi contoh, cukup satu kata yang mencakup semuanya. Sangat umum di lisan maupun tulisan.</div><div class='gd-ex-line'>・<span class='gd-jp'>いずれにせよ、結果が出たら連絡します。</span>(Bagaimanapun, kalau hasilnya sudah keluar aku kabari)</div><div class='gd-ex-line'>・<span class='gd-jp'>何にせよ、無事でよかった。</span>(Pokoknya, syukurlah kamu selamat)</div><div class='gd-sec'><span class='gd-tag'>Dipakai sekali saja</span>「にせよ」 yang berdiri sendiri＝\"walaupun ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談にせよ、そんなことを言ってはいけない。</span>(Walaupun bercanda, tidak boleh mengatakan hal seperti itu)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Nomina dan kata sifat-な bentuk sekarang tidak memakai だ: bukan 学生だにせよ, tetapi <span class='gd-jp'>学生にせよ</span> atau <span class='gd-jp'>学生であるにせよ</span>.<br>・「せよ」 mirip bentuk perintah (\"lakukan!\"), tetapi di sini hanya ungkapan tetap dan <b>tidak berarti perintah</b>.<br>・Bagian belakang harus berlaku untuk kedua kemungkinan. Kalau kesimpulannya hanya cocok untuk salah satu sisi, pola ini tidak bisa dipakai.<br>・Sangat bernuansa tulisan. Ke teman, <span class='gd-jp'>行っても行かなくても</span> terdengar lebih natural; kalau pakai にせよ, kesannya seperti membaca surat dinas.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>にしろ…にしろ</b>: artinya persis sama, nuansanya sedikit lebih lembut dan masih bisa dipakai di lisan.<br><span class='gd-jp'>行くにしろ行かないにしろ、連絡してください。</span>(Pergi atau tidak, tolong kabari)<br><b>であれ…であれ</b>: terutama dengan nomina, lebih kaku dan lebih formal daripada にせよ.<br><span class='gd-jp'>大人であれ子どもであれ、ルールは守るべきだ。</span>(Dewasa maupun anak-anak, semuanya seharusnya menaati aturan)<br><b>ようが…まいが</b>: membawa emosi kuat \"terserah, toh sama saja\".<br><span class='gd-jp'>行こうが行くまいが、私には関係ない。</span>(Kamu pergi atau tidak, bukan urusanku)</div><div class='gd-warn'>Trik memilih: untuk \"entah A entah B\" yang diucapkan dengan tenang, pakai にせよ／にしろ; kalau hanya nomina dan butuh yang lebih formal, pakai であれ; kalau ada emosi \"terserah deh, toh tidak akan berubah\", pakai ようが.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Untuk \"apa pun isinya, tetap ～\", pelajari <span class='gd-jp'>いかんにかかわらず</span>: <span class='gd-jp'>理由のいかんにかかわらず、遅刻は認めません。</span>(Apa pun alasannya, keterlambatan tidak akan diterima)</div>","n1-30":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜と思いきや」artinya kira-kira <b>「Kirain ～, eh ternyata malah…」</b>. Bagian depan berisi perkiraanmu semula, bagian belakang berisi apa yang benar-benar terjadi. Hasilnya <b>kebalikan total</b> dari perkiraan, jadi ada rasa kaget karena perkiraanmu terpatahkan begitu saja.</div><div class='gd-ex-line'>・<span class='gd-jp'>晴れると思いきや、午後から急に雨が降り出した。</span>（Kirain bakal cerah, eh sore harinya tiba-tiba hujan turun）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depan pakai <b>bentuk biasa</b> (bentuk tanpa ます/です), lalu langsung tambahkan 「と思いきや」.<br><span class='gd-pair'><span class='gd-jp'>合格した</span> → <span class='gd-jp'>合格したと思いきや</span></span><br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → <span class='gd-jp'>簡単だと思いきや</span></span></div><div class='gd-sec'><span class='gd-tag'>かと思いきや</span>Di tengahnya sering ada tambahan 「か」, dengan nuansa seperti \"kirain jangan-jangan sudah ～\". Bentuk ini sangat umum. Waktu menambahkan か, perhatikan ini:<br><b>Kata kerja dan kata sifat-い</b>: langsung tambahkan か.<br><span class='gd-pair'><span class='gd-jp'>終わった</span> → <span class='gd-jp'>終わったかと思いきや</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いかと思いきや</span></span><br><b>Kata benda dan kata sifat-な</b>: buang 「だ」 dulu, baru tambahkan か.<br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → buang だ → <span class='gd-jp'>簡単かと思いきや</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → buang だ → <span class='gd-jp'>雨かと思いきや</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>もう帰ったかと思いきや、まだ会社にいた。</span>（Kirain dia sudah pulang, ternyata masih di kantor）</div><div class='gd-ex-line'>・<span class='gd-jp'>高いかと思いきや、意外と安かった。</span>（Kirain mahal, nggak tahunya lumayan murah）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は怒るかと思いきや、笑って許してくれた。</span>（Kirain dia bakal marah, eh ternyata dia malah tersenyum dan memaafkanku）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'>Biasanya muncul dalam tulisan, berita, narasi TV, atau postingan media sosial, yaitu situasi saat kamu \"bercerita\", dengan nuansa kaget atau lucu. Di internet, orang bahkan sering menulis 「〜と思いきや…」 lalu berhenti di situ, sengaja bikin penasaran sampai kalimat berikutnya mengungkap jawabannya.</div><div class='gd-h'>Hati-hati di sini</div><div class='gd-warn'>・Saat menambah か pada kata benda dan kata sifat-な, <b>だ tidak boleh dipertahankan</b>: yang benar <span class='gd-jp'>簡単かと思いきや</span>, bukan 「簡単だかと思いきや」.<br>・「思いきや」adalah satu blok tetap yang <b>tidak bisa diubah bentuknya</b>. Tidak ada bentuk seperti 「思いましたきや」.<br>・Bacanya <b>おもいきや</b>. Jangan tertukar dengan <span class='gd-jp'>思い切り</span> (sekuat tenaga, sepuasnya) dan <span class='gd-jp'>思い切って</span> (memberanikan diri). Tampangnya mirip, tapi artinya sama sekali tidak berhubungan.<br>・Bagian belakang adalah <b>fakta yang sudah terjadi</b>, jadi biasanya pakai bentuk lampau. Tidak boleh diikuti kalimat niat, perintah, atau ajakan: 「雨だと思いきや、傘を持っていこう」 itu salah.<br>・Hasilnya harus <b>berlawanan</b> dengan perkiraan. Kalau hasilnya sama seperti yang kamu duga, pola ini tidak bisa dipakai.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Dalam obrolan sehari-hari, yang lebih sering dipakai adalah <b>と思ったら</b>. Pola ini juga bisa berarti \"kirain ～, ternyata…\". Dalam arti itu, と思ったら bisa menggantikan と思いきや, hanya saja nuansanya lebih lisan:<br><span class='gd-jp'>簡単かと思ったら、意外と難しかった。</span>（Kirain gampang, ternyata di luar dugaan sulit）<br>Tapi と思ったら punya arti lain: <b>「baru saja ～, langsung…」</b>, untuk perubahan yang terjadi cepat berturut-turut. Arti ini tidak dimiliki と思いきや:<br><span class='gd-jp'>子どもは泣いたと思ったら、もう笑っている。</span>（Anak itu baru saja menangis, eh sudah tertawa lagi）<br>Kalau kalimat ini diganti dengan と思いきや, jadinya janggal, karena intinya adalah \"perubahan yang cepat\", bukan \"perkiraan yang meleset\".</div><div class='gd-warn'>Trik cepat: kalau maksudnya \"perkiraan meleset\", keduanya boleh dipakai. Pakai と思いきや untuk tulisan dan と思ったら untuk ngobrol. Kalau maksudnya \"baru saja ～, langsung…\", hanya と思ったら yang bisa dipakai.</div>","n1-31":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜ものを」punya nuansa seperti <b>「Kenapa nggak bilang dari tadi sih!」</b>. Sebenarnya kalau melakukan hal itu semuanya beres, tapi malah tidak dilakukan, dan akhirnya jadi berantakan. Ada perasaan <b>sayang, kesal, dan menyalahkan</b>, kadang ditujukan ke orang lain, kadang ke diri sendiri.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depan pakai bentuk biasa (bentuk kamus, tanpa ます). Yang paling sering adalah menyambungnya setelah 「〜ばいい」 atau 「〜ばよかった」:<br><span class='gd-pair'><span class='gd-jp'>言えばいい</span> → <span class='gd-jp'>言えばいいものを</span></span><br><span class='gd-pair'><span class='gd-jp'>聞けばよかった</span> → <span class='gd-jp'>聞けばよかったものを</span></span><br>Kata sifat-な disambung dengan 「な」: <span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利なものを</span></span>. Tidak ada bentuk 「便利だものを」.</div><div class='gd-h'>Tiga bentuk yang paling sering muncul</div><div class='gd-sec'><span class='gd-tag'>〜ばいいものを</span>Padahal cukup melakukan itu saja, tapi malah tidak dilakukan. Paling sering dipakai untuk menegur orang lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>謝ればすむものを、意地を張るから話がややこしくなる。</span>（Padahal minta maaf saja sudah beres, tapi malah gengsi, makanya urusannya jadi ribet）</div><div class='gd-ex-line'>・<span class='gd-jp'>黙っていればいいものを、余計な一言で彼を怒らせてしまった。</span>（Padahal diam saja sudah aman, eh malah nambah satu kalimat yang bikin dia marah）</div><div class='gd-sec'><span class='gd-tag'>〜ば〜たものを</span>\"Kalau saja ～, pasti sudah ～\", tapi kenyataannya tidak terjadi, jadi terasa sayang.</div><div class='gd-ex-line'>・<span class='gd-jp'>言ってくれれば手伝ったものを。</span>（Kalau kamu bilang dari awal, kan aku pasti bantu）</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少し早く家を出ていれば間に合ったものを。</span>（Kalau saja berangkat sedikit lebih awal, pasti keburu）</div><div class='gd-sec'><span class='gd-tag'>Berhenti di akhir kalimat</span>Bagian \"tapi kamu tidak melakukannya\" langsung ditelan dan tidak diucapkan, hanya tersisa nuansa menghela napas. Kalimat ketiga di atas contohnya, dan bentuk ini sering muncul di drama dan novel Jepang.</div><div class='gd-h'>Hati-hati di sini</div><div class='gd-warn'>・Jangan tertukar dengan 「kata benda もの＋を」: <span class='gd-jp'>おいしいものを食べた</span> memakai もの yang berarti \"makanan/benda\", dan langsung disambung kata kerja. Sedangkan 「〜ものを」biasanya diikuti koma, lalu \"tapi hasilnya malah…\", atau bahkan tidak dilanjutkan sama sekali.<br>・Pola ini membicarakan hal yang <b>sudah terjadi dan tidak bisa diubah</b>, jadi tidak bisa diikuti permintaan atau perintah. Tidak ada kalimat seperti 「早く言えばいいものを、言ってください」.<br>・Nuansanya cenderung tulisan dan agak sastrawi, plus mengandung sindiran. Dalam obrolan sehari-hari orang biasanya bilang 「〜ばよかったのに」. Kalau kamu pakai 「ものを」untuk menegur atasan atau pelanggan, kesannya sangat tidak sopan.<br>・Bagian belakangnya berisi keluhan atau helaan napas, bukan sekadar pernyataan fakta. Karena itu bagian depannya hampir selalu berupa pengandaian \"padahal begitu saja sudah cukup\".</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>のに</b>: artinya paling dekat dan paling sering dipakai dalam percakapan sehari-hari.<br><span class='gd-jp'>早く言えばよかったのに。</span>（Kan tinggal bilang dari tadi）<br><b>ものを</b>: sama-sama keluhan, tapi lebih bersifat tulisan dan emosinya lebih berat.<br><span class='gd-jp'>早く言えばよかったものを。</span>（Padahal tinggal bilang dari tadi, duh）<br>Selain itu, のに juga bisa dipakai untuk menyatakan fakta kontras biasa \"padahal ～ tapi ～\" (<span class='gd-jp'>雨なのに出かけた。</span> Padahal hujan, dia tetap pergi). ものを jarang dipakai seperti itu.</div><div class='gd-sec'><b>ものの</b> (N2): bedanya cuma satu huruf, tapi artinya \"memang ～, tetapi ～\", menyampaikan fakta dengan tenang tanpa menyalahkan siapa pun.<br><span class='gd-jp'>先生に相談しようと思ったものの、言い出せなかった。</span>（Memang aku sempat ingin konsultasi ke guru, tapi tidak berani membuka mulut）<br><span class='gd-jp'>先生に相談すればよかったものを、一人で悩んでいた。</span>（Padahal tinggal konsultasi ke guru, tapi malah pusing sendirian）</div><div class='gd-warn'>Trik cepat: kalau di depannya ada 「〜ばいい／〜ばよかった」 dan terasa ada helaan napas \"tahu begitu…\", itu ものを. Kalau hanya menyatakan \"memang… tetapi…\" secara datar, itu ものの.</div>","n1-43":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜とは」setara dengan <b>「ternyata…」「tak disangka…」</b> dalam bahasa Indonesia. Saat kamu menemui hal yang sama sekali tak terduga, lalu kaget, terharu, bahkan melongo atau kecewa, taruh hal itu di depan とは. Reaksinya mirip waktu kita bilang, 「Hah? Masa dia pelakunya!」</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kaget・Tak terduga</span>Kejadiannya berbeda total dari yang kamu bayangkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな所で君に会うとは。</span>（Tak disangka bisa ketemu kamu di tempat seperti ini）</div><div class='gd-ex-line'>・<span class='gd-jp'>まさか一回で合格するとは思わなかった。</span>（Tak kusangka bisa lulus dalam sekali coba）</div><div class='gd-sec'><span class='gd-tag'>Melongo・Kecewa</span>Bukan sekadar kaget, tapi juga ada rasa tidak puas, seperti 「kok bisa begini sih」.</div><div class='gd-ex-line'>・<span class='gd-jp'>大人がこんな簡単なルールも守れないとは、情けない。</span>（Orang dewasa kok tidak bisa menaati aturan sesederhana ini, memalukan）</div><div class='gd-sec'><span class='gd-tag'>Kalimat menggantung</span>Bagian belakang seperti 「驚いた」「思わなかった」 sering langsung dibuang, sehingga yang tersisa hanya kesan 「ternyata……」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が犯人だったとは……。</span>（Ternyata dia pelakunya……）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya pakai <b>bentuk biasa</b>, yaitu bentuk tanpa です・ます, lalu tambahkan とは.<br>Kata kerja: <span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会うとは</span></span><span class='gd-pair'><span class='gd-jp'>負けた</span> → <span class='gd-jp'>負けたとは</span></span><br>Kata sifat-い: <span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>こんなに高いとは</span></span><br>Kata sifat-な: <span class='gd-pair'><span class='gd-jp'>簡単</span> → <span class='gd-jp'>こんなに簡単だとは</span></span><br>Kata benda: <span class='gd-pair'><span class='gd-jp'>犯人</span> → <span class='gd-jp'>犯人だとは</span></span>. だ-nya kadang dihilangkan, jadi bisa juga <span class='gd-jp'>犯人とは</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Di depannya sering ada <span class='gd-jp'>まさか</span> (sama sekali tak menyangka), dan di belakangnya sering muncul <span class='gd-jp'>思わなかった</span>, <span class='gd-jp'>思いもよらなかった</span>, <span class='gd-jp'>夢にも思わなかった</span>, <span class='gd-jp'>信じられない</span>, atau <span class='gd-jp'>驚きだ</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>自分が日本で働くことになるとは、夢にも思わなかった。</span>（Mimpi pun tidak pernah, ternyata aku akan bekerja di Jepang）</div><div class='gd-h'>Hal yang gampang keliru</div><div class='gd-warn'>・は di とは dibaca 「わ」, jadi seluruhnya dibaca とわ.<br>・Di depannya harus bentuk biasa, tidak boleh bentuk ます. <span class='gd-jp'>会いますとは</span> itu salah.<br>・Untuk hal yang sekadar pengandaian dan belum pasti, とは tidak bisa dipakai (misalnya 「もし合格するとは」 itu salah). Tapi kabar yang belum terjadi namun sudah pasti boleh: <span class='gd-jp'>彼女が来月結婚するとは、驚いた。</span>（Kaget, ternyata dia akan menikah bulan depan）<br>・とは terdengar cukup formal dan lebih cocok untuk tulisan. Waktu ngobrol dengan teman, orang Jepang lebih sering bilang なんて. Memakai とは tetap boleh, tapi kesannya jadi lebih berlebihan dan agak dramatis.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>なんて</b>: artinya sama, 「ternyata」, hanya saja lebih lisan.<br><span class='gd-jp'>こんな所で会うなんて！</span>（Ternyata ketemu di sini! Antarteman）<br><span class='gd-jp'>こんな所でお会いするとは。</span>（Tak disangka bertemu di sini, lebih formal）</div><div class='gd-sec'><b>とは yang berarti 「yang disebut ～」</b>: tulisannya sama-sama とは, tetapi fungsinya mendefinisikan sebuah kata. Setelahnya ada penjelasan atau pertanyaan, dan sama sekali tidak ada rasa kaget.<br><span class='gd-jp'>幸せとは何だろう。</span>（Apa sih yang disebut kebahagiaan?）<br><span class='gd-jp'>彼が幸せだったとは。</span>（Ternyata dia bahagia）</div><div class='gd-sec'><b>と思いきや</b>: 「Awalnya mengira ～, tapi ternyata……」. Di belakangnya kamu harus menyebutkan <b>hasil yang sebenarnya</b>.<br><span class='gd-jp'>晴れると思いきや、雨が降ってきた。</span>（Kukira cuaca akan cerah, ternyata malah turun hujan）<br><span class='gd-jp'>こんなに雨が降るとは。</span>（Tak disangka hujannya sederas ini）</div><div class='gd-warn'>Trik membedakan: kalau di depan とは ada satu peristiwa utuh yang mengagetkanmu dan di belakangnya ada kesan, itu 「ternyata」. Kalau di depannya hanya satu kata benda dan di belakangnya penjelasan tentang kata itu, itu 「yang disebut」. Kalau kamu menulis dugaan awal dulu lalu hasil sebenarnya, itu と思いきや.</div>","n1-47":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ともなると」setara dengan <b>「kalau sudah sampai tahap ～, ya wajar kalau ～」</b>. Saat status sudah naik, usia sudah sampai, atau masa tertentu sudah tiba, keadaannya otomatis berbeda dari biasa. Kalau kita bilang 「Sudah jadi kepala departemen, ya tanggung jawabnya pasti berat」, dalam bahasa Jepang jadinya <span class='gd-jp'>部長ともなると、責任も重くなる。</span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Status・Jabatan</span>Begitu menduduki posisi yang lebih tinggi, kamu akan menghadapi situasi yang sesuai dengan posisi itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>部長ともなると、毎日会議ばかりだ。</span>（Kalau sudah jadi kepala departemen, tiap hari isinya rapat melulu）</div><div class='gd-sec'><span class='gd-tag'>Usia・Tahap</span>Kalau seseorang sudah sampai tahap tertentu, dengan sendirinya ia jadi berbeda.</div><div class='gd-ex-line'>・<span class='gd-jp'>高校生ともなると、親とあまり話さなくなる。</span>（Kalau sudah SMA, jadi jarang ngobrol dengan orang tua）</div><div class='gd-sec'><span class='gd-tag'>Periode</span>Begitu masa khusus tertentu tiba, selalu terjadi hal yang sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>年末ともなると、どこの店も人でいっぱいだ。</span>（Kalau sudah akhir tahun, toko mana pun penuh orang）</div><div class='gd-sec'><span class='gd-tag'>Skala urusan</span>Kalau yang dikerjakan adalah urusan besar dan berbobot, situasi setelahnya ikut membesar.</div><div class='gd-ex-line'>・<span class='gd-jp'>家を建てるともなると、決めることが山ほどある。</span>（Kalau sudah sampai membangun rumah, hal yang harus diputuskan banyak sekali）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda + ともなると: <span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長ともなると</span></span><br>Bentuk kamus kata kerja (bentuk dasar yang kamu temukan di kamus) + ともなると: <span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学するともなると</span></span><br>Yang ditaruh di depan biasanya status, usia, masa, atau urusan yang <b>satu tingkat di atas biasa dan berbobot</b>. Di belakangnya ada keadaan atau penilaian yang <b>memang wajar</b> muncul di tahap itu.</div><div class='gd-h'>Hal yang gampang keliru</div><div class='gd-warn'>・Nuansanya 「sudah sampai tahap seperti ini」. Kalau hanya membicarakan perubahan biasa, seperti 「kalau musim semi tiba, bunga mekar」, <span class='gd-jp'>春になると</span> terdengar lebih natural.<br>・Di belakangnya biasanya keadaan umum atau penilaian, misalnya tanggung jawab berat, sangat ramai, atau banyak yang harus disiapkan. Jarang diikuti niat sendiri seperti 「aku akan ～」 atau permintaan kepada orang lain seperti 「tolong ～」.<br>・「とも」di sini bukan berarti 「juga/semua」, dan sama sekali berbeda dari <span class='gd-jp'>ともなく</span> (tanpa sengaja ～). Jangan dicampuradukkan hanya karena sama-sama ada とも.<br>・Pola ini formal dan lebih cocok untuk tulisan. Waktu ngobrol dengan teman, bilang <span class='gd-jp'>部長になると</span> atau <span class='gd-jp'>部長にもなると</span> terasa lebih santai.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ともなれば</b>: artinya hampir sama, dan dalam kebanyakan kasus bisa saling menggantikan.<br><span class='gd-jp'>部長ともなれば、責任も重くなる。</span>（Kalau sudah jadi kepala departemen, tanggung jawab ya jadi berat）</div><div class='gd-sec'><b>とあって</b>: artinya 「karena sedang menghadapi situasi khusus kali ini, maka di depan mata terjadi ～」. Yang dibicarakan adalah hal yang sudah terlihat dan benar-benar terjadi. Sedangkan <b>ともなると</b> membicarakan kecenderungan umum: 「kalau sudah sampai tahap ini, biasanya selalu ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>連休とあって、高速道路はどこも渋滞している。</span>（Karena sedang libur panjang, jalan tol di mana-mana sekarang macet）</div><div class='gd-ex-line'>・<span class='gd-jp'>連休ともなると、高速道路はどこも渋滞する。</span>（Setiap kali libur panjang tiba, jalan tol di mana-mana macet）</div><div class='gd-warn'>Trik membedakan: kalau maksudnya 「kali ini karena ～, makanya ～」, pakai とあって. Kalau maksudnya 「kalau sudah sampai tahap ～, otomatis selalu ～」, pakai ともなると.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'><span class='gd-jp'>〜たる</span> juga sering muncul bersama status, tetapi maksudnya 「karena berstatus ini, seharusnya bersikap seperti ini」: <span class='gd-jp'>教師たる者、生徒の手本でなければならない。</span>（Sebagai guru, harus menjadi teladan bagi murid）. ともなると membicarakan <b>akibat yang alami</b> dari sebuah status, sedangkan たる membicarakan <b>sikap yang semestinya</b> dari status itu. Ingat keduanya sambil dibandingkan ya.</div>","n1-67":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜をよそに」artinya kurang lebih <b>「tidak menghiraukan ～」「cuek terhadap ～」</b>. <span class='gd-jp'>よそ</span> berarti 「rumah orang lain, tempat lain」. Jadi <span class='gd-jp'>〜をよそに</span> memperlakukan kekhawatiran atau penolakan orang lain, atau situasi di sekitar, sebagai <b>urusan orang lain</b>, lalu tetap berjalan dengan caranya sendiri.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Tidak peduli perasaan orang lain</span>Ini pemakaian yang paling umum. Di depan, taruh kekhawatiran, penolakan, harapan, atau kritik orang lain. Di belakang, ceritakan bahwa tokohnya tetap melakukan urusannya sendiri. Sering ada nuansa 「kok gitu sih」, tapi tidak selalu menyindir. Bisa juga hanya deskripsi yang netral.</div><div class='gd-ex-line'>・<span class='gd-jp'>親の心配をよそに、息子は毎晩遅くまで遊んでいる。</span>（Orang tuanya sudah begitu khawatir, tapi anaknya tetap main sampai larut setiap malam）</div><div class='gd-ex-line'>・<span class='gd-jp'>周囲の反対をよそに、彼女は会社を辞めて留学した。</span>（Tidak menghiraukan penolakan orang-orang di sekitarnya, dia keluar dari pekerjaan dan pergi kuliah ke luar negeri）</div><div class='gd-sec'><span class='gd-tag'>Tidak terpengaruh situasi sekitar</span>Di depan, taruh situasi yang 「seharusnya berpengaruh」, seperti kondisi ekonomi atau kehebohan di masyarakat. Di belakang, ceritakan bahwa tokohnya sama sekali tidak terpengaruh.</div><div class='gd-ex-line'>・<span class='gd-jp'>不景気をよそに、この店はいつも行列ができている。</span>（Ekonomi lagi lesu, tapi toko ini tetap saja selalu antre panjang）</div><div class='gd-ex-line'>・<span class='gd-jp'>世間の騒ぎをよそに、本人はのんびり旅行を楽しんでいた。</span>（Di luar sana heboh, tapi orangnya sendiri santai menikmati liburan）</div><div class='gd-h'>Cara menyambungkan</div><div class='gd-sec'>Langsung disambung ke <b>kata benda</b>: kata benda＋をよそに<br><span class='gd-pair'><span class='gd-jp'>家族の心配</span> → <span class='gd-jp'>家族の心配をよそに</span></span><span class='gd-pair'><span class='gd-jp'>ファンの期待</span> → <span class='gd-jp'>ファンの期待をよそに</span></span><br>Kata benda yang paling sering dipasangkan: <span class='gd-jp'>心配</span>、<span class='gd-jp'>反対</span>、<span class='gd-jp'>期待</span>、<span class='gd-jp'>批判</span>、<span class='gd-jp'>不安</span>、<span class='gd-jp'>騒ぎ</span>.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di depan harus kata benda. Jangan tulis 「心配するをよそに」. Ubah dulu jadi kata benda <span class='gd-jp'>心配</span>.<br>・Yang ditaruh di depan adalah <b>reaksi orang lain atau situasi di sekitar</b>, bukan hal yang seharusnya kamu kerjakan sendiri. Untuk 「tidak mengerjakan PR malah pergi main」, jangan bilang 「宿題をよそに」. Lebih alami pakai <span class='gd-jp'>宿題そっちのけで遊ぶ</span>.<br>・Biasanya dipakai untuk menggambarkan perilaku <b>orang lain</b>. Ini ungkapan tulis yang sering muncul di berita dan artikel, jarang dipakai saat ngobrol dengan teman.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>をものともせず</b>＝tidak menganggap <b>kesulitan atau bahaya</b> sebagai penghalang, dan ada nuansa pujian:<br><span class='gd-jp'>けがをものともせず、彼は最後まで走った。</span>（Tidak menghiraukan cederanya, dia berlari sampai akhir: kita kagum padanya）<br><b>をよそに</b>＝tidak peduli pada <b>perasaan orang lain atau situasi sekitar</b>, lalu berbuat sesuai kemauan sendiri:<br><span class='gd-jp'>家族の心配をよそに、彼は最後まで走った。</span>（Keluarganya sudah begitu khawatir, tapi dia tetap berlari sampai akhir: yang ditekankan adalah dia tidak menggubris keluarganya）</div><div class='gd-sec'><b>にもかかわらず</b>＝sekadar 「meskipun ～, tetapi ～」:<br><span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（Meskipun hujan, tetap banyak orang yang datang）<br>Kalimat ini hanya menyatakan fakta 「meskipun hujan, tetap banyak orang yang datang」, jadi にもかかわらず paling alami. Inti をよそに adalah 「tokohnya menganggap enteng hal yang seharusnya dia pedulikan atau yang seharusnya memengaruhi dia, dan tetap berjalan dengan caranya sendiri」. Karena itu ungkapan ini sering dipakai untuk kekhawatiran atau penolakan orang lain, atau situasi sekitar seperti kondisi ekonomi yang seharusnya berdampak.</div><div class='gd-warn'>Tips menentukan: kalau mengatasi kesulitan dan pantas dikagumi, pakai をものともせず. Kalau tidak peduli pendapat orang lain dan tidak terpengaruh sekitar, pakai をよそに. Kalau hanya 「meskipun ～ tetapi」 yang biasa, pakai にもかかわらず.</div>","n1-70":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ずにはおかない」artinya kurang lebih <b>「pasti membuat orang ～」「tidak akan berhenti sebelum ～」</b>. Ada dua pemakaian. Pertama, sesuatu punya kekuatan begitu besar sehingga <b>pasti</b> membuat orang merasakan sesuatu. Kedua, seseorang sudah bertekad dan <b>tidak akan berhenti sebelum tercapai</b>. Ini ungkapan N1 yang kaku, biasanya muncul di resensi film, resensi buku, berita, dan novel.</div><div class='gd-sec'>Kalau diuraikan, lebih mudah diingat: <span class='gd-jp'>おく</span> berarti 「membiarkan begitu saja」. 「Tidak akan membiarkan begitu saja tanpa melakukan ～」, artinya 「pasti melakukan ～」.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sesuatu pasti memicu reaksi</span>Ini pemakaian yang paling umum. Subjeknya film, karya, satu kalimat, atau suatu peristiwa, dan kamu mengatakan bahwa hal itu <b>pasti</b> membuat orang terharu, terkejut, atau berpikir.<br>Orang yang terpengaruh ditandai dengan <b>を</b> atau <b>に</b> (<span class='gd-jp'>人を～させる</span>／<span class='gd-jp'>人に～させる</span>), jadi kata kerjanya biasanya <b>bentuk kausatif</b>, yaitu bentuk 「membuat seseorang ～」: <span class='gd-pair'><span class='gd-jp'>感動する</span> → <span class='gd-jp'>感動させる</span></span>（membuat orang terharu）.</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画は、観客を感動させずにはおかない。</span>（Film ini pasti membuat penontonnya terharu）</div><div class='gd-ex-line'>・<span class='gd-jp'>この小説の結末は、読者を驚かせずにはおかないだろう。</span>（Akhir novel ini pasti akan membuat pembacanya terkejut）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の言葉は、聞く人の心を動かさずにはおかない。</span>（Kata-katanya pasti menggerakkan hati orang yang mendengarnya）</div><div class='gd-sec'><span class='gd-tag'>Tidak berhenti sebelum tercapai</span>Subjeknya orang. Ini menunjukkan tekad yang kuat, dengan semangat keras kepala 「aku pasti akan membuatnya terjadi」.</div><div class='gd-ex-line'>・<span class='gd-jp'>今度こそ、真相を明らかにせずにはおかない。</span>（Kali ini aku tidak akan berhenti sebelum kebenarannya terungkap）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんな失礼なことを言われたんだ。必ず謝らせずにはおかない。</span>（Aku sudah dikatai sekasar itu. Aku pasti akan membuatnya minta maaf）</div><div class='gd-h'>Cara menyambungkan</div><div class='gd-sec'>Ubah kata kerja ke bentuk ない dulu, lalu <b>buang ない</b> dan tambahkan <b>ずにはおかない</b>.<br><span class='gd-pair'><span class='gd-jp'>感動させる</span> → <span class='gd-jp'>感動させない</span> → <span class='gd-jp'>感動させずにはおかない</span></span><br><span class='gd-pair'><span class='gd-jp'>動かす</span> → <span class='gd-jp'>動かさない</span> → <span class='gd-jp'>動かさずにはおかない</span></span><br>Kelompok ketiga perlu diingat khusus: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはおかない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはおかない</span>（こず）</span></div><div class='gd-sec'>Ada cara tulis lain: bentuk ない <b>langsung</b> ditambah <b>ではおかない</b>. ない tidak perlu dibuang, artinya sama:<br><span class='gd-pair'><span class='gd-jp'>感動させない</span> → <span class='gd-jp'>感動させないではおかない</span></span><br>「ずには」lebih sering dipakai dan lebih bernuansa tulisan.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・する harus berubah jadi <b>せず</b>, bukan しず: <span class='gd-jp'>明らかにせずにはおかない</span>.<br>・Pada pemakaian pertama, orang yang terpengaruh adalah objek yang ditandai を／に, bukan subjek. <span class='gd-jp'>観客は感動せずにはおかない</span> itu salah. Untuk bilang 「film membuat penonton terharu」, pakai <span class='gd-jp'>映画は観客を感動させずにはおかない</span>.<br>・Nadanya sangat berat dan seperti bahasa tulis. Dalam obrolan sehari-hari, untuk bilang 「pasti bikin nangis」 cukup <span class='gd-jp'>絶対泣けるよ</span>. Kalau pakai ずにはおかない, kedengarannya seperti sedang membacakan naskah resensi.<br>・Pemakaian kedua menunjukkan tekad 「akan kulakukan walau harus mati-matian」. Jangan dipakai untuk hal sepele seperti 「menghabiskan semangkuk ramen ini」.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ずにはいられない</b>（N2）＝<b>orangnya sendiri tidak tahan</b>: <span class='gd-jp'>この映画を見て、泣かずにはいられなかった。</span>（Setelah menonton film ini, aku tidak bisa menahan tangis）<br><b>ずにはおかない</b>＝<b>sesuatu pasti membuat orang</b> begitu: <span class='gd-jp'>この映画は、見る人を泣かせずにはおかない。</span>（Film ini pasti membuat orang yang menontonnya menangis）</div><div class='gd-sec'><b>ずにはすまない</b>（n1-71）＝menurut logika atau keadaan, <b>kalau tidak dilakukan rasanya tidak pantas</b>: <span class='gd-jp'>失礼なことを言ってしまったから、謝らずにはすまない。</span>（Aku sudah mengatakan hal yang tidak sopan, jadi tidak pantas kalau tidak minta maaf）<br><b>ずにはおかない</b>＝aku <b>harus membuatnya terjadi</b>: <span class='gd-jp'>失礼なことを言われたから、謝らせずにはおかない。</span>（Aku dikatai hal yang tidak sopan, jadi aku pasti akan membuatnya minta maaf）</div><div class='gd-warn'>Tips menentukan: 「tidak tahan sendiri」 itu ずにはいられない. 「Sesuatu pasti membuat orang ～」 atau 「aku harus melakukannya」 itu ずにはおかない. 「Tidak pantas kalau tidak dilakukan」 itu ずにはすまない.</div><div class='gd-h'>Setelah ini belajar apa</div><div class='gd-sec'>Lanjut ke <span class='gd-jp'>〜ずにはすまない・ないではすまない</span>（n1-71）. Keduanya sering keluar bersamaan di ujian, jadi paling jelas kalau dipelajari sambil dibandingkan.</div>","n1-72":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜を余儀なくされる」artinya <b>「terpaksa ~」</b>, ungkapan yang sering muncul di berita. Misalnya 「Karena terkena topan, acara terpaksa dibatalkan」. Itu bukan keinginan sendiri, tapi <b>keadaan atau situasi besar yang membuatmu tidak punya pilihan lain</b>. <span class='gd-jp'>余儀</span> artinya 「cara lain」, jadi <span class='gd-jp'>余儀ない</span> artinya 「tidak ada cara lain」.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Berita・laporan</span>Untuk peristiwa besar seperti bencana alam, pandemi, atau ekonomi, yang membuat seseorang atau suatu pihak akhirnya terpaksa melakukan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>大雨で、試合は中止を余儀なくされた。</span>(Karena hujan deras, pertandingan terpaksa dibatalkan)</div><div class='gd-ex-line'>・<span class='gd-jp'>地震で、多くの住民が避難生活を余儀なくされている。</span>(Karena gempa, banyak warga terpaksa hidup di pengungsian)</div><div class='gd-sec'><span class='gd-tag'>Menceritakan pengalaman sendiri di situasi formal</span>Dipakai juga saat menulis laporan atau menjelaskan riwayat kerja di wawancara.</div><div class='gd-ex-line'>・<span class='gd-jp'>会社の倒産で、退職を余儀なくされました。</span>(Karena perusahaan bangkrut, saya terpaksa berhenti bekerja)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya ada <b>kata benda</b>, khususnya kata benda yang menyatakan 「suatu tindakan」. Yang paling umum adalah <span class='gd-jp'>中止</span>、<span class='gd-jp'>延期</span>、<span class='gd-jp'>変更</span>、<span class='gd-jp'>撤退</span>、<span class='gd-jp'>入院</span>、<span class='gd-jp'>移転</span>, yaitu kata yang bisa ditambah する.<br>Kalau yang kamu pegang adalah kata kerja, buang する dan sisakan kata bendanya: <span class='gd-pair'><span class='gd-jp'>延期する</span> → <span class='gd-jp'>延期を余儀なくされた</span></span><br>Subjek kalimat (yang ada di depan は／が) adalah <b>pihak yang terdampak dan dipaksa keadaan</b>: pertandingan, toko lama, warga, aku.</div><div class='gd-h'>Bentuk yang paling sering muncul</div><div class='gd-sec'><span class='gd-tag'>余儀なくされた</span>Untuk hal yang sudah terjadi. Ini yang paling umum.<br><span class='gd-tag'>余儀なくされている</span>Sekarang masih terus terpaksa begitu, seperti hidup di pengungsian pada contoh di atas.<br><span class='gd-tag'>余儀なくさせる</span>Kebalikannya: dilihat dari sisi 「penyebab」, dan subjeknya sering berupa peristiwa itu sendiri:</div><div class='gd-ex-line'>・<span class='gd-jp'>円安が、計画の見直しを余儀なくさせた。</span>(Melemahnya yen memaksa rencana ditinjau ulang)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Bacanya <b>よぎなく</b>, bukan よぎむなく.<br>・Di depannya tidak boleh langsung kata kerja: katakan <span class='gd-jp'>中止を余儀なくされた</span>, bukan 「中止するを余儀なくされた」.<br>・Tidak bisa dipakai untuk hal yang kamu pilih sendiri atau kamu inginkan. Kalau kamu ganti pekerjaan karena ingin mencoba hal baru, itu bukan 「terpaksa」.<br>・Nadanya berat dan sangat formal, jadi kalau dipakai untuk hal sepele akan terdengar berlebihan. 「宿題を余儀なくされた」 terdengar seperti bercanda.<br>・Dalam bahasa Indonesia ada 「terpaksa」 dan 「dipaksa」, dan banyak orang langsung memakai させられる. Padahal maknanya beda, lihat di bawah.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama soal 「berhenti kerja」:<br><b>を余儀なくされる</b> = dipaksa oleh <b>keadaan</b>. Tidak ada orang tertentu yang memaksamu. Formal dan cenderung bahasa tulis:<br><span class='gd-jp'>会社の倒産で、退職を余儀なくされた。</span>(Karena perusahaan bangkrut, terpaksa berhenti kerja)<br><b>させられる</b> = <b>seseorang</b> memaksamu melakukannya, sering dengan nuansa tidak rela, dan sering dipakai juga dalam percakapan:<br><span class='gd-jp'>上司に無理やり退職させられた。</span>(Dipaksa atasan untuk berhenti kerja)<br><b>ざるを得ない</b> = <b>kamu sendiri</b> menimbang lalu merasa tidak ada pilihan lain. Intinya ada pada penilaianmu sendiri:<br><span class='gd-jp'>体調が悪くて、退職せざるを得なかった。</span>(Kondisi tubuhku buruk, jadi aku terpaksa berhenti kerja)</div><div class='gd-warn'>Trik menentukan: kalau ada seorang 「orang」 yang memaksamu, pakai させられる. Kalau kamu berpikir dulu lalu terpaksa melakukannya, pakai ざるを得ない. Kalau situasi besar seperti bencana, resesi, atau keadaan zaman yang membuatmu tak punya jalan lain, dan konteksnya formal, pakai を余儀なくされる.</div>","n1-77":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜んばかりに」artinya <b>「seolah-olah mau ~」「hampir saja ~」</b>. Ini cara melebih-lebihkan untuk menggambarkan seberapa jauh suatu keadaan: ia <b>nyaris</b> melakukan tindakan itu, tapi biasanya <b>belum benar-benar melakukannya</b>. Seperti kalau kamu bilang 「dia panik sampai hampir menangis」, yang digambarkan adalah seberapa paniknya, bukan bahwa dia sungguh menangis.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ない, buang 「ない」, lalu tambahkan 「んばかり」.<br><span class='gd-pair'><span class='gd-jp'>泣く</span> → <span class='gd-jp'>泣かない</span> → <span class='gd-jp'>泣かんばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わない</span> → <span class='gd-jp'>言わんばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>あふれる</span> → <span class='gd-jp'>あふれない</span> → <span class='gd-jp'>あふれんばかり</span></span><br><b>する adalah pengecualian</b>: bukan しんばかり, tapi pakai bentuk klasik <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんばかり</span></span></div><div class='gd-h'>Bentuk yang paling sering muncul</div><div class='gd-sec'><span class='gd-tag'>んばかりに＋tindakan</span>Menggambarkan 「bagaimana」 suatu tindakan dilakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は泣かんばかりに頼んできた。</span>(Dia memohon kepadaku seolah-olah mau menangis)</div><div class='gd-ex-line'>・<span class='gd-jp'>犬が飛びつかんばかりに喜んで走ってきた。</span>(Anjing itu berlari ke arahku dengan gembira, seolah mau menerkam)</div><div class='gd-sec'><span class='gd-tag'>んばかりの＋kata benda</span>Langsung menerangkan kata benda di belakangnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>会場は割れんばかりの拍手に包まれた。</span>(Seluruh aula dipenuhi tepuk tangan yang menggelegar)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は「お前のせいだ」と言わんばかりの顔で私を見た。</span>(Dia menatapku dengan wajah seakan-akan berkata 「Ini salahmu」)</div><div class='gd-sec'><span class='gd-tag'>んばかりだ</span>Diletakkan di akhir kalimat.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の喜びようは、今にも踊り出さんばかりだった。</span>(Dia begitu gembira, seolah-olah sebentar lagi akan menari)</div><div class='gd-sec'>Di antaranya, <span class='gd-jp'>言わんばかり</span>、<span class='gd-jp'>割れんばかり</span>、<span class='gd-jp'>あふれんばかり</span>、<span class='gd-jp'>泣かんばかり</span> muncul sangat sering, jadi hafalkan sebagai satu paket. Secara keseluruhan nuansanya cenderung bahasa tulis dan novel, tapi 「<span class='gd-jp'>〜と言わんばかりの顔</span>」 sering juga terdengar dalam obrolan sehari-hari.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・「ん」di sini <b>bukan berarti 「tidak」</b>. <span class='gd-jp'>泣かん</span> memang mirip 「tidak menangis」 dalam dialek Kansai, tapi dalam pola tata bahasa ini ん adalah ん klasik yang berarti 「hampir akan ~」. <span class='gd-jp'>泣かんばかり</span> artinya 「hampir menangis」, bukan 「tidak menangis」.<br>・する berubah menjadi <b>せんばかり</b>. Menulis しんばかり itu salah.<br>・Ini gambaran yang dilebih-lebihkan, dipakai untuk menggambarkan <b>keadaan atau tingkat</b>. Kalau hanya mau bilang 「kelihatannya mau menangis」, dalam percakapan sehari-hari cukup pakai <span class='gd-jp'>泣きそうな顔</span>. Memakai <span class='gd-jp'>泣かんばかり</span> akan terdengar dramatis.<br>・Biasanya artinya 「nyaris」, bukan benar-benar terjadi. <span class='gd-jp'>あふれんばかり</span> artinya 「penuh sampai hampir meluap」, airnya belum benar-benar meluap.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Di depan <b>とばかりに</b> ada sebuah 「ucapan」, artinya 「dengan sikap seolah-olah berkata ~」. Maknanya hampir sama dengan <span class='gd-jp'>と言わんばかりに</span>:</div><div class='gd-ex-line'>・<span class='gd-jp'>店長は「早く帰れ」と言わんばかりに時計を見た。</span>(Manajer toko melirik jam seakan-akan berkata 「Cepat pulang」)</div><div class='gd-ex-line'>・<span class='gd-jp'>店長は「早く帰れ」とばかりに時計を見た。</span>(Sama seperti di atas)</div><div class='gd-sec'>Bedanya ada pada apa yang boleh ditaruh di depannya. Di depan <b>んばかりに</b> ada <b>tindakan yang nyaris dilakukan</b>, seperti menangis, meluap, atau melompat. Di depan <b>とばかりに</b> ada <b>kata-kata di dalam hati</b>. Jadi 「seolah-olah mau menangis」 hanya bisa <span class='gd-jp'>泣かんばかりに</span>, tidak bisa 泣くとばかりに.</div><div class='gd-warn'>Trik menentukan: kalau di depannya 「satu kalimat ucapan」, とばかりに atau と言わんばかりに sama-sama bisa. Kalau di depannya 「tindakan yang nyaris dilakukan」, hanya bisa bentuk ない + んばかりに.</div>","n1-89":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>Tata bahasa ini kurang lebih sama dengan <b>“tanpa ～ langsung ～”</b> dalam bahasa Indonesia, dan ada dua cara pakainya:<br><span class='gd-jp'>なしに</span>：“pergi <b>tanpa</b> pamit”. Ini menggambarkan seseorang <b>langsung melakukan sesuatu tanpa melakukan hal yang seharusnya dilakukan dulu</b>.<br><span class='gd-jp'>なしには</span>：“tanpa kamu, <b>mustahil</b> berhasil”. Artinya <b>kalau A tidak ada, B sama sekali tidak bisa terjadi</b>.<br>Bedanya cuma satu 「は」, tapi cara pakainya jauh berbeda.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>なしに</span>Sesuatu yang seharusnya ada ternyata tidak ada, tapi tetap langsung dilakukan. Sering terselip rasa kurang puas, seperti “kok begitu sih”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は連絡なしに会社を休んだ。</span>（Dia tidak masuk kerja tanpa kabar sama sekali）</div><div class='gd-ex-line'>・<span class='gd-jp'>断りなしに、人の物を使ってはいけない。</span>（Tanpa izin, kamu tidak boleh memakai barang orang lain）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一言の断りもなしに帰ってしまった。</span>（Dia pulang begitu saja, pamit sepatah kata pun tidak）</div><div class='gd-sec'>Kalau disisipi 「も」 jadi <span class='gd-jp'>もなしに</span>, nuansanya lebih kuat, seperti “bahkan ～ pun tidak ada”.</div><div class='gd-sec'><span class='gd-tag'>なしには</span>A adalah syarat yang tidak boleh kurang. Tanpa A, B tidak mungkin terjadi.</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画は、涙なしには見られない。</span>（Film ini pasti bikin menangis; mustahil menontonnya tanpa air mata）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの協力なしには、成功できなかった。</span>（Tanpa bantuan kalian semua, saya tidak mungkin berhasil）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの協力なしには、成功しなかったでしょう。</span>（Kalau tidak ada bantuan kalian semua, sepertinya tidak akan berhasil）</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'><b>Nomina</b> langsung disambung:<span class='gd-pair'><span class='gd-jp'>許可</span> → <span class='gd-jp'>許可なしに</span></span><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力なしには</span></span><br><b>Verba</b> harus ditambah 「こと」 dulu, jadi 「bentuk kamus＋ことなしに（は）」. Ini lebih bersifat bahasa tulis:</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は休むことなしに働き続けた。</span>（Dia terus bekerja tanpa istirahat sedikit pun）</div><div class='gd-ex-line'>・<span class='gd-jp'>努力することなしには、夢はかなわない。</span>（Kalau tidak berusaha, mimpi tidak akan terwujud）</div><div class='gd-sec'><b>Bagian belakang なしには pasti negatif</b>. Yang umum adalah <span class='gd-jp'>〜できない</span>, <span class='gd-jp'>〜られない</span>, <span class='gd-jp'>〜ありえない</span>, tapi bisa juga <span class='gd-jp'>〜ない</span> atau <span class='gd-jp'>〜なかった（でしょう）</span>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Setelah なしに belum tentu negatif</b>: <span class='gd-jp'>連絡なしに休んだ</span> adalah kalimat afirmatif. Yang wajib negatif di belakangnya hanya <b>なしには</b>.<br>・Setelah なしには tidak boleh ada kalimat afirmatif: ×<span class='gd-jp'>協力なしには成功した</span>, maknanya jadi tidak nyambung.<br>・Verba tidak bisa disambung langsung: ×<span class='gd-jp'>連絡しなしに</span>. Tulis <span class='gd-jp'>連絡なしに</span> (pakai nomina), atau <span class='gd-jp'>連絡することなしに</span>.<br>・Ini ragam yang cukup formal dan tulis. Dalam percakapan sehari-hari biasanya dipakai <b>なしで</b>: <span class='gd-jp'>予約なしで入れますか。</span>（Boleh masuk tanpa reservasi?）</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama membahas “tanpa reservasi”:<br><span class='gd-jp'>予約なしに店に入った。</span>（Masuk toko tanpa reservasi: menjelaskan <b>bagaimana</b> dia melakukannya）<br><span class='gd-jp'>予約なしには入れない。</span>（Tanpa reservasi tidak bisa masuk: bicara soal <b>syarat yang diperlukan</b>）</div><div class='gd-sec'><b>なくして（は）</b>：Maknanya hampir sama dengan なしには, tapi lebih kaku dan sering dipakai dalam pidato atau tulisan.<br><span class='gd-jp'>皆さんの協力なくしては、成功はありえなかった。</span>（Tanpa bantuan hadirin sekalian, keberhasilan itu mustahil）</div><div class='gd-sec'><b>あっての</b>：Hal yang sama dilihat dari arah sebaliknya, yaitu “ada A, baru ada B”.<br><span class='gd-jp'>お客様あっての店だ。</span>（Ada pelanggan, baru ada toko ini）<br>＝<span class='gd-jp'>お客様なしには、店は成り立たない。</span>（Tanpa pelanggan, toko tidak bisa bertahan）</div><div class='gd-warn'>Trik memilih: “melakukan sesuatu tanpa ～” pakai なしに; “tanpa ～ mustahil” pakai なしには (belakangnya pasti negatif); mau lebih formal, ganti jadi なくしては; mau menyampaikan dari sudut “ada A baru ada B”, pakai あっての.</div>","n1-91":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜に足る」 kurang lebih sama dengan <b>“layak ～” atau “pantas ～”</b>. Artinya orang atau hal ini <b>cukup memenuhi syarat</b> untuk dipercaya, dihormati, atau memuaskan. Kebalikannya, 「〜に足りない」, mirip <b>“tidak perlu ditakuti” atau “tidak layak disebut”</b>, yaitu tidak berharga atau tidak perlu dipikirkan. 「足る」 dibaca <b>たる</b>. Ini ragam tulis yang kaku, sering muncul di berita, ulasan, dan novel.</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'><b>Verba bentuk kamus＋に足る</b>：<span class='gd-pair'><span class='gd-jp'>信頼する</span> → <span class='gd-jp'>信頼するに足る</span></span><span class='gd-pair'><span class='gd-jp'>満足する</span> → <span class='gd-jp'>満足するに足る</span></span><br><b>Untuk verba 「〜する」, buang する dan sambungkan nomina di depannya langsung</b>：<span class='gd-pair'><span class='gd-jp'>信頼</span> → <span class='gd-jp'>信頼に足る</span></span><span class='gd-pair'><span class='gd-jp'>尊敬</span> → <span class='gd-jp'>尊敬に足る</span></span><br>Paling sering diletakkan sebelum nomina sebagai penjelas, seperti 「<span class='gd-jp'>信頼に足る人物</span>」, tapi bisa juga di akhir kalimat sebagai kesimpulan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>に足る</span>Dipakai untuk menilai secara formal bahwa seseorang, data, alasan, atau hasil itu “layak dan memenuhi standar”. Sering berpasangan dengan verba penilaian seperti <span class='gd-jp'>信頼する・尊敬する・満足する・納得する・信じる</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は尊敬に足る先輩だ。</span>（Dia senior yang pantas dihormati）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の説明は、納得するに足るものだった。</span>（Penjelasannya cukup untuk meyakinkan orang）</div><div class='gd-ex-line'>・<span class='gd-jp'>この報告書には、信頼に足るデータがない。</span>（Laporan ini tidak punya data yang bisa dipercaya）</div><div class='gd-sec'><span class='gd-tag'>に足りない</span>Dipakai untuk bilang bahwa sesuatu sama sekali tidak penting atau tidak perlu ditakuti. Kebanyakan muncul dalam ungkapan tetap, dan <span class='gd-jp'>に足らない</span> juga sering dipakai dengan arti yang sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなのは取るに足りない問題だ。</span>（Itu cuma masalah sepele yang tidak layak disebut）</div><div class='gd-ex-line'>・<span class='gd-jp'>相手は新人ばかりだ。恐れるに足りない。</span>（Lawannya cuma pemula semua, tidak perlu ditakuti）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<span class='gd-jp'>取るに足りない</span> bukan “tidak cukup untuk diambil”, tapi satu paket ungkapan yang harus dihafal, artinya “remeh, tidak berarti”. Ini beda dengan “kurang” dalam <span class='gd-jp'>お金が足りない</span> (uang tidak cukup).<br>・Yang boleh ada di depannya hanya <b>bentuk kamus</b> atau “nomina dari verba する”, bukan bentuk た atau ます: <span class='gd-jp'>信頼したに足る</span> itu salah. Nomina biasa juga tidak bisa sembarangan, misalnya <span class='gd-jp'>彼に足る</span> tidak masuk akal.<br>・Bentuk negatif <span class='gd-jp'>に足りない</span> terutama dipakai dalam ungkapan tetap seperti <span class='gd-jp'>取るに足りない</span> dan <span class='gd-jp'>恐れるに足りない</span>. Untuk bilang “tidak bisa dipercaya” secara umum, <span class='gd-jp'>信頼できない</span> atau <span class='gd-jp'>信頼に値しない</span> terdengar lebih alami.<br>・Ini bahasa tulis. Kalau ngobrol dengan teman dan mau bilang “orang itu bisa diandalkan”, cukup pakai <span class='gd-jp'>あの人は信頼できる</span>. Kalau pakai に足る, kedengarannya seperti membaca surat dinas.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama menilai sebuah buku:<br><b>に足る</b>＝layak, memenuhi standar: <span class='gd-jp'>これは読むに足る本だ。</span>（Ini buku yang layak dibaca）<br><b>に値する</b>＝punya nilai tertentu. Maknanya sangat dekat, dan sering bisa saling menggantikan. Bedanya, bentuk negatifnya <span class='gd-jp'>に値しない</span> bebas dipakai: <span class='gd-jp'>この本は一読に値しない。</span>（Buku ini tidak layak dibaca sekali pun）<br><b>に堪えない</b>（n1-36）＝begitu buruk sampai <b>tidak tahan</b>, dengan emosi yang kuat: <span class='gd-jp'>読むに堪えない文章だ。</span>（Tulisan yang tidak tahan untuk dibaca）<br>Jadi 「<span class='gd-jp'>取るに足りない</span>」 artinya “tidak penting, tidak perlu dipikirkan”, sedangkan 「<span class='gd-jp'>見るに堪えない</span>」 artinya “terlalu buruk, tidak tahan melihatnya”. Arahnya benar-benar berbeda.</div><div class='gd-warn'>Trik memilih: “layak ～ / tidak layak disebut” pakai に足る・に足りない; kalau mau bebas bilang “tidak layak ～” pakai に値しない; “buruk sampai tidak tahan” pakai に堪えない.</div>","n1-93":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜たが最後」kira-kira berarti <b>\"begitu sudah ~, tamat sudah\"</b> atau <b>\"sekali kena, tidak bisa balik lagi\"</b>. Kalau kamu sudah melakukan hal di depannya, hasilnya pasti buruk, tidak bisa ditarik kembali, dan tidak bisa dihentikan. Rasanya seperti \"keripik kentang kalau sudah dibuka, pasti habis sebungkus\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk た (bentuk lampau「〜た」), lalu langsung tambahkan「が最後」.<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったが最後</span></span><br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝た</span> → <span class='gd-jp'>寝たが最後</span></span><br><span class='gd-pair'><span class='gd-jp'>見つかる</span> → <span class='gd-jp'>見つかった</span> → <span class='gd-jp'>見つかったが最後</span></span><br>「最後」dibaca <b>さいご</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kebiasaan seseorang</span>Kalau seseorang sudah melakukan hal tertentu, hasilnya pasti begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一度寝たが最後、朝まで何をしても起きない。</span>(Kalau dia sudah tertidur, tamat sudah. Sampai pagi dibangunkan dengan cara apa pun tidak akan bangun)</div><div class='gd-sec'><span class='gd-tag'>Tidak bisa berhenti</span>Sekali mulai, tidak bisa dihentikan.</div><div class='gd-ex-line'>・<span class='gd-jp'>このドラマは見始めたが最後、止まらなくなる。</span>(Drama ini begitu mulai ditonton, langsung tidak bisa berhenti)</div><div class='gd-sec'><span class='gd-tag'>Peringatan akibat</span>Mengingatkan \"jangan sampai begitu, nanti nasibmu buruk\".</div><div class='gd-ex-line'>・<span class='gd-jp'>部長に見つかったが最後、一時間は説教される。</span>(Kalau ketahuan kepala bagian, tamat sudah. Minimal kamu diceramahi satu jam)</div><div class='gd-sec'>Dalam percakapan, bentuk ini sering diganti <b>「〜たら最後」</b>. Artinya sama, tapi nuansanya lebih lisan:</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなこと言ったら最後、絶交されるよ。</span>(Kalau kata-kata seperti itu sudah terucap, tamat sudah. Kamu bakal diputus pertemanan lho)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di belakangnya <b>hanya boleh hasil yang buruk</b>. Hal baik seperti \"begitu menang lotre, hidupnya langsung enak\" tidak bisa pakai が最後.<br>・Bagian depannya selalu bentuk た, bahkan untuk hal yang belum terjadi. Kamu tidak bisa bilang「食べるが最後」.<br>・「最後」di sini bukan \"terakhir\" atau \"akhirnya\" seperti biasa, tapi berarti \"habis perkara, tamat\". Jangan diterjemahkan \"setelah makan, pada akhirnya ...\".<br>・Di belakangnya biasanya ada deskripsi atau penilaian \"pasti jadi begini\". Jarang diikuti permintaan \"tolong ~\" atau tekad \"aku akan ~\".<br>・Sering muncul bersama ungkapan \"tidak bisa balik lagi\" seperti <span class='gd-jp'>二度と〜ない</span>, <span class='gd-jp'>止まらない</span>, dan <span class='gd-jp'>終わりだ</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>〜が早いか</b>: Sering juga diterjemahkan \"begitu ~ langsung\", tapi hanya menyatakan <b>waktunya sangat cepat</b>, entah hasilnya baik atau buruk.<br>・<span class='gd-jp'>彼は布団に入るが早いか、眠ってしまった。</span>(Begitu masuk ke futon, dia langsung tertidur)<br>・<span class='gd-jp'>彼は布団に入ったが最後、昼まで出てこない。</span>(Kalau dia sudah masuk futon, tamat sudah. Sampai siang tidak akan keluar)<br>Kalimat pertama soal \"kecepatan\", kalimat kedua soal \"setelah itu tidak bisa ditarik kembali\".</div><div class='gd-sec'><b>〜たところで</b>: Sama-sama disambung setelah bentuk た, tapi artinya <b>\"meskipun dilakukan, percuma\"</b>.<br>・<span class='gd-jp'>彼に話したが最後、みんなに知られてしまう。</span>(Kalau sudah cerita ke dia, tamat sudah. Semua orang pasti tahu)<br>・<span class='gd-jp'>今さら彼に話したところで、何も変わらない。</span>(Cerita ke dia sekarang pun tidak akan mengubah apa-apa)</div><div class='gd-warn'>Trik membedakan: \"sekali dilakukan, tidak bisa balik dan akibatnya parah\" = が最後; \"begitu ~ langsung\" = が早いか; \"dilakukan pun percuma\" = たところで.</div>","n1-18":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜に至る」seperti yang sering kamu dengar di berita: <b>\"berkembang menjadi ~\"</b> atau <b>\"akhirnya sampai pada tahap ~\"</b>. Setelah waktu berlalu dan serangkaian perkembangan, sesuatu akhirnya sampai pada suatu hasil. Hasil ini biasanya hal yang berbobot, misalnya gugatan hukum, kebangkrutan, perdamaian, atau kesimpulan. Pola ini sangat bernuansa tulisan dan formal, paling sering muncul di berita, laporan, konferensi pers, dan penjelasan perusahaan.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata benda</b>: langsung tambahkan に至る, tanpa の di tengah.<br><span class='gd-pair'><span class='gd-jp'>訴訟</span> → <span class='gd-jp'>訴訟に至る</span></span><span class='gd-pair'><span class='gd-jp'>和解</span> → <span class='gd-jp'>和解に至る</span></span><br><b>Kata kerja</b>: pakai bentuk kamus (bentuk asli seperti yang tertulis di kamus) lalu tambahkan に至る.<br><span class='gd-pair'><span class='gd-jp'>中止する</span> → <span class='gd-jp'>中止するに至る</span></span><span class='gd-pair'><span class='gd-jp'>考える</span> → <span class='gd-jp'>考えるに至る</span></span></div><div class='gd-sec'><span class='gd-jp'>至る</span> sendiri adalah <b>kata kerja golongan 1 (godan)</b>, perubahannya sama seperti <span class='gd-jp'>帰る</span>:<br><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至った</span></span><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至っていない</span></span><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至らなかった</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Sampai pada suatu hasil</span>Paling sering dipakai dalam bentuk lampau 「〜に至った」. Di depannya sering ada <span class='gd-jp'>ついに</span>, <span class='gd-jp'>〜の末</span>, atau <span class='gd-jp'>〜結果</span> untuk menunjukkan bahwa ada proses panjang sebelumnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>長い話し合いの末、両社は合併に至った。</span>(Setelah perundingan yang panjang, kedua perusahaan akhirnya memutuskan untuk merger)</div><div class='gd-ex-line'>・<span class='gd-jp'>留学を通して、日本で働きたいと考えるに至った。</span>(Lewat studi di luar negeri, aku perlahan sampai pada pikiran ingin bekerja di Jepang)</div><div class='gd-sec'><span class='gd-tag'>Belum sampai tahap itu</span>Bentuk negatifnya sering ditulis 「〜には至っていない」, artinya sesuatu belum berkembang sampai tahap tersebut.</div><div class='gd-ex-line'>・<span class='gd-jp'>この技術は、まだ実用化には至っていない。</span>(Teknologi ini belum sampai pada tahap bisa dipakai secara nyata)</div><div class='gd-sec'><span class='gd-tag'>Ungkapan tetap</span>Tiga kalimat di bawah ini sangat umum, hafalkan sebagai satu kalimat utuh.</div><div class='gd-ex-line'>・<span class='gd-jp'>幸い、大事には至らなかった。</span>(Untungnya tidak sampai menjadi masalah besar)</div><div class='gd-ex-line'>・<span class='gd-jp'>中止に至った経緯をご説明します。</span>(Saya akan menjelaskan kronologi sampai diputuskannya pembatalan)</div><div class='gd-ex-line'>・<span class='gd-jp'>1990年に創業し、現在に至る。</span>(Didirikan tahun 1990 dan terus berjalan hingga sekarang)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata kerja harus bentuk kamus, bukan bentuk た: yang benar <span class='gd-jp'>中止するに至った</span>, bukan 「中止したに至った」. Makna lampau cukup diletakkan pada <span class='gd-jp'>至った</span>.<br>・Pola ini sangat bernuansa tulisan. Kalau ngobrol dengan teman dan ingin bilang \"akhirnya kami putus\", cukup pakai <span class='gd-jp'>結局別れることになった</span>. Kalau bilang 「別れるに至った」, kedengarannya seperti membaca siaran pers.<br>・Hasilnya harus berbobot, dan di depannya biasanya ada sebuah proses. Hal kecil seperti lapar lalu beli roti tidak bisa pakai 「パンを買うに至った」.<br>・Meskipun secara harfiah artinya \"tiba\", untuk \"tiba di suatu tempat\" dalam keseharian pakai <span class='gd-jp'>着く</span>.<br>・Kalau <span class='gd-jp'>至らない</span> dipakai sendirian, sering artinya lain, yaitu \"kurang teliti, kurang sempurna\": <span class='gd-jp'>至らない点もありますが、よろしくお願いします。</span>(Mungkin ada hal yang kurang sempurna, mohon bimbingannya)</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Di N1 ada tiga anggota keluarga 「至る」 yang mirip. Kita bandingkan dengan satu situasi yang sama, \"kondisi perusahaan sangat buruk\":<br><b>に至る</b> = sesuatu <b>akhirnya berkembang menjadi</b> suatu hasil:<br><span class='gd-jp'>赤字が続き、ついに倒産に至った。</span>(Kerugian terus berlanjut, dan akhirnya sampai pada kebangkrutan)<br><b>に至るまで</b> = menyatakan cakupan, <b>dari A sampai B, bahkan B juga</b>:<br><span class='gd-jp'>社長から新入社員に至るまで、全員が毎日残業している。</span>(Dari direktur sampai karyawan baru, semua orang lembur setiap hari)<br><b>に至っては</b> = <b>kalau soal B, lebih parah lagi</b>, mengangkat contoh yang paling ekstrem:<br><span class='gd-jp'>どの部署も業績が悪いが、営業部に至っては目標の半分にも届いていない。</span>(Kinerja semua divisi buruk, tapi divisi penjualan lebih parah lagi, bahkan setengah target pun tidak tercapai)</div><div class='gd-warn'>Trik membedakan: yang ada di akhir kalimat dan menyatakan \"akhirnya jadi begini\" adalah に至る; yang di depannya ada 「AからB」 dan membahas cakupan adalah に至るまで; yang ada di tengah kalimat sebagai topik dan memunculkan \"contoh yang lebih parah\" adalah に至っては.</div><div class='gd-h'>Setelah ini belajar apa?</div><div class='gd-sec'>Lanjutkan dengan <span class='gd-jp'>〜に至るまで</span> dan <span class='gd-jp'>〜に至っては</span>. Kalau ketiganya dihafal bersama, kamu paling tidak akan tertukar. Kamu juga bisa belajar <span class='gd-jp'>〜を経て</span> (melalui ~), yang sering muncul bersama に至る: <span class='gd-jp'>何度もの議論を経て、合意に至った。</span>(Setelah melalui diskusi berkali-kali, akhirnya tercapai kesepakatan)</div>","n1-19":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に至るまで」 kira-kira berarti <b>「mulai dari ~ sampai ~, semuanya ~」</b>. Misalnya kalimat \"dari bos sampai pekerja paruh waktu, semuanya ikut\". Intinya bukan \"berhenti sampai di mana\", tapi menekankan bahwa <b>sampai ujung yang sejauh itu dan sedetail itu pun ikut tercakup</b>, jadi cakupannya luas sekali.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋に至るまで. Yang paling sering, pola ini dipasangkan dengan 「から」:<br><b>Aから Bに至るまで</b>＝dari A terus sampai (bahkan) B (semuanya)<br><span class='gd-pair'><span class='gd-jp'>子供から高齢者</span> → <span class='gd-jp'>子供から高齢者に至るまで</span></span>(dari anak-anak sampai lansia)<br>B biasanya ditaruh di <b>ujung lain</b> dari cakupan itu, dan sering kali ujung yang \"tak disangka ikut terhitung juga\". Di belakangnya sering muncul kata-kata yang berarti \"semua\", seperti <span class='gd-jp'>全員</span>, <span class='gd-jp'>すべて</span>, <span class='gd-jp'>誰もが</span>, <span class='gd-jp'>細かく</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Cakupan orang</span>Dari atas sampai bawah, dari yang tua sampai yang muda, semua orang termasuk.</div><div class='gd-ex-line'>・<span class='gd-jp'>社長から新入社員に至るまで、全員が会議に参加した。</span>(Dari direktur sampai karyawan baru, semuanya ikut rapat)</div><div class='gd-ex-line'>・<span class='gd-jp'>子供から高齢者に至るまで、誰もが楽しめるイベントだ。</span>(Acara yang bisa dinikmati semua orang, dari anak-anak sampai lansia)</div><div class='gd-sec'><span class='gd-tag'>Cakupan detail</span>Dari garis besar sampai detail kecil, semuanya diperhatikan.</div><div class='gd-ex-line'>・<span class='gd-jp'>服装から髪型に至るまで、細かく決められている。</span>(Dari pakaian sampai model rambut, semuanya diatur sampai ke detailnya)</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋の隅々に至るまで、きれいに掃除した。</span>(Bahkan sampai ke setiap sudut ruangan dibersihkan sampai bersih)</div><div class='gd-sec'><span class='gd-tag'>Cakupan waktu</span>Dari masa yang sudah lama berlalu terus sampai sekarang, menekankan rentang waktu yang panjang.</div><div class='gd-ex-line'>・<span class='gd-jp'>創業から現在に至るまで、この味を守り続けている。</span>(Dari awal berdiri sampai sekarang, rasa ini terus dijaga)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Kata \"sampai ~\" dalam bahasa Indonesia gampang membuatmu mengira pola ini <b>menarik garis batas atau menetapkan batas atas</b>. Padahal justru kebalikannya: bukan \"hanya sampai di sini\", tapi \"<b>sampai di sini pun ikut tercakup</b>\". Intinya, cakupannya luas.<br>・A dan B harus <b>sejenis</b>, yaitu dua ujung dari hal yang sama: orang dengan orang, benda dengan benda, waktu dengan waktu.<br>・Kalau cuma bilang titik akhir biasa seperti \"tunggu sampai jam berapa\" atau \"jalan sampai stasiun\", cukup pakai <span class='gd-jp'>まで</span>. Pakai に至るまで di situ akan terdengar aneh.<br>・Ini ungkapan yang <b>formal dan tertulis</b>, sering muncul di berita, pengumuman, dan profil perusahaan. Kalau ngobrol dengan teman, cukup bilang <span class='gd-jp'>おじいちゃんまでみんなスマホ持ってるよ</span> (bahkan kakek pun punya ponsel, lho).</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama memakai 「至る」, di N1 ada tiga pola yang gampang tertukar. Kita bandingkan dengan satu situasi yang sama, yaitu \"keluarga dan ponsel pintar\":<br><b>に至るまで</b>＝cakupannya luas, <b>semuanya termasuk</b>:<br><span class='gd-jp'>祖父母から孫に至るまで、家族全員がスマホを持っている。</span>(Dari kakek-nenek sampai cucu, seluruh keluarga punya ponsel pintar)<br><b>に至っては</b>＝<b>memilih satu hal yang paling ekstrem</b> dari sekelompok hal, biasanya dengan nada mengkritik:<br><span class='gd-jp'>うちの家族は機械に弱い。祖母に至っては、電話のかけ方も知らない。</span>(Keluargaku lemah soal mesin. Apalagi nenek, bahkan cara menelepon saja tidak tahu)<br><b>に至る</b>＝sesuatu berkembang terus, <b>akhirnya sampai pada suatu hasil</b>:<br><span class='gd-jp'>何度も話し合って、ようやく祖母もスマホを買うに至った。</span>(Setelah berdiskusi berkali-kali, akhirnya nenek pun sampai membeli ponsel pintar)</div><div class='gd-warn'>Trik cepat: untuk \"dari ~ sampai ~, semuanya\" pakai に至るまで; untuk \"yang paling parah di antaranya adalah ~\" pakai に至っては; untuk \"pada akhirnya berkembang jadi ~\" pakai に至る.</div>","n1-20":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜を経て」 kira-kira berarti <b>\"setelah melewati ~\", \"melalui ~\", \"lewat ~\"</b>. Intinya, di tengah jalan ada <b>satu proses, satu tahap, atau satu tempat yang dilewati</b>, baru kemudian sampai pada hasil di belakangnya. Nadanya formal, sering muncul di berita, laporan, profil tokoh, dan pidato, tapi jarang dipakai saat ngobrol dengan teman.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋を経て　<span class='gd-pair'><span class='gd-jp'>長い議論</span> → <span class='gd-jp'>長い議論を経て</span>(setelah melewati diskusi yang panjang)</span><br>Di depannya hanya bisa <b>kata benda</b>, tidak bisa langsung kata kerja. Untuk menyebut \"persiapan\", tulis <span class='gd-jp'>準備を経て</span>, bukan 「準備するを経て」.<br>「経て」 dibaca <b>へて</b>, bentuk dasarnya <span class='gd-jp'>経る</span> (へる), artinya \"melewati\".</div><div class='gd-sec'>Kalau mau menyambung ke kata benda, ubah jadi <b>を経た＋kata benda</b>:<br><span class='gd-pair'><span class='gd-jp'>厳しい訓練</span> → <span class='gd-jp'>厳しい訓練を経た選手</span>(atlet yang sudah melewati latihan keras)</span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Melewati sebuah proses</span>Hal-hal yang butuh waktu dan tenaga, seperti diskusi, pemeriksaan, negosiasi, atau persiapan. Setelah semua itu selesai, baru ada hasilnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>長い議論を経て、ようやく結論が出た。</span>(Setelah diskusi yang panjang, akhirnya ada kesimpulan)</div><div class='gd-ex-line'>・<span class='gd-jp'>厳しい審査を経て、新しい薬が発売された。</span>(Setelah melewati pemeriksaan yang ketat, obat baru itu dirilis)</div><div class='gd-sec'><span class='gd-tag'>Melewati waktu</span>Sering dipakai bersama 「歳月」 dan 「年月」, terasa seperti \"setelah sekian tahun berlalu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>10年の歳月を経て、橋が完成した。</span>(Setelah sepuluh tahun berlalu, jembatan itu akhirnya selesai)</div><div class='gd-sec'><span class='gd-tag'>Menjalani suatu peran</span>Sangat umum di profil tokoh, untuk menceritakan tahap-tahap yang pernah dilalui seseorang.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は会社員を経て、作家になった。</span>(Setelah sempat jadi karyawan kantoran, dia menjadi penulis)</div><div class='gd-sec'><span class='gd-tag'>Lewat suatu tempat</span>Tempat yang dilewati di tengah rute perjalanan.</div><div class='gd-ex-line'>・<span class='gd-jp'>香港を経て、日本に着いた。</span>(Lewat Hong Kong, dia tiba di Jepang)</div><div class='gd-ex-line'>・<span class='gd-jp'>台北から台中を経て、高雄へ向かう。</span>(Dari Taipei lewat Taichung, menuju Kaohsiung)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・「経て」 dibaca <b>へて</b>, bukan けいて, dan bukan juga たって.<br>・Kanji 「経」 yang sama juga ada di <span class='gd-jp'>経つ</span> (たつ) yang berarti \"waktu berlalu\". <span class='gd-jp'>3年経って</span> dibaca さんねんたって, artinya \"sudah lewat tiga tahun\" dalam percakapan biasa. Keduanya mirip, tapi cara baca dan nuansanya berbeda.<br>・Ini ungkapan formal. Kalau ngobrol dengan teman, misalnya bilang \"transit lewat Hong Kong\", lebih natural pakai <span class='gd-jp'>香港経由で</span> atau <span class='gd-jp'>香港で乗り換えて</span>. Memakai 「を経て」 untuk urusan sehari-hari akan terdengar seperti membaca siaran pers.<br>・Di depannya harus ada <b>proses yang memang layak disebut</b>. Untuk hal kecil seperti makan atau mandi, cukup pakai 「〜てから」, bukan 「を経て」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>を経て vs 経って</b>: keduanya bisa dipakai untuk \"setelah beberapa waktu berlalu\".<br><span class='gd-jp'>3年経って、やっと仕事に慣れた。</span>(Setelah tiga tahun, akhirnya terbiasa dengan pekerjaan): gaya lisan. 「経って」 langsung menyambung ke kata waktu, tanpa を.<br><span class='gd-jp'>3年の歳月を経て、作品が完成した。</span>(Setelah tiga tahun berlalu, karya itu selesai): gaya formal, biasanya membawa kesan \"butuh banyak usaha sampai ada hasilnya\".</div><div class='gd-sec'><b>を経て vs に至る</b>: sering muncul bersamaan, tapi posisinya berbeda.<br><span class='gd-jp'>何度もの交渉を経て、合意に至った。</span>(Setelah negosiasi berkali-kali, akhirnya tercapai kesepakatan)<br>「を経て」 membicarakan <b>jalan yang dilewati di tengah</b>, sedangkan 「に至る」 membicarakan <b>titik akhir yang dicapai</b>.</div><div class='gd-warn'>Trik cepat: untuk \"apa yang dilewati di tengah\" pakai 「を経て」; untuk \"akhirnya sampai di mana\" pakai 「に至る」; kalau cuma bilang sambil lalu \"sudah lewat beberapa tahun\", pakai 「経って」.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'><span class='gd-jp'>〜に至る</span> dan <span class='gd-jp'>〜に至るまで</span> di level yang sama bisa kamu hafalkan bersama 「を経て」. Ketiganya berguna kalau kamu menulis teks tentang \"dari proses sampai hasil\".</div>","n1-38":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に難くない」kurang lebih berarti <b>「tidak sulit dibayangkan」「tidak sulit dipahami」「sudah bisa ditebak」</b>. Dari sedikit petunjuk saja, kamu bisa menebak situasi atau perasaan di baliknya. Cara bacanya <b>かたくない</b>. Pola ini bernuansa tulisan dan formal, sering muncul di berita, ulasan, dan artikel.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Yang ada di depannya hampir selalu kata untuk \"membayangkan di kepala\", dan pilihannya itu-itu saja. Paling cepat kalau dihafal sebagai satu paket:<br><span class='gd-jp'>想像に難くない</span>（tidak sulit dibayangkan）<br><span class='gd-jp'>理解に難くない</span>（tidak sulit dipahami）<br><span class='gd-jp'>予想に難くない</span>（tidak sulit diperkirakan）<br><span class='gd-jp'>推測に難くない</span>（tidak sulit ditebak）<br><span class='gd-jp'>察するに難くない</span>（tidak sulit disadari atau ditebak）<br>Kata seperti 想像 dan 理解 biasanya langsung disambung dengan 「に」 sebagai kata benda. <span class='gd-jp'>察する</span> sendiri kata kerja, jadi dipakai dalam bentuk kamus (辞書形).</div><div class='gd-sec'>Isi dugaanmu diletakkan di depan. Ada tiga bentuk yang umum: 「〜は」「〜ことは」「〜のは」.</div><div class='gd-ex-line'>・<span class='gd-jp'>親を亡くした彼の悲しみは想像に難くない。</span>（Betapa sedihnya dia yang kehilangan orang tua, itu mudah dibayangkan）</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画に反対の声が上がることは予想に難くない。</span>（Tidak sulit diperkirakan bahwa rencana ini akan memicu suara penolakan）</div><div class='gd-ex-line'>・<span class='gd-jp'>物価がこれだけ上がれば、生活が苦しくなるのは想像に難くない。</span>（Kalau harga naik sebanyak ini, hidup jadi susah itu sudah bisa ditebak）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の表情から、何があったかは察するに難くない。</span>（Dari raut wajahnya, tidak sulit menebak apa yang terjadi）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・「難くない」dibaca <b>かたくない</b>, jangan dibaca むずかしくない.<br>・Yang dimaksud adalah \"tidak sulit untuk <b>dibayangkan</b>\" di kepala, bukan \"mudah untuk <b>dikerjakan</b>\". Kalau mau bilang \"soal ini gampang dikerjakan\", pakai <span class='gd-jp'>この問題は簡単だ</span>, bukan に難くない.<br>・Jangan sembarangan memasang kata kerja di depannya. Cukup pakai 想像, 理解, 予想, 推測, dan 察する.<br>・Gayanya kaku, jadi tidak dipakai dalam obrolan sehari-hari. Kalau ngobrol dengan teman dan mau bilang \"sudah bisa ditebak\", <span class='gd-jp'>想像できる</span> atau <span class='gd-jp'>想像がつく</span> terdengar lebih natural.<br>・Jangan tertipu oleh 「ない」 dan mengira ini kalimat negatif. 「難くない」＝tidak sulit＝<b>sangat mudah</b>, jadi nadanya tetap afirmatif.</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'>Di N1 ada beberapa pola 「〜に＋negatif」 yang bentuknya mirip tapi artinya jauh berbeda. Coba bandingkan dalam satu situasi: seorang teman terkena PHK dari perusahaannya.<br><b>に難くない</b>＝tidak sulit ditebak: <span class='gd-jp'>彼のショックは想像に難くない。</span>（Betapa besar syok yang dia rasakan, itu mudah dibayangkan）<br><b>には当たらない</b>＝tidak perlu bereaksi seperti itu: <span class='gd-jp'>この不景気だから、リストラされても驚くには当たらない。</span>（Dengan ekonomi seburuk ini, kena PHK pun tidak perlu kaget）<br><b>に堪えない</b>＝terlalu buruk sampai tidak tahan dilihat atau didengar: <span class='gd-jp'>会社の説明は聞くに堪えない言い訳ばかりだった。</span>（Penjelasan perusahaan isinya alasan yang tidak tahan didengar）</div><div class='gd-warn'>Trik membedakan: \"sudah bisa ditebak\" berarti に難くない; \"tidak perlu sampai segitunya\" berarti には当たらない; \"parah sampai tak tertahankan\" berarti に堪えない.</div>","n1-37":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜を禁じ得ない」kurang lebih berarti <b>「tak kuasa menahan rasa ～」「tanpa sadar merasa ～」</b>. Saat melihat atau mendengar sesuatu, perasaan seperti iba, kaget, atau marah muncul begitu saja dan tidak bisa ditahan. Pola ini sangat formal, biasanya muncul di ulasan berita, artikel, dan pidato, dan hampir tidak dipakai dalam obrolan biasa.</div><div class='gd-h'>Kalau dipecah, jadi mudah dipahami</div><div class='gd-sec'><span class='gd-jp'>禁じる</span> artinya \"melarang\", dan <span class='gd-jp'>得ない</span> artinya \"tidak bisa ～\". Digabung jadi \"mau dilarang pun tidak bisa\", maksudnya perasaan itu tidak bisa dibendung dan muncul sendiri.<br>Cara bacanya <b>きんじえない</b>. 「得」 di sini dibaca 「え」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya taruh <b>kata benda yang menyatakan perasaan</b>, lalu tambahkan 「を禁じ得ない」. Untuk kejadian yang sudah lewat, jadi 「を禁じ得なかった」.<br><span class='gd-pair'><span class='gd-jp'>同情</span> → <span class='gd-jp'>同情を禁じ得ない</span></span>（tak kuasa menahan rasa iba）<br><span class='gd-pair'><span class='gd-jp'>驚き</span> → <span class='gd-jp'>驚きを禁じ得なかった</span></span>（waktu itu tak kuasa menahan kagetku）<br>Kata benda yang sering dipasangkan: <span class='gd-jp'>同情</span>、<span class='gd-jp'>驚き</span>、<span class='gd-jp'>怒り</span>、<span class='gd-jp'>憤り</span>、<span class='gd-jp'>涙</span>、<span class='gd-jp'>戸惑い</span>、<span class='gd-jp'>疑問</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Tersentuh oleh suatu kejadian</span>Biasanya di depan dijelaskan dulu \"melihat apa, mendengar apa, atau teringat apa\", baru kemudian dikatakan bahwa perasaannya tak tertahankan.</div><div class='gd-ex-line'>・<span class='gd-jp'>その知らせを聞いて、驚きを禁じ得なかった。</span>（Mendengar kabar itu, aku tak kuasa menahan rasa kaget）</div><div class='gd-ex-line'>・<span class='gd-jp'>被害者の話を聞き、涙を禁じ得なかった。</span>（Mendengar cerita korban, aku tak kuasa menahan air mata）</div><div class='gd-sec'><span class='gd-tag'>Pernyataan sikap secara resmi</span>Sering dipakai di ulasan atau tajuk rencana untuk menyatakan pendapat yang kuat.</div><div class='gd-ex-line'>・<span class='gd-jp'>政府の対応には、怒りを禁じ得ない。</span>（Terhadap cara pemerintah menangani ini, aku tak kuasa menahan rasa marah）</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画には疑問を禁じ得ない。</span>（Terhadap rencana ini, aku tak bisa tidak merasa ragu）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Di depannya harus <b>kata benda</b>, tidak boleh langsung kata kerja. Yang benar <span class='gd-jp'>涙を禁じ得ない</span> dan <span class='gd-jp'>驚きを禁じ得ない</span>, bukan 「泣くを禁じ得ない」 atau 「驚くを禁じ得ない」.<br>・Pola ini untuk perasaan yang muncul pada <b>dirimu sendiri</b>, bukan untuk menggambarkan perasaan orang lain.<br>・Nadanya sangat kaku. Kalau ngobrol dengan teman lalu bilang 「感動を禁じ得なかった」, kedengarannya seperti membaca naskah. Dalam percakapan, cukup bilang <span class='gd-jp'>思わず泣いちゃった</span>（aku sampai nangis tanpa sadar）.<br>・「得ない」 dibaca <b>えない</b>, jangan dibaca うない.</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'>Situasinya sama: mendengar nasib seseorang lalu merasa sangat iba.<br><b>を禁じ得ない</b>＝perasaan <b>muncul dan tak bisa ditahan</b>, sangat formal, di depannya kata benda:<br><span class='gd-jp'>彼の話を聞いて、同情を禁じ得なかった。</span>（Mendengar ceritanya, aku tak kuasa menahan rasa iba padanya）<br><b>ずにはいられない</b>（N2）＝\"tidak bisa tidak ～\", di depannya kata kerja, bisa juga untuk tindakan, lebih sering dipakai dan tidak sekaku itu:<br><span class='gd-jp'>彼の話を聞いて、同情せずにはいられなかった。</span>（Mendengar ceritanya, aku tak bisa tidak merasa kasihan padanya）<br><span class='gd-jp'>あまりにおかしくて、笑わずにはいられなかった。</span>（Lucu sekali, aku tidak bisa tidak tertawa）<br>Kalau <b>に堪えない</b> dipasang pada kata benda perasaan, artinya \"sampai batas ekstrem, sangat ～\". Contoh yang umum: <span class='gd-jp'>感謝に堪えない</span>（sangat berterima kasih）、<span class='gd-jp'>遺憾に堪えない</span>、<span class='gd-jp'>同情に堪えない</span>、<span class='gd-jp'>憤慨に堪えない</span>. Biasanya dipakai dalam sambutan resmi atau tulisan. Kesannya perasaan itu begitu kuat sampai tak tertahankan:<br><span class='gd-jp'>被災された方々のことを思うと、同情に堪えない。</span>（Kalau teringat para korban bencana, rasa ibaku tak terkira）<br>Selain itu, に堪えない setelah kata kerja punya arti lain: <span class='gd-jp'>見るに堪えない</span> artinya \"parah sampai tak tahan dilihat\". Ini tidak ada hubungannya dengan を禁じ得ない, jadi jangan dicampur.</div><div class='gd-warn'>Trik membedakan: perasaan yang \"muncul dan tak tertahankan\" pakai を禁じ得ない; perasaan yang \"begitu kuat sampai tak tertanggungkan, sampai batas ekstrem\" pakai に堪えない; \"tak tahan untuk melakukan sesuatu\" secara umum pakai ずにはいられない.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Satu kelompok dengan pola perasaan kuat ini, di N1 ada juga <span class='gd-jp'>〜て止まない</span> (terus ～ dari lubuk hati), misalnya <span class='gd-jp'>皆様のご健康を願って止みません。</span>（Dengan sepenuh hati saya mendoakan kesehatan Anda semua）. Pola ini sering muncul di pidato dan penutup surat.</div>","n1-36":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜に堪えない」punya dua arti yang arahnya justru berlawanan, dan keduanya ada padanannya dalam bahasa Indonesia:<br>①<b>‘tak sedap dipandang, tak tahan didengar’</b>: sesuatu begitu buruk atau menyedihkan sampai kamu tidak sanggup melihat atau mendengarnya.<br>②<b>‘tak terkira terima kasihnya, tak terkira harunya’</b>: perasaan di hati begitu penuh sampai tak tertampung, alias ‘sangat ～’.<br>Keduanya sangat formal dan bahasa tulis, jadi hampir tidak pernah dipakai dalam obrolan sehari-hari.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>①<b>Kata kerja bentuk kamus＋に堪えない</b>: di depannya hampir hanya ada tiga kata kerja, yaitu ‘melihat, mendengar, membaca’.<br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るに堪えない</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くに堪えない</span></span><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読むに堪えない</span></span><br>②<b>Kata benda perasaan＋に堪えない</b>: yang paling sering muncul adalah <span class='gd-jp'>感謝</span>, <span class='gd-jp'>感激</span>, <span class='gd-jp'>感慨</span>, <span class='gd-jp'>遺憾</span>, dan <span class='gd-jp'>痛恨</span>.<br><span class='gd-pair'><span class='gd-jp'>感謝</span> → <span class='gd-jp'>感謝に堪えません</span></span><span class='gd-pair'><span class='gd-jp'>遺憾</span> → <span class='gd-jp'>遺憾に堪えない</span></span><br>「堪えない」dibaca <b>たえない</b>, dan sering juga langsung ditulis dengan hiragana「たえない」.</div><div class='gd-h'>Pemakaian ①: terlalu buruk untuk dilihat atau didengar</div><div class='gd-sec'><span class='gd-tag'>Kritik, rasa jijik</span>Dipakai untuk isi yang terlalu buruk, terlalu kasar, atau terlalu menyedihkan, sehingga tidak layak dilihat, didengar, atau dibaca. Di belakangnya sering langsung ada kata benda, misalnya「聞くに堪えない悪口」.</div><div class='gd-ex-line'>・<span class='gd-jp'>聞くに堪えない悪口だった。</span>(Cacian itu begitu kasar sampai tak tahan didengar)</div><div class='gd-ex-line'>・<span class='gd-jp'>この翻訳はひどくて、読むに堪えない。</span>(Terjemahan ini begitu buruk sampai tak sanggup dibaca)</div><div class='gd-ex-line'>・<span class='gd-jp'>事故の現場は見るに堪えない状態だった。</span>(Lokasi kecelakaan itu dalam kondisi yang tak tega dilihat)</div><div class='gd-h'>Pemakaian ②: perasaan yang penuh sampai tak tertampung</div><div class='gd-sec'><span class='gd-tag'>Pidato formal</span>Sering muncul dalam pidato, surat terima kasih, pernyataan permintaan maaf, dan pidato duka. Isinya perasaan kuat <b>dirimu sendiri</b>. Kalau bicara langsung kepada orang, biasanya dipakai「〜に堪えません」.</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様の温かいご支援に、感謝の念に堪えません。</span>(Atas dukungan hangat dari Bapak/Ibu sekalian, kami tak terkira berterima kasih)</div><div class='gd-ex-line'>・<span class='gd-jp'>このような事態となり、誠に遺憾に堪えません。</span>(Dengan terjadinya keadaan seperti ini, kami sungguh amat menyesalkannya)</div><div class='gd-ex-line'>・<span class='gd-jp'>二十年ぶりに母校を訪れ、感慨に堪えない。</span>(Setelah dua puluh tahun, aku kembali ke almamater, dan hatiku dipenuhi rasa haru)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・②<b>bukan arti negatif</b>. 「<span class='gd-jp'>感謝に堪えない</span>」bukan ‘berterima kasih sampai tak tahan, jadi kesal’, tetapi ‘rasa terima kasihnya penuh sampai tak tertampung di hati’, artinya ‘sangat berterima kasih’.<br>・Tidak bisa dipakai untuk menahan sesuatu secara fisik. Untuk ‘panasnya tak tertahankan’, katakan <span class='gd-jp'>暑くてたまらない</span> atau <span class='gd-jp'>暑さに耐えられない</span>, bukan 暑さに堪えない.<br>・①mengkritik bahwa barangnya sendiri terlalu buruk atau terlalu menyedihkan. Artinya bukan ‘aku tidak sempat melihat’ atau ‘aku tidak mau melihat’.<br>・②sangat formal. Kalau kamu bilang「感謝に堪えない」ke temanmu, rasanya seperti sedang pidato. Dalam keseharian cukup bilang <span class='gd-jp'>本当にありがとう</span>.<br>・Di depan ② harus ada kata benda perasaan berkanji seperti ‘感謝, 遺憾’. Kata sifat tidak bisa langsung dipasang, misalnya tidak bisa bilang 悲しいに堪えない.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Untuk ‘sebuah kecelakaan’ yang sama, ketiga ungkapan ini terasa berbeda:<br><b>に堪えない</b>＝di situasi formal, menyatakan <b>perasaan yang sangat dalam</b> dari dirimu, seperti pernyataan resmi:<br><span class='gd-jp'>このような事故が起きたことは、誠に遺憾に堪えません。</span>(Terjadinya kecelakaan seperti ini sangat kami sesalkan)<br><b>を禁じ得ない</b>＝suatu hal membuat perasaan tertentu <b>muncul tak tertahankan</b>. Fokusnya pada ‘tak bisa dikendalikan’:<br><span class='gd-jp'>遺族の話を聞いて、涙を禁じ得なかった。</span>(Mendengar cerita keluarga korban, aku tak bisa menahan air mata)<br><b>てたまらない</b>＝bahasa lisan untuk ‘～ banget, ～ sampai tak tahan’, untuk perasaan pribadi atau sensasi tubuh:<br><span class='gd-jp'>あの映像を思い出すと、つらくてたまらない。</span>(Setiap teringat gambar itu, rasanya sedih sekali)</div><div class='gd-warn'>Tips cepat memilih: untuk pernyataan atau pidato yang mengatakan ‘sangat ～’, pakai に堪えない; untuk ‘tak bisa menahan ～’, pakai を禁じ得ない; untuk obrolan dengan teman seperti ‘～ banget’, pakai てたまらない.</div><div class='gd-h'>Yang bisa dipelajari setelah ini</div><div class='gd-sec'>Kalau diubah ke bentuk positif「〜に堪える」, artinya jadi ‘tahan uji ～, layak untuk ～’: <span class='gd-jp'>大人の鑑賞に堪える作品だ。</span>(Ini karya yang layak dinikmati orang dewasa). Ada juga「〜に足る」yang artinya mirip, jadi sekalian dipelajari ya.</div>","n1-39":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜てやまない」sepadan dengan <b>‘dengan sepenuh hati ～’ atau ‘～ tiada henti’</b>. <span class='gd-jp'>やむ</span> artinya ‘berhenti’, seperti di <span class='gd-jp'>雨がやむ</span> (hujan berhenti). Jadi <span class='gd-jp'>願ってやまない</span> secara harfiah ‘harapan yang tak bisa berhenti’, yaitu perasaan yang terus tersimpan di hati, sangat dalam dan kuat. Ini ungkapan formal bahasa tulis, sering muncul dalam pidato, ucapan selamat, dan artikel.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja bentuk て＋やまない. Biasanya ditulis dengan hiragana <span class='gd-jp'>やまない</span>, jarang dengan kanji.<br><span class='gd-pair'><span class='gd-jp'>願う</span> → <span class='gd-jp'>願って</span> → <span class='gd-jp'>願ってやまない</span></span><br><span class='gd-pair'><span class='gd-jp'>期待する</span> → <span class='gd-jp'>期待して</span> → <span class='gd-jp'>期待してやまない</span></span><br>Di situasi formal saat bicara kepada orang, pakai bentuk sopan <span class='gd-jp'>やみません</span>; untuk hal yang sudah lewat, pakai <span class='gd-jp'>やまなかった</span>.<br>Di depannya hampir selalu kata kerja yang menyatakan perasaan: <span class='gd-jp'>願う</span>, <span class='gd-jp'>祈る</span>, <span class='gd-jp'>望む</span>, <span class='gd-jp'>期待する</span>, <span class='gd-jp'>愛する</span>, <span class='gd-jp'>尊敬する</span>, <span class='gd-jp'>信じる</span>, <span class='gd-jp'>憧れる</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Pidato・ucapan selamat</span>Mendoakan lawan bicara. Ini pemakaian yang paling khas.</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご健康を祈ってやみません。</span>(Dari lubuk hati, kami mendoakan kesehatan Bapak/Ibu sekalian)</div><div class='gd-sec'><span class='gd-tag'>Keyakinan sendiri</span>Dalam tulisan, untuk menyatakan pemikiran yang sudah lama kamu pegang.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は彼の才能を信じてやまない。</span>(Aku selalu sangat percaya pada bakatnya)</div><div class='gd-sec'><span class='gd-tag'>Memikat orang</span>Subjeknya benda, yang berarti sesuatu itu terus memikat orang dengan begitu dalam.</div><div class='gd-ex-line'>・<span class='gd-jp'>この町の景色は、今も多くの人を魅了してやまない。</span>(Pemandangan kota ini sampai sekarang masih terus memikat banyak orang)</div><div class='gd-sec'><span class='gd-tag'>Menerangkan kata benda</span>Saat membicarakan perasaan orang lain, sering diletakkan di depan kata benda sebagai penjelas.</div><div class='gd-ex-line'>・<span class='gd-jp'>祖父が愛してやまなかった海</span>(Laut yang sepanjang hidupnya sangat dicintai kakek)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Meski sering diartikan ‘tiada henti’, ungkapan ini <b>tidak</b> dipakai untuk menyatakan tindakan yang berlangsung terus. <span class='gd-jp'>雨が降ってやまない</span> dan <span class='gd-jp'>走ってやまない</span> sama-sama salah; untuk hujan yang tak berhenti, langsung bilang <span class='gd-jp'>雨がやまない</span>. Ungkapan ini hanya untuk <b>perasaan dan harapan</b>.<br>・Hanya menyambung ke kata kerja, tidak ke kata sifat. Untuk ‘senang banget’, tidak bisa bilang 嬉しくてやまない; katakan <span class='gd-jp'>嬉しくてたまらない</span>.<br>・Ini ungkapan yang sangat formal. Kalau kamu bilang <span class='gd-jp'>君を愛してやまない</span> saat ngobrol dengan teman, kedengarannya seperti membaca naskah.<br>・Di situasi formal saat bicara kepada orang, pakai <span class='gd-jp'>願ってやみません</span>, jangan bilang 願ってやまないです.<br>・Kalau ditaruh di akhir kalimat, subjeknya biasanya ‘aku’. Perasaan orang lain biasanya muncul dalam tulisan, atau diletakkan di depan kata benda seperti contoh di atas.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Untuk ‘kampung halaman’ yang sama, ketiganya mengungkapkan perasaan yang berbeda:<br><b>てやまない</b>＝perasaan mendalam yang sudah lama tersimpan di hati, bahasa tulis: <span class='gd-jp'>故郷を愛してやまない。</span>(Aku sangat mencintai kampung halamanku)<br><b>てたまらない</b>(N2)＝perasaan saat ini yang begitu kuat sampai tak tertahankan, bisa juga dipakai dalam bahasa lisan: <span class='gd-jp'>故郷に帰りたくてたまらない。</span>(Kangen banget ingin pulang kampung, sampai tak tahan)<br><b>を禁じ得ない</b>＝perasaan yang muncul tak tertahankan saat melihat suatu hal: <span class='gd-jp'>故郷の変わりように驚きを禁じ得ない。</span>(Melihat perubahan kampung halaman, aku tak bisa menahan rasa kaget)</div><div class='gd-warn'>Tips cepat memilih: untuk cita-cita, cinta, dan keyakinan yang sudah lama, pakai <span class='gd-jp'>てやまない</span>; untuk perasaan tak nyaman atau keinginan kuat saat ini, pakai <span class='gd-jp'>てたまらない</span>; untuk reaksi yang muncul tak tertahankan karena tersentuh suatu hal, pakai <span class='gd-jp'>を禁じ得ない</span>.</div>","n1-34":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜極まりない」artinya kira-kira <b>「sangat … sekali, … keterlaluan, … tak terkira」</b>, seperti \"kurang ajar sekali\" atau \"berbahaya sekali\". Pola ini khusus dipakai untuk <b>mengkritik dengan keras</b>. Nadanya kaku, seperti di berita, kolom opini, atau surat protes resmi. 「〜極まる」artinya sama, hanya terdengar lebih kuno.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kritik keras</span>Memberi penilaian yang sangat berat pada sikap atau perbuatan orang lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店員の対応は失礼極まりない。</span>（Cara pelayan itu melayani sangat kurang ajar.）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜中に大声で騒ぐなんて、迷惑極まりない。</span>（Berisik teriak-teriak tengah malam, mengganggu sekali.）</div><div class='gd-sec'><span class='gd-tag'>Menggambarkan situasi yang sangat buruk</span>Dipakai di berita atau laporan untuk hal yang berbahaya atau merepotkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨の夜に無灯火で走るのは危険極まりない。</span>（Mengendarai kendaraan tanpa lampu di malam hujan itu sangat berbahaya.）</div><div class='gd-sec'><span class='gd-tag'>Diletakkan sebelum kata benda</span>Langsung dipakai untuk menerangkan benda di belakangnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>退屈極まりない会議が三時間も続いた。</span>（Rapat yang membosankan setengah mati itu berlangsung tiga jam penuh.）</div><div class='gd-h'>Cara menyambungkan</div><div class='gd-sec'>Untuk kata sifat-な, buang 「な」 lalu sambungkan langsung:<br><span class='gd-pair'><span class='gd-jp'>失礼な</span> → <span class='gd-jp'>失礼極まりない</span></span><span class='gd-pair'><span class='gd-jp'>危険な</span> → <span class='gd-jp'>危険極まる</span></span><br>Kata yang paling sering dipasangkan: <span class='gd-jp'>失礼、無礼、危険、迷惑、不快、不愉快、退屈、非常識、無責任</span>. Hampir semuanya terdiri dari dua kanji atau lebih dan memang sudah bermakna negatif.<br><br>Ujung 「極まりない」adalah 「ない」, jadi bisa diubah ke bentuk lampau seperti kata sifat-い:<span class='gd-pair'><span class='gd-jp'>失礼極まりない</span> → <span class='gd-jp'>失礼極まりなかった</span></span><br>Kata sifat-い tidak bisa disambung langsung. Tambahkan dulu 「こと」:<span class='gd-pair'><span class='gd-jp'>情けない</span> → <span class='gd-jp'>情けないこと極まりない</span></span>（memalukan sekali）</div><div class='gd-h'>Hal yang sering keliru</div><div class='gd-warn'>・「ない」 di 「極まりない」<b>bukan negasi</b>. 「極まり」 berarti \"ujung/batas\", jadi 「極まりない」 berarti \"tidak ada batasnya\", yaitu \"sangat ekstrem～\". <span class='gd-jp'>失礼極まりない</span> artinya \"sangat tidak sopan\", bukan \"tidak tidak sopan\".<br>・Jangan menyelipkan な di tengah. Yang benar <span class='gd-jp'>失礼極まりない</span>, bukan 「失礼な極まりない」.<br>・Hampir selalu dipakai untuk hal buruk. Kalau mau memuji makanan enak atau barang yang berguna, pakai ungkapan lain, jangan dipaksakan.<br>・Nadanya berat dan kaku. Kalau mengeluh ke teman, cukup bilang <span class='gd-jp'>本当に失礼だよね</span>. Kalau kamu bilang 「失礼極まりない」 langsung ke orangnya, itu sama saja dengan memutus hubungan secara resmi.<br>・Cara baca: 極まりない dibaca きわまりない, 極まる dibaca きわまる.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Misalnya sama-sama diperlakukan tidak sopan oleh pelayan:<br><b>極まりない</b>＝memberikan <b>penilaian</b> yang sangat berat dengan kepala dingin: <span class='gd-jp'>あの店員の態度は失礼極まりない。</span>（Sikap pelayan itu sangat tidak sopan.）<br><b>といったらない</b>＝seruan saat <b>emosi meluap</b>. Lebih lisan, dan kata sifat-い bisa disambung langsung: <span class='gd-jp'>あの店員の態度、腹が立つといったらない。</span>（Sikap pelayan itu bikin kesal bukan main.）</div><div class='gd-sec'><b>の至り</b>juga bisa diartikan \"sangat～\", tetapi arahnya berlawanan. Pola ini membicarakan perasaan <b>diri sendiri</b>, biasanya hal baik seperti rasa bangga atau terima kasih, dan dipakai dalam pidato atau situasi sopan.<br><span class='gd-jp'>このような賞をいただき、光栄の至りです。</span>（Menerima penghargaan seperti ini, saya merasa sangat terhormat.）</div><div class='gd-warn'>Tips membedakan: untuk mengkritik hal buruk, pakai 「極まりない」. Untuk dengan sopan menyatakan diri merasa terhormat atau sangat berterima kasih, pakai 「の至り」. Untuk seruan saat emosi meledak karena marah, malu, atau senang, pakai 「といったらない」.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kanji yang sama punya dua ungkapan umum lainnya:<br>Kata benda＋の極み：<span class='gd-jp'>こんな料理を毎日食べるなんて、贅沢の極みだ。</span>（Makan masakan seperti ini setiap hari benar-benar kemewahan puncak.）<br>Ungkapan tetap 「感極まる」：<span class='gd-jp'>優勝が決まった瞬間、感極まって泣き出した。</span>（Begitu juara dipastikan, dia terharu sampai menangis.）</div>","n1-52":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜まじき」artinya kira-kira <b>「Sebagai ～, masa berbuat begitu!」</b>. Dipakai untuk mencela orang yang melakukan sesuatu yang <b>tidak pantas dengan statusnya</b>, seperti \"tidak layak\" atau \"tidak pantas\" di berita. Nadanya berat dan formal, biasanya muncul di berita, editorial, atau pidato resmi.</div><div class='gd-h'>Cara menyambungkan</div><div class='gd-sec'>Kata kerja bentuk kamus (bentuk dasar yang kamu temukan di kamus)＋まじき＋kata benda<br><span class='gd-pair'><span class='gd-jp'>ある</span> → <span class='gd-jp'>あるまじき行為</span></span>（perbuatan yang tidak seharusnya ada）<br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許すまじき犯罪</span></span>（kejahatan yang tidak termaafkan）<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うまじきこと</span></span>（hal yang tidak boleh diucapkan）<br>Selain <span class='gd-jp'>するまじき</span>, untuk 「する」 kamu juga akan menemukan bentuk yang lebih kuno, yaitu <span class='gd-jp'>すまじき</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Status＋にあるまじき</span>Lebih dari 90% kemunculannya memakai rangkaian tetap ini: 「orang atau status＋に（atau として）＋あるまじき＋kata benda」, artinya \"～ yang tidak seharusnya ada pada orang dengan status itu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>医者にあるまじき行為だ。</span>（Itu perbuatan yang tidak pantas dilakukan seorang dokter.）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロにあるまじきミスだ。</span>（Ini kesalahan yang tidak boleh dilakukan seorang profesional.）</div><div class='gd-ex-line'>・<span class='gd-jp'>社会人としてあるまじき態度だと叱られた。</span>（Aku dimarahi karena itu sikap yang tidak pantas bagi orang dewasa yang sudah bekerja.）</div><div class='gd-sec'><span class='gd-tag'>許すまじき</span>Tanpa menyebut status, langsung mengatakan \"hal ini sama sekali tidak boleh dimaafkan\".</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもを狙った許すまじき犯罪だ。</span>（Ini kejahatan yang menyasar anak-anak dan tidak termaafkan.）</div><div class='gd-h'>Hal yang sering keliru</div><div class='gd-warn'>・まじき <b>harus diikuti kata benda</b>, tidak bisa langsung mengakhiri kalimat:<br>　×<span class='gd-jp'>教師にあるまじきだ。</span><br>　○<span class='gd-jp'>教師にあるまじき発言だ。</span><br>・Artinya \"<b>tidak seharusnya</b>\", bukan \"<b>tidak bisa / tidak mampu</b>\". Ini penilaian moral dan tidak ada kaitannya dengan kemampuan.<br>・「許す」 di 「許すまじき」 adalah soal <b>pihak lain</b> memaafkan atau tidak. Jadi 「政治家として許すまじき発言」 gampang terbaca sebagai \"kami, sebagai politisi, tidak bisa memaafkan\". Untuk mengatakan \"politisi itu tidak pantas bicara begitu\", yang paling jelas adalah <span class='gd-jp'>政治家としてあるまじき発言</span>.<br>・Sangat kaku, jadi terdengar aneh kalau diucapkan dalam obrolan sehari-hari. Dalam percakapan, cukup bilang <span class='gd-jp'>先生なのに、ありえない。</span>（Padahal dia guru, keterlaluan banget.）</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Misalnya sama-sama mengecam guru yang menghukum fisik muridnya:<br><b>べきではない</b>＝\"tidak seharusnya\" yang umum, bisa dipakai di situasi apa saja dan boleh di akhir kalimat: <span class='gd-jp'>教師は体罰をするべきではない。</span>（Guru tidak boleh menghukum fisik.）<br><b>まじき</b>＝sama-sama \"tidak seharusnya\", tetapi lebih berat dan lebih tertulis, serta hanya bisa diletakkan sebelum kata benda: <span class='gd-jp'>体罰は教師にあるまじき行為だ。</span>（Hukuman fisik adalah perbuatan yang tidak pantas bagi seorang guru.）<br><b>べからざる</b>＝intinya \"tidak boleh / tidak boleh kurang\", sering membahas aturan atau keharusan dan tidak selalu terkait status: <span class='gd-jp'>水は生活に欠くべからざるものだ。</span>（Air adalah sesuatu yang tak tergantikan dalam kehidupan.）</div><div class='gd-warn'>Tips membedakan: kalau di depannya ada 「status＋に／として」 dan kamu sedang mencela orang yang tidak layak, itu まじき. Kalau membahas aturan atau hal yang \"tak tergantikan\", itu べからざる.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「〜たる」＝sebagai orang yang berstatus ～. Pola ini sering muncul bersama まじき karena maknanya berdekatan: <span class='gd-jp'>教師たる者、生徒の手本でなければならない。</span>（Seorang guru harus menjadi teladan bagi murid-muridnya.）</div>","n1-59":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜には当たらない」artinya <b>「tidak perlu ～」「tidak usah sampai ～」</b>. Dipakai untuk mengomentari sesuatu dengan tenang: hal ini tidak seserius itu, dan <b>reaksi seperti itu terlalu berlebihan</b>. Misalnya tidak perlu kaget, tidak perlu sedih, atau tidak perlu memarahi orang. Rasanya mirip dengan kalimat \"Ngapain heboh begitu?\", hanya saja nadanya lebih formal dan lebih sering muncul di tulisan, ulasan, atau pidato resmi.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja bentuk kamus (bentuk dasar yang kamu temukan di kamus) ＋には当たらない<br><span class='gd-pair'><span class='gd-jp'>驚く</span> → <span class='gd-jp'>驚くには当たらない</span></span> (tidak perlu kaget)<br><span class='gd-pair'><span class='gd-jp'>悲観する</span> → <span class='gd-jp'>悲観するには当たらない</span></span> (tidak perlu pesimis)<br>Kalau mau lebih sopan, pakai <span class='gd-jp'>〜には当たりません</span>. 「は」kadang dihilangkan, jadi <span class='gd-jp'>驚くに当たらない</span>, artinya sama saja.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mengomentari reaksi yang berlebihan</span>Biasanya alasan disebut dulu di depan: \"karena memang sudah begitu\" atau \"baru segitu saja\". Lalu kesimpulannya menyusul: \"jadi tidak perlu ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はずっと努力してきたのだから、合格したのも驚くには当たらない。</span>(Dia selalu berusaha keras, jadi tidak perlu kaget kalau dia lulus.)</div><div class='gd-ex-line'>・<span class='gd-jp'>一度失敗したくらいで、悲観するには当たらない。</span>(Baru gagal sekali, tidak perlu pesimis.)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが言ったことだから、そんなに責めるには当たらない。</span>(Itu kan ucapan anak kecil, tidak perlu disalahkan sampai segitunya.)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Di depannya sering ada kata kerja tentang \"reaksi\": <span class='gd-jp'>驚く</span>, <span class='gd-jp'>嘆く</span>, <span class='gd-jp'>悲観する</span>, <span class='gd-jp'>責める</span>, <span class='gd-jp'>非難する</span>, <span class='gd-jp'>褒める</span>, <span class='gd-jp'>感心する</span>.<br>Bagian alasannya sering berpasangan dengan <span class='gd-jp'>〜くらいで</span> (baru segitu saja sudah ～), <span class='gd-jp'>〜からといって</span> (meskipun karena ～), <span class='gd-jp'>〜のだから</span> (toh sudah ～).</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・<span class='gd-jp'>当たる</span> di sini tidak ada hubungannya dengan \"menang undian\" atau \"mengenai sasaran\". Ingat seluruh kalimatnya sebagai satu ungkapan tetap.<br>・Yang ada di depannya adalah <b>reaksi atau penilaian terhadap sesuatu</b>. Untuk makna \"tidak perlu repot-repot melakukan suatu tindakan\", misalnya \"tidak perlu repot-repot datang\", bahasa Jepang biasanya pakai <span class='gd-jp'>〜には及ばない</span>, bukan pola ini (dibandingkan di bawah).<br>・Kalau kata benda disambung dengan <span class='gd-jp'>に当たらない</span>, maknanya sering lain: \"tidak termasuk ～, tidak tergolong ～\". Contohnya <span class='gd-jp'>これは違反には当たらない。</span> (Ini tidak termasuk pelanggaran.) Waktu baru belajar, ingat saja <b>kata kerja bentuk kamus＋には当たらない＝tidak perlu ～</b>.<br>・Kalau diterjemahkan \"tidak pantas ～\" atau \"tidak layak ～\", orang bisa salah paham seolah-olah artinya \"hal itu tidak berharga\". Makna sebenarnya adalah \"reaksi seperti itu tidak perlu dan tidak masuk akal\", jadi \"tidak perlu ～\" lebih tepat.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>には及ばない</b>＝tidak perlu repot-repot melakukan (sering bernada perhatian, diucapkan kepada lawan bicara)<br>Situasi: bawahan membuat kesalahan kecil.<br>Atasan berkata kepada bawahan: <span class='gd-jp'>わざわざ謝りに来るには及ばないよ。</span> (Tidak perlu repot-repot datang untuk minta maaf.)<br>Rekan kerja mengomentari kejadian itu: <span class='gd-jp'>一度のミスで、そこまで彼を責めるには当たらない。</span> (Baru sekali salah, tidak perlu menyalahkannya sampai segitunya.)</div><div class='gd-sec'><b>に足りない</b>＝objeknya sendiri bobotnya kurang, tidak cukup untuk ～<br>Situasi: besok ada pertandingan.<br><span class='gd-jp'>あんな相手は恐れるに足りない。</span> (Lawan seperti itu tidak perlu ditakuti: intinya lawannya terlalu lemah.)<br><span class='gd-jp'>初めての試合だからといって、恐れるには当たらない。</span> (Meski ini pertandingan pertama, tidak perlu takut: intinya rasa takut itu tidak ada gunanya.)</div><div class='gd-warn'>Trik membedakan: untuk bilang \"reaksi itu tidak perlu\", pakai には当たらない; untuk bilang \"tidak perlu repot-repot melakukannya\", pakai には及ばない; untuk bilang \"objeknya sendiri tidak berbobot\", pakai に足りない.</div>","n1-62":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜がてら」artinya <b>「sekalian ～」「sambil ～」</b>. Kamu keluar rumah sekali jalan, dan dua urusan beres sekaligus: jalan-jalan sambil beli roti, atau mengantar teman ke stasiun sambil ngobrol. Intinya, <b>satu tindakan punya dua tujuan sekaligus</b>, seperti sekali dayung dua tiga pulau terlampaui.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Kata benda＋がてら</span>Ini yang paling umum. Di depannya ada kata benda yang berupa \"tindakan\", seperti <span class='gd-jp'>散歩</span>, <span class='gd-jp'>買い物</span>, <span class='gd-jp'>見物</span> (melihat-lihat tempat wisata), <span class='gd-jp'>運動</span>, <span class='gd-jp'>ドライブ</span>.<br><span class='gd-pair'><span class='gd-jp'>散歩</span> → <span class='gd-jp'>散歩がてら</span></span> (sambil jalan-jalan)</div><div class='gd-ex-line'>・<span class='gd-jp'>散歩がてら、パンを買ってきた。</span>(Sambil jalan-jalan, aku sekalian beli roti.)</div><div class='gd-ex-line'>・<span class='gd-jp'>花見がてら、久しぶりに実家に帰った。</span>(Aku pulang ke rumah orang tua yang sudah lama tidak kukunjungi, sekalian melihat bunga sakura.)</div><div class='gd-sec'><span class='gd-tag'>Bentuk ます＋がてら</span>Untuk kata kerja, buang「ます」lalu langsung tambahkan がてら.<br><span class='gd-pair'><span class='gd-jp'>送ります</span> → buang ます → <span class='gd-jp'>送りがてら</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで送りがてら、ちょっと話そうか。</span>(Aku antar sampai stasiun ya, sekalian ngobrol sebentar.)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'>Kalimat di belakangnya biasanya berupa tindakan <b>berpindah tempat atau keluar rumah</b>, seperti <span class='gd-jp'>行く</span>, <span class='gd-jp'>来る</span>, <span class='gd-jp'>寄る</span> (mampir), <span class='gd-jp'>歩く</span>, <span class='gd-jp'>出かける</span>. Soalnya \"sekalian\" memang berarti \"toh sudah keluar, ya sekalian saja\".</div><div class='gd-ex-line'>・<span class='gd-jp'>運動がてら、一駅歩いて帰った。</span>(Sekalian olahraga, aku jalan kaki satu stasiun lalu pulang.)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Di depannya harus ada <b>tindakan</b>. <span class='gd-jp'>散歩がてら</span> boleh, tapi kata yang bukan tindakan seperti 「雨がてら」「休みがてら」tidak bisa dipakai.<br>・Kedua hal itu harus dilakukan oleh <b>orang yang sama</b>.<br>・Ini bukan bahasa tulis. Dalam obrolan sehari-hari pun sering terdengar, hanya sedikit lebih dewasa daripada <span class='gd-jp'>ついでに</span>.<br>・Yang dibahas adalah hal yang dilakukan sekalian pada <b>kesempatan kali ini</b>, bukan dua hal yang dijalani bersamaan dalam jangka panjang. Untuk jangka panjang, pakai <span class='gd-jp'>かたわら</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama \"pergi belanja, sekalian mampir ke kantor pos\":<br><b>ついでに</b>＝paling kasual dan paling praktis; tujuan utamanya belanja, kantor pos hanya tambahan: <span class='gd-jp'>買い物のついでに、郵便局に寄った。</span><br><b>がてら</b>＝satu kali keluar dengan dua tujuan: <span class='gd-jp'>買い物がてら、郵便局に寄った。</span></div><div class='gd-sec'><b>かたがた</b>＝sangat formal, banyak dipakai untuk kunjungan dan salam, sering muncul dalam situasi bisnis atau surat: <span class='gd-jp'>お礼かたがた、ご挨拶に伺いました。</span> (Saya datang untuk berterima kasih, sekalian menyampaikan salam.)<br><b>かたわら</b>＝dalam jangka panjang, menjalankan pekerjaan utama sambil mengerjakan hal lain: <span class='gd-jp'>会社に勤めるかたわら、小説を書いている。</span> (Sambil bekerja di kantor, dia menulis novel.)<br><b>ながら</b>＝dua gerakan dilakukan pada waktu yang sama: <span class='gd-jp'>歩きながら電話する。</span> (Menelepon sambil berjalan.)</div><div class='gd-warn'>Trik membedakan: untuk \"sekalian\" sehari-hari, pakai ついでに atau がてら; untuk kunjungan atau salam kepada klien atau orang yang lebih tua, pakai かたがた; untuk dua hal yang dijalani bersamaan dalam jangka panjang, pakai かたわら; untuk dua gerakan tubuh pada saat yang sama, pakai ながら.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Lanjut lihat <span class='gd-jp'>〜かたがた</span> dan <span class='gd-jp'>〜かたわら</span>. Hafalkan ketiganya bersama, dan soal pilihan ganda di ujian akan jauh lebih mudah dibedakan.</div>","n1-53":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜べからず」itu seperti tulisan di papan pengumuman: <b>「dilarang ～」「tidak boleh ～」「jangan ～」</b>. Ini ragam bahasa klasik, kesannya mirip tulisan «Dilarang Masuk» atau «Dilarang Berisik», yaitu kaku dan formal. Hampir tidak dipakai dalam percakapan sehari-hari. Kamu paling sering menemukannya di <b>papan pengumuman, slogan, dan pepatah</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Papan pengumuman</span>Aturan larangan yang ditulis untuk dibaca semua orang, ditaruh di akhir kalimat.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに入るべからず。</span>(Dilarang masuk ke sini)</div><div class='gd-ex-line'>・<span class='gd-jp'>ここにごみを捨てるべからず。</span>(Dilarang membuang sampah di sini)</div><div class='gd-sec'><span class='gd-tag'>Pepatah・slogan</span>Banyak pepatah lama dan kata mutiara memakai bentuk ini. Hafalkan saja satu kalimat utuhnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>働かざる者食うべからず。</span>(Orang yang tidak bekerja tidak pantas makan)</div><div class='gd-ex-line'>・<span class='gd-jp'>初心忘るべからず。</span>(Jangan lupakan niat awal)</div><div class='gd-sec'><span class='gd-tag'>べからざる＋kata benda</span>Kalau di belakangnya ada kata benda, ganti jadi <b>べからざる</b>. Artinya「(hal) yang tidak boleh ～」, sering muncul di tulisan dan berita.</div><div class='gd-ex-line'>・<span class='gd-jp'>水は生活に欠くべからざるものだ。</span>(Air adalah sesuatu yang tak boleh tidak ada dalam kehidupan)</div><div class='gd-ex-line'>・<span class='gd-jp'>それは許すべからざる行為だ。</span>(Itu perbuatan yang tidak bisa dimaafkan)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja pakai <b>bentuk kamus</b> (bentuk dasar yang kamu temukan di kamus), lalu langsung tambahkan:<br><span class='gd-pair'><span class='gd-jp'>入る</span> → <span class='gd-jp'>入るべからず</span></span><span class='gd-pair'><span class='gd-jp'>捨てる</span> → <span class='gd-jp'>捨てるべからず</span></span><br><b>する</b> biasanya berubah jadi <b>す</b> dulu, baru disambung: <span class='gd-pair'><span class='gd-jp'>駐車する</span> → <span class='gd-jp'>駐車すべからず</span></span> (bentuk するべからず juga ada, tapi すべからず lebih asli)<br>Untuk menerangkan kata benda, ganti ず jadi ざる: <span class='gd-pair'><span class='gd-jp'>欠くべからず</span> → <span class='gd-jp'>欠くべからざるもの</span></span></div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Di akhir kalimat pakai <b>べからず</b>, di depan kata benda pakai <b>べからざる</b>. Jangan tulis「べからずもの」.<br>・Bentuk ini hanya untuk tulisan di papan atau di teks, <b>tidak bisa dipakai untuk melarang orang secara langsung</b>. Kalau kamu bilang 「吸うべからず」ke temanmu, kedengarannya aneh. Dalam percakapan pakai <span class='gd-jp'>吸わないで</span> atau <span class='gd-jp'>吸っちゃだめ</span>.<br>・Tidak bisa disambung dengan bentuk ない. 「行かないべからず」salah, karena べからず sendiri sudah berarti「tidak boleh」.<br>・「忘る」dalam <span class='gd-jp'>初心忘るべからず</span> adalah bentuk dasar klasik dari <span class='gd-jp'>忘れる</span>. Ini ungkapan tetap, jadi hafalkan apa adanya dan jangan diubah sendiri.<br>・<span class='gd-jp'>すべからく</span> kelihatannya mirip, tapi itu kata lain. Artinya「seharusnya, sudah semestinya」, bukan bentuk negatif.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'>Kita pakai situasi yang sama, yaitu「merokok」:<br><b>べからず</b> = <b>aturan larangan</b> di papan pengumuman: <span class='gd-jp'>ここでたばこを吸うべからず。</span>(Dilarang merokok di sini)<br><b>べきではない</b> = <b>menasihati</b> bahwa「tidak seharusnya」. Bisa dipakai dalam percakapan maupun tulisan: <span class='gd-jp'>ここでたばこを吸うべきではない。</span>(Tidak seharusnya merokok di sini)<br><b>まじき</b> = tidak pantas untuk <b>status</b> orang itu: <span class='gd-jp'>患者の前でたばこを吸うなんて、医者にあるまじき行為だ。</span>(Merokok di depan pasien adalah perbuatan yang tidak pantas bagi seorang dokter)</div><div class='gd-sec'>Selain itu, <b>べく</b> cuma mirip penampilannya, artinya sama sekali berbeda, yaitu「demi ～ / agar ～」: <span class='gd-jp'>合格すべく、毎日勉強している。</span>(Agar lulus, aku belajar setiap hari)</div><div class='gd-warn'>Tips membedakan: kalau「larangan」di papan pengumuman atau pepatah, pakai べからず. Kalau menasihati「tidak seharusnya」, pakai べきではない. Kalau menyangkut「sebagai ～」, pakai まじき. Kalau「demi ～」, itu べく.</div>","n1-55":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜たる」kira-kira sama dengan <b>「sebagai ～」</b>, nuansanya mirip «sebagai guru» atau «sebagai orang tua». Kamu angkat dulu sebuah status yang punya bobot, lalu lanjutkan dengan «orang dengan status ini <b>seharusnya</b> begini».<br><span class='gd-jp'>たる</span> adalah ungkapan yang sangat lama, artinya sama dengan <span class='gd-jp'>である</span>, dan khusus dipakai di depan kata benda. Karena itu kedengarannya sangat formal dan berwibawa, dan biasanya muncul di tulisan, pidato, atau ceramah.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋たる＋kata benda. Yang paling sering, di belakangnya ada <span class='gd-jp'>者</span> (sering juga ditulis <span class='gd-jp'>もの</span>, artinya sama-sama「orang」):<br><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者たる者</span></span> (orang yang berstatus dokter)<br><span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親たるもの</span></span> (orang yang berstatus orang tua)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Menyatakan apa yang seharusnya</span>Ini pemakaian terbanyak. Di belakangnya sering ada <span class='gd-jp'>べきだ</span>, <span class='gd-jp'>なければならない</span>, atau <span class='gd-jp'>てはならない</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>医者たる者、患者の話をよく聞くべきだ。</span>(Sebagai dokter, seharusnya mendengarkan cerita pasien dengan baik)</div><div class='gd-ex-line'>・<span class='gd-jp'>プロたる者、言い訳はしない。</span>(Sebagai profesional, tidak mencari alasan)</div><div class='gd-sec'><span class='gd-tag'>Mengkritik yang tidak dilakukan</span>Angkat dulu statusnya, lalu katakan bahwa orang itu malah melakukan hal yang tidak pantas.</div><div class='gd-ex-line'>・<span class='gd-jp'>教師たる者が生徒にうそをつくなんて、許されることではない。</span>(Seorang guru berbohong kepada muridnya itu tidak bisa dimaafkan)</div><div class='gd-sec'><span class='gd-tag'>Disambung kata benda lain</span>Di belakangnya tidak harus 者, bisa juga kata benda seperti「資格」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼に代表たる資格はない。</span>(Dia tidak punya kualifikasi untuk menjadi perwakilan)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Di depannya hanya bisa <b>kata benda</b>, dan biasanya yang menunjukkan status, jabatan, atau posisi, yaitu kata yang membawa「tanggung jawab」. Tidak bisa disambung dengan kata kerja atau kata sifat.<br>・Ini bukan た (bentuk lampau) ditambah る. <span class='gd-jp'>たる</span> secara utuh adalah satu kata, jadi jangan dipisah-pisah.<br>・Kesannya sangat kaku. Dipakai dalam obrolan sehari-hari, kedengarannya seperti sedang menceramahi. Untuk percakapan, 「sebagai ～ seharusnya ～」cukup pakai <span class='gd-jp'>〜なんだから</span>: <span class='gd-jp'>先生なんだから、ちゃんとしてよ。</span>(Kamu kan guru, yang serius dong)<br>・Jangan campur dengan <span class='gd-jp'>足る</span> (layak, pantas) yang bunyinya sama. Perbedaannya dibahas di bawah.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'>Kita pakai contoh yang sama, yaitu guru:<br><b>たる者</b> = angkat statusnya dulu, lalu bilang apa yang seharusnya (atau mengkritik karena tidak dilakukan): <span class='gd-jp'>教師たる者、生徒の手本であるべきだ。</span>(Sebagai guru, seharusnya menjadi teladan bagi murid)<br><b>にあるまじき</b> = langsung menilai suatu <b>perbuatan atau ucapan</b> sebagai「hal yang tidak pantas bagi status ini」. Di belakangnya ada kata benda seperti <span class='gd-jp'>行為</span> atau <span class='gd-jp'>発言</span>: <span class='gd-jp'>教師にあるまじき発言だ。</span>(Ini ucapan yang tidak pantas bagi seorang guru)<br><b>ともなれば</b> = kalau sudah sampai tingkat itu, <b>otomatis</b> ～. Ini menyatakan hasil yang wajar, bukan kewajiban: <span class='gd-jp'>ベテラン教師ともなれば、生徒の顔を見ただけで悩みに気づく。</span>(Kalau sudah level guru senior, hanya dengan melihat wajah murid sudah tahu dia punya masalah)<br><b>に足る</b> = <b>layak</b> ～. Di depannya ada kata seperti <span class='gd-jp'>信頼</span> atau <span class='gd-jp'>尊敬</span>, dan ada tambahan <span class='gd-jp'>に</span>: <span class='gd-jp'>彼は信頼に足る教師だ。</span>(Dia guru yang layak dipercaya)</div><div class='gd-warn'>Tips membedakan: untuk bilang「sebagai ～ seharusnya begini」atau「sebagai ～ kok malah…」, angkat dulu statusnya dengan たる(者). Untuk langsung menilai suatu perbuatan sebagai「tidak pantas bagi seorang ～」, pakai「～にあるまじき＋行為／発言」. Untuk「kalau sudah sampai level itu, otomatis ～」, pakai ともなれば. Untuk「layak ～」, pakai に足る.</div><div class='gd-h'>Lanjut belajar setelah ini</div><div class='gd-sec'><span class='gd-jp'>〜まじき</span> (tidak pantas ～) yang juga dipakai untuk menilai status, serta <span class='gd-jp'>〜ともなれば</span> yang berarti「kalau sudah sampai level itu」, bisa kamu hafalkan sekalian.</div>","n1-56":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜なくして（は）」artinya <b>「tanpa ～, mustahil …」</b>. Di depan kamu taruh sesuatu yang sangat penting, lalu di belakang bilang \"kalau tidak ada itu, hal tersebut sama sekali tidak mungkin terwujud\". Pola ini dipakai untuk menekankan bahwa <b>hal itu mutlak tidak boleh kurang</b>. Nuansanya sangat formal, biasanya muncul dalam tulisan, pidato, atau pidato penerimaan penghargaan.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Nomina langsung diikuti なくして, <b>tanpa menyisipkan「が」atau「を」</b>:<br><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力なくして</span></span><span class='gd-pair'><span class='gd-jp'>協力</span> → <span class='gd-jp'>協力なくしては</span></span><br>Di belakangnya harus ada ungkapan \"mustahil / tidak bisa\". Yang paling umum adalah <span class='gd-jp'>あり得ない</span> (tidak mungkin ada), <span class='gd-jp'>できない</span>, dan <span class='gd-jp'>語れない</span> (tidak bisa dibicarakan).<br>Kalau yang ditaruh di depan adalah sebuah tindakan, pakai \"bentuk kamus＋ことなくして\": <span class='gd-pair'><span class='gd-jp'>苦労する</span> → <span class='gd-jp'>苦労することなくして</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menjelaskan syarat</span>Menjelaskan syarat yang tidak boleh kurang di balik sebuah keberhasilan atau hasil.</div><div class='gd-ex-line'>・<span class='gd-jp'>日々の努力なくして成功はあり得ない。</span>（Tanpa usaha setiap hari, mustahil sukses）</div><div class='gd-ex-line'>・<span class='gd-jp'>信頼関係なくして、いいチームは作れない。</span>（Tanpa rasa saling percaya, tidak mungkin terbentuk tim yang bagus）</div><div class='gd-ex-line'>・<span class='gd-jp'>苦労することなくして、本当の喜びは味わえない。</span>（Tanpa bersusah payah, kita tidak akan merasakan kebahagiaan yang sejati）</div><div class='gd-sec'><span class='gd-tag'>Ucapan terima kasih</span>Menoleh ke belakang dan berkata \"dulu tanpa kalian, ini tidak akan berhasil\". Bagian akhirnya sering memakai bentuk lampau.</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご協力なくしては、このプロジェクトは成功しませんでした。</span>（Tanpa bantuan Anda sekalian, proyek ini tidak akan berhasil）</div><div class='gd-sec'><span class='gd-tag'>Penilaian</span>Mengatakan bahwa posisi seseorang atau sesuatu begitu penting sampai tidak bisa tidak disebut.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の存在なくして、日本のサッカーの歴史は語れない。</span>（Kalau bicara sejarah sepak bola Jepang, kita tidak bisa melewatkan dia）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Bagian belakang harus berupa makna \"mustahil / tidak bisa\". Kamu <b>tidak boleh</b> bilang「努力なくして成功した」, karena itu bertentangan dengan dirinya sendiri.<br>・Jangan tambahkan「を」: <span class='gd-jp'>財布をなくして困った</span> artinya \"dompetku hilang dan aku jadi repot\". Itu adalah kata kerja <span class='gd-jp'>なくす</span> (menghilangkan), tidak ada hubungannya dengan pola ini.<br>・Yang ditaruh di depan harus hal yang <b>benar-benar penting</b>, seperti usaha, cinta, bantuan, atau kepercayaan. Kalau dipakai untuk hal sepele seperti payung, kedengarannya berlebihan. Dalam keseharian, cukup bilang <span class='gd-jp'>傘がないと出かけられない</span>.<br>・Pola ini sangat kaku dan tidak dipakai saat ngobrol dengan teman. Dalam percakapan, cukup pakai「〜がなかったら、〜できない」.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama untuk berterima kasih atas bantuan semua orang:<br><b>なくしては</b>＝tanpa ～ tidak bisa (paling formal): <span class='gd-jp'>皆様の協力なくしては、成功できませんでした。</span><br><b>なしには</b>＝maknanya hampir sama, tapi sedikit kurang kaku: <span class='gd-jp'>皆様の協力なしには、成功できませんでした。</span><br><b>あっての</b>＝dibalik, \"karena ada A, maka ada B\": <span class='gd-jp'>皆様の協力あっての成功でした。</span>（Keberhasilan ini ada berkat bantuan semuanya）</div><div class='gd-sec'>Perlu diingat, 「なしに」tanpa は masih bisa sekadar berarti \"melakukan ～ tanpa didahului ...\": <span class='gd-jp'>連絡なしに休んだ。</span>（Dia tidak masuk tanpa memberi kabar dulu）<br>なくして tidak punya penggunaan seperti ini. Ia hanya dipakai untuk makna \"tanpa itu, tidak mungkin\".</div><div class='gd-warn'>Trik cepat: kalau di belakang ada makna \"mustahil / tidak bisa\", なくして dan なしには sama-sama bisa dipakai, hanya なくして lebih formal. Kalau di belakang maknanya \"langsung melakukan begitu saja\", hanya なしに yang bisa. Kalau mau mengatakannya dari sisi \"ada\", pakai あっての.</div><div class='gd-h'>Yang bisa dipelajari berikutnya</div><div class='gd-sec'>「〜あっての」(karena ada A, maka ada B) adalah kebalikan dari なくして. Menghafal keduanya sekaligus paling praktis: <span class='gd-jp'>お客様あっての商売だ。</span>（Bisnis ada karena ada pelanggan）</div>","n1-57":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「にして」adalah <b>bahasa tulis</b> yang sangat kaku, mirip gaya bahasa baku dalam bahasa Indonesia seperti \"baru pada usia ...\", \"dalam sekejap\", atau \"sekaligus\". Ada tiga arti yang umum: <b>「baru ketika sampai ～」</b> (termasuk \"hanya ～ yang bisa\"), <b>「dalam sekejap」</b>, dan <b>「sekaligus ～ dan ～」</b>. Dua yang pertama sering mengandung nuansa kagum seperti \"hebat ya / tak disangka\". Arti \"sekaligus\" hanya menyandingkan dua status atau sifat dengan nada formal dan tegas, jadi tidak selalu mengandung rasa terkejut.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Pada dasarnya dipasang setelah nomina: <span class='gd-pair'><span class='gd-jp'>50歳</span> → <span class='gd-jp'>50歳にして</span></span><br>Untuk makna \"sekaligus\", pola ini juga sering dipasang setelah adjektiva-な (adjektiva yang diikuti な seperti <span class='gd-jp'>簡潔な</span>). Hilangkan な, lalu sambungkan: <span class='gd-pair'><span class='gd-jp'>簡潔な</span> → <span class='gd-jp'>簡潔にして</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Baru ketika sampai ～</span>Di depan taruh \"tahap\" seperti usia, percobaan ke berapa, atau tahun ke berapa. Di belakang sering muncul <span class='gd-jp'>初めて</span> atau <span class='gd-jp'>ようやく</span>, yang berarti \"setelah menempuh sejauh ini, akhirnya ...\".</div><div class='gd-ex-line'>・<span class='gd-jp'>三度目の挑戦にして、ようやく合格した。</span>（Pada percobaan ketiga, akhirnya dia lulus）</div><div class='gd-ex-line'>・<span class='gd-jp'>50歳にして初めて海外に行った。</span>（Baru pada usia 50 tahun, dia pertama kali pergi ke luar negeri）</div><div class='gd-sec'>Kalau di belakang dipasang <span class='gd-jp'>なお</span>, artinya jadi \"sudah sampai tahap ini pun masih ...\":</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は90歳にしてなお現役の医者だ。</span>（Dia sudah berusia 90 tahun, tapi masih aktif praktik sebagai dokter）</div><div class='gd-sec'><span class='gd-tag'>Hanya ～ yang bisa</span>Di depan taruh orang, artinya \"hanya orang seperti itu yang bisa\". Sering ditulis sebagai「〜にして初めて」.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは彼にして初めてできる仕事だ。</span>（Ini pekerjaan yang hanya bisa dilakukan olehnya）</div><div class='gd-ex-line'>・<span class='gd-jp'>この親にしてこの子あり。</span>（Buah jatuh tak jauh dari pohonnya）</div><div class='gd-sec'><span class='gd-tag'>Dalam sekejap</span>Dipasang setelah waktu yang sangat singkat seperti <span class='gd-jp'>一瞬</span> atau <span class='gd-jp'>一夜</span>, artinya \"dalam sekejap mata langsung ...\". Dalam percakapan, orang langsung bilang <span class='gd-jp'>一瞬で</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>町は一瞬にして炎に包まれた。</span>（Seluruh kota diselimuti api dalam sekejap）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は一夜にしてスターになった。</span>（Dalam semalam dia menjadi bintang）</div><div class='gd-sec'><span class='gd-tag'>Sekaligus ～ dan ～</span>「AにしてB」＝memiliki A dan B sekaligus. Maknanya sama dengan「で」: <span class='gd-jp'>医者で作家</span> adalah cara bicara biasa, sedangkan <span class='gd-jp'>医者にして作家</span> adalah gaya tulis yang formal.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者にして作家でもある。</span>（Dia seorang dokter sekaligus penulis）</div><div class='gd-ex-line'>・<span class='gd-jp'>説明は簡潔にして明快だった。</span>（Penjelasannya ringkas sekaligus jelas）</div><div class='gd-sec'>Selain itu, <span class='gd-jp'>幸いにして</span> (untungnya) dan <span class='gd-jp'>不幸にして</span> (sayangnya) adalah ungkapan tetap. Hafalkan saja sebagai satu kata:<br><span class='gd-jp'>幸いにして、けが人はいなかった。</span>（Untungnya, tidak ada korban luka）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Untuk makna \"baru ketika sampai ～\", di depan harus ada <b>tahap kehidupan atau jumlah kali</b> (usia, percobaan ke berapa, tahun ke berapa). Kamu tidak bisa asal menaruh jam, jadi「3時にして」itu salah.<br>・Ini bahasa untuk tulisan, pidato, dan berita. Kalau dipakai ngobrol dengan teman, kedengarannya dibuat-buat. Dalam percakapan, cukup pakai「で」atau「〜歳で初めて」.<br>・Saat dipasang setelah adjektiva-な, hilangkan な: yang benar <span class='gd-jp'>簡潔にして</span>, bukan「簡潔なにして」.<br>・Jangan tertukar dengan bentuk-て dari「〜にする」: <span class='gd-jp'>ジュースにして飲む</span> artinya \"dijadikan jus lalu diminum\", tidak ada hubungannya dengan pola ini. Lihat konteks kalimatnya untuk membedakan.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>にして</b>＝suatu hal <b>baru</b> terjadi ketika sampai tahap ini:<br><span class='gd-jp'>50歳にして初めてパソコンを買った。</span>（Baru pada usia 50 tahun, dia pertama kali membeli komputer）<br><b>にしては</b>＝\"untuk ukuran ～, tergolong cukup ...\", yaitu menilai sesuatu yang berbeda dari kesan umum:<br><span class='gd-jp'>50歳にしては体力がある。</span>（Untuk ukuran usia 50 tahun, staminanya tergolong bagus）</div><div class='gd-warn'>Trik cepat: kalau di belakang ada「初めて／ようやく／なお」yang menyatakan sesuatu akhirnya terjadi atau masih tetap begitu, itu にして. Kalau di belakang menilai \"dibandingkan umumnya bagaimana\", itu にしては. Dengan tambahan satu「は」, artinya sudah sangat berbeda.</div>","n1-64":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ずくめ」mirip dengan <b>“serba ~”</b> atau <b>“penuh dengan ~”</b> dalam bahasa Indonesia, seperti “serba hitam”. Kalau dilihat dari awal sampai akhir, semuanya didominasi satu jenis hal yang sama. Contohnya: berpakaian serba hitam, setahun penuh kabar baik yang datang terus, atau aturan begitu banyak sampai kamu diatur di mana-mana.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Nomina langsung diberi ずくめ, semudah itu.<br><span class='gd-pair'><span class='gd-jp'>黒</span> → <span class='gd-jp'>黒ずくめ</span></span><span class='gd-pair'><span class='gd-jp'>いいこと</span> → <span class='gd-jp'>いいことずくめ</span></span><span class='gd-pair'><span class='gd-jp'>規則</span> → <span class='gd-jp'>規則ずくめ</span></span><br>Setelah tersambung, cara pakainya sama seperti nomina biasa:<br>Kalau diikuti nomina, tambahkan「の」：<span class='gd-jp'>黒ずくめの男</span>（pria yang berpakaian serba hitam）<br>Di akhir kalimat, tambahkan「だ」：<span class='gd-jp'>いいことずくめだ</span><br>Kalau kalimat belum selesai, pakai「で」：<span class='gd-jp'>規則ずくめで、疲れる</span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>ずくめ<b>tidak bisa dipasang ke sembarang nomina</b>. Orang Jepang biasanya memakai beberapa kombinasi tetap saja, jadi hafalkan dulu yang di bawah ini.</div><div class='gd-sec'><span class='gd-tag'>Warna, pakaian</span>Seluruh tubuh berwarna sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>黒ずくめの男が店に入ってきた。</span>（Seorang pria berpakaian serba hitam masuk ke toko）</div><div class='gd-sec'><span class='gd-tag'>Hal baik</span>Hal baik datang satu demi satu.</div><div class='gd-ex-line'>・<span class='gd-jp'>今年は結婚に昇進に、いいことずくめだった。</span>（Tahun ini menikah, lalu naik jabatan, pokoknya serba baik）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行中はごちそうずくめで、3キロも太った。</span>（Selama liburan makannya serba hidangan mewah, berat badanku naik sampai 3 kilo）</div><div class='gd-sec'><span class='gd-tag'>Aturan, batasan</span>Diatur di mana-mana, biasanya dengan nuansa kesal karena merasa terikat erat.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの会社は規則ずくめで、息が詰まる。</span>（Perusahaan kami penuh aturan, sampai sesak rasanya）</div><div class='gd-sec'><span class='gd-tag'>Sering di berita</span>Dipakai untuk menggambarkan hal yang banyak sekali bedanya dari biasanya.</div><div class='gd-ex-line'>・<span class='gd-jp'>今回の大会は異例ずくめだった。</span>（Turnamen kali ini penuh hal di luar kebiasaan）</div><div class='gd-sec'>Dari contoh di atas kelihatan bahwa ずくめ<b>sendiri tidak menentukan baik atau buruk</b>. Intinya hanya “keseluruhannya seragam”. <span class='gd-jp'>黒ずくめ</span> netral, <span class='gd-jp'>いいことずくめ</span> positif, dan <span class='gd-jp'>規則ずくめ</span> cenderung negatif.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Hanya bisa dipasang ke <b>nomina</b>. Kalau mau bilang “semuanya enak”, pakai <span class='gd-jp'>美味しいものずくめ</span> atau <span class='gd-jp'>ごちそうずくめ</span>. Adjektiva tidak bisa langsung disambung, jadi 美味しいずくめ itu salah.<br>・<b>Kotoran yang menempel di badan</b> tidak memakai ずくめ. “Badan penuh lumpur” adalah <span class='gd-jp'>泥まみれ</span>, bukan 泥ずくめ. “Basah kuyup oleh keringat” adalah <span class='gd-jp'>汗まみれ</span>.<br>・<span class='gd-jp'>結構ずくめ</span>（syaratnya begitu bagus sampai tak ada celah）sering terdengar agak curiga: <span class='gd-jp'>結構ずくめの話には気をつけたほうがいい。</span>（Sebaiknya waspada dengan tawaran yang isinya serba menguntungkan）<br>・Kadang kamu akan melihat tulisan「づくめ」. Itu hal yang sama, tapi sekarang umumnya ditulis ずくめ.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama membicarakan satu pakaian, lihat apa bedanya ketiga ungkapan ini:<br><b>ずくめ</b>＝keseluruhannya seragam: <span class='gd-jp'>黒ずくめの服</span>（dari atas sampai bawah serba hitam）<br><b>まみれ</b>＝permukaan tertutup cairan atau serbuk yang menempel, hampir selalu negatif: <span class='gd-jp'>泥まみれの服</span>（pakaian berlumuran lumpur）<br><b>だらけ</b>＝sesuatu begitu banyak sampai ada di mana-mana, kebanyakan hal yang tidak baik: <span class='gd-jp'>しわだらけの服</span>（pakaian penuh kerutan）</div><div class='gd-warn'>Kunci cepat: keseluruhan seragam (pakaian, hal baik, aturan, dan kombinasi tetap lainnya) → ずくめ; menempel di permukaan dan menutupi seluruhnya → まみれ; jumlahnya banyak sampai ada di mana-mana → だらけ.</div>","n1-63":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜まみれ」setara dengan <b>“berlumuran ~”</b>, <b>“bersimbah ~”</b>, atau <b>“penuh ~ di badan”</b>, seperti “berlumuran lumpur”, “bersimbah keringat”, “berlumur darah”. Intinya, hal seperti lumpur, keringat, darah, atau debu <b>menempel di permukaan dan menutupi seluruhnya</b>, dan biasanya berupa sesuatu yang kotor atau tidak menyenangkan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Tubuh atau benda penuh kotoran</span>Pemakaian paling dasar. Kata yang sering muncul bersamanya: <span class='gd-jp'>泥</span>、<span class='gd-jp'>汗</span>、<span class='gd-jp'>血</span>、<span class='gd-jp'>ほこり</span>（debu）、<span class='gd-jp'>油</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>泥まみれになって、子供と遊んだ。</span>（Bermain dengan anak-anak sampai badan berlumuran lumpur）</div><div class='gd-ex-line'>・<span class='gd-jp'>汗まみれで家に帰ってきた。</span>（Pulang ke rumah dengan bersimbah keringat）</div><div class='gd-ex-line'>・<span class='gd-jp'>倉庫からほこりまみれのアルバムが出てきた。</span>（Dari gudang ditemukan sebuah album yang penuh debu）</div><div class='gd-sec'><span class='gd-tag'>Kiasan: terbelit hal buruk</span>Bisa juga dipakai untuk hal abstrak, seperti terbungkus utang atau kebohongan sampai tidak bisa lepas.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は借金まみれだ。</span>（Dia terlilit utang di mana-mana）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人の話は嘘まみれだ。</span>（Omongan orang itu isinya bohong semua）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Sangat mudah, <b>nomina langsung ditambah まみれ</b>：<span class='gd-pair'><span class='gd-jp'>泥</span> → <span class='gd-jp'>泥まみれ</span></span><br>Setelah tersambung, anggap saja sebagai nomina. Bentuk yang paling umum:<br>・<span class='gd-jp'>〜まみれになる</span>：menjadi penuh ～ di sekujur badan<br>・<span class='gd-jp'>〜まみれだ</span>：（sekarang）penuh ～<br>・<span class='gd-jp'>〜まみれで</span>：dalam keadaan penuh ～（lalu melakukan sesuatu）<br>・<span class='gd-jp'>〜まみれの＋名詞</span>：（benda）yang berlumuran ～　Contoh: <span class='gd-jp'>血まみれのシャツ</span>（kemeja berlumur darah）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・まみれ punya kesan “<b>menempel dan melekat di permukaan</b>”, jadi jangan dipakai untuk hal yang cuma “jumlahnya banyak”. Untuk orang yang banyak, bilang <span class='gd-jp'>人でいっぱい</span> atau <span class='gd-jp'>人だらけ</span>, bukan 人まみれ.<br>・Luka atau salah ketik bukan sesuatu yang “menempel”, jadi biasanya pakai <span class='gd-jp'>だらけ</span>：<span class='gd-jp'>傷だらけ</span>、<span class='gd-jp'>間違いだらけ</span>。<br>・Nuansanya negatif. Hal baik atau benda indah umumnya tidak memakai まみれ. Untuk arti positif seperti “penuh bunga” atau “penuh kebahagiaan”, kamu perlu ungkapan lain.<br>・Kalau diikuti nomina, tambahkan「の」: yang benar <span class='gd-jp'>血まみれのシャツ</span>, bukan 血まみれシャツ.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>だらけ</b>＝<b>banyak, ada di mana-mana</b>（fokusnya jumlah yang banyak dan tersebar di mana-mana）：<span class='gd-jp'>この作文は間違いだらけだ。</span>（Karangan ini penuh kesalahan）<br><b>まみれ</b>＝<b>berlumuran, menempel menutupi permukaan</b>（fokusnya tertutup cairan atau serbuk）：<span class='gd-jp'>顔が汗まみれだ。</span>（Wajahnya bersimbah keringat）<br>Untuk lumpur, keringat, dan darah, keduanya bisa dipakai: <span class='gd-jp'>泥だらけ</span> dan <span class='gd-jp'>泥まみれ</span> sama-sama benar, hanya saja まみれ memberi gambaran “menempel tebal” yang lebih kuat.</div><div class='gd-sec'><b>ずくめ</b>＝<b>seragam dari awal sampai akhir</b>（tidak selalu negatif, bisa juga hal baik）：<span class='gd-jp'>黒ずくめの服</span>（penampilan serba hitam）、<span class='gd-jp'>いいことずくめ</span>（serba hal baik）<br>Sedangkan <b>まみれ</b> berarti tertutup kotoran: <span class='gd-jp'>泥まみれの服</span>（pakaian berlumuran lumpur）</div><div class='gd-warn'>Kunci cepat: menempel di badan dan menutupi → まみれ; jumlahnya banyak, ada di mana-mana → だらけ; seragam, semuanya sama → ずくめ.</div><div class='gd-h'>Setelah ini, pelajari juga</div><div class='gd-sec'><span class='gd-jp'>〜ずくめ</span>（serba ～, penuh ～）sering dibandingkan dengan pola ini. Lihat sekalian, karena kalau dihafal berdua, kamu paling tidak akan tertukar.</div>","n1-1":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に至っては」kira-kira berarti <b>「apalagi kalau soal ～, malah lebih parah…」「～ lebih ekstrem lagi, sampai-sampai…」</b>. Pertama kamu bilang keadaan semua orang atau keseluruhannya, lalu kamu pilih <b>satu hal yang paling ekstrem</b> dan sebutkan khusus.<br>Seperti saat kamu mengeluh: \"Di rumahku semua orang susah bangun pagi, <b>apalagi ayahku, lebih parah lagi</b>, tidurnya sampai siang tidak bangun-bangun.\"</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋に至っては.<br><span class='gd-pair'><span class='gd-jp'>父</span> → <span class='gd-jp'>父に至っては</span></span><span class='gd-pair'><span class='gd-jp'>数学</span> → <span class='gd-jp'>数学に至っては</span></span><br>Pola kalimat utuhnya biasanya: <b>keadaan secara keseluruhan → 〇〇に至っては → hal yang paling ekstrem</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの家族はみんな朝が弱い。父に至っては、昼まで起きてこない。</span>（Semua orang di rumahku susah bangun pagi, ayahku malah lebih parah, tidur sampai siang tidak bangun-bangun.）</div><div class='gd-ex-line'>・<span class='gd-jp'>成績が悪く、数学に至っては赤点だ。</span>（Nilainya jelek, dan matematika bahkan sampai tidak lulus.）</div><div class='gd-ex-line'>・<span class='gd-jp'>会議では誰も意見を言わなかった。部長に至っては、最初から最後まで寝ていた。</span>（Di rapat tidak ada yang menyampaikan pendapat. Kepala departemen malah lebih parah, tidur dari awal sampai akhir.）</div><div class='gd-sec'>Di bagian belakang kalimat sering dipakai ungkapan penekan seperti 「<span class='gd-jp'>さえ</span>」「<span class='gd-jp'>まで</span>」「<span class='gd-jp'>一度も〜ない</span>」, supaya kesan \"ekstrem\"-nya makin terasa.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Di depan harus ada dulu sebuah <b>keseluruhan</b> (sekelompok orang, beberapa mata pelajaran, atau satu situasi), baru kamu bisa \"memilih yang paling ekstrem\". Kalau tiba-tiba bilang 「父に至っては…」 tanpa konteks apa pun, orang Jepang tidak akan paham kamu sedang membandingkan apa.<br>・Hampir selalu dipakai untuk hal yang <b>buruk atau bikin geleng-geleng kepala</b>. Kalau dipakai untuk memuji, misalnya \"dia lebih hebat lagi, dapat nilai sempurna\", kedengarannya aneh.<br>・Hal yang disebut belakangan harus benar-benar <b>paling ekstrem</b>. Kalau cuma tingkat biasa, pola ini terasa berlebihan.<br>・Ini ungkapan yang cenderung tulis dan formal. Saat ngobrol dengan teman, lebih sering bilang 「<span class='gd-jp'>父なんか、昼まで寝てるよ</span>」.<br>・Cara bacanya <b>いたっては</b>, 「至」 dibaca いた.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'><b>に至っては</b> = dari keseluruhan, <b>memilih satu yang paling ekstrem</b> (kebanyakan negatif):<br>・<span class='gd-jp'>部屋はどこも汚かった。台所に至っては、足の踏み場もなかった。</span>（Semua ruangan kotor, dapurnya malah lebih parah, sampai tidak ada tempat untuk berpijak.）<br><b>に至るまで</b> = dari A sampai B, <b>semuanya tercakup</b>, menekankan jangkauan yang luas, bisa untuk hal baik maupun buruk:<br>・<span class='gd-jp'>リビングから台所に至るまで、全部きれいに掃除した。</span>（Dari ruang tamu sampai dapur, semuanya sudah dibersihkan sampai bersih.）</div><div class='gd-sec'><b>ときたら</b> = cuma mengangkat satu orang untuk <b>dikeluhkan</b>, di depannya tidak perlu menyebut kelompok dulu. Nadanya lebih santai dan penuh rasa tidak puas:<br>・<span class='gd-jp'>うちの父ときたら、毎晩飲んで帰ってくる。</span>（Kalau soal ayahku, tiap malam pulang setelah minum-minum.）<br>・<span class='gd-jp'>家族はみんなお酒好きだが、父に至っては毎晩飲んで帰ってくる。</span>（Semua orang di rumahku suka minum, ayahku malah lebih parah, tiap malam pulang setelah minum.）</div><div class='gd-warn'>Trik membedakan: kalau bilang dulu \"semuanya ～\" lalu \"di antaranya si anu lebih parah\" → に至っては; kalau \"dari A sampai B semuanya\" → に至るまで; kalau cuma \"duh, soal si anu itu bikin kesal\" → ときたら.</div>","n1-4":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜たりとも…ない」kira-kira berarti <b>「satu ～ pun tidak…」</b>, dan ini versi yang lebih menekan. Seperti orang yang menggebrak meja dan bilang \"Satu rupiah pun tidak akan kukasih!\" atau \"Satu menit pun tidak boleh dibuang percuma!\". Nada yang <b>tegas, tanpa kompromi</b> seperti itu diungkapkan dengan たりとも dalam bahasa Jepang.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Rumusnya tetap: <b>「一」＋ satuan hitung ＋たりとも＋ bentuk negatif</b>.<br><span class='gd-pair'><span class='gd-jp'>一日</span> → <span class='gd-jp'>一日たりとも</span></span>（satu hari pun）<br><span class='gd-pair'><span class='gd-jp'>一円</span> → <span class='gd-jp'>一円たりとも</span></span>（satu yen pun）<br><span class='gd-pair'><span class='gd-jp'>一人</span> → <span class='gd-jp'>一人たりとも</span></span>（satu orang pun）<br>Di belakangnya <b>harus berupa bentuk negatif</b>, misalnya <span class='gd-jp'>〜ない</span>、<span class='gd-jp'>〜ません</span>、<span class='gd-jp'>〜できない</span>、<span class='gd-jp'>許されない</span>、<span class='gd-jp'>〜するな</span>.<br>Kombinasi yang paling sering muncul: <span class='gd-jp'>一秒</span>、<span class='gd-jp'>一瞬</span>、<span class='gd-jp'>一日</span>、<span class='gd-jp'>一円</span>、<span class='gd-jp'>一人</span>、<span class='gd-jp'>一歩</span>、<span class='gd-jp'>一滴</span>、<span class='gd-jp'>一度</span>. Semuanya adalah \"satuan terkecil\", menekankan bahwa sekecil itu pun tidak boleh.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Tekad yang kuat</span>Kamu sendiri sama sekali tidak mau atau tidak ingin melakukan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>残り時間、一秒たりとも無駄にしたくない。</span>（Sisa waktunya, satu detik pun aku tidak mau menyia-nyiakannya.）</div><div class='gd-sec'><span class='gd-tag'>Aturan, perintah</span>Tidak boleh, tidak diizinkan. Sering dipakai oleh atasan, pelatih, atau di pengumuman.</div><div class='gd-ex-line'>・<span class='gd-jp'>試合が終わるまで、一瞬たりとも気を抜くな。</span>（Sampai pertandingan selesai, jangan lengah sedetik pun.）</div><div class='gd-ex-line'>・<span class='gd-jp'>医療ミスは一件たりとも許されない。</span>（Kesalahan medis, satu kasus pun tidak bisa ditoleransi.）</div><div class='gd-sec'><span class='gd-tag'>Perasaan yang kuat</span>Sering dipakai bersama 「〜たことはない」 untuk mengungkapkan \"belum pernah sekali pun\".</div><div class='gd-ex-line'>・<span class='gd-jp'>君のことを一日たりとも忘れたことはない。</span>（Tidak ada satu hari pun aku melupakanmu.）</div><div class='gd-h'>Satu ungkapan tetap yang khusus</div><div class='gd-sec'><span class='gd-jp'>何人たりとも</span> = \"siapa pun tidak boleh ～\". Di sini 何人 dibaca <b>なんぴと</b>, bahasa tulis yang sangat kaku, sering muncul di pengumuman, novel, dan dialog anime.</div><div class='gd-ex-line'>・<span class='gd-jp'>何人たりとも、ここに立ち入ることは許さない。</span>（Siapa pun tidak diizinkan masuk ke sini.）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Di depan hanya boleh <b>「一」</b>: <span class='gd-jp'>二日たりとも</span>、<span class='gd-jp'>三人たりとも</span> keduanya salah. Yang ditekankan adalah \"jumlah terkecil\".<br>・Di belakang <b>harus negatif</b>, kamu tidak bisa membuat kalimat positif seperti 「一日たりとも休む」.<br>・Setelah satuan hitung, langsung sambung たりとも, jangan menambah 「も」 atau 「の」: 「一日もたりとも」 itu salah.<br>・Nadanya berat dan cenderung bahasa tulis. Dalam obrolan sehari-hari, <span class='gd-jp'>一円も払わない</span> sudah cukup; kalau diganti たりとも, kesannya seperti sedang bersumpah atau membuat pernyataan.<br>・Kalau cuma menggambarkan fakta (misalnya \"di kelas tidak ada satu murid pun\"), <span class='gd-jp'>一人もいなかった</span> lebih natural; たりとも cocok untuk tekad, aturan, dan emosi yang kuat.<br>・何人 di 何人たりとも dibaca なんぴと, bukan なんにん.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Masih soal \"uang\", lihat tiga cara bilangnya:<br><b>一〜も…ない</b> = sekadar bilang \"satu pun tidak ada\", netral, untuk sehari-hari: <span class='gd-jp'>財布には一円もない。</span>（Di dompet tidak ada uang satu yen pun.）<br><b>一〜たりとも…ない</b> = membawa pendirian yang kuat, tanpa kompromi: <span class='gd-jp'>税金は一円たりとも無駄にできない。</span>（Uang pajak, satu yen pun tidak boleh disia-siakan.）<br><b>すら</b> = mengangkat satu hal yang \"paling mendasar\" untuk menekankan, di depannya tidak harus berupa 「一＋satuan hitung」: <span class='gd-jp'>今月は電車代すらない。</span>（Bulan ini bahkan ongkos kereta pun tidak ada.）</div><div class='gd-warn'>Trik membedakan: kalau cuma menyatakan \"satu pun tidak ada\", pakai も; kalau 「一＋satuan hitung」 ditambah nada tekad, larangan, atau \"sama sekali tidak boleh\", pakai たりとも; kalau mengangkat \"bahkan hal sedasar ini pun ～\", pakai すら.</div>","n1-69":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜を皮切りに」artinya <b>“diawali dari ～”, “dimulai dari ～ sebagai pembuka”</b>. Contohnya konser: “Mulai dari konser di Jakarta, lalu lanjut tur keliling Indonesia”. Konser di Jakarta itulah si 「皮切り」, yaitu yang pertama. Intinya, <b>setelah itu masih ada serangkaian hal yang menyusul</b>.</div><div class='gd-sec'>Awalnya 「皮切り」 berarti moksa (terapi bakar ramuan di kulit) yang pertama, yang paling panas dan paling sakit. Lalu maknanya meluas menjadi “yang pertama dari serangkaian kejadian”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Acara, tur</span>Dimulai dari perhentian pertama, lalu disusul perhentian demi perhentian.</div><div class='gd-ex-line'>・<span class='gd-jp'>東京公演を皮切りに、全国ツアーが始まった。</span>（Diawali dari konser di Tokyo, tur keliling seluruh negeri pun dimulai）</div><div class='gd-sec'><span class='gd-tag'>Bisnis berkembang</span>Dari toko pertama atau produk pertama, lalu makin lama makin banyak.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は渋谷店を皮切りに、各地に店舗を増やしている。</span>（Toko ini berawal dari cabang Shibuya, lalu terus menambah cabang di berbagai tempat）</div><div class='gd-sec'><span class='gd-tag'>Satu orang memulai, yang lain menyusul</span>Satu orang bicara lebih dulu, lalu yang lain ikut bersuara satu per satu.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の発言を皮切りに、次々と意見が出た。</span>（Begitu dia angkat bicara, pendapat lain langsung bermunculan satu per satu）</div><div class='gd-sec'>Di bagian belakang kalimat, biasanya dipasangkan dengan kata seperti <span class='gd-jp'>次々と</span>（berturut-turut）, <span class='gd-jp'>相次いで</span>（susul-menyusul）, <span class='gd-jp'>各地で</span>（di berbagai tempat）, untuk menunjukkan bahwa “setelah ini masih banyak lagi”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Langsung sambung ke kata benda：<span class='gd-pair'><span class='gd-jp'>東京公演</span> → <span class='gd-jp'>東京公演を皮切りに</span></span><br>Kalau berupa tindakan, biasanya dipakai bentuk kata bendanya：<span class='gd-jp'>発売</span>（mulai dijual）、<span class='gd-jp'>開店</span>（pembukaan toko）、<span class='gd-jp'>発言</span>（pernyataan）。<br>Menambahkan 「して」 artinya sama, dua-duanya boleh dipakai. Tanpa 「して」, 「を皮切りに」 lebih ringkas dan lebih sering muncul dalam tulisan：<span class='gd-jp'>東京公演を皮切りにして</span>。<br>Kamu juga akan menemukan <span class='gd-jp'>を皮切りとして</span>, artinya sama.</div><div class='gd-h'>Hal yang sering keliru</div><div class='gd-warn'>・<b>Setelahnya harus ada “serangkaian” hal</b>. Kalau hanya terjadi satu hal, tidak bisa dipakai：<span class='gd-jp'>入学を皮切りに、一人暮らしを始めた</span> itu salah, karena setelahnya hanya ada satu hal. Harus diganti jadi <span class='gd-jp'>入学をきっかけに</span>。<br>・Ini bukan sekadar “mulai dari ～”. Untuk titik awal waktu, cukup pakai 「から」：<span class='gd-jp'>月曜日から仕事が始まる</span>, jangan bilang 月曜日を皮切りに。<br>・<b>Jarang dipakai untuk rentetan hal buruk</b>. Untuk gempa atau kecelakaan yang terjadi beruntun, orang Jepang biasanya tidak memakai 皮切り. Pemakaian utamanya untuk hal yang “berkembang terus”, seperti acara, bisnis, dan pertandingan.<br>・Nuansanya cukup formal, sering muncul di berita, laporan, dan teks pengenalan. Jarang dipakai saat ngobrol dengan teman.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama soal konser, tapi tata bahasa yang berbeda membuat artinya jauh berbeda：<br><b>を皮切りに</b>＝konser ini adalah <b>perhentian pertama</b>, dan masih banyak konser sesudahnya：</div><div class='gd-ex-line'>・<span class='gd-jp'>そのライブを皮切りに、彼らは全国を回った。</span>（Diawali dari konser itu, mereka keliling ke seluruh negeri）</div><div class='gd-sec'><b>をきっかけに</b>＝karena hal itu, <b>terjadi suatu perubahan</b>（belum tentu ada rangkaian）：</div><div class='gd-ex-line'>・<span class='gd-jp'>そのライブをきっかけに、彼らは有名になった。</span>（Berkat konser itu, mereka jadi terkenal）</div><div class='gd-sec'><b>を限りに</b>＝justru kebalikannya, ini adalah <b>yang terakhir</b>, sampai di sini saja：</div><div class='gd-ex-line'>・<span class='gd-jp'>今日のライブを限りに、活動を休止する。</span>（Konser hari ini adalah yang terakhir, setelah itu mereka vakum）</div><div class='gd-warn'>Tips menentukan: “perhentian pertama, lalu disusul banyak hal” pakai を皮切りに; “berubah karena suatu hal” pakai をきっかけに; “yang terakhir, selesai sampai di sini” pakai を限りに.</div>","n1-75":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜きらいがある」artinya <b>“punya kecenderungan ～”, “punya kebiasaan buruk ～”</b>, dan selalu untuk kecenderungan yang <b>kurang baik</b>. Nadanya mirip catatan guru di rapor: “Anak ini cenderung terburu-buru dalam bekerja”. Jelas-jelas menyebut kekurangan, tapi disampaikan dengan sopan dan halus. Biasanya muncul di tulisan, ulasan, atau percakapan yang cukup formal.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja bentuk kamus＋きらいがある　<span class='gd-pair'><span class='gd-jp'>抱え込む</span> → <span class='gd-jp'>抱え込むきらいがある</span></span><br>Kata kerja bentuk ない＋きらいがある　<span class='gd-pair'><span class='gd-jp'>聞かない</span> → <span class='gd-jp'>聞かないきらいがある</span></span><br>Kata benda＋の＋きらいがある　<span class='gd-pair'><span class='gd-jp'>独断</span> → <span class='gd-jp'>独断のきらいがある</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼は何でも一人で抱え込むきらいがある。</span>（Dia punya kebiasaan memikul semuanya sendirian）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は人の話を最後まで聞かないきらいがある。</span>（Dia cenderung tidak mendengarkan omongan orang sampai selesai）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼のやり方は独断のきらいがある。</span>（Caranya cenderung agak sepihak）</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>〜すぎるきらいがある</span>Sangat sering dipakai untuk mengkritik sesuatu yang “berlebihan”.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの部長は細かいことを気にしすぎるきらいがある。</span>（Kepala bagian kami cenderung terlalu memikirkan hal-hal kecil）</div><div class='gd-sec'><span class='gd-tag'>Membicarakan kelompok</span>Untuk menilai gaya umum suatu kelompok, organisasi, atau masyarakat.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近のニュースは話題性を重視しすぎるきらいがある。</span>（Berita belakangan ini cenderung terlalu mementingkan sensasi）</div><div class='gd-h'>Hal yang sering keliru</div><div class='gd-warn'>・Kanjinya ditulis 「嫌い」, tapi di sini <b>tidak ada hubungannya dengan “benci”</b>. Artinya “kecenderungan, kebiasaan buruk”. Sekarang biasanya langsung ditulis dengan hiragana <span class='gd-jp'>きらい</span>。<br>・Hanya bisa untuk kecenderungan yang <b>buruk</b>. Untuk bilang seseorang “perhatian”, tidak bisa pakai ini. Pakai <span class='gd-jp'>優しいところがある</span>。<br>・Yang dibicarakan adalah <b>gaya atau sifat sehari-hari</b> seseorang (atau kelompok), bukan kejadian sekali saja. Untuk “kemarin dia terlambat”, tidak bisa pakai きらいがある.<br>・Kalau menyambung ke kata benda, wajib pakai 「の」: yang benar <span class='gd-jp'>独断のきらいがある</span>, bukan 「独断きらいがある」。<br>・Nuansanya kaku. Saat ngobrol dengan teman dan ingin bilang “dia gampang overthinking”, lebih natural pakai <span class='gd-jp'>考えすぎるところがある</span> atau <span class='gd-jp'>考えすぎがちだ</span>。</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama tentang orang yang mudah berpikir negatif：<br><b>がち</b>＝“sering ～, gampang ～”, fokusnya pada <b>frekuensi yang sering</b>, dan bisa dipakai dalam percakapan sehari-hari：<span class='gd-jp'>彼は物事を悲観的に考えがちだ。</span>（Dia sering memandang segala hal secara pesimis）<br><b>きらいがある</b>＝“punya kecenderungan buruk ～”, terkesan <b>menilai sifat orang secara halus</b>, lebih ke bahasa tulis：<span class='gd-jp'>彼は物事を悲観的に考えるきらいがある。</span>（Dia punya kecenderungan memandang segala hal secara pesimis）<br><b>気味</b>＝“terasa agak ～”, membicarakan <b>kondisi ringan saat ini</b>, bukan sifat：<span class='gd-jp'>最近、ちょっと疲れ気味だ。</span>（Belakangan ini rasanya agak capek）<br>Satu lagi: がち juga bisa dipakai untuk cuaca atau fenomena alam (<span class='gd-jp'>冬は空気が乾燥しがちだ</span>, di musim dingin udara gampang kering), sedangkan きらいがある pada dasarnya hanya dipakai untuk menilai gaya orang atau kelompok.</div><div class='gd-warn'>Tips menentukan: saat ngobrol dan ingin bilang “sering ～”, pakai がち; untuk “terasa agak ～”, pakai 気味; untuk menulis ulasan atau menunjuk “kebiasaan buruk” seseorang atau kelompok dengan sopan, pakai きらいがある.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Sering muncul bersama 「ともすると・ともすれば」（kalau lengah sedikit saja, langsung ～）：<span class='gd-jp'>人はともすると、楽な方を選ぶきらいがある。</span>（Kalau lengah sedikit saja, manusia cenderung memilih jalan yang lebih mudah）</div>","n1-80":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜にとどまらず」artinya <b>“tidak hanya terbatas pada ～, tetapi juga meluas sampai ～”</b>, ungkapan yang sering muncul di berita. <span class='gd-jp'>とどまる</span> artinya “berhenti di tempat”, jadi <span class='gd-jp'>とどまらず</span> berarti “tidak berhenti di situ”. Di bagian depan kamu sebut cakupan yang lebih kecil, lalu di belakang cakupan yang lebih besar, seperti riak air yang menyebar lingkaran demi lingkaran.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Cakupan meluas</span>Paling sering dipakai untuk hal yang bisa “menyebar”: dampak, bencana, popularitas, atau kegiatan. Ini sering muncul di berita, laporan, dan pidato, dan termasuk gaya tulis yang formal.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の人気は日本にとどまらず、アジア全体に広がっている。</span>（Popularitasnya tidak hanya di Jepang, tetapi meluas ke seluruh Asia）</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は一つの会社にとどまらず、業界全体に関わる。</span>（Masalah ini tidak hanya menyangkut satu perusahaan, tetapi juga seluruh industri）</div><div class='gd-sec'><span class='gd-tag'>Tindakan yang lebih jauh</span>Di bagian depan kamu juga bisa menaruh kata kerja. Artinya “tidak berhenti pada melakukan ～, tetapi melangkah lebih jauh lagi”.</div><div class='gd-ex-line'>・<span class='gd-jp'>ボランティアたちは物資を届けるにとどまらず、被災者の話にも耳を傾けた。</span>（Para relawan tidak hanya mengantarkan bantuan, tetapi juga mendengarkan cerita para korban bencana）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋にとどまらず：<span class='gd-pair'><span class='gd-jp'>国内</span> → <span class='gd-jp'>国内にとどまらず</span></span><br>Kata kerja bentuk kamus (bentuk dasar yang kamu temukan di kamus)＋にとどまらず：<span class='gd-pair'><span class='gd-jp'>届ける</span> → <span class='gd-jp'>届けるにとどまらず</span></span><br>Kamu juga sering menemukan bentuk dengan「だけ」, yaitu <span class='gd-jp'>国内だけにとどまらず</span>. Artinya sama, hanya penekanannya sedikit lebih kuat.</div><div class='gd-sec'>Kalau di akhir kalimat atau menerangkan kata benda, bentuknya berubah menjadi <b>にとどまらない</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の才能は音楽にとどまらない。</span>（Bakatnya tidak terbatas pada musik saja）</div><div class='gd-h'>Hal yang gampang keliru</div><div class='gd-warn'>・Yang benar <span class='gd-jp'>とどまる</span>, bukan <span class='gd-jp'>とまる</span>. <span class='gd-jp'>涙が止まらない</span> artinya “air mata tidak bisa berhenti” dan tidak ada hubungannya dengan pola ini. Jangan sampai「とど」ketinggalan.<br>・Di belakang harus ada <b>cakupan yang lebih besar</b>, sering dengan「も」「まで」「へと」: <span class='gd-jp'>海外にも</span>、<span class='gd-jp'>全国へと</span>. Kalau hanya ditulis separuh kalimat, ucapanmu terasa menggantung.<br>・Pola ini sangat formal, jadi jangan dipakai untuk hal sehari-hari yang sepele. Untuk “Aku tidak hanya makan ramen, tapi juga sushi”, cukup bilang <span class='gd-jp'>ラーメンだけじゃなくて、寿司も食べた</span>. Kalau pakai にとどまらず, kedengarannya seperti sedang membacakan siaran pers.<br>・<span class='gd-jp'>にとどまる</span> tanpa bentuk negatif juga sering muncul, dengan arti sebaliknya: “hanya berhenti di ～”: <span class='gd-jp'>今回の値上げは一部の商品にとどまる。</span>（Kenaikan harga kali ini hanya terbatas pada sebagian produk）</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'>Sama-sama bicara tentang sebuah anime yang populer:<br><b>だけでなく</b> ＝ “tidak hanya ～, tetapi juga ～” yang paling umum, bisa dipakai di situasi apa saja: <span class='gd-jp'>このアニメは子どもだけでなく、大人にも人気だ。</span>（Anime ini populer tidak hanya di kalangan anak-anak, tetapi juga orang dewasa）<br><b>に限らず</b> ＝ tidak terbatas pada satu golongan, <b>golongan lain pun sama</b>: <span class='gd-jp'>このアニメは子どもに限らず、大人にも人気だ。</span>（Tidak terbatas pada anak-anak, orang dewasa juga suka ＝ semua orang suka）<br><b>にとどまらず</b> ＝ cakupannya <b>menyebar keluar</b>: <span class='gd-jp'>このアニメの人気は日本にとどまらず、世界中に広がっている。</span>（Popularitasnya tidak hanya di Jepang, tetapi menyebar ke seluruh dunia）<br><b>はおろか</b> ＝ yang di depan tak perlu dibicarakan lagi, <b>bahkan yang paling ekstrem</b> pun ～: <span class='gd-jp'>このアニメは、子どもはおろか、お年寄りまで知っている。</span>（Anak-anak tak perlu disebut lagi, bahkan para lansia pun tahu）</div><div class='gd-warn'>Tips memilih: kalau dampak atau cakupannya “makin lama makin luas”, pakai にとどまらず. Kalau maksudnya “tidak terbatas pada golongan tertentu”, pakai に限らず. Kalau maksudnya “bahkan yang paling ekstrem pun”, pakai はおろか. Kalau ragu, pakai だけでなく, itu yang paling aman.</div>","n1-81":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜すら」artinya <b>“bahkan ～ pun …”</b>. Kamu menyebut contoh yang paling dasar dan paling tidak mungkin bermasalah, lalu memakainya untuk menunjukkan betapa ekstrem situasinya: <span class='gd-jp'>名前すら知らない</span>, bahkan namanya pun tidak tahu, apalagi hal-hal lainnya. Artinya hampir sama dengan「さえ」, tetapi <b>nadanya lebih kaku dan lebih bergaya tulis</b>, sering muncul di artikel, berita, dan ulasan.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Kata benda＋すら</span>Cara paling dasar. 「が」dan「を」yang semula ada langsung digantikan oleh すら.<br><span class='gd-pair'><span class='gd-jp'>時間がない</span> → <span class='gd-jp'>時間すらない</span></span>（bahkan waktu pun tidak ada）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、食事する時間すらない。</span>（Saking sibuknya, bahkan waktu untuk makan pun tidak ada）</div><div class='gd-sec'><span class='gd-tag'>Kata benda＋ですら</span>Sering dipakai kalau bagian depannya “orang” dan orang itu adalah pelaku tindakan. 「で」di sini bukan berarti “di (tempat)”, jadi hafalkan saja 「ですら」 sebagai satu paket.</div><div class='gd-ex-line'>・<span class='gd-jp'>専門家ですら答えられない問題だ。</span>（Ini masalah yang bahkan para ahli pun tidak bisa menjawabnya）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもですら知っていることだ。</span>（Ini hal yang bahkan anak kecil pun tahu）</div><div class='gd-sec'><span class='gd-tag'>Kata benda＋に・と dll.＋すら</span>Partikel seperti「に」「と」tetap dipertahankan, lalu すら ditambahkan setelahnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>このことは親にすら話していない。</span>（Hal ini bahkan kepada orang tuaku pun belum kuceritakan）</div><div class='gd-sec'><span class='gd-tag'>Bentuk て＋すらいない</span>Yang ditekankan adalah <b>tindakannya itu sendiri</b>: bahkan langkah “melakukan”-nya pun belum dilakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はメールを読んですらいない。</span>（Email itu pun bahkan belum dia baca）</div><div class='gd-h'>Hal yang gampang keliru</div><div class='gd-warn'>・すら <b>tidak harus dipasangkan dengan bentuk negatif</b>. Memang di belakangnya paling sering ada「ない」, tetapi kalimat positif seperti <span class='gd-jp'>子どもですら知っている</span> juga sangat wajar.<br>・「に」「と」tidak boleh dihilangkan: katakan <span class='gd-jp'>親にすら</span>, jangan 親すら話していない.<br>・<span class='gd-jp'>メールすら読んでいない</span> berarti “bahkan emailnya pun belum dibaca” (fokus pada emailnya), sedangkan <span class='gd-jp'>メールを読んですらいない</span> berarti “bahkan membacanya pun belum” (fokus pada tindakan membaca). Posisi すら berbeda, jadi yang ditekankan juga berbeda.<br>・すら nadanya agak kaku. Waktu mengobrol dengan teman, <span class='gd-jp'>名前も知らない</span> atau <span class='gd-jp'>名前さえ知らない</span> terdengar lebih natural.<br>・すら sering membawa kesan “kaget, tak habis pikir, atau kritik”, jarang dipakai untuk memuji orang.</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'><b>すら</b> dan <b>さえ</b> hampir bisa saling menggantikan untuk arti “bahkan ～ pun”:<br><span class='gd-jp'>名前すら知らない。</span>／<span class='gd-jp'>名前さえ知らない。</span>（Bahkan namanya pun tidak tahu）<br>Bedanya, すら lebih bergaya tulis, dan さえ punya satu pemakaian yang <b>tidak</b> dimiliki すら: 「〜さえ〜ば」＝ asalkan ～ sudah cukup.<br><span class='gd-jp'>時間さえあれば行ける。</span>（Asalkan ada waktu, aku bisa pergi）<br>Kalimat ini <b>tidak bisa</b> diganti dengan すら.</div><div class='gd-warn'>Tips memilih: untuk arti “bahkan ～ pun”, keduanya boleh, dan すら terasa lebih kuat kalau kamu menulis artikel. Untuk arti “asalkan ～”, hanya さえ yang bisa dipakai.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>すら sering dipasangkan dengan「<span class='gd-jp'>〜はおろか</span>」(apalagi ～), dengan hal yang sulit di depan dan hal yang mudah di belakang:<br><span class='gd-jp'>漢字はおろか、ひらがなすら書けない。</span>（Apalagi kanji, bahkan hiragana pun tidak bisa menulisnya）</div>","n1-5":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜であれ」artinya <b>「siapa/apa pun ~, tetap …」「sekalipun ~, tetap …」</b>. Misalnya “siapa pun harus antre” atau “sekalipun direktur, tetap harus menaati aturan”. Apa pun yang ada di depan, kesimpulan di belakang tidak berubah. Pola ini sangat formal, jadi biasanya muncul di berita, pidato, dan tulisan.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depan taruh <b>kata benda</b>, lalu langsung tambahkan であれ: <span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長であれ</span></span><br>Untuk kata sifat-な, buang 「な」 lalu langsung tambahkan であれ: <span class='gd-pair'><span class='gd-jp'>有名な</span> → <span class='gd-jp'>有名であれ</span></span><br>Kamu juga bisa memakai kata tanya seperti 「誰、何、どんな～」: <span class='gd-pair'><span class='gd-jp'>誰</span> → <span class='gd-jp'>誰であれ</span></span><span class='gd-pair'><span class='gd-jp'>どう</span> → <span class='gd-jp'>どうであれ</span></span><br>「であれ」sebenarnya bentuk perintah dari 「である」 (bentuk tulis dari 「だ」, sering dipakai dalam tulisan). Tapi di sini <b>bukan menyuruh orang melakukan sesuatu</b>. Ini pemakaian konsesif yang artinya “apa pun itu, sama saja”, yaitu “sekalipun ~”.</div><div class='gd-h'>Tiga bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>たとえ＋名詞＋であれ</span>Sekalipun statusnya atau situasinya istimewa, hasilnya tetap sama. Di depannya sering ditambah 「たとえ」 (sekalipun) untuk menguatkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>たとえ子供であれ、自分のしたことには責任がある。</span>(Sekalipun masih anak-anak, ia tetap bertanggung jawab atas perbuatannya sendiri)</div><div class='gd-sec'><span class='gd-tag'>誰／何／どんな～＋であれ</span>Siapa pun, apa pun, semuanya sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>誰であれ、許可なく入ることはできない。</span>(Siapa pun tidak boleh masuk tanpa izin)</div><div class='gd-ex-line'>・<span class='gd-jp'>理由はどうであれ、約束を破ったのは事実だ。</span>(Apa pun alasannya, faktanya kamu melanggar janji)</div><div class='gd-sec'><span class='gd-tag'>AであれBであれ</span>Entah A maupun B, hasilnya tetap sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>男であれ女であれ、能力があれば評価される。</span>(Entah laki-laki maupun perempuan, kalau punya kemampuan pasti dihargai)</div><div class='gd-ex-line'>・<span class='gd-jp'>晴れであれ雨であれ、試合は予定どおり行う。</span>(Entah cerah maupun hujan, pertandingan tetap diadakan sesuai rencana)</div><div class='gd-sec'>Kalimat di belakang biasanya berisi <b>kesimpulan yang tidak berubah karena hal itu</b>. Yang sering muncul: 「〜できない」「許されない」「〜べきだ」「変わりはない」.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di depan harus kata benda atau batang kata sifat-な. Kata kerja tidak bisa langsung disambung: <b>tidak bisa</b> bilang 「行くであれ」. Kalau mau memakai kata kerja, ganti dengan 「〜ようが」 atau 「〜にせよ」.<br>・Pola ini kaku, jadi terdengar aneh kalau dipakai ngobrol santai. Dalam percakapan pakai 「でも」, misalnya: <span class='gd-jp'>誰でも許可が必要だよ。</span>(Siapa pun butuh izin, lho)<br>・Untuk bilang “siapa pun tidak boleh masuk”, pakai <span class='gd-jp'>誰も入れない</span>. Jangan bilang <span class='gd-jp'>誰でも入れない</span> (terdengar sangat tidak natural). Kalau mau bilang “tidak semua orang bisa masuk”, katakan <span class='gd-jp'>誰でも入れるわけではない</span>.<br>・<span class='gd-jp'>であれ</span> dan <span class='gd-jp'>であれば</span> hanya beda satu huruf, tapi artinya sama sekali berbeda. であれば berarti “kalau ~”: <span class='gd-jp'>社長であれば決められる。</span>(Kalau direktur, bisa memutuskan). であれ berarti “sekalipun ~, tetap …”: <span class='gd-jp'>社長であれ、勝手には決められない。</span>(Sekalipun direktur, tidak boleh memutuskan seenaknya)</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Sama-sama bilang “apa pun alasannya, terlambat tetap tidak boleh”:<br><b>であれ</b>: di depan kata benda atau batang kata sifat-な, paling formal.<br><span class='gd-jp'>どんな理由であれ、遅刻は許されない。</span><br><b>にせよ</b>: di depan bisa kata benda maupun kata kerja, sedikit lebih tidak kaku.<br><span class='gd-jp'>どんな理由にせよ、遅刻はよくない。</span><br><span class='gd-jp'>行くにせよ行かないにせよ、連絡してください。</span>(Entah pergi atau tidak, tolong kabari aku)<br><b>ようが／ようと</b>: di depan bentuk volisional kata kerja (bentuk 〜う／〜よう), nuansanya “seberapa pun ~, aku tidak peduli”.<br><span class='gd-jp'>どんな理由があろうと、遅刻は許されない。</span></div><div class='gd-warn'>Tips cepat: kalau di depan kata benda dan situasinya sangat formal, pakai であれ. Kalau mau memakai kata kerja, pakai にせよ atau ようが.</div><div class='gd-h'>Setelah ini, pelajari juga</div><div class='gd-sec'>Pola lain yang artinya “entah A entah B” adalah 「〜にせよ…にせよ」, serta ungkapan tetap 「〜かれ〜かれ」: <span class='gd-jp'>多かれ少なかれ</span> (sedikit banyak), <span class='gd-jp'>遅かれ早かれ</span> (cepat atau lambat).</div>","n1-6":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜とあれば」artinya <b>“kalau itu ~, ya (aku) akan …”</b>. Di depan ditaruh <b>alasan khusus yang bobotnya berat</b>, seperti “demi anak”, “perintah atasan”, atau “sahabat yang minta tolong”. Di belakang menyusul “ya aku bersedia” atau “ya mau tidak mau harus kulakukan”. Dalam bahasa Indonesia rasanya seperti “kalau demi anak, sesusah apa pun rela”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda langsung disambung: <span class='gd-pair'><span class='gd-jp'>子供のため</span> → <span class='gd-jp'>子供のためとあれば</span></span><br>Kata sifat-な juga langsung disambung: <span class='gd-pair'><span class='gd-jp'>必要</span> → <span class='gd-jp'>必要とあれば</span></span><br>Kata kerja memakai bentuk biasa (bentuk kamus, bentuk ない, atau bentuk た): <span class='gd-pair'><span class='gd-jp'>社長が来る</span> → <span class='gd-jp'>社長が来るとあれば</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Rela berkorban</span>Demi orang atau hal yang penting, apa pun rela dilakukan. Paling sering muncul bersama 「のため」.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供のためとあれば、親はどんな苦労も厭わない。</span>(Kalau demi anak, orang tua rela susah payah seperti apa pun)</div><div class='gd-ex-line'>・<span class='gd-jp'>家族のためとあれば、どんな仕事でもする。</span>(Kalau demi keluarga, pekerjaan apa pun akan kulakukan)</div><div class='gd-sec'><span class='gd-tag'>Mau tidak mau menerima</span>Posisi atau situasi pihak lain begitu istimewa, sehingga rasanya tidak pantas kalau tidak dilakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>親友の頼みとあれば、断るわけにはいかない。</span>(Kalau sahabat yang minta tolong, tidak mungkin menolak)</div><div class='gd-ex-line'>・<span class='gd-jp'>社長の命令とあれば、従うしかない。</span>(Kalau itu perintah direktur, ya terpaksa menurut)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Di dunia bisnis, dua kalimat baku ini sering sekali terdengar:</div><div class='gd-ex-line'>・<span class='gd-jp'>必要とあれば、いつでもご連絡ください。</span>(Kalau memang perlu, silakan hubungi kami kapan saja)</div><div class='gd-ex-line'>・<span class='gd-jp'>お客様のご希望とあれば、できる限り対応いたします。</span>(Kalau itu permintaan pelanggan, kami akan berusaha menyesuaikan semampu kami)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di depan harus ada <b>alasan yang bobotnya berat</b>. Syarat sehari-hari yang biasa saja tidak pakai pola ini: untuk “kalau hujan, bawa payung”, katakan <span class='gd-jp'>雨なら傘を持っていく</span>. Kalau jadi 「雨とあれば」, terdengar aneh.<br>・Di belakang biasanya ada <b>tekad atau penilaian</b>, seperti <span class='gd-jp'>何でもする</span>, <span class='gd-jp'>喜んで</span>, <span class='gd-jp'>しかない</span>, <span class='gd-jp'>わけにはいかない</span>. Bukan sekadar menceritakan apa yang terjadi.<br>・Setelah kata benda, langsung sambung とあれば. Tidak perlu menambah だ.<br>・Nuansanya formal dan condong ke bahasa tulis. Waktu ngobrol dengan teman, cukup bilang <span class='gd-jp'>子供のためなら</span>. Artinya hampir sama, tapi lebih santai.<br>・Arti “demi” datang dari <span class='gd-jp'>のため</span> di depannya. とあれば sendiri hanya berarti “kalau itu ~”, jadi tidak semua kalimat punya arti “demi”.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>「とあれば」dan 「とあって」sama-sama diawali 「と＋あ…」dan hanya beda sedikit di belakang. 「ともなれば」juga diawali と, jadi kelihatan mirip. Kita bandingkan dengan situasi “direktur” yang sama:<br><b>とあれば</b>＝<b>kalau itu</b> ~, ya …(pengandaian, di belakang berisi tekad): <span class='gd-jp'>社長の命令とあれば、従うしかない。</span>(Kalau itu perintah direktur, ya terpaksa menurut)<br><b>とあって</b>＝<b>karena itu</b> ~, jadi …(fakta yang sudah terjadi, di belakang menggambarkan keadaan): <span class='gd-jp'>社長の命令とあって、みんな必死に働いている。</span>(Karena itu perintah direktur, semua orang bekerja mati-matian)<br><b>ともなれば</b>＝<b>begitu sudah sampai pada</b> posisi atau tingkat ~, otomatis …: <span class='gd-jp'>社長ともなれば、責任も重くなる。</span>(Begitu sudah jadi direktur, tanggung jawab otomatis jadi berat)</div><div class='gd-warn'>Tips cepat: “kalau itu ~, aku bersedia / terpaksa” pakai とあれば. “Karena itu ~, makanya sekarang begini” pakai とあって. “Kalau sudah sampai tahap ~, otomatis begini” pakai ともなれば.</div>","n1-7":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜をおいて」artinya <b>“tak ada yang lain selain ~”, “kalau bukan ~, siapa lagi?”</b>. Si pembicara sudah menimbang banyak orang atau hal yang mungkin, lalu menyimpulkan: <b>yang paling cocok memang hanya yang satu ini</b>. Ungkapan ini bukan sekadar bilang “hanya”, tapi juga mengandung penilaian yang sangat tinggi.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋<span class='gd-jp'>をおいて</span>＋<span class='gd-jp'>ほかに</span>〜<span class='gd-jp'>ない</span>／<span class='gd-jp'>いない</span><br>Kalau yang dibicarakan orang, pakai <span class='gd-jp'>いない</span>. Kalau benda, waktu, atau tempat, pakai <span class='gd-jp'>ない</span>.<br><span class='gd-pair'><span class='gd-jp'>彼</span> → <span class='gd-jp'>彼をおいてほかにいない</span></span>（tidak ada orang lain selain dia）<br><span class='gd-pair'><span class='gd-jp'>今</span> → <span class='gd-jp'>今をおいてほかにない</span></span>（tidak ada waktu lain selain sekarang）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Untuk orang</span>Paling sering dipakai saat merekomendasikan seseorang atau memuji bahwa dialah satu-satunya pilihan.</div><div class='gd-ex-line'>・<span class='gd-jp'>次のリーダーにふさわしいのは、山田さんをおいてほかにいない。</span>（Yang paling pantas jadi pemimpin berikutnya ya Yamada, tak ada yang lain）</div><div class='gd-sec'><span class='gd-tag'>Untuk waktu</span><span class='gd-jp'>今をおいてほかにない</span>adalah ungkapan baku yang artinya “ya sekarang ini, kalau lewat ya sudah”.</div><div class='gd-ex-line'>・<span class='gd-jp'>留学するなら、今をおいてほかにない。</span>（Kalau mau kuliah ke luar negeri, ya sekarang waktunya）</div><div class='gd-sec'><span class='gd-tag'>Pertanyaan retoris</span>Bagian belakangnya tidak harus「ない」. Bisa juga memakai nada retoris “memangnya ada siapa lagi?”, dan artinya tetap sama: “hanya dia”.</div><div class='gd-ex-line'>・<span class='gd-jp'>この役を演じられるのは、彼をおいて誰がいるだろうか。</span>（Yang bisa memerankan tokoh ini, selain dia memangnya ada siapa lagi?）</div><div class='gd-h'>Bagian yang sering keliru</div><div class='gd-warn'>・<b>Tidak bisa dipakai untuk fakta biasa</b>. “Di ruangan itu tidak ada siapa-siapa selain dia” hanyalah keadaan objektif, jadi katakan <span class='gd-jp'>部屋には彼以外誰もいなかった</span>, bukan をおいて.<br>・Biasanya dipakai untuk <b>penilaian positif</b>, seperti “paling cocok”, “paling hebat”, “hanya dia yang bisa”. Kalau dipakai untuk hal buruk, rasanya aneh.<br>・<span class='gd-jp'>をおいて</span>dan<span class='gd-jp'>において</span>hanya beda satu huruf, tapi artinya sama sekali berbeda: <span class='gd-jp'>会議室において</span>artinya “di ruang rapat”, menunjukkan tempat atau situasi.<br>・Ini gaya bicara yang cukup formal dan tertulis, sering muncul di artikel, pidato, dan berita. Kalau ngobrol dengan teman, cukup bilang <span class='gd-jp'>彼しかいないよ</span>.<br>・<span class='gd-jp'>何をおいても</span>adalah ungkapan tetap lain yang artinya “apa pun yang terjadi, ini yang didahulukan”: <span class='gd-jp'>何をおいても駆けつける</span>（apa pun yang terjadi, aku pasti datang）. Jangan tertukar dengan arti “tidak ada selain ~”.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Misalnya sama-sama membicarakan sebuah toko lama yang hebat:<br><b>をおいて</b>＝<b>memilih satu-satunya</b> di antara banyak kandidat: <span class='gd-jp'>この味を出せるのは、あの店をおいてほかにない。</span>（Yang bisa menghasilkan rasa ini, ya hanya toko itu）<br><b>ならでは</b>＝ciri khas yang <b>hanya dimiliki</b> oleh sesuatu itu: <span class='gd-jp'>これはあの店ならではの味だ。</span>（Ini rasa khas toko itu）<br><b>以外</b>＝sekadar bilang <b>“selain ~”</b>, tanpa penilaian: <span class='gd-jp'>あの店以外で食べたことがない。</span>（Selain di toko itu, aku belum pernah makan di tempat lain）</div><div class='gd-warn'>Trik menentukan: kalau maksudnya “siapa/mana yang dipilih? jawabannya cuma ini”, pakai をおいて. Kalau maksudnya “ciri khas ini milik dia saja”, pakai ならでは. Kalau hanya menyatakan secara objektif “selain ~”, pakai 以外.</div>","n1-11":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ならまだしも」artinya <b>“kalau ~ sih masih bisa dimaklumi, tapi…”</b>. Kamu mundur selangkah dulu dengan bilang “kalau cuma segini, aku masih bisa terima”, lalu menunjukkan “tapi kali ini sudah kelewatan”. Inti kalimatnya ada di bagian belakang: <b>kamu sedang mengeluh dan menyatakan tidak bisa menerimanya</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>一度ならまだしも、三度も遅刻するなんて。</span>（Sekali sih masih maklum, tapi sampai tiga kali terlambat!）</div><div class='gd-h'>Kita bedah</div><div class='gd-sec'><span class='gd-jp'>まだしも</span>bisa dibayangkan sebagai「<span class='gd-jp'>まだ</span>（masih）＋<span class='gd-jp'>しも</span>（penekan）」, artinya “masih bisa dimaklumi”. Jadi struktur kalimatnya selalu:<br><b>keadaan yang lebih ringan dan masih bisa ditoleransi</b>＋ならまだしも, <b>keadaan yang lebih parah dan tidak bisa diterima</b>.<br>Keadaan ringan di depan itu sering kali sebenarnya bukan yang terjadi, hanya dipakai sebagai pembanding. Misalnya <span class='gd-jp'>冗談ならまだしも</span>, maksud tersiratnya “kamu jelas tidak sedang bercanda”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata benda</b>: langsung disambung. <span class='gd-pair'><span class='gd-jp'>冗談</span> → <span class='gd-jp'>冗談ならまだしも</span></span><br><b>Kata sifat-な</b>: tanpa だ, langsung disambung. <span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手ならまだしも</span></span><br><b>Kata kerja dan kata sifat-い</b>: pakai bentuk biasa (bentuk kamus, tanpa ます／です). <span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らないならまだしも</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Tidak puas dengan hal yang sudah terjadi</span></div><div class='gd-ex-line'>・<span class='gd-jp'>知らないならまだしも、知っていて黙っていたのは許せない。</span>（Kalau memang tidak tahu sih masih maklum, tapi sudah tahu dan diam saja, itu tidak bisa kumaafkan）</div><div class='gd-sec'><span class='gd-tag'>Menilai situasi yang belum terjadi</span>Bagian belakang tidak harus soal masa lalu. Bisa juga berupa penilaian tentang pengandaian atau masa depan.</div><div class='gd-ex-line'>・<span class='gd-jp'>夏はまだしも、冬はこの部屋じゃ無理だ。</span>（Kalau musim panas sih masih oke, tapi musim dingin tinggal di kamar ini jelas mustahil）</div><div class='gd-sec'><span class='gd-tag'>Meminta orang lain berhenti</span>Bagian belakang juga bisa berupa permintaan atau larangan.</div><div class='gd-ex-line'>・<span class='gd-jp'>一日ならまだしも、毎日来るのはやめてほしい。</span>（Sehari sih tidak apa-apa, tapi kalau datang tiap hari, tolong jangan）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Setelah kata benda, sering juga langsung dipakai <span class='gd-jp'>はまだしも</span>, seperti <span class='gd-jp'>夏はまだしも</span> di atas, dengan arti yang sama.<br>Selain itu ada <span class='gd-jp'>ならともかく</span> yang artinya sangat dekat, dan sering kali bisa saling menggantikan.</div><div class='gd-h'>Bagian yang sering keliru</div><div class='gd-warn'>・<b>Urutannya tidak boleh terbalik</b>: yang ringan di depan, yang parah di belakang. Kalau bilang <span class='gd-jp'>三度ならまだしも、一度遅刻するなんて</span>, logikanya jadi tidak masuk akal.<br>・Setelah kata benda dan kata sifat-な, jangan tambahkan だ: yang benar <span class='gd-jp'>冗談ならまだしも</span>, bukan 冗談だならまだしも.<br>・Bagian belakang berisi penilaian negatif (seperti <span class='gd-jp'>ありえない</span>, <span class='gd-jp'>許せない</span>, <span class='gd-jp'>無理だ</span>, <span class='gd-jp'>やめてほしい</span>), jadi tidak bisa dipakai untuk memuji atau membicarakan hal baik.<br>・Nadanya mengeluh dan menegur. Kalau langsung dipakai ke orang yang lebih tua atau ke pelanggan, terdengar menyalahkan, jadi hati-hati dengan situasinya.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama melihat orang dewasa menangis karena hal sepele:<br><b>ならまだしも</b>：<span class='gd-jp'>子どもならまだしも、大人がこんなことで泣くなんて。</span>（Kalau anak kecil sih masih maklum, tapi orang dewasa menangis karena hal seperti ini!）<br><b>ではあるまいし</b>：<span class='gd-jp'>子どもではあるまいし、こんなことで泣かないで。</span>（Kamu kan bukan anak kecil, jangan menangis karena hal seperti ini）<br>Inti <b>ならまだしも</b> adalah <b>kesenjangan</b> “yang di depan masih bisa diterima, tapi tingkat yang di belakang tidak”, dan sering dipakai untuk mengeluh atau menyatakan tidak bisa menerima. Inti <b>ではあるまいし</b> adalah “kan bukan ~”, yaitu <b>menyangkal premis di depan</b>, lalu meminta lawan bicara melakukan sesuatu atau menyampaikan penilaian.</div><div class='gd-warn'>Trik menentukan: kalau maksudmu “A sih masih oke, tapi B keterlaluan”, pakai ならまだしも. Kalau maksudmu “kan bukan A, jadi seharusnya kamu…”, pakai ではあるまいし.</div>","n1-24":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜とあって」sering dipakai di berita dan laporan, artinya <b>「karena situasinya istimewa seperti ini, makanya wajar kalau…」</b>. Mirip gaya berita Indonesia: 「Bertepatan dengan hari pertama libur panjang, bandara dipadati penumpang」. Nuansa 「bertepatan dengan～」 itulah yang dimaksud. Bagian depan menyebut hari atau acara istimewa, bagian belakang menyebut pemandangan atau reaksi orang-orang karenanya.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Hari・acara istimewa</span>Hal yang tidak ada setiap hari, seperti libur panjang, diskon besar, atau festival kembang api, jadi orang-orang berdatangan dan suasananya sangat ramai.</div><div class='gd-ex-line'>・<span class='gd-jp'>連休初日とあって、空港は大混雑だった。</span>（Bertepatan dengan hari pertama libur panjang, bandara penuh sesak）</div><div class='gd-ex-line'>・<span class='gd-jp'>年に一度のセールとあって、店の前には朝から長い列ができていた。</span>（Karena ini diskon yang hanya setahun sekali, sejak pagi sudah ada antrean panjang di depan toko）</div><div class='gd-sec'><span class='gd-tag'>Reaksi orang</span>Karena situasinya langka, orang yang mengalaminya jadi tegang, bersemangat, atau lebih serius dari biasanya.</div><div class='gd-ex-line'>・<span class='gd-jp'>初めての海外旅行とあって、娘はずいぶん張り切っている。</span>（Karena ini pertama kalinya pergi ke luar negeri, anak perempuanku semangat sekali）</div><div class='gd-ex-line'>・<span class='gd-jp'>人気歌手が来るとあって、会場には若い人が大勢集まった。</span>（Karena penyanyi terkenal akan datang, banyak sekali anak muda berkumpul di lokasi acara）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata benda</b>: disambung langsung, biasanya tanpa 「だ」.<br><span class='gd-pair'><span class='gd-jp'>連休</span> → <span class='gd-jp'>連休とあって</span></span><span class='gd-pair'><span class='gd-jp'>花火大会</span> → <span class='gd-jp'>花火大会とあって</span></span><br><b>Kata kerja, kata sifat-い</b>: pakai bentuk biasa (bentuk tanpa ます／です, bentuk lampau juga boleh).<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るとあって</span></span><span class='gd-pair'><span class='gd-jp'>優勝した</span> → <span class='gd-jp'>優勝したとあって</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとあって</span></span></div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Bagian belakang hanya boleh berisi <b>hasil atau keadaan yang benar-benar terlihat</b>, bukan niat, ajakan, atau permintaanmu sendiri.<br>×<span class='gd-jp'>連休とあって、旅行に行こう。</span><br>○<span class='gd-jp'>連休だから、旅行に行こう。</span>（Karena libur panjang, ayo pergi liburan）<br>・Bagian depan harus hal yang <b>istimewa dan jarang terjadi</b>. Alasan yang terlalu biasa terdengar aneh, misalnya 「lapar jadi beli roti」. Untuk itu cukup pakai 「から」「ので」.<br>・Setelah kata benda biasanya tidak ada だ: yang benar <span class='gd-jp'>連休とあって</span>, bukan 連休だとあって.<br>・Ini gaya bahasa tulis dan berita. Kalau ngobrol dengan teman, 「〜から」「〜ので」 lebih natural.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama dalam situasi yang berhubungan dengan 「社長」(direktur):<br><b>とあって</b> = karena ～, <b>makanya terlihat hasil seperti ini</b> (hal yang sudah terjadi)<br><span class='gd-jp'>社長が来るとあって、社員はみんな緊張している。</span>（Karena direktur akan datang, semua karyawan tegang）<br><b>とあれば</b> = <b>kalau memang ～</b>, maka (mau) … (pengandaian, syarat)<br><span class='gd-jp'>社長の頼みとあれば、断るわけにはいかない。</span>（Kalau itu permintaan direktur, tidak mungkin menolak）<br><b>にあって</b> = <b>berada dalam posisi atau keadaan ～</b><br><span class='gd-jp'>社長という立場にあって、そんな発言は許されない。</span>（Sebagai direktur, ucapan seperti itu tidak boleh）</div><div class='gd-warn'>Trik membedakan: 「karena ～, makanya (semua orang) jadi…」 itu とあって; 「kalau memang ～」 itu とあれば; 「berada dalam ～」 itu にあって.</div>","n1-25":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ばこそ」artinya <b>「justru karena ～, makanya…」</b>. Maknanya hampir sama dengan 「からこそ」, hanya saja lebih formal dan lebih terasa seperti bahasa tulis atau pidato. Sering dipakai untuk hal yang kelihatannya tidak enak, padahal di baliknya ada alasan baik, misalnya 「Justru karena sayang kamu, aku memarahimu」.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menyebut alasan yang sebenarnya</span>Tindakanmu mungkin disalahpahami orang, dan kamu ingin menegaskan 「aku melakukan ini karena ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたを思えばこそ、厳しく言うのです。</span>（Justru karena memikirkanmu, aku bicara dengan keras）</div><div class='gd-ex-line'>・<span class='gd-jp'>信頼していればこそ、この仕事を任せたのです。</span>（Justru karena percaya padamu, pekerjaan ini kuserahkan kepadamu）</div><div class='gd-sec'><span class='gd-tag'>Bisa dilakukan karena ada syarat ini</span>Menekankan bahwa suatu kondisi baik adalah kuncinya.</div><div class='gd-ex-line'>・<span class='gd-jp'>若ければこそ、失敗を恐れずに挑戦できる。</span>（Justru karena masih muda, kita bisa menantang diri tanpa takut gagal）</div><div class='gd-ex-line'>・<span class='gd-jp'>健康であればこそ、好きなことに挑戦できる。</span>（Justru karena sehat, kita bisa menantang diri pada hal yang kita sukai）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah dulu kata di depan menjadi bentuk 「〜ば」, lalu tambahkan <b>こそ</b>.<br><b>Golongan 1 (kata kerja godan)</b>: ganti bunyi terakhir dengan bunyi baris え di baris yang sama, lalu tambah ば.<br><span class='gd-pair'><span class='gd-jp'>思う</span> → う jadi え → <span class='gd-jp'>思えばこそ</span></span><br><b>Golongan 2 (kata kerja ichidan)</b>: buang る, tambah れば.<br><span class='gd-pair'><span class='gd-jp'>信じる</span> → <span class='gd-jp'>信じればこそ</span></span><br><b>Golongan 3 (する・来る)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すればこそ</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ればこそ</span>（くればこそ）</span><br>Untuk 「〜ている」, ubah いる jadi いれば: <span class='gd-pair'><span class='gd-jp'>案じている</span> → <span class='gd-jp'>案じていればこそ</span></span></div><div class='gd-sec'><b>Kata sifat-い</b>: ganti い dengan ければ. <span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若ければこそ</span></span><br><b>Kata benda, kata sifat-な</b>: tambahkan であれば. <span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親であればこそ</span></span><span class='gd-pair'><span class='gd-jp'>健康</span> → <span class='gd-jp'>健康であればこそ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>親であればこそ、子どもの幸せを願うのだ。</span>（Justru karena orang tua, kita mengharapkan kebahagiaan anak）</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・「ば」di sini <b>bukan 「kalau」</b>, tapi 「karena」. <span class='gd-jp'>思えばこそ</span> bukan 「kalau memikirkan」, melainkan 「justru karena memikirkan (kamu)」. Ini sisa pemakaian bahasa Jepang klasik, jadi bentuknya kelihatan persis sama dengan bentuk pengandaian.<br>・Kata benda dan kata sifat-な tidak bisa disambung langsung: yang benar <span class='gd-jp'>健康であればこそ</span>, bukan 「健康ばこそ」.<br>・Nadanya sangat formal dan jarang dipakai saat ngobrol. Dengan teman, cukup pakai <span class='gd-jp'>からこそ</span>; kalau pakai ばこそ, terdengar seperti membaca naskah.<br>・Alasan di depan biasanya positif dan tulus (cinta, kepercayaan, kesehatan, usaha), dan jarang dipakai untuk alasan sial atau negatif.<br>・Bagian belakang kalimat sering diakhiri <span class='gd-jp'>のだ／のです</span>, yang memberi kesan 「sebenarnya begitu」. Coba perhatikan di contoh-contohnya.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>からこそ</b> = justru karena ～ makanya…, bisa dipakai di lisan maupun tulisan: <span class='gd-jp'>好きだからこそ、厳しく言うんだよ。</span>（Justru karena aku suka kamu, aku bicara agak keras）<br><b>ばこそ</b> = artinya sama, tapi lebih formal, banyak dipakai di tulisan dan pidato: <span class='gd-jp'>愛すればこそ、厳しく言うのである。</span>（Justru karena cinta, aku berkata dengan tegas）<br><b>あっての</b> = 「ada ～ barulah ada…」, disambung dengan kata benda, intinya 「tanpa itu tidak akan ada」: <span class='gd-jp'>健康あっての人生だ。</span>（Ada kesehatan, barulah ada kehidupan）</div><div class='gd-warn'>Trik membedakan: untuk bicara sehari-hari pakai からこそ; untuk tulisan atau sambutan yang ingin terdengar khidmat pakai ばこそ; untuk makna 「tanpa itu tidak ada apa-apa」 pakai あっての.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Masih di N1, ungkapan untuk menyatakan sebab lainnya yang bisa kamu pelajari adalah <span class='gd-jp'>〜ゆえ（に）</span> (karena ～, lebih bersifat bahasa tulis) dan <span class='gd-jp'>〜あっての</span>.</div>","n1-12":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「AこそあれB（ない）」artinya <b>「A memang ada, tapi B sama sekali tidak ada」</b>. Dalam bahasa sehari-hari: <b>「hanya ada A, tidak ada B」</b>. Contohnya seperti kalimat \"Terhadapnya hanya ada rasa terima kasih, tidak ada dendam\". Ini bahasa tulis yang kaku. Untuk obrolan sehari-hari, cukup pakai 「<span class='gd-jp'>Aはあっても、Bはない</span>」.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Hanya A, tidak ada B</span>Taruh sepasang hal yang <b>berlawanan atau berkontras</b> di depan dan belakang, misalnya terima kasih dan dendam, kritik dan pujian. Pertama kamu mengakui bahwa A memang ada. Tekanannya ada pada B di belakang yang \"sama sekali tidak ada\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼には感謝こそあれ、恨みは少しもない。</span>（Terhadapnya hanya ada rasa terima kasih, dendam sedikit pun tidak ada）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の行動には批判こそあれ、賞賛の声はほとんど聞かれない。</span>（Terhadap tindakannya hanya ada kritik, suara pujian hampir tidak terdengar）</div><div class='gd-sec'><span class='gd-tag'>Ungkapan tetap</span><span class='gd-jp'>程度の差こそあれ</span>、<span class='gd-jp'>多少の違いこそあれ</span>＝「Memang ada perbedaan tingkat, tetapi……」. Di sini bagian belakangnya <b>tidak harus negatif</b>. Biasanya dipakai untuk bilang bahwa \"sebenarnya semua orang sama saja\".</div><div class='gd-ex-line'>・<span class='gd-jp'>程度の差こそあれ、誰にでも悩みはある。</span>（Tingkatnya memang berbeda, tapi setiap orang punya masalah）</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'>Kata benda langsung ditambah こそあれ：<span class='gd-pair'><span class='gd-jp'>感謝</span> → <span class='gd-jp'>感謝こそあれ</span></span><span class='gd-pair'><span class='gd-jp'>批判</span> → <span class='gd-jp'>批判こそあれ</span></span><br>Penutup yang sering muncul di bagian belakang: 「<span class='gd-jp'>〜はない</span>」「<span class='gd-jp'>ほとんど〜ない</span>」「<span class='gd-jp'>〜ことはない</span>」.</div><div class='gd-h'>Hal yang sering keliru</div><div class='gd-warn'>・Di depannya harus <b>kata benda</b>. Bentuk kamus kata kerja tidak bisa langsung disambung, jadi 「批判するこそあれ」 itu salah. Kalau mau pakai kata kerja, gunakan 「こそすれ」 di bawah, dan sambungkan dengan <b>bentuk ます yang ます-nya dibuang</b>.<br>・Artinya <b>bukan</b> 「justru karena ada ～」. Ini salah paham yang sering ada di buku pelajaran lama. 「Justru karena」 itu tata bahasa yang lain.<br>・Kedua sisi harus berupa pasangan kontras dalam satu topik yang sama. Kalau tidak nyambung, misalnya \"festivalnya terasa sederhana, tapi tidak ada tanda kemunduran\", orang Jepang akan merasa kalimatnya aneh.<br>・Nuansanya sangat formal, sering muncul di artikel, ulasan, dan pidato. Kalau dipakai ngobrol dengan teman, kedengarannya seperti membacakan surat dinas.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>こそすれ</b> juga berarti \"hanya A, tidak ada B\", bedanya di depannya ada <b>tindakan</b>.<br>Cara menyambung: <b>kata kerja bentuk ます (ます dibuang)＋こそすれ</b><br><span class='gd-pair'><span class='gd-jp'>上がります</span> → buang ます → <span class='gd-jp'>上がりこそすれ</span></span><br><span class='gd-pair'><span class='gd-jp'>褒められます</span> → buang ます → <span class='gd-jp'>褒められこそすれ</span></span><br>Kata kerja する bisa pakai 「kata benda＋こそすれ」, bisa juga 「し＋こそすれ」：<span class='gd-pair'><span class='gd-jp'>感謝します</span> → <span class='gd-jp'>感謝こそすれ</span>／<span class='gd-jp'>感謝しこそすれ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>物価は上がりこそすれ、下がることはないだろう。</span>（Harga barang hanya akan naik, tidak mungkin turun）</div><div class='gd-ex-line'>・<span class='gd-jp'>褒められこそすれ、叱られる理由はない。</span>（Seharusnya dipuji, tidak ada alasan untuk dimarahi）</div><div class='gd-sec'>Bandingkan dalam situasi yang sama:<br><span class='gd-jp'>彼女には感謝こそあれ、恨みはない。</span>（Yang <b>ada</b> di hati adalah rasa terima kasih: bicara soal \"keberadaan\"）<br><span class='gd-jp'>彼女には感謝こそすれ、恨むことはない。</span>（Yang <b>kulakukan</b> adalah berterima kasih: bicara soal \"tindakan\"）<br>Kalau diterjemahkan ke bahasa Indonesia, kedua kalimat ini artinya hampir sama.</div><div class='gd-sec'>Satu lagi, 「justru karena ～ maka ～」 itu <span class='gd-jp'>〜ばこそ</span>, dan 「hanya kalau ～ baru ～」 itu <span class='gd-jp'>〜てこそ</span>, misalnya <span class='gd-jp'>努力してこそ成功できる</span>（hanya dengan berusaha kamu bisa berhasil）. Jangan sampai tertukar dengan こそあれ hanya karena sama-sama ada こそ.</div><div class='gd-warn'>Trik menentukan: kalau di depannya <b>kata benda</b> (感謝、批判、差), pakai こそあれ. Kalau di depannya <b>kata kerja</b>, pakai こそすれ, dan kata kerjanya diubah dulu ke bentuk ます lalu ます-nya dibuang, misalnya 「上がり（こそすれ）」「褒められ（こそすれ）」「感謝し（こそすれ）」. Jangan sampai menulis 「褒められるこそすれ」.</div>","n1-13":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜まで（のこと）だ」mirip dengan <b>「paling-paling tinggal ～ saja」</b> dan <b>「aku cuma ～ kok」</b>. <span class='gd-jp'>まで</span> aslinya berarti \"sampai\". Di sini bayangkan artinya <b>「urusannya paling mentok sampai tahap ini, bukan masalah besar」</b>. Arti berbeda tergantung di depannya bentuk kamus atau bentuk た, jadi kita bahas terpisah di bawah.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Bentuk kamus: paling-paling tinggal ～</span>Dipakai saat rencana tidak berjalan dan kamu sudah menyiapkan jalan mundur, dengan sikap \"tidak apa-apa, ya tinggal begitu saja\". Di depannya sering ada 「〜なら」「〜ば」「〜ても」, yang dulu menyebut kemungkinan tidak lancar.</div><div class='gd-ex-line'>・<span class='gd-jp'>だめなら、また一からやり直すまでだ。</span>（Kalau gagal, paling-paling mulai lagi dari awal）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰も手伝ってくれないなら、一人でやるまでだ。</span>（Kalau tidak ada yang mau membantu, ya aku kerjakan sendiri saja）</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が動かなければ、歩いて帰るまでのことだ。</span>（Kalau keretanya tidak jalan, paling-paling aku jalan kaki pulang）</div><div class='gd-sec'><span class='gd-tag'>Bentuk た: hanya ～ saja</span>Dipakai untuk menjelaskan hal yang sudah kamu lakukan, artinya \"tidak ada maksud lain\" atau \"bukan hal yang hebat\". Sering dipakai saat diberi ucapan terima kasih, kedengarannya rendah hati.</div><div class='gd-ex-line'>・<span class='gd-jp'>当然のことをしたまでです。</span>（Saya hanya melakukan apa yang seharusnya）</div><div class='gd-ex-line'>・<span class='gd-jp'>念のため、確認したまでです。</span>（Saya hanya memastikan, untuk berjaga-jaga）</div><div class='gd-ex-line'>・<span class='gd-jp'>思ったことを言ったまでだ。</span>（Aku hanya mengatakan apa yang kupikirkan）</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'>Kata kerja bentuk kamus＋までだ／までのことだ：<span class='gd-pair'><span class='gd-jp'>やり直す</span> → <span class='gd-jp'>やり直すまでだ</span></span><br>Kata kerja bentuk た＋までだ／までのことだ：<span class='gd-pair'><span class='gd-jp'>した</span> → <span class='gd-jp'>したまでです</span></span><br>Dengan atau tanpa 「<span class='gd-jp'>のこと</span>」 artinya sama, tapi kalau ada terasa lebih seperti \"ya cuma begitu saja\". Untuk bentuk sopan, cukup ganti <span class='gd-jp'>だ</span> dengan <span class='gd-jp'>です</span>.</div><div class='gd-h'>Hal yang sering keliru</div><div class='gd-warn'>・<span class='gd-jp'>まで</span> di sini bukan \"sampai ～\". <span class='gd-jp'>帰るまで</span> kalau berdiri sendiri artinya \"sampai pulang\", jadi perhatikan apakah di belakangnya ditutup dengan <span class='gd-jp'>だ</span>.<br>・Jangan tertukar antara bentuk kamus dan bentuk た: <span class='gd-jp'>やり直すまでだ</span> artinya \"paling-paling ulang saja\" (belum dilakukan), sedangkan <span class='gd-jp'>やり直したまでだ</span> artinya \"aku hanya mengulang saja\" (sudah dilakukan).<br>・Bentuk kamus punya nuansa \"nekat, pasrah saja\", biasanya untuk menyatakan tekad pihak <b>diri sendiri</b>, bukan untuk menyuruh orang lain.<br>・Yang ada di depannya biasanya rencana cadangan yang \"sebenarnya bukan pilihan utama tapi tidak masalah\", bukan hal yang menyenangkan.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>〜までだ</b>＝paling-paling tinggal dilakukan: <span class='gd-jp'>聞かれたら、説明するまでだ。</span>（Kalau ditanya, ya tinggal dijelaskan）<br><b>〜までもない</b>＝sama sekali tidak perlu dilakukan: <span class='gd-jp'>簡単だから、説明するまでもない。</span>（Ini mudah, tidak perlu dijelaskan）</div><div class='gd-sec'><b>〜までだ</b>＝masih ada jalan mundur, optimis: <span class='gd-jp'>失敗したら、またやるまでだ。</span>（Kalau gagal, ya coba lagi saja）<br><b>〜ばそれまでだ</b>＝begitu terjadi, semuanya tamat, pesimis: <span class='gd-jp'>一度失敗すれば、それまでだ。</span>（Sekali gagal, selesai sudah）</div><div class='gd-warn'>Trik menentukan: 「kata kerja＋までだ」berarti masih ada jalan; 「それまでだ」berarti jalannya sudah buntu; 「までもない」berarti tidak perlu lewat jalan ini.</div>","n1-26":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜手前」kira-kira artinya <b>“sudah terlanjur bilang, masa mau mundur…” “dilihat orang begini, malu kalau…”</b>. Karena kamu sudah mengatakan atau melakukan sesuatu, atau ada orang lain yang memperhatikan, kamu terpaksa melakukan sesuatu atau tidak bisa melakukan hal tertentu demi menjaga <b>muka dan posisimu sendiri</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sudah terlanjur bilang</span>Di depannya ada verba, biasanya hal yang sudah kamu katakan atau lakukan. Karena sudah telanjur, sekarang kamu tidak bisa menjilat ludah sendiri.</div><div class='gd-ex-line'>・<span class='gd-jp'>引き受けた手前、途中でやめるわけにはいかない。</span>（Sudah terima tugasnya, masa berhenti di tengah jalan）</div><div class='gd-ex-line'>・<span class='gd-jp'>「絶対合格する」と言った手前、遊んでいられない。</span>（Sudah sesumbar “pasti lulus”, mana bisa santai-santai main）</div><div class='gd-sec'><span class='gd-tag'>Ada orang yang melihat</span>Di depannya ada orang, artinya “di depan ～” atau “memikirkan bagaimana ～ memandangku”. Yang dijaga adalah <b>citramu sendiri</b> di mata orang-orang itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>みんなの手前、そんなことは言えない。</span>（Di depan semua orang, aku tidak bisa bilang hal seperti itu）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの手前、夫婦げんかはしないようにしている。</span>（Demi anak, kami berusaha tidak bertengkar di depan mereka）</div><div class='gd-sec'><span class='gd-tag'>Status diri sendiri</span>Dengan 「〜である手前」, kamu menyebut statusmu sendiri. Artinya “sebagai ～, masa …”.</div><div class='gd-ex-line'>・<span class='gd-jp'>教師である手前、生徒の前でたばこは吸えない。</span>（Sebagai guru, masa merokok di depan murid）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Verba: langsung sambung dengan bentuk biasa (bentuk tanpa ます). Yang paling sering dipakai adalah bentuk た, tapi bentuk kamus dan bentuk ている juga bisa.<br><span class='gd-pair'><span class='gd-jp'>約束した</span> → <span class='gd-jp'>約束した手前</span></span><span class='gd-pair'><span class='gd-jp'>言っている</span> → <span class='gd-jp'>言っている手前</span></span><br>Nomina: tambahkan 「の」 lalu sambung.<span class='gd-pair'><span class='gd-jp'>部下</span> → <span class='gd-jp'>部下の手前</span></span><br>Bagian belakangnya hampir selalu berupa ungkapan “terpaksa” atau “tidak boleh”, misalnya <span class='gd-jp'>〜わけにはいかない</span>, <span class='gd-jp'>〜しかない</span>, <span class='gd-jp'>〜られない</span>, <span class='gd-jp'>〜ないといけない</span>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Yang dijaga adalah muka dan posisi <b>dirimu sendiri (atau subjek kalimat)</b>, bukan muka lawan bicara. <span class='gd-jp'>部長は部下の手前、ミスを認めにくかった。</span> artinya sang kepala bagian gengsi mengaku salah di depan bawahannya. Yang dijaga adalah citra kepala bagian itu sendiri, bukan muka bawahannya.<br>・Bagian belakangnya hampir selalu berkesan terpaksa, seperti “mau tidak mau ～” atau “tidak boleh ～”. Tidak bisa dipakai untuk hal yang menyenangkan atau dinanti-nanti. Kalimat seperti 「約束した手前、楽しみだ」 terdengar aneh.<br>・<span class='gd-jp'>手前</span> dibaca <b>てまえ</b>. Arti asalnya “sisi yang dekat, sebelum sampai”, misalnya <span class='gd-jp'>駅の手前で降りる</span> (turun sebelum sampai stasiun). Kalau melihat “nomina＋の手前”, perhatikan konteksnya: kalau di depannya ada orang dan di belakangnya hal yang tidak bisa dilakukan atau terpaksa dilakukan, itu pola tata bahasa ini, bukan soal posisi.<br>・Ini ungkapan yang agak formal dan cenderung tertulis. Dalam obrolan sehari-hari, kamu lebih sering mendengar yang seperti 「言っちゃったし…」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><span class='gd-jp'>〜からには</span> dan <span class='gd-jp'>〜以上</span> juga bisa diterjemahkan “karena sudah ～”, tapi fokusnya berbeda:<br><b>からには／以上</b> = karena sudah ～, maka harus bertanggung jawab sampai akhir. Fokusnya pada <b>logika dan tekad</b>.<br><b>手前</b> = karena sudah ～, kalau tidak begitu, <b>jadi malu</b>. Fokusnya pada <b>bagaimana orang lain memandangku</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したからには、必ず行く。</span>（Karena sudah berjanji, aku pasti datang: soal tekad）</div><div class='gd-ex-line'>・<span class='gd-jp'>約束した手前、行かないわけにはいかない。</span>（Sudah janji sama orangnya, tidak datang rasanya tidak enak: soal muka）</div><div class='gd-sec'>Setelah からには dan 以上, kamu bisa menyambung keinginanmu sendiri, tapi dengan 手前 tidak bisa:<br><span class='gd-jp'>日本に来たからには、富士山に登りたい。</span>（Karena sudah datang ke Jepang, aku ingin mendaki Gunung Fuji）<br>Kalau diganti 手前, kalimat ini jadi tidak masuk akal, karena mendaki Gunung Fuji atau tidak tidak ada hubungannya dengan muka.</div><div class='gd-warn'>Tips menentukan: kalau di belakangnya bisa ditambah “kalau tidak, memalukan / tidak enak”, pakai 手前. Kalau cuma “karena sudah ～, ya seharusnya ～”, pakai からには atau 以上.</div>","n1-32":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜ところを」yang paling sering muncul kira-kira artinya <b>“di tengah kesibukan Anda, kami masih merepotkan” “maaf mengganggu waktu istirahat Anda”</b>. Pertama kamu menyebut keadaan lawan bicara (sedang sibuk, istirahat, lelah), lalu di belakangnya ada <b>ucapan terima kasih atau permintaan maaf</b>. Ini basa-basi yang sangat formal. Selain itu, pola ini juga bisa berarti <b>“seharusnya ～, tapi malah …”</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Basa-basi: mengganggu lawan bicara</span>Di depan ada keadaan lawan bicara, di belakang ada “terima kasih”, “maaf”, atau hal yang dilakukan lawan bicara untukmu. Sering muncul di telepon bisnis, pidato, dan email.</div><div class='gd-ex-line'>・<span class='gd-jp'>お忙しいところをありがとうございます。</span>（Di tengah kesibukan Anda, terima kasih）</div><div class='gd-ex-line'>・<span class='gd-jp'>お休みのところ、申し訳ありません。</span>（Maaf mengganggu waktu istirahat Anda）</div><div class='gd-ex-line'>・<span class='gd-jp'>お疲れのところ、すみません。少しだけいいですか。</span>（Maaf mengganggu, Anda pasti lelah. Boleh minta waktu sebentar?）</div><div class='gd-sec'><span class='gd-tag'>Seharusnya ～ tapi…</span>Di depan kamu menyebut “seharusnya begini”, di belakang kenyataannya berubah jadi lain, biasanya hal yang menguntungkan kamu.</div><div class='gd-ex-line'>・<span class='gd-jp'>本来ならこちらから伺うべきところを、わざわざお越しいただきました。</span>（Seharusnya kami yang datang berkunjung, tapi Anda malah repot-repot datang）</div><div class='gd-ex-line'>・<span class='gd-jp'>普通なら罰金のところを、今回は注意だけで済んだ。</span>（Biasanya kena denda, tapi kali ini cuma ditegur dan selesai）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Verba</b>: langsung sambung.<br><span class='gd-pair'><span class='gd-jp'>休んでいる</span> → <span class='gd-jp'>休んでいるところを</span></span><br><span class='gd-pair'><span class='gd-jp'>伺うべき</span> → <span class='gd-jp'>伺うべきところを</span></span><br><b>Adjektiva い</b>: langsung sambung. Dalam basa-basi, di depannya sering ditambah お.<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>お忙しいところを</span></span><br><b>Adjektiva な</b>: tambahkan な lalu sambung.<br><span class='gd-pair'><span class='gd-jp'>大変</span> → <span class='gd-jp'>大変なところを</span></span><br><b>Nomina</b>: tambahkan の lalu sambung.<br><span class='gd-pair'><span class='gd-jp'>お休み</span> → <span class='gd-jp'>お休みのところを</span></span><br><span class='gd-pair'><span class='gd-jp'>ご多忙</span> → <span class='gd-jp'>ご多忙のところを</span></span><br>Saat bicara, 「を」 sering dihilangkan. Cukup bilang <span class='gd-jp'>お忙しいところ</span> pun sama sekali tidak masalah.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah adjektiva い tidak boleh ditambah の: yang benar <span class='gd-jp'>お忙しいところ</span>, bukan お忙しいのところ. の hanya untuk nomina.<br>・Ini ungkapan yang sangat formal. Kalau kamu bilang 「お忙しいところを」 ke teman, jadinya terdengar kaku dan berjarak. Antar teman, cukup <span class='gd-jp'>忙しいのにごめんね</span>.<br>・Dalam pemakaian basa-basi, yang disebut di depan adalah keadaan <b>lawan bicara</b>, bukan keadaanmu. Kalau kamu sendiri sibuk tapi tetap membantu, kamu tidak akan bilang 「私の忙しいところを」.<br>・Hal di belakangnya biasanya <b>berdampak pada lawan bicara</b>: mengganggu, merepotkan, atau hal yang lawan bicara lakukan untukmu. Tidak bisa disambung dengan hal yang tidak ada hubungannya dengan lawan bicara.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>ところを＋見る／見つかる</b> = <b>adegan saat kepergok</b>. Ini 「ところ」 dari N3 ditambah を sebagai objek, bukan basa-basi: <span class='gd-jp'>タバコを吸っているところを先生に見られた。</span>（Waktu sedang merokok, aku dilihat guru）<br><b>ところを (seharusnya ～ tapi…)</b> = semestinya begitu, tapi kenyataannya berakhir baik: <span class='gd-jp'>普通なら怒られるところを、許してもらった。</span>（Biasanya pasti dimarahi, tapi aku dimaafkan）<br><b>ものを</b> = “padahal kalau ～ kan sudah beres”, bernada mengeluh atau menyesal, sering di akhir kalimat: <span class='gd-jp'>一言言ってくれればよかったものを。</span>（Padahal tinggal bilang satu kata saja）</div><div class='gd-warn'>Tips menentukan: kalau di belakangnya ada 「見られた、見つかった」 → adegan kepergok. Kalau di belakangnya terima kasih, maaf, atau keuntungan → basa-basi / seharusnya ～ tapi…. Kalau seluruh kalimat berisi keluhan “tahu begitu kan lebih baik ～” → ものを.</div><div class='gd-h'>Setelah ini, belajar yang berikut</div><div class='gd-sec'>Maknanya sangat mirip dan juga sering dipakai dalam basa-basi, yaitu 「中」: <span class='gd-jp'>お足元の悪い中、お越しいただきありがとうございます。</span>（Di tengah cuaca yang kurang baik, terima kasih sudah datang）</div>","n1-35":"<div class='gd-h'>Langsung paham dalam satu kalimat</div><div class='gd-sec'>「〜の至り」kira-kira berarti <b>「…sekali / sungguh …」</b>, seperti dalam «sungguh suatu kehormatan» atau «terima kasih yang sebesar-besarnya». Dalam bahasa Jepang, <span class='gd-jp'>光栄の至りです</span> artinya «saya benar-benar merasa sangat terhormat». Ini ungkapan yang sangat formal. Biasanya muncul di pidato upacara, pidato saat menerima penghargaan, dan surat bisnis. Kamu tidak akan memakainya saat ngobrol santai dengan teman.</div><div class='gd-h'>Apa itu 「至り」?</div><div class='gd-sec'><span class='gd-jp'>至り</span> adalah kata benda yang berasal dari kata kerja <span class='gd-jp'>至る</span> (sampai, tiba), dan artinya «sampai di titik puncak». Jadi <span class='gd-jp'>光栄の至り</span> = kehormatan yang sudah sampai di puncak = terhormat sekali.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda + の至り, dan di akhir kalimat biasanya diikuti です atau でございます.<br><span class='gd-pair'><span class='gd-jp'>光栄</span> → <span class='gd-jp'>光栄の至りです</span></span><br><span class='gd-pair'><span class='gd-jp'>感激</span> → <span class='gd-jp'>感激の至りでございます</span></span><br>Perhatikan baik-baik: kata benda yang dipakai di depannya <b>hampir selalu itu-itu saja</b>. Tidak semua kata benda bisa dimasukkan.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Terima kasih・Kehormatan</span>Yang paling umum adalah <span class='gd-jp'>光栄の至り</span> dan <span class='gd-jp'>感激の至り</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>このような賞をいただき、光栄の至りです。</span>（Menerima penghargaan seperti ini, sungguh suatu kehormatan besar bagi saya）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様から温かいお言葉をいただき、感激の至りです。</span>（Menerima kata-kata hangat dari Anda semua, saya sangat terharu）</div><div class='gd-sec'><span class='gd-tag'>Rasa tidak enak・Malu</span>Yang umum adalah <span class='gd-jp'>恐縮の至り</span> (sangat sungkan, tidak enak hati) dan <span class='gd-jp'>赤面の至り</span> (malu sampai wajah memerah).</div><div class='gd-ex-line'>・<span class='gd-jp'>お忙しいところお越しいただき、恐縮の至りでございます。</span>（Di tengah kesibukan Anda, Anda masih berkenan hadir. Kami sungguh merasa sungkan）</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな初歩的なミスをしてしまい、赤面の至りです。</span>（Saya membuat kesalahan dasar seperti ini, sungguh memalukan）</div><div class='gd-sec'><span class='gd-tag'>Satu yang istimewa</span><span class='gd-jp'>若気の至り</span> artinya agak berbeda: «kesalahan yang dibuat karena masih muda dan belum berpikir panjang». Di sini 至り lebih dekat ke «akibat yang ditimbulkan». Ungkapan ini sering dipakai untuk mengenang kelakuan konyol di masa lalu dengan nada menertawakan diri sendiri, jadi tidak harus dipakai di situasi formal.</div><div class='gd-ex-line'>・<span class='gd-jp'>学生時代は若気の至りで、ずいぶん無茶をした。</span>（Waktu masih kuliah, namanya juga darah muda, aku banyak berbuat nekat）</div><div class='gd-h'>Bagian yang mudah salah</div><div class='gd-warn'>・Di depannya harus ada <b>kata benda + の</b>. Kata sifat tidak bisa langsung dipasang. <span class='gd-jp'>嬉しいの至り</span> dan <span class='gd-jp'>ありがたいの至り</span> keduanya salah. Kalau mau mengungkapkan rasa senang atau terima kasih, pakai kombinasi tetap seperti <span class='gd-jp'>光栄</span> dan <span class='gd-jp'>感激</span>.<br>・Jangan asal mengganti kata bendanya. Hafalkan saja 光栄・感激・恐縮・赤面・若気, itu paling aman.<br>・Ungkapan ini terutama untuk perasaan <b>diri sendiri</b>, dan terdengar rendah hati. Kalau dipakai untuk perasaan orang lain, misalnya «Pak Kepala Bagian sangat merasa terhormat», kedengarannya akan aneh.<br>・Nadanya sangat formal. Kalau kamu bilang ke teman <span class='gd-jp'>ケーキありがとう、感激の至り！</span>, kedengarannya seperti bercanda, pura-pura bergaya.<br>・<span class='gd-jp'>若気</span> dibaca <span class='gd-jp'>わかげ</span>, bukan わかき.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>の至り</b> = rasa terima kasih atau malu diri sendiri yang sudah sampai puncak, nadanya rendah hati: <span class='gd-jp'>お招きいただき、光栄の至りです。</span>（Atas undangan Anda, sungguh suatu kehormatan bagi saya）<br><b>極まりない</b> = suatu hal atau sikap yang «sangat sekali ~», kebanyakan dipakai untuk mengkritik atau mengeluh: <span class='gd-jp'>連絡もなく欠席するなんて、失礼極まりない。</span>（Tidak hadir tanpa kabar sama sekali, benar-benar kurang ajar）<br><b>に至る</b> = kata kerja yang berarti sesuatu «berkembang sampai pada hasil atau tahap tertentu»: <span class='gd-jp'>何度も話し合った結果、ようやく合意に至った。</span>（Setelah berkali-kali berunding, akhirnya tercapai kesepakatan）</div><div class='gd-warn'>Trik cepat: untuk perasaan diri sendiri yang «sangat sekali», pakai の至り. Untuk mencela orang atau mengeluh «keterlaluan ~», pakai 極まりない. Untuk hal yang «berkembang sampai ~», pakai に至る.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'><span class='gd-jp'>〜に堪えない</span> juga ungkapan untuk menyatakan perasaan yang kuat di situasi formal: <span class='gd-jp'>皆様のご支援には感謝に堪えません。</span>（Atas dukungan Anda semua, kami tak terhingga berterima kasih）</div>","n1-41":"<div class='gd-h'>Langsung paham dalam satu kalimat</div><div class='gd-sec'>「〜といったらない」kira-kira berarti <b>«… banget», «… parah», «… sekali, sampai tak terkatakan»</b>. Secara harfiah artinya «kalau bicara soal seberapa ~, rasanya tidak ada kata yang cukup untuk menggambarkannya». Dipakai untuk melebih-lebihkan, menekankan bahwa suatu perasaan sudah sangat kuat. Bisa untuk hal baik maupun buruk: senang banget, dingin banget, malu banget, semuanya bisa.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata benda</b> + といったらない (yang paling umum adalah mengubah kata sifat menjadi kata benda berakhiran 「～さ」)<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い diganti さ → <span class='gd-jp'>寒さといったらない</span></span><br><b>Kata sifat-い</b>: langsung disambung<br><span class='gd-pair'><span class='gd-jp'>うれしい</span> → <span class='gd-jp'>うれしいといったらない</span></span><br><b>Kata sifat-な</b>: tanpa な, langsung disambung<br><span class='gd-pair'><span class='gd-jp'>退屈</span> → <span class='gd-jp'>退屈といったらない</span></span></div><div class='gd-sec'>Untuk hal yang terjadi di <b>masa lalu</b>, ubah menjadi 「といったら<b>なかった</b>」.</div><div class='gd-ex-line'>・<span class='gd-jp'>初めて富士山を見た時の感動といったらなかった。</span>（Rasa haru saat pertama kali melihat Gunung Fuji itu benar-benar tak bisa diungkapkan）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日同じ作業ばかりで、退屈といったらない。</span>（Setiap hari kerjanya itu-itu saja, bosan banget）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ったらない</span>Bentuk singkat lisan dari 「といったらない」. Sering terdengar saat ngobrol dengan teman atau curhat dan mengeluh. Di depannya biasanya langsung kata sifat-い.</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の工事、うるさいったらないよ。</span>（Proyek bangunan di sebelah itu, berisik banget）</div><div class='gd-sec'><span class='gd-tag'>ったらありゃしない</span>Lebih lisan dan lebih emosional. Kebanyakan dipakai untuk mengeluh, saat malu, atau marah.</div><div class='gd-ex-line'>・<span class='gd-jp'>みんなの前で転ぶなんて、恥ずかしいったらありゃしない。</span>（Jatuh di depan semua orang, malunya bukan main）</div><div class='gd-h'>Bagian yang mudah salah</div><div class='gd-warn'>・「ない」di sini <b>bukan negasi</b>. <span class='gd-jp'>うれしいといったらない</span> artinya «senang sekali», bukan «tidak senang».<br>・Kata sifat-な jangan ditambah な: bilang <span class='gd-jp'>退屈といったらない</span>, bukan 退屈なといったらない.<br>・Kalau kejadiannya sudah lewat, pakai 「といったらなかった」. Kalau tidak, kedengarannya seperti masih terjadi sekarang.<br>・Di depannya biasanya kata sifat atau kata benda, terutama 「～さ」. Kata kerja jarang disambung langsung.<br>・「ったらない」dan「ったらありゃしない」sangat lisan, jadi jangan dipakai di situasi formal atau kepada atasan.<br>・Jangan tertukar dengan 「といったら（kalau bicara soal ~）」: <span class='gd-jp'>日本といったら、やっぱり寿司だ。</span>（Kalau bicara soal Jepang, ya tetap sushi）Di belakangnya tidak ada ない, dan artinya benar-benar lain.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>〜ったら（n1-44）</b>: di depannya <b>orang</b>, artinya «aduh, ~ itu lho», dengan nada pasrah atau mengeluh, dan di belakangnya ada kalimat utuh.<br><span class='gd-jp'>うちの母ったら、また夜中に電話してきた。</span>（Ibuku nih, nelepon tengah malam lagi）<br><span class='gd-jp'>うちの母、心配性ったらない。</span>（Ibuku itu cemasan banget）</div><div class='gd-warn'>Trik cepat: kalau 「ったら」 langsung diikuti 「ない」 dan di depannya kata sifat atau 「～さ」, itu sedang menyatakan tingkat. Kalau di depannya orang dan di belakangnya ada satu kalimat, itu sedang mengeluhkan orang tersebut.</div><div class='gd-sec'><b>〜極まりない（n1-34）</b>: juga berarti «sampai puncak ~», tetapi lebih kaku dan bernuansa tulisan, kebanyakan untuk penilaian negatif, seperti di berita atau surat keluhan pelanggan. 「といったらない」 lebih terasa seperti menceritakan perasaan pribadi, dan bisa dipakai untuk hal positif maupun negatif.<br><span class='gd-jp'>あの店員の態度は失礼極まりない。</span>（Sikap pelayan itu sangat tidak sopan: terdengar seperti komplain resmi）<br><span class='gd-jp'>あの店員の態度の悪さといったらなかった。</span>（Sikap pelayan itu buruk banget: terdengar seperti cerita pengalaman ke teman）</div><div class='gd-warn'>Trik cepat: untuk tulisan formal atau kritik tegas, pakai 「極まりない」. Untuk menceritakan perasaan sendiri dengan sedikit emosi dan melebih-lebihkan, pakai 「といったらない」.</div>","n1-42":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「Aと言わずBと言わず」artinya kira-kira <b>「baik A maupun B, semuanya ～」</b>. Dua contoh yang mewakili disebut supaya terasa bahwa <b>keseluruhannya begitu</b>. Mirip dengan kalimat Indonesia \"tangan dan kakinya penuh lumpur\", padahal maksudnya seluruh badannya kotor.</div><div class='gd-ex-line'>・<span class='gd-jp'>手と言わず足と言わず、泥だらけになった。</span>（Baik tangan maupun kaki, semuanya penuh lumpur）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Nomina＋と言わず＋nomina＋と言わず, jadi <b>setiap nomina harus diikuti satu 「と言わず」</b>.<br>「言わず」adalah bentuk yang lebih klasik dari 「言わない」. Secara harfiah artinya \"tidak menyebut A, tidak menyebut B juga\", maksudnya \"tidak membeda-bedakan A dan B\". Sering juga ditulis dengan hiragana: <span class='gd-jp'>といわず</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Tubuh</span>Dari kepala sampai kaki, seluruh tubuh.</div><div class='gd-ex-line'>・<span class='gd-jp'>顔と言わず腕と言わず、蚊に刺されてしまった。</span>（Di muka, di lengan, di mana-mana digigit nyamuk）</div><div class='gd-sec'><span class='gd-tag'>Tempat</span>Seluruh ruangan atau seluruh area.</div><div class='gd-ex-line'>・<span class='gd-jp'>壁と言わず床と言わず、部屋中に落書きがしてあった。</span>（Entah di dinding entah di lantai, seluruh ruangan penuh coretan）</div><div class='gd-sec'><span class='gd-tag'>Waktu</span>Tidak peduli jamnya, terus-menerus begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>昼と言わず夜と言わず、工事の音が響いている。</span>（Siang maupun malam, suara pembangunan terus menggema）</div><div class='gd-ex-line'>・<span class='gd-jp'>平日と言わず週末と言わず、この店はいつも行列ができている。</span>（Hari biasa maupun akhir pekan, toko ini selalu antre）</div><div class='gd-sec'>Kamu akan sering menemukan kata-kata bermakna \"semua\" seperti <span class='gd-jp'>部屋中</span>, <span class='gd-jp'>町中</span>, <span class='gd-jp'>いつも</span>, dan <span class='gd-jp'>だらけ</span> di bagian belakang kalimat. Kata-kata itu menyambung dengan makna \"tidak membedakan A dan B\" di depannya.</div><div class='gd-h'>Hal yang sering salah</div><div class='gd-warn'>・Kedua 「と言わず」 harus ditulis. <span class='gd-jp'>手と足と言わず</span> itu salah, yang benar <span class='gd-jp'>手と言わず足と言わず</span>.<br>・A dan B harus <b>sejenis</b> dan merupakan bagian dari satu keseluruhan (tangan dan kaki = seluruh tubuh, siang dan malam = sehari penuh). Kalau asal menggabungkan dua hal yang tidak berhubungan, kedengarannya aneh.<br>・Pola ini dipakai untuk <b>menggambarkan keadaan yang benar-benar terlihat</b>, dan sering untuk keadaan yang mengejutkan atau kurang menyenangkan (badan penuh lumpur, luka di mana-mana, berisik terus).<br>・Ini ungkapan tulisan yang agak kaku, lebih sering muncul di novel dan berita. Dalam percakapan sehari-hari orang Jepang biasanya bilang <span class='gd-jp'>手も足も</span> atau <span class='gd-jp'>どこもかしこも</span>.<br>・Jangan tertukar dengan 「と言わず」 yang berdiri sendiri: <span class='gd-jp'>明日と言わず、今すぐ行こう。</span>（Jangan tunggu besok, ayo pergi sekarang juga）Ini artinya \"tidak perlu menunggu sampai A\", berbeda dengan pola ini.<br>・「言わず」 dalam <span class='gd-jp'>何も言わずに帰った</span>（pulang tanpa mengatakan apa-apa）benar-benar berarti \"tidak berkata\", tidak ada hubungannya dengan pola ini.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama berarti \"baik A maupun B\", tetapi <span class='gd-jp'>Aであれ Bであれ</span> terasa berbeda:<br><b>と言わず</b> = <b>menggambarkan keadaan nyata di depan mata</b>, di mana-mana begitu:<br><span class='gd-jp'>駅前と言わず住宅街と言わず、どこも観光客であふれている。</span>（Baik di depan stasiun maupun di kawasan perumahan, semua tempat penuh turis）<br><b>であれ</b> = <b>yang mana pun, aturan atau penilaian yang sama berlaku</b>:<br><span class='gd-jp'>駅前であれ住宅街であれ、ごみを捨ててはいけない。</span>（Di depan stasiun maupun di kawasan perumahan, tidak boleh membuang sampah sembarangan）<br>Kalimat kedua berisi aturan, jadi kalau diganti dengan と言わず akan terasa tidak natural.</div><div class='gd-warn'>Tips menentukan: kalau kamu menggambarkan \"ke mana pun memandang, semuanya begitu\", pakai と言わず; kalau menyatakan aturan atau penilaian \"apa pun jenisnya tetap harus ～\", pakai であれ.</div>","n1-44":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「Nomina＋ったら」artinya kira-kira <b>\"Aduh, si dia itu lho, ada-ada saja...\"</b>. Kamu menyebut dulu orang di sekitarmu, lalu membicarakan hal yang bikin kamu kesal tapi juga geli. Intinya adalah <b>pasrah dan mengeluh, tetapi dengan rasa sayang</b>, bukan benar-benar memarahi.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Cukup tambahkan 「ったら」 langsung setelah nomina, tanpa perubahan bentuk.<br><span class='gd-pair'><span class='gd-jp'>弟</span> → <span class='gd-jp'>弟ったら</span></span><span class='gd-pair'><span class='gd-jp'>お母さん</span> → <span class='gd-jp'>お母さんったら</span></span><span class='gd-pair'><span class='gd-jp'>あなた</span> → <span class='gd-jp'>あなたったら</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mengeluh ke orang lain</span>Saat ngobrol dengan teman tentang keluarga, rekan kerja, atau hewan peliharaan, dipakai untuk membuka topik \"dia mulai lagi\".</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの猫ったら、また私の椅子で寝てる。</span>（Kucingku ini lho, tidur lagi di kursiku）</div><div class='gd-ex-line'>・<span class='gd-jp'>父ったら、また眼鏡をなくしたの。</span>（Ayahku ini lho, menghilangkan kacamatanya lagi）</div><div class='gd-sec'><span class='gd-tag'>Menegur langsung</span>Memanggil lawan bicara langsung dengan nuansa \"ih, kamu ini!\", sering dipasangkan dengan 「もう」.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう、お母さんったら！その話はしないでって言ったでしょ。</span>（Ih, Ibu ini! Kan sudah kubilang jangan bahas hal itu）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんったら、冗談ばっかり。</span>（Tanaka-san ini, bercanda melulu）</div><div class='gd-sec'>Kalimat setelahnya sering berhenti di tengah, seperti <span class='gd-jp'>弟ったら、また忘れ物して…。</span>（Adikku ini, lupa bawa barang lagi...）. Bagian yang tidak diucapkan itu seperti helaan napas \"haduh\".</div><div class='gd-h'>Hal yang sering salah</div><div class='gd-warn'>・Ini <b>bukan \"kalau\"</b>. 「たら」 di <span class='gd-jp'>雨が降ったら</span> berarti \"kalau ～\", sedangkan nomina＋ったら berarti \"si ini lho, ada-ada saja\". Keduanya benar-benar berbeda.<br>・Nuansanya sangat santai dan akrab, dipakai untuk keluarga, teman, dan hewan peliharaan. Tidak cocok dipakai langsung kepada atasan atau pelanggan, atau dalam situasi formal.<br>・Setelahnya biasanya hal yang <b>bikin kamu melongo, pasrah, atau sedikit malu</b>. Kalau hanya ingin memuji atau berterima kasih, pakai 「は」 biasa saja. Kalaupun dipakai untuk hal baik, nuansanya tetap malu atau pasrah seperti \"dia terlalu sungkan, ih\".<br>・Ada 「っ」 kecil sebelum たら, jadi bacanya berhenti sebentar dulu: 「ったら」, bukan 「たら」.<br>・Kamu juga akan mendengar <span class='gd-jp'>お母さんってば</span>, nuansanya mirip ったら dan sama-sama bahasa lisan.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>ったら</b> = pasrah yang diselipi rasa sayang, boleh juga dipakai untuk memanggil lawan bicara langsung:<br><span class='gd-jp'>うちの子ったら、またゲームばっかり。</span>（Anakku ini lho, main game melulu lagi）<br><b>ときたら</b> = mengomel lebih serius, nuansa negatifnya lebih kuat, biasanya diceritakan ke orang lain dan tidak dipakai untuk memanggil orangnya langsung:<br><span class='gd-jp'>うちの子ときたら、毎日ゲームばっかりで全然勉強しない。</span>（Kalau bicara soal anakku, tiap hari main game melulu dan sama sekali tidak belajar）<br><b>ったらない</b> = biasanya didahului adjektiva, artinya \"～ banget\", tidak ada hubungannya dengan mengeluhkan seseorang:<br><span class='gd-jp'>あの時は恥ずかしいったらなかった。</span>（Waktu itu malunya bukan main）</div><div class='gd-warn'>Tips menentukan: kalau kamu bilang \"ih, ada-ada saja\" sambil tersenyum, itu ったら; kalau mengomel sambil mengerutkan dahi, itu ときたら; kalau setelah ったら ada 「ない」 dan sebelumnya adjektiva, artinya \"～ banget\".</div><div class='gd-h'>Lanjut belajar setelah ini</div><div class='gd-sec'>Lanjutkan dengan <span class='gd-jp'>～ときたら</span> supaya kamu bisa membedakan dua nuansa: \"mengeluh dengan sayang\" dan \"mengomel serius\".</div>","n1-45":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ときたら」itu seperti kita lagi curhat sambil mengeluh: <b>“Nah, soal si anu di rumah itu lho… duh, beneran deh”</b>. Kamu sebut dulu orang atau benda yang bikin kamu kesal, lalu lanjut mengomelinya. Inti kalimatnya adalah <b>rasa tidak puas, geleng-geleng kepala, dan pasrah karena tidak bisa berbuat apa-apa</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Nomina langsung ditambah ときたら. Di depannya biasanya orang atau benda.<br><span class='gd-pair'><span class='gd-jp'>うちの息子</span> → <span class='gd-jp'>うちの息子ときたら</span></span>（soal anak laki-lakiku）<br><span class='gd-pair'><span class='gd-jp'>このパソコン</span> → <span class='gd-jp'>このパソコンときたら</span></span>（soal laptop ini）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mengomeli orang di sekitarmu</span>Paling sering dipakai untuk keluarga, rekan kerja, atau atasan, yaitu orang-orang yang dekat denganmu dan bikin pusing.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの息子ときたら、ゲームばかりしている。</span>（Soal anak laki-lakiku, kerjanya main game melulu)</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの部長ときたら、会議のたびに話が長い。</span>（Soal kepala divisi kami, setiap rapat ngomongnya lama banget）</div><div class='gd-sec'><span class='gd-tag'>Mengeluh soal benda</span>Benda yang susah dipakai juga bisa.</div><div class='gd-ex-line'>・<span class='gd-jp'>このパソコンときたら、すぐ固まるんだから。</span>（Laptop ini nih, sedikit-sedikit hang）</div><div class='gd-sec'><span class='gd-tag'>Menyalahkan diri sendiri</span>Mengomeli diri sendiri juga sangat natural.</div><div class='gd-ex-line'>・<span class='gd-jp'>私ときたら、また傘を電車に忘れてきた。</span>（Aduh aku ini, payungnya ketinggalan di kereta lagi）</div><div class='gd-sec'><span class='gd-tag'>Kalimat tidak diselesaikan</span>Dalam percakapan, isi keluhannya sering dihilangkan. Cukup sampai ときたら, dan nada bicaramu yang menunjukkan kekesalan.</div><div class='gd-ex-line'>・<span class='gd-jp'>まったく、うちの主人ときたら……</span>（Ya ampun, suamiku itu lho……）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Pola ini dipakai untuk mengomeli seseorang atau sesuatu <b>kepada pihak ketiga</b>, jadi tidak bisa dipakai untuk menegur orangnya langsung. Berkata 「お母さんときたら！」 langsung ke ibumu itu salah.<br>・Bagian belakangnya berupa deskripsi dan keluhan, bukan permintaan atau keputusan seperti 「〜てください」 atau 「〜よう」. Kalimat seperti <span class='gd-jp'>うちの部長ときたら、早く帰ってください</span> yang diakhiri permintaan itu tidak tepat.<br>・Pada dasarnya nuansanya negatif, jangan dipakai untuk memuji. <span class='gd-jp'>うちの息子ときたら、頭がいい</span> terdengar aneh.<br>・Nuansanya lisan dan santai, jarang dipakai di tulisan formal atau laporan.<br>・Dalam percakapan kadang kamu akan dengar kalimat seperti <span class='gd-jp'>夏ときたら、やっぱりビールでしょ。</span>（Bicara soal musim panas, ya pasti bir dong）. Itu pola “kalau A, langsung teringat B”, bukan keluhan, jadi jangan sampai tertukar.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ったら</b>: Bisa dipakai untuk mengeluh juga, tapi nadanya lebih ringan dan sering terdengar akrab, seperti “duh, kamu ini ya”. Pola ini juga <b>boleh dipakai langsung ke orangnya</b>.<br><span class='gd-jp'>もう、お母さんったら！</span>（Duh, Ibu ini ya!）: Boleh, karena langsung ke ibumu<br><b>ときたら</b>: Kritiknya lebih tajam dan hanya dipakai saat membicarakan orang itu kepada orang lain.<br><span class='gd-jp'>うちの母ときたら、人の話を全然聞かない。</span>（Soal ibuku, dia sama sekali tidak mau dengar omongan orang）: Curhat ke teman</div><div class='gd-sec'><b>に至っては</b>: Kamu sebut dulu sekelompok orang atau banyak hal, lalu pilih <b>yang paling parah</b>.<br><span class='gd-jp'>みんな遅刻したが、田中さんに至っては来なかった。</span>（Semua terlambat, dan Tanaka lebih parah lagi, dia malah tidak datang）<br><b>ときたら</b> tidak perlu dibandingkan dengan yang lain, langsung menunjuk satu orang untuk diomeli.</div><div class='gd-warn'>Tips menentukan: kalau menegur langsung “kamu ini ya”, pakai ったら. Kalau mengomeli seseorang kepada orang lain, pakai ときたら. Kalau memilih yang paling parah dari sebuah kelompok, pakai に至っては.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Pola ini sering muncul bersama 「<span class='gd-jp'>まったく</span>」 dan 「<span class='gd-jp'>〜んだから</span>」 sehingga nada mengeluhnya makin kuat: <span class='gd-jp'>うちの夫ときたら、まったく何もしないんだから。</span>（Soal suamiku, dia benar-benar tidak mengerjakan apa-apa）</div>","n1-46":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜にあって」setara dengan bahasa tulis formal Indonesia <b>“berada di tengah ~”, “dalam situasi ~”, “sebagai ~”</b>. Di depannya ada zaman, situasi, atau status yang khusus, dan di belakangnya ada keadaan atau tindakan dalam lingkungan itu, atau apa yang seharusnya dilakukan. Sering muncul di berita, pidato, dan tulisan, tapi hampir tidak dipakai dalam obrolan sehari-hari.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Hanya menyambung ke nomina: Nomina＋にあって<br><span class='gd-pair'><span class='gd-jp'>非常時</span> → <span class='gd-jp'>非常時にあって</span></span>（di masa darurat seperti ini）<br><span class='gd-pair'><span class='gd-jp'>現代</span> → <span class='gd-jp'>現代にあって</span></span>（di zaman sekarang）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Zaman atau situasi khusus</span>Misalnya masa darurat, resesi, atau era ledakan informasi.</div><div class='gd-ex-line'>・<span class='gd-jp'>この非常時にあって、リーダーは冷静であるべきだ。</span>（Di masa darurat seperti ini, seorang pemimpin harus tetap tenang）</div><div class='gd-ex-line'>・<span class='gd-jp'>情報があふれる現代にあって、正しい情報を選ぶ力が必要だ。</span>（Di zaman sekarang yang banjir informasi, kita butuh kemampuan memilih informasi yang benar）</div><div class='gd-sec'><span class='gd-tag'>Status atau posisi</span>Sering ditulis dalam bentuk 「〜という立場にあって」.</div><div class='gd-ex-line'>・<span class='gd-jp'>社長という立場にあって、軽率な発言は許されない。</span>（Sebagai direktur utama, tidak boleh asal bicara）</div><div class='gd-sec'><span class='gd-tag'>Berada di suatu tempat</span>Biasanya tempat yang tidak lazim seperti 「異国」 atau 「戦場」, dengan nuansa sastrawi.</div><div class='gd-ex-line'>・<span class='gd-jp'>異国にあって、家族からの手紙が何よりの支えだった。</span>（Di negeri orang, surat dari keluarga adalah penopang terbesarku）</div><div class='gd-h'>Dua bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>にあっても</span>Dengan tambahan 「も」, artinya menjadi <b>“bahkan ketika berada di ~, tetap …”</b>. Bagian belakangnya biasanya “tetap tidak menyerah” atau “tetap tegar”.</div><div class='gd-ex-line'>・<span class='gd-jp'>どんな苦境にあっても、彼女は笑顔を忘れなかった。</span>（Sesulit apa pun keadaannya, dia tidak pernah lupa tersenyum）</div><div class='gd-sec'><span class='gd-tag'>にあっては</span>Dengan tambahan 「は」, menekankan <b>“dalam situasi seperti ini, mau tak mau …”</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>この不況下にあっては、どの会社も節約せざるを得ない。</span>（Dalam resesi seperti ini, perusahaan mana pun terpaksa berhemat）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Hanya menyambung ke nomina. Kalau mau pakai verba, ubah dulu jadi nomina, atau pakai bentuk 「〜という状況にあって」.<br>・Di depannya harus ada <b>lingkungan atau status khusus yang layak disebut</b>. Waktu biasa seperti 「月曜日にあって」 atau 「普通の日にあって」 terdengar janggal.<br>・Ini bahasa tulis yang sangat kaku. Kalau ngobrol dengan teman, cukup pakai 「忙しい中」 atau 「〜なのに」. Memakai にあって akan terdengar seperti membaca siaran pers.<br>・Jangan tertukar dengan sekadar “berada di mana”: <span class='gd-jp'>その店は駅前にあって便利だ。</span>（Toko itu ada di depan stasiun, jadi praktis）. あって di sini hanya berarti “terletak di”, bukan pola tata bahasa ini.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>にあたって</b> (beda satu huruf saja, paling sering salah baca) = <b>saat akan melakukan sesuatu, pada kesempatan itu</b>, dan bisa menyambung ke verba.<br><span class='gd-jp'>社長に就任するにあたって、一言ご挨拶申し上げます。</span>（Pada kesempatan pelantikan saya sebagai direktur utama, izinkan saya menyampaikan sepatah kata）<br><span class='gd-jp'>社長という立場にあって、軽率な発言は許されない。</span>（Sebagai direktur utama, tidak boleh asal bicara）<br>Kalimat pertama menekankan momen pelantikannya, kalimat kedua menekankan bahwa orangnya terus berada di posisi direktur utama.</div><div class='gd-sec'><b>とあって</b> = <b>karena ~, maka</b> (menyatakan sebab).<br><span class='gd-jp'>不況とあって、就職が厳しい。</span>（Karena sedang resesi, cari kerja jadi sulit）<br><span class='gd-jp'>不況にあって、この会社は売り上げを伸ばしている。</span>（Di tengah resesi, perusahaan ini justru terus menaikkan penjualan）<br>とあって itu “karena begini, jadinya begitu”, sedangkan にあって itu “berada dalam lingkungan ini, bagaimana sikapnya”.</div><div class='gd-warn'>Tips menentukan: “berada di ~ / sebagai ~” pakai にあって, “saat akan melakukan ~” pakai にあたって, “karena ~” pakai とあって.</div>","n1-48":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「～ともなれば」artinya kira-kira <b>\"kalau sudah sampai tahap ～, ya wajar kalau…\"</b>. Di depannya kamu taruh status, usia, atau masa yang <b>satu tingkat lebih tinggi dari biasanya</b>. Di belakangnya kamu bilang \"kalau sudah di level ini, otomatis jadi begini\". Nadanya mirip kalimat \"Dia kan sudah jadi direktur, wajar dong kalau waktu libur pun masih terima telepon kerja\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Naik status atau usia</span>Setelah menduduki suatu jabatan atau mencapai usia tertentu, tanggung jawab dan harapan orang lain ikut berubah.</div><div class='gd-ex-line'>・<span class='gd-jp'>プロともなれば、これくらいは当然できる。</span>（Kalau sudah profesional, segini sih pasti bisa)</div><div class='gd-ex-line'>・<span class='gd-jp'>社長ともなれば、休みの日も仕事の電話が来る。</span>（Kalau sudah jadi direktur, hari libur pun tetap ada telepon kerja)</div><div class='gd-sec'><span class='gd-tag'>Saat musimnya tiba</span>Begitu masuk musim atau hari yang istimewa, suasana di sekitar otomatis berbeda.</div><div class='gd-ex-line'>・<span class='gd-jp'>12月ともなれば、街はクリスマス一色になる。</span>（Begitu bulan 12 tiba, seluruh kota dipenuhi suasana Natal)</div><div class='gd-sec'><span class='gd-tag'>Kalau benar-benar mau melakukan hal besar</span>Kalau disambung dengan kata kerja, artinya \"kalau sampai benar-benar harus melakukan hal sebesar itu\". Nuansa \"seandainya\"-nya terasa lebih jelas.</div><div class='gd-ex-line'>・<span class='gd-jp'>海外に引っ越すともなれば、準備することが山ほどある。</span>（Kalau sampai pindah ke luar negeri, banyak sekali yang harus disiapkan)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋ともなれば：<span class='gd-pair'><span class='gd-jp'>大学生</span> → <span class='gd-jp'>大学生ともなれば</span></span><br>Kata kerja bentuk kamus＋ともなれば：<span class='gd-pair'><span class='gd-jp'>結婚する</span> → <span class='gd-jp'>結婚するともなれば</span></span><br>Di belakangnya sering muncul ungkapan \"sudah semestinya\" atau \"memang seharusnya\", seperti <span class='gd-jp'>当然</span>、<span class='gd-jp'>～なければならない</span>、<span class='gd-jp'>～ものだ</span>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Bagian depan harus terasa seperti <b>sudah naik ke tingkat yang berbeda</b>. <span class='gd-jp'>小学生ともなれば</span> bisa dipakai karena dibandingkan dengan anak TK, sudah naik satu tingkat. Kalau kamu taruh kata biasa saja, kalimatnya jadi aneh.<br>・Bagian belakang berisi hal yang \"otomatis terjadi\", jadi <b>jangan dipakai untuk kemauan atau permintaan sendiri</b>. Kalau mau bilang \"kalau sudah jadi direktur, aku mau lebih giat\", jangan bilang <span class='gd-jp'>社長ともなれば、もっと頑張りたい</span>, tapi <span class='gd-jp'>社長になったら、もっと頑張りたい。</span><br>・Nadanya cukup formal, jadi lebih sering muncul di berita, tulisan, dan pidato. Dalam obrolan sehari-hari orang biasanya bilang <span class='gd-jp'>～になると</span> atau <span class='gd-jp'>～となると</span>.<br>・Jangan tertukar dengan <span class='gd-jp'>となれば</span>. Tanpa <span class='gd-jp'>も</span>, artinya cuma \"kalau memang begitu\", tanpa penekanan \"sudah sampai level ini\". Contoh: <span class='gd-jp'>明日も雨となれば、試合は中止だ。</span>（Kalau besok juga hujan, pertandingan dibatalkan)</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>ともなると</b>: artinya hampir sama, dan di ujian biasanya keduanya bisa saling menggantikan.<br><span class='gd-jp'>12月ともなると、街はクリスマス一色になる。</span><br><span class='gd-jp'>12月ともなれば、街はクリスマス一色になる。</span><br>Dua-duanya benar. Kalau mau dibedakan, <span class='gd-jp'>ともなれば</span> punya <span class='gd-jp'>ば</span>, jadi nuansa \"seandainya benar-benar sampai tahap itu\" sedikit lebih terasa.</div><div class='gd-sec'><b>とあれば</b>: bentuknya mirip, tapi arahnya berlawanan. Artinya \"kalau memang demi ～ / kalau memang itu permintaan ～\", dan di belakangnya sering ada hal yang <b>rela kamu lakukan atau terpaksa kamu lakukan</b>.<br><span class='gd-jp'>社長の命令とあれば、従うしかない。</span>（Kalau memang perintah direktur, ya terpaksa menurut)<br><span class='gd-jp'>社長ともなれば、責任も重くなる。</span>（Kalau sudah jadi direktur, tanggung jawab otomatis ikut berat)</div><div class='gd-warn'>Trik cepat: kalau depannya \"naik satu tingkat\" dan belakangnya \"otomatis jadi begitu\", pakai ともなれば／ともなると. Kalau depannya \"alasan khusus\" dan belakangnya \"ya sudah, aku lakukan\", pakai とあれば.</div>","n1-49":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'><span class='gd-jp'>ともなく</span> punya dua cara pakai, dan inti keduanya sama: <b>\"tidak jelas\"</b>.<br>Yang pertama, <b>tindakan tanpa tujuan</b>, seperti \"nonton TV sambil lalu\". TV menyala dan matamu memang menatap layar, tapi sebenarnya tidak sedang melihat apa-apa.<br>Yang kedua, <b>tidak bisa menyebut asalnya</b>: \"entah dari mana\" atau \"entah siapa yang mulai duluan\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Melakukan sesuatu tanpa sengaja</span>Kamu tidak berniat melakukannya, tapi tahu-tahu sudah melakukannya. Ciri paling khasnya, <b>kata kerja yang sama dipakai di depan dan di belakang</b>, atau dua kata kerja yang maknanya dekat.</div><div class='gd-ex-line'>・<span class='gd-jp'>見るともなく窓の外を見ていた。</span>（Aku tidak sedang melihat apa-apa secara khusus, hanya menatap ke luar jendela)</div><div class='gd-ex-line'>・<span class='gd-jp'>聞くともなく隣の席の話を聞いていた。</span>（Aku tidak sengaja menguping, tapi obrolan meja sebelah tetap terdengar)</div><div class='gd-ex-line'>・<span class='gd-jp'>見るともなくテレビを眺めていたら、見覚えのある街が映った。</span>（Waktu aku menonton TV sambil lalu, tiba-tiba muncul pemandangan kota yang kukenal)</div><div class='gd-sec'><span class='gd-tag'>Tidak bisa menyebut siapa atau di mana</span>Di depannya ada kata tanya seperti 「どこ、誰、いつ」. Di belakangnya sering ada <span class='gd-jp'>から</span>、<span class='gd-jp'>へ</span>、<span class='gd-jp'>に</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>どこからともなく、いい匂いがしてきた。</span>（Entah dari mana, tercium aroma yang harum)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰からともなく拍手が起こった。</span>（Entah siapa yang mulai duluan, semua orang jadi bertepuk tangan)</div><div class='gd-ex-line'>・<span class='gd-jp'>男はどこへともなく歩いていった。</span>（Pria itu berjalan pergi entah ke mana)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰にともなく「ありがとう」とつぶやいた。</span>（Tanpa ditujukan ke siapa pun, ia bergumam pelan 「ありがとう」)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: pakai bentuk kamus (辞書形) lalu tambahkan <span class='gd-jp'>ともなく</span>, kemudian sambung dengan kata kerja yang sama.<br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るともなく見る</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くともなく聞く</span></span><br><b>Kata tanya</b>: 「どこ、誰、いつ」＋partikel, lalu tambahkan <span class='gd-jp'>ともなく</span>.<br><span class='gd-pair'><span class='gd-jp'>どこから</span> → <span class='gd-jp'>どこからともなく</span></span><span class='gd-pair'><span class='gd-jp'>誰から</span> → <span class='gd-jp'>誰からともなく</span></span></div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata kerjanya harus bentuk kamus: <span class='gd-jp'>見るともなく</span>. Jangan buang ます lalu jadi 「見ともなく」, dan jangan pakai bentuk lampau 「見たともなく」.<br>・Kata kerja yang bisa dipakai sangat terbatas, hampir semuanya <span class='gd-jp'>見る</span>、<span class='gd-jp'>聞く</span>、<span class='gd-jp'>言う</span>、<span class='gd-jp'>考える</span>、<span class='gd-jp'>待つ</span>, yaitu hal yang secara alami dilakukan mata, telinga, mulut, dan pikiran. Jangan asal dipasang ke kata kerja lain.<br>・<span class='gd-jp'>どこからともなく</span> dan <span class='gd-jp'>どことなく</span> mirip sekali, tapi artinya beda. <span class='gd-jp'>どことなく</span> artinya \"entah kenapa terasa agak ～\", jadi membicarakan kesan: <span class='gd-jp'>彼はどことなく父に似ている。</span>（Entah di bagian mana, dia agak mirip ayahku). Kalau mau bilang \"datang dari mana\", pakai <span class='gd-jp'>どこからともなく</span>.<br>・\"Tanpa sengaja\" bukan berarti \"tidak melakukan\". Pada <span class='gd-jp'>見るともなく見る</span>, kamu tetap melihat, hanya saja tanpa tujuan.<br>・Ini ungkapan yang cenderung tertulis, sering muncul di novel dan esai. Dalam obrolan sehari-hari orang biasanya bilang <span class='gd-jp'>なんとなく</span> atau <span class='gd-jp'>どこからか</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b><span class='gd-jp'>ともなると</span></b> yang selevel (artinya sama dengan <span class='gd-jp'>ともなれば</span>) hanya beda sedikit bentuknya, tapi artinya sama sekali lain. Artinya: begitu sampai tingkat atau posisi tertentu, <b>otomatis jadi ～</b>. Di depannya biasanya kata benda, tapi bisa juga kata kerja bentuk kamus.<br>Coba bandingkan dalam situasi \"tinggal sendiri\" yang sama:<br><b><span class='gd-jp'>ともなく</span></b> (tanpa sengaja): <span class='gd-jp'>一人の部屋で、見るともなくテレビを見ていた。</span>（Sendirian di kamar, aku menonton TV sambil lalu)<br><b><span class='gd-jp'>ともなく</span></b> (tidak bisa menyebut asalnya): <span class='gd-jp'>夜中、どこからともなく猫の鳴き声が聞こえてきた。</span>（Tengah malam, entah dari mana terdengar suara kucing mengeong)<br><b><span class='gd-jp'>ともなると</span></b> (kata benda): <span class='gd-jp'>夜中ともなると、この辺りはすっかり静かになる。</span>（Kalau sudah tengah malam, daerah sini jadi sangat sunyi)<br><b><span class='gd-jp'>ともなると</span></b> (kata kerja): <span class='gd-jp'>一人暮らしをするともなると、家事も全部自分でやらなければならない。</span>（Kalau sudah sampai tinggal sendiri, semua pekerjaan rumah harus dikerjakan sendiri)</div><div class='gd-warn'>Trik cepat:<br>・<span class='gd-jp'>ともなく</span> biasanya berbentuk \"kata kerja yang sama＋ともなく＋kata kerja yang sama\" atau \"どこから／誰から＋ともなく\", artinya tanpa sengaja, atau tidak bisa menyebut siapa atau di mana.<br>・Di belakang <span class='gd-jp'>ともなると</span> ada makna \"jadi ～, wajar kalau ～\", artinya begitu sampai tingkat atau posisi itu, otomatis muncul kondisi tertentu.<br>Jangan hanya melihat apakah depannya kata benda atau kata kerja. Lihat bentuk dan makna kalimat secara keseluruhan.</div>","n1-50":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「AともBともつかない」artinya <b>「dibilang A bukan, dibilang B pun bukan」</b>, seperti \"senyum bukan, tertawa pun bukan\" atau \"dibilang biru bukan, dibilang hijau pun bukan\". Hal yang ada di depan matamu terjebak di antara dua pilihan, dan kamu tidak bisa memastikan itu masuk ke sisi yang mana.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>A dan B diisi <b>kata benda</b> atau <b>bentuk biasa kata kerja</b> (bentuk kamus, bentuk ている, bentuk ない, yaitu bentuk tanpa ます). Setelah masing-masing, tambahkan 「とも」, lalu akhiri dengan 「つかない」.<br><span class='gd-pair'><span class='gd-jp'>本気</span>＋<span class='gd-jp'>冗談</span> → <span class='gd-jp'>本気とも冗談ともつかない</span></span><br><span class='gd-pair'><span class='gd-jp'>笑っている</span>＋<span class='gd-jp'>泣いている</span> → <span class='gd-jp'>笑っているとも泣いているともつかない</span></span><br>「つかない」di sini berarti \"tidak bisa menentukan, tidak bisa memutuskan\", dan biasanya ditulis dengan hiragana. Setelahnya paling sering langsung disambung kata benda, misalnya ekspresi, suara, nada bicara, jawaban, atau warna.</div><div class='gd-h'>Dua pola yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ともつかない</span>Hal itu sendiri memang ambigu, jadi sekalipun kamu melihat atau mendengarnya, kamu tetap tidak bisa membedakannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>本気とも冗談ともつかない言い方だった。</span>（Cara bicaranya bikin bingung, entah dia serius atau bercanda）</div><div class='gd-ex-line'>・<span class='gd-jp'>ため息ともあくびともつかない声が聞こえた。</span>（Terdengar suara yang tidak jelas apakah itu helaan napas atau menguap）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は笑っているとも泣いているともつかない顔をしていた。</span>（Wajahnya seperti tersenyum tapi juga seperti menangis, sulit ditebak）</div><div class='gd-sec'><span class='gd-tag'>とも言わない</span>A dan B biasanya berpasangan berlawanan (ya dan tidak). Artinya lawan bicara <b>tidak menunjukkan sikap</b>, tidak mengiyakan dan tidak menolak.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は行くとも行かないとも言わない。</span>（Dia tidak bilang akan pergi, dan tidak bilang tidak pergi juga）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長はいいとも悪いとも言わなかった。</span>（Kepala bagian tidak bilang bagus, dan tidak bilang jelek juga）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・「つかない」dipakai kalau <b>hal itu sendiri</b> tidak bisa dibedakan, untuk menggambarkan hal yang ada di depan mata seperti ekspresi, suara, atau jawaban. Jangan memakainya untuk sekadar \"aku tidak tahu jawabannya\". Kalau mau bilang \"aku tidak tahu dia akan datang atau tidak\", katakan <span class='gd-jp'>彼が来るか来ないか分からない</span>.<br>・Setelah A dan setelah B, <b>dua-duanya harus</b> diberi とも. Kalau hanya satu, atau ditulis seperti 「AかBともつかない」, itu salah.<br>・Kata kerja langsung disambung とも, tanpa tambahan 「の」. Cukup tulis <span class='gd-jp'>笑っているとも</span>, tidak perlu menjadi 笑っているのとも.<br>・Ini gaya bahasa tulis, khas novel. Dalam obrolan sehari-hari, cukup bilang <span class='gd-jp'>冗談か本気か分からない</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>AともBとも言わない</b>: dua-duanya <b>tidak dikatakan</b>, sikapnya tidak jelas.<br><span class='gd-jp'>彼は賛成とも反対とも言わなかった。</span>（Dia tidak bilang setuju, dan tidak bilang menolak juga）<br><b>Aと言わずBと言わず</b>: baik A maupun B, <b>semuanya</b> sama.<br><span class='gd-jp'>手と言わず足と言わず泥だらけになった。</span>（Tangan, kaki, pokoknya seluruh badan penuh lumpur）<br>Keduanya berbentuk \"A…B…\" ditambah 「言わ」, jadi kelihatan mirip, tapi artinya sangat berbeda. Yang satu berarti \"dua-duanya tidak disebut\", yang satu lagi \"di mana pun sama saja\".</div><div class='gd-sec'><b>〜ともなく</b> juga memakai 「とも」, tetapi hanya <b>satu kali</b>. Di depannya sering ada kata tanya, dan artinya \"tidak jelas dari mana atau siapa\".<br><span class='gd-jp'>どこからともなく音楽が聞こえてきた。</span>（Entah dari mana, terdengar musik）</div><div class='gd-warn'>Trik cepat menilai: kalau ada dua pilihan dan kamu tidak bisa memastikan mana yang benar, pakai ともつかない. Kalau kedua sisi sama-sama tidak diberi sikap, pakai とも言わない. Kalau keduanya tercakup dan semuanya begitu, pakai と言わず. Kalau hanya ada satu kata tanya, \"entah dari mana, entah siapa\", pakai ともなく.</div>","n1-51":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜てまで」artinya <b>「rela ～ demi …」「sampai ～ pun demi …」</b>. Demi mencapai suatu tujuan, seseorang bahkan melakukan hal yang biasanya tidak dilakukan dan berharga mahal. Orang Jepang yang mengucapkan kalimat ini sering membawa nada \"perlu sampai segitunya, ya?\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk て, tambahkan 「まで」, lalu sambung dengan tujuan yang benar-benar ingin kamu capai.<br><span class='gd-pair'><span class='gd-jp'>借金する</span> → <span class='gd-jp'>借金して</span> → <span class='gd-jp'>借金してまで</span></span><br><span class='gd-pair'><span class='gd-jp'>無理をする</span> → <span class='gd-jp'>無理をしてまで</span></span><br><span class='gd-pair'><span class='gd-jp'>嘘をつく</span> → <span class='gd-jp'>嘘をついてまで</span></span><br>Kerangka kalimatnya adalah <b>「Aてまで、B」＝ demi B, rela melakukan A</b>. A adalah harga yang kamu bayar, B adalah hal yang kamu inginkan.</div><div class='gd-h'>Pola yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Tidak sepadan</span>Diikuti 「〜必要はない」atau 「〜たくない」, artinya \"sampai segitunya demi hal ini tidak sepadan\". Ini penggunaan yang paling umum.</div><div class='gd-ex-line'>・<span class='gd-jp'>借金してまで、ブランド品を買う必要はない。</span>（Tidak perlu sampai berutang demi membeli barang bermerek）</div><div class='gd-ex-line'>・<span class='gd-jp'>体を壊してまで働きたくない。</span>（Aku tidak mau bekerja sampai merusak kesehatan）</div><div class='gd-sec'><span class='gd-tag'>Tak habis pikir, mempertanyakan</span>Dipakai dalam bentuk pertanyaan saat kamu merasa pengorbanan orang lain berlebihan.</div><div class='gd-ex-line'>・<span class='gd-jp'>そこまでして行きたいの？</span>（Sampai segitunya kamu masih mau pergi?）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達を裏切ってまで、出世したかったのか。</span>（Segitu ingin naik jabatan sampai tega mengkhianati temanmu?）</div><div class='gd-sec'><span class='gd-tag'>Sekadar menggambarkan usaha</span>Tidak selalu bernada kritik. Pola ini juga bisa sekadar menggambarkan seseorang yang berkorban banyak, kadang disertai rasa kagum.</div><div class='gd-ex-line'>・<span class='gd-jp'>徹夜してまで並んで、限定スイーツを手に入れた。</span>（Rela begadang mengantre, akhirnya dapat juga makanan manis edisi terbatas itu）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長は自分の給料を減らしてまで、社員を守った。</span>（Direktur rela memotong gajinya sendiri demi melindungi karyawan）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Jangan terbalik urutannya</b>: sebelum てまで adalah \"pengorbanan\", baru setelahnya \"tujuan\". <span class='gd-jp'>借金してまで買う</span> artinya \"berutang demi membeli\". Kalau ditulis 「買ってまで借金する」, artinya jadi \"membeli demi berutang\", yang maknanya tidak masuk akal.<br>・Di bagian depan harus ada hal yang <b>tidak biasa dan butuh pengorbanan besar</b>. Kalau kamu memasukkan hal ringan yang memang biasa dilakukan, kalimatnya tidak punya rasa \"rela sampai segitunya\" dan terdengar aneh.<br>・<span class='gd-jp'>そこまでして</span> adalah ungkapan tetap yang sering dipakai dalam percakapan, artinya \"sampai melakukan hal sejauh itu\", dengan nuansa yang sama seperti てまで. Perhatikan bahwa ungkapan ini menyatakan <b>pengorbanannya terlalu besar</b>, bukan \"padahal situasinya sudah begini\".<br>・Kata benda harus diubah dulu menjadi kata kerja dengan 「する」atau 「をする」sebelum bisa disambung てまで: <span class='gd-jp'>借金してまで</span>、<span class='gd-jp'>無理をしてまで</span>、<span class='gd-jp'>家族を犠牲にしてまで</span>. Kamu tidak bisa langsung menulis 「借金まで」, karena artinya jadi \"bahkan sampai berutang pun…\", yang maknanya lain.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Semuanya kata kerja + 「まで」. Hanya bentuk kata kerjanya yang berbeda, tetapi artinya sama sekali lain:<br><b>Bentuk kamus＋まで</b>＝sampai ～<br>・<span class='gd-jp'>彼が来るまで待った。</span>（Aku menunggu sampai dia datang）<br><b>Bentuk て＋まで</b>＝rela ～ demi<br>・<span class='gd-jp'>3時間も待ってまで、彼に会いたかった。</span>（Aku rela menunggu tiga jam karena ingin bertemu dengannya）<br><b>Bentuk kamus＋までだ（di akhir kalimat）</b>＝paling-paling ～ saja<br>・<span class='gd-jp'>彼が来ないなら、一人で行くまでだ。</span>（Kalau dia tidak datang, ya sudah, aku pergi sendiri saja）</div><div class='gd-warn'>Trik cepat menilai: kalau sebelum まで ada <b>bentuk て</b>, artinya \"rela sampai\". Kalau <b>bentuk kamus</b> dan kalimatnya belum selesai, artinya \"sampai\". Kalau <b>までだ</b> ada di akhir kalimat, artinya \"paling-paling／ya sudah saja\".</div>","n1-60":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「Aかたがた」kurang lebih berarti <b>「sekalian menyampaikan terima kasih」「sekalian menyapa」</b>. Saat kamu mengunjungi atau menulis surat kepada seseorang, kamu sekalian membawa satu tujuan lain, misalnya berterima kasih, melaporkan kabar terbaru, atau menyapa. Ini ungkapan yang sangat formal, sering muncul saat mengunjungi orang yang lebih tua, klien, atau dalam surat bisnis.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya taruh <b>kata benda</b>, dan biasanya kata benda yang bermakna \"tindakan\", seperti <span class='gd-jp'>お礼</span> (ucapan terima kasih), <span class='gd-jp'>ご挨拶</span> (salam/sapaan), <span class='gd-jp'>ご報告</span> (laporan), <span class='gd-jp'>お見舞い</span> (menjenguk orang sakit), <span class='gd-jp'>散歩</span> (jalan-jalan santai).<br><span class='gd-pair'><span class='gd-jp'>お礼</span> → <span class='gd-jp'>お礼かたがた</span></span><span class='gd-pair'><span class='gd-jp'>ご報告</span> → <span class='gd-jp'>ご報告かたがた</span></span><br>Di belakangnya biasanya ada tindakan seperti \"berkunjung\" atau \"menulis surat, menyampaikan sambutan\". Yang paling sering muncul: <span class='gd-jp'>伺う</span>, <span class='gd-jp'>お邪魔する</span>, <span class='gd-jp'>申し上げる</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Berkunjung ke rumah</span>Menjelaskan tujuan kedatanganmu hari ini.</div><div class='gd-ex-line'>・<span class='gd-jp'>先日のお礼かたがた、ご挨拶に伺いました。</span>(Saya datang hari ini untuk menyapa Anda, sekaligus berterima kasih atas kejadian beberapa hari lalu.)</div><div class='gd-ex-line'>・<span class='gd-jp'>近くまで来ましたので、ご挨拶かたがたお邪魔しました。</span>(Kebetulan saya sedang di sekitar sini, jadi sekalian mampir untuk menyapa Anda.)</div><div class='gd-sec'><span class='gd-tag'>Surat</span>Sangat sering dipakai di penutup surat bisnis atau surat salam, hampir seperti kalimat baku.</div><div class='gd-ex-line'>・<span class='gd-jp'>略儀ながら書中をもちまして、お礼かたがたご挨拶申し上げます。</span>(Mohon maaf kami hanya bisa menyampaikannya lewat surat ini, sebagai ucapan terima kasih sekaligus salam.)</div><div class='gd-ex-line'>・<span class='gd-jp'>転勤のご報告かたがた、お手紙を差し上げます。</span>(Saya menulis surat ini juga untuk mengabarkan bahwa saya dipindahtugaskan.)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Di depannya kata benda, bukan bentuk kamus kata kerja: katakan <span class='gd-jp'>お礼かたがた</span>, bukan <span class='gd-jp'>お礼を言うかたがた</span>.<br>・\"Sekalian\" dalam bahasa Indonesia kadang terdengar seolah hal itu tidak penting, tetapi かたがた tidak punya nuansa itu. Terima kasih dan salamnya sama-sama tujuan yang tulus. Memakai <span class='gd-jp'>お礼かたがた</span> tidak akan dianggap tidak sopan, malah terasa pantas.<br>・Ungkapan ini sangat formal, dan di belakangnya sering muncul bentuk merendah seperti <span class='gd-jp'>伺う</span> atau <span class='gd-jp'>申し上げる</span>. Kalau kamu bilang ke teman \"aku sekalian mampir ke minimarket\", jangan pakai ini.<br>・<span class='gd-jp'>方々</span> (かたがた) dalam <span class='gd-jp'>ご来場の方々</span> dan <span class='gd-jp'>関係者の方々</span> berarti \"hadirin sekalian\". Bunyinya sama, tapi tidak ada hubungannya dengan tata bahasa ini.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>かたがた</b> = situasi formal, saat berkunjung atau menulis surat, <b>sekalian membawa tujuan lain</b>:<br><span class='gd-jp'>お礼かたがた、先生のお宅に伺いました。</span> (Saya berkunjung ke rumah guru, sekaligus berterima kasih.)<br><b>がてら</b> = percakapan sehari-hari, <b>pergi untuk A, sambil lewat melakukan B</b>:<br><span class='gd-jp'>散歩がてら、パンを買ってきた。</span> (Aku jalan-jalan, sekalian beli roti.)<br><b>かたわら</b> = dalam waktu lama, <b>sambil menjalani pekerjaan utama, juga mengerjakan hal lain</b>. Tidak ada hubungannya dengan \"sekalian\":<br><span class='gd-jp'>会社に勤めるかたわら、小説を書いている。</span> (Dia bekerja di kantor, sambil menulis novel.)</div><div class='gd-warn'>Trik membedakan: pada kunjungan atau surat formal, untuk \"sekalian berterima kasih dan menyapa\" pakai かたがた; untuk melakukan sesuatu sambil lewat saat keluar rumah sehari-hari pakai がてら; untuk menjalani dua hal sekaligus dalam jangka panjang pakai かたわら.</div>","n1-61":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「AかたわらB」berarti <b>「di sela-sela mengerjakan A (pekerjaan utama), kamu juga mengerjakan B」</b>, mirip dengan istilah \"kerja sampingan\" atau \"side hustle\" zaman sekarang. Arti asli <span class='gd-jp'>かたわら</span> adalah \"samping\": hal utama ada di tengah, dan di sampingnya ada hal lain yang dikerjakan juga.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Dikerjakan bersamaan dalam jangka panjang</span>Dipakai untuk menggambarkan kehidupan atau kondisi kerja seseorang: pekerjaan utamanya apa, dan apa lagi yang ia kerjakan dalam jangka panjang. Sering muncul di profil tokoh, artikel berita, dan tulisan perkenalan diri.</div><div class='gd-ex-line'>・<span class='gd-jp'>会社に勤めるかたわら、週末は小説を書いている。</span>(Di sela-sela bekerja di kantor, dia menulis novel di akhir pekan.)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は大学で教えるかたわら、翻訳の仕事もしている。</span>(Selain mengajar di universitas, dia juga bekerja sebagai penerjemah.)</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事のかたわら、日本語の勉強を続けている。</span>(Di sela-sela pekerjaan, aku terus belajar bahasa Jepang.)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja: bentuk kamus (bentuk dasar di kamus) + かたわら<br><span class='gd-pair'><span class='gd-jp'>働く</span> → <span class='gd-jp'>働くかたわら</span></span><span class='gd-pair'><span class='gd-jp'>店を経営する</span> → <span class='gd-jp'>店を経営するかたわら</span></span><br>Kata benda: kata benda + の + かたわら<br><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事のかたわら</span></span><span class='gd-pair'><span class='gd-jp'>育児</span> → <span class='gd-jp'>育児のかたわら</span></span><br>Kata bendanya biasanya kata seperti \"pekerjaan, penelitian, mengasuh anak\", yang memang mewakili satu kegiatan tersendiri.</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Ini <b>bukan</b> berarti \"mengerjakan ini dan itu pada saat yang sama\". <span class='gd-jp'>音楽を聞くかたわら勉強する</span> itu salah; untuk kasus seperti ini pakai <span class='gd-jp'>聞きながら</span>.<br>・Kedua kegiatan itu <b>berlangsung dalam jangka waktu tertentu</b>, jadi di belakangnya sering dipasangkan dengan 「〜ている」. Hal yang hanya terjadi sekali tidak cocok.<br>・Taruh hal yang <b>utama</b> di depan dan hal sampingan di belakang. Jangan terbalik.<br>・Di depannya tidak boleh bentuk た: <span class='gd-jp'>勤めたかたわら</span> itu salah, selalu pakai bentuk kamus.<br>・Ini bahasa tulis, jarang dipakai saat ngobrol dengan teman. Dalam percakapan biasanya orang bilang <span class='gd-jp'>仕事しながら</span> atau <span class='gd-jp'>本業のほかに</span>.<br>・Kalau kamu menemukan pola 「kata benda のかたわらで」 seperti <span class='gd-jp'>母のかたわらで</span>, biasanya itu arti harfiahnya \"di samping ～\", bukan tata bahasa ini.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ながら</b> = melakukan dua hal sekaligus pada saat yang sama:<br><span class='gd-jp'>音楽を聞きながら勉強する。</span> (Belajar sambil mendengarkan musik.)<br><b>かたわら</b> = dua peran atau dua pekerjaan dalam jangka panjang:<br><span class='gd-jp'>会社で働くかたわら、夜間の大学に通っている。</span> (Selain bekerja di siang hari, dia juga kuliah malam.)<br><b>がてら</b> = dalam satu kali keluar, sekalian mengurus hal lain, bersifat singkat dan sekali jalan:<br><span class='gd-jp'>散歩がてら、パンを買ってきた。</span> (Aku keluar jalan-jalan, sekalian beli roti.)<br><b>かたがた</b> = maknanya dekat dengan がてら, tetapi lebih formal, banyak dipakai untuk berkunjung, berterima kasih, dan menyapa. Di belakangnya ada tindakan nyata, di depannya tujuan yang dibawa sekalian:<br><span class='gd-jp'>先日のお礼かたがた、ご挨拶に伺いました。</span> (Saya datang menyapa Anda, sekaligus menyampaikan terima kasih atas kejadian beberapa hari lalu.)</div><div class='gd-warn'>Trik membedakan: untuk seseorang yang menjalani dua hal dalam jangka panjang, pakai かたわら; untuk mengurus dua hal dalam satu kali keluar, pakai がてら (dalam situasi formal pakai かたがた); untuk melakukan dua hal pada saat yang sama, pakai ながら.</div>","n1-54":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜かろう」adalah <b>versi tulisan gaya lama</b> dari 「〜いだろう」, artinya \"mungkin ~\" atau \"pasti ~\". <span class='gd-jp'>難しいだろう</span> ditulis jadi <span class='gd-jp'>難しかろう</span> artinya tetap sama, hanya saja terdengar seperti editorial, novel, atau kakek di drama kolosal zaman dulu yang sedang bicara.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Hanya bisa dipakai dengan kata sifat-い</b>: buang 「い」 di akhir, lalu tambahkan 「かろう」.<br><span class='gd-pair'><span class='gd-jp'>難しい</span> → buang い → <span class='gd-jp'>難しかろう</span></span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒かろう</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かろう</span></span><br><b>Dua ini harus diingat khusus</b>:<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかろう</span></span> (berasal dari <span class='gd-jp'>よい</span>)<br><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なかろう</span></span><br>Perubahan 「〜たい」 sama seperti kata sifat-い, jadi bisa juga disambung: <span class='gd-pair'><span class='gd-jp'>帰りたい</span> → <span class='gd-jp'>帰りたかろう</span></span> (mungkin ingin sekali pulang)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Dugaan dalam tulisan</span>Dipakai untuk menduga keadaan dalam artikel atau ulasan, sering muncul bersama <span class='gd-jp'>さぞ</span> (pasti).</div><div class='gd-ex-line'>・<span class='gd-jp'>山の上はさぞ寒かろう。</span> (Di atas gunung pasti dingin sekali.)</div><div class='gd-ex-line'>・<span class='gd-jp'>最初は苦しかろうが、すぐに慣れる。</span> (Awalnya mungkin berat, tapi kamu akan segera terbiasa.)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ではなかろうか</span>= \"bukankah ~?\" Sangat sering muncul di makalah dan editorial, sebagai cara yang lebih halus untuk menyampaikan pendapat.</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画には無理があるのではなかろうか。</span> (Bukankah rencana ini agak dipaksakan?)</div><div class='gd-sec'><span class='gd-tag'>よかろう</span>Orang yang lebih tua atau atasan berkata \"baiklah, boleh\", dengan nuansa dari atas ke bawah dan menyetujui dengan agak terpaksa.</div><div class='gd-ex-line'>・<span class='gd-jp'>まあ、よかろう。今回だけは許してやる。</span> (Hmm, baiklah. Kali ini saja kumaafkan.)</div><div class='gd-sec'><span class='gd-tag'>Ungkapan tetap</span><span class='gd-jp'>安かろう悪かろう</span> = murah ya murahan (ada harga, ada kualitas).</div><div class='gd-ex-line'>・<span class='gd-jp'>安かろう悪かろうの時代は終わった。</span> (Zaman \"murah berarti murahan\" sudah berlalu.)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata sifat-な dan kata benda <b>tidak bisa</b> disambung dengan かろう: <span class='gd-jp'>静かかろう</span> itu salah, yang benar <span class='gd-jp'>静かだろう</span> atau <span class='gd-jp'>静かであろう</span>. Kata benda juga sama, pakai <span class='gd-jp'>学生だろう</span> atau <span class='gd-jp'>学生であろう</span>.<br>・Kata kerja juga tidak bisa: katakan <span class='gd-jp'>行くだろう</span> atau <span class='gd-jp'>行くであろう</span>.<br>・<span class='gd-jp'>いい</span> harus berubah jadi <span class='gd-jp'>よかろう</span>, tidak ada bentuk 「いかろう」.<br>・「ろう」 dibaca panjang, jadi ろー.<br>・Kalau ngobrol dengan teman lalu bilang <span class='gd-jp'>暑かろう</span>, kamu akan terdengar seperti sedang main drama kolosal. Sehari-hari cukup pakai <span class='gd-jp'>暑いだろう</span>.<br>・<span class='gd-jp'>よかろう</span> bernada dari atas ke bawah, jadi tidak sopan kalau diucapkan kepada atasan atau guru.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>「〜かろうが／〜かろうと」 punya dua arti, tergantung susunan kalimatnya:<br><b>Mungkin ~, tetapi …</b> (dugaan lalu kontras): <span class='gd-jp'>その試験は難しかろうが、準備すれば突破できる。</span> (Ujian itu mungkin sulit, tapi kalau kamu mempersiapkan diri, pasti bisa lulus.)<br><b>Entah ~ atau tidak, tetap …</b> (versi kata sifat-い dari <span class='gd-jp'>〜ようが／〜ようと</span>): <span class='gd-jp'>高かろうが安かろうが、必要なものは買う。</span> (Mau mahal atau murah, barang yang diperlukan tetap dibeli.)<br><span class='gd-jp'>どんなに辛かろうと、最後までやり抜く。</span> (Seberat apa pun, aku akan bertahan sampai akhir.)</div><div class='gd-warn'>Trik membedakan: kalau di depannya ada 「どんなに」 atau 「いくら」, atau ada dua bentuk berpasangan (高かろうが安かろうが) → artinya \"entah ~, tetap …\". Kalau hanya satu dan di belakangnya ada \"tetapi …\" → artinya \"mungkin ~, tetapi\".</div><div class='gd-h'>Yang bisa dipelajari berikutnya</div><div class='gd-sec'>Versi \"entah ~\" untuk kata kerja dan kata benda adalah <span class='gd-jp'>〜ようが／〜ようと</span>: <span class='gd-jp'>雨が降ろうが、試合は行われる。</span> (Biarpun hujan, pertandingan tetap dilaksanakan.)</div>","n1-58":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜とばかりに」 artinya <b>\"seolah-olah berkata '~'\"</b>. Orangnya tidak mengucapkannya, tetapi gerak-gerik dan ekspresinya jelas sedang mengatakan sesuatu. Taruh <b>kata-kata dalam hatinya</b> di depan, lalu sambung dengan tindakan yang ia lakukan.<br>Misalnya kepala bagian terus melirik jam tangan. Ia tidak bicara, tapi semua orang tahu ia sedang bilang \"ayo pulang\". Nah, di situasi seperti itu kamu pakai pola ini.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menggambarkan sikap orang lain</span>Kamu menuliskan \"kata-kata\" di balik tindakan orang itu. Paling sering muncul di novel, berita, dan deskripsi suasana.</div><div class='gd-ex-line'>・<span class='gd-jp'>「早く帰れ」とばかりに、課長は時計をちらちら見た。</span> (Kepala bagian terus melirik jam, seolah berkata \"cepat pulang sana\".)</div><div class='gd-ex-line'>・<span class='gd-jp'>「遊ぼう」とばかりに、犬がボールをくわえて走ってきた。</span> (Anjing itu berlari datang sambil menggigit bola, seolah berkata \"ayo main\".)</div><div class='gd-ex-line'>・<span class='gd-jp'>「待ってました」とばかりに、彼は勢いよく手を挙げた。</span> (Seolah berkata \"ini yang kutunggu-tunggu\", ia mengangkat tangan dengan semangat.)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Yang diletakkan di depan adalah <b>satu kalimat ucapan</b>, jadi bentuknya bebas: nada perintah (<span class='gd-jp'>帰れ</span>), nada mengajak (<span class='gd-jp'>遊ぼう</span>), bentuk ます (<span class='gd-jp'>待ってました</span>), atau satu kata dan seruan pun boleh. Biasanya diberi 「」 supaya langsung kelihatan bahwa itu ucapan.<br>Kalau di belakangnya ada kata benda, berubah jadi <b>とばかりの</b>:<br>・<span class='gd-jp'>「もう帰れ」とばかりの冷たい態度だった。</span> (Sikapnya dingin, seolah berkata \"pergi sana\".)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ここぞとばかりに</span><span class='gd-jp'>ここぞ</span> = \"inilah saatnya\". Seluruh kalimat jadi \"seolah mendapat kesempatan, langsung ~ habis-habisan\". Sangat sering dipakai.</div><div class='gd-ex-line'>・<span class='gd-jp'>会議で、彼はここぞとばかりに不満を言い始めた。</span> (Di rapat, ia memanfaatkan kesempatan itu dan mulai mengeluarkan semua keluhannya.)</div><div class='gd-sec'><span class='gd-tag'>今だとばかりに</span>\"Sekarang saatnya!\" Melihat momen yang pas lalu langsung bertindak.</div><div class='gd-ex-line'>・<span class='gd-jp'>相手が転んだ瞬間、今だとばかりに走り出した。</span> (Begitu lawannya jatuh, ia langsung berlari seolah berkata \"sekarang saatnya\".)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Ini cara bicara saat <b>melihat orang lain dari samping</b>, jadi biasanya tidak dipakai untuk diri sendiri. Apa yang ada di pikiranmu sendiri kamu tahu persis, jadi tidak perlu \"kelihatannya seperti berkata\".<br>・Kalimat di depannya <b>sebenarnya tidak diucapkan</b>. Kalau orangnya benar-benar mengatakannya, pakai saja 「〜と言って」.<br>・ばかり di sini bukan berarti \"hanya\", jadi jangan diartikan \"cuma ~\".<br>・Pola ini tidak terbatas pada bentuk biasa. Di depannya boleh bentuk perintah, bentuk ます, atau satu kata, karena memang mengutip sebuah ucapan.<br>・Kebanyakan dipakai dalam tulisan dan penggambaran suasana, jarang dipakai dalam obrolan sehari-hari.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>とばかりに</b> = di depannya ada <b>ucapan</b>: \"seolah berkata '~'\"<br><b>んばかりに</b> = di depannya ada <b>tindakan yang hampir terjadi</b>: \"nyaris saja ~\"<br>Situasi yang sama: seorang anak senang sekali mendapat hadiah.</div><div class='gd-ex-line'>・<span class='gd-jp'>「やった」とばかりに、子どもは両手を上げた。</span> (Anak itu mengangkat kedua tangannya, seolah berkata \"yeay\".)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもは飛び上がらんばかりに喜んだ。</span> (Anak itu senang sampai nyaris melompat.)</div><div class='gd-sec'>Cara menyambung んばかりに: ubah dulu ke bentuk ない, buang 「ない」, lalu tambahkan 「ん」.<br><span class='gd-pair'><span class='gd-jp'>飛び上がる</span> → <span class='gd-jp'>飛び上がらない</span> → <span class='gd-jp'>飛び上がらんばかりに</span></span><br><span class='gd-pair'><span class='gd-jp'>泣き出す</span> → <span class='gd-jp'>泣き出さない</span> → <span class='gd-jp'>泣き出さんばかりに</span></span><br>※<b>する berubah jadi 「せん」</b>, bukan 「しん」: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんばかりに</span></span> (contoh: <span class='gd-jp'>今にも爆発せんばかりに</span>)<br>Oh ya, <span class='gd-jp'>「帰れ」と言わんばかりに</span> (nyaris mengucapkan \"pulang sana\") artinya hampir sama dengan <span class='gd-jp'>「帰れ」とばかりに</span>, jadi bisa saling menggantikan.</div><div class='gd-warn'>Trik membedakan: kalau di depannya ada sebuah \"ucapan\", pakai とばかりに. Kalau di depannya ada \"tindakan yang nyaris dilakukan\", pakai んばかりに.</div><div class='gd-h'>Yang bisa dipelajari berikutnya</div><div class='gd-sec'>Sama-sama menggambarkan \"keadaan\", jadi lanjutkan dengan <span class='gd-jp'>〜んばかりに</span> (nyaris ~). Kalau dua-duanya dihafal bersamaan, kamu paling kecil kemungkinan tertukar.</div>","n1-65":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜いかん」setara dengan <b>「tergantung ～」「bergantung pada ～」</b> dalam bahasa Indonesia yang formal. Kanjinya ditulis 如何 (artinya \"bagaimana\"), tapi sekarang kebanyakan langsung ditulis dengan hiragana <span class='gd-jp'>いかん</span>. Artinya: hasilnya seperti apa, itu tergantung kondisi hal yang disebut di depannya. Pola ini kaku dan sangat resmi, jadi biasanya hanya muncul di berita, pengumuman, kontrak, atau pidato atasan.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Hanya disambung dengan <b>kata benda</b>. 「の」di tengah boleh dipakai atau tidak, dan yang lebih umum adalah tanpa 「の」.<br><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力いかん</span></span> (tergantung seberapa besar usahanya)<br><span class='gd-pair'><span class='gd-jp'>試験の結果</span> → <span class='gd-jp'>試験の結果いかん</span></span> (tergantung hasil ujian)<br>Kata benda di depannya harus berupa sesuatu yang <b>bisa baik atau buruk, tinggi atau rendah</b>, misalnya: <span class='gd-jp'>結果</span>、<span class='gd-jp'>努力</span>、<span class='gd-jp'>態度</span>、<span class='gd-jp'>対応</span>、<span class='gd-jp'>天候</span>、<span class='gd-jp'>返答</span>、<span class='gd-jp'>内容</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>いかんだ／いかんにかかっている</span>Ditaruh di akhir kalimat, artinya \"semuanya tergantung pada ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できるかどうかは、本人の努力いかんだ。</span>(Lulus atau tidak, tergantung usaha orangnya sendiri)</div><div class='gd-ex-line'>・<span class='gd-jp'>今期の業績は、チームの努力いかんにかかっている。</span>(Kinerja periode ini bergantung pada usaha tim)</div><div class='gd-sec'><span class='gd-tag'>いかんで／いかんによって</span>Ditaruh di tengah kalimat, artinya \"ditentukan atau berubah menurut ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>参加費は人数いかんで変わります。</span>(Biaya partisipasi berubah tergantung jumlah orang)</div><div class='gd-sec'><span class='gd-tag'>いかんでは／いかんによっては</span>Dengan tambahan 「は」, artinya menjadi \"tergantung situasinya, <b>bahkan mungkin</b> ～\". Di belakangnya biasanya ada hasil yang khusus, dan sering kali kurang menyenangkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>天候いかんでは、試合が中止になることもあります。</span>(Tergantung cuacanya, pertandingan bisa saja dibatalkan)</div><div class='gd-ex-line'>・<span class='gd-jp'>会社の対応いかんでは、訴訟も考えています。</span>(Tergantung bagaimana perusahaan menanganinya, kami juga mempertimbangkan untuk menggugat)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Bacanya <b>いかん</b>. Kanji 如何 yang sama dibaca いかが di <span class='gd-jp'>如何ですか</span>, jadi jangan tertukar.<br>・Tidak bisa langsung disambung dengan kata kerja atau kata sifat. Untuk bilang \"tergantung kamu mau berusaha atau tidak\", tulis <span class='gd-jp'>努力いかんで</span>, bukan 「頑張るいかんで」.<br>・Kata benda di depannya harus yang bisa berubah-ubah. Kata seperti 「明日」, yang tidak punya sisi baik-buruk atau tinggi-rendah, tidak bisa dipakai.<br>・Pola ini terlalu formal. Kalau ngobrol dengan teman, 「天気いかんで決めよう」terdengar aneh. Untuk percakapan pakai <span class='gd-jp'>天気次第で決めよう</span> atau <span class='gd-jp'>天気によって決めよう</span>.<br>・Dalam percakapan, <span class='gd-jp'>それはいかん</span> yang berdiri sendiri artinya \"itu tidak boleh\". Itu kata lain dan tidak ada hubungannya dengan pola ini.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>次第</b> (N2) ＝ artinya hampir sama, tapi bisa dipakai di lisan maupun tulisan dan terasa lebih santai:<br><span class='gd-jp'>結果次第で、計画を変えるかもしれない。</span>(Tergantung hasilnya, rencana mungkin berubah)<br><b>いかん</b> ＝ artinya sama, tapi dengan nada dokumen resmi atau laporan:<br><span class='gd-jp'>結果いかんでは、計画を変更することもあり得る。</span>(Tergantung hasilnya, rencana juga dapat diubah)<br><b>いかんによらず／いかんにかかわらず</b> (n1-66) ＝ artinya berlawanan, yaitu \"<b>apa pun</b> ～nya, hasilnya sama\":<br><span class='gd-jp'>理由のいかんにかかわらず、返金はいたしません。</span>(Apa pun alasannya, kami tidak melayani pengembalian dana)</div><div class='gd-warn'>Trik cepat membedakan: kalau setelah いかん ada 「で・によって・だ・にかかっている」, artinya \"<b>tergantung itu</b>\". Kalau diikuti 「によらず・にかかわらず・を問わず」, artinya \"<b>tidak peduli itu</b>\". Kalau mau terdengar lebih santai, ganti いかん dengan 次第.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Lanjutkan ke <span class='gd-jp'>いかんによらず</span> dan <span class='gd-jp'>いかんにかかわらず</span> di n1-66, serta <span class='gd-jp'>理由のいかんを問わず</span> (tanpa memandang alasan) yang sering terlihat di pengumuman.</div>","n1-66":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜いかんによらず／いかんにかかわらず」setara dengan <b>「apa pun ～nya, tetap saja ……」「tanpa memandang ～」</b> dalam bahasa Indonesia yang formal. Di depannya ada sesuatu yang bisa punya berbagai kondisi (alasan, hasil, cuaca), dan kesimpulan di belakangnya <b>tidak berubah karena itu</b>. Pola ini paling sering kamu temui di pengumuman, kontrak, dan aturan pembatalan tiket. Dalam obrolan sehari-hari hampir tidak dipakai.</div><div class='gd-h'>Kita bedah dulu</div><div class='gd-sec'><span class='gd-jp'>いかん</span> kalau ditulis dengan kanji menjadi <span class='gd-jp'>如何</span>, artinya \"isi atau kondisinya seperti apa\".<br><span class='gd-jp'>によらず</span> ＝ tidak mengikuti, tidak bergantung pada; <span class='gd-jp'>にかかわらず</span> ＝ tidak ada kaitannya dengan ～.<br>Keduanya berarti sama: \"apa pun ～nya\". Ada juga satu ungkapan lain yang sering muncul: <span class='gd-jp'>いかんを問わず</span> (tanpa menanyakan bagaimana ～).</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda ＋ の ＋ いかんによらず／いかんにかかわらず<br><span class='gd-pair'><span class='gd-jp'>理由</span> → <span class='gd-jp'>理由のいかんによらず</span></span><span class='gd-pair'><span class='gd-jp'>天候</span> → <span class='gd-jp'>天候のいかんにかかわらず</span></span><br>Kata benda di depannya harus berupa sesuatu yang <b>punya beberapa kemungkinan</b>, misalnya <span class='gd-jp'>理由</span>、<span class='gd-jp'>結果</span>、<span class='gd-jp'>事情</span>、<span class='gd-jp'>国籍</span>、<span class='gd-jp'>天候</span>.<br>Dalam dokumen resmi, 「の」kadang dihilangkan sehingga jadi <span class='gd-jp'>理由いかんにかかわらず</span>. Cukup kenali saja kalau kamu membacanya, dan saat menulis sendiri pakai versi dengan 「の」dulu.</div><div class='gd-h'>Bentuk yang paling sering muncul</div><div class='gd-sec'><span class='gd-tag'>Aturan・pengumuman</span>Toko atau perusahaan menyatakan \"tidak ada pengecualian\".</div><div class='gd-ex-line'>・<span class='gd-jp'>理由のいかんを問わず、購入後のキャンセルはできません。</span>(Apa pun alasannya, pembelian tidak dapat dibatalkan setelah dibeli)</div><div class='gd-ex-line'>・<span class='gd-jp'>天候のいかんにかかわらず、イベントは予定通り開催されます。</span>(Bagaimana pun cuacanya, acara tetap diadakan sesuai jadwal)</div><div class='gd-sec'><span class='gd-tag'>Syarat・ketentuan</span>Menunjukkan bahwa semua orang diperlakukan sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>国籍のいかんによらず、どなたでも応募できます。</span>(Apa pun kewarganegaraannya, siapa saja boleh mendaftar)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di depannya hanya boleh <b>kata benda</b>. Kata kerja atau kata sifat tidak bisa langsung disambung: <span class='gd-jp'>行くいかんによらず</span> itu salah.<br>・Di depannya harus ada kata yang \"punya berbagai kondisi\". <span class='gd-jp'>雨のいかんにかかわらず</span> tidak natural, karena 「雨」tidak punya \"bagaimananya\". Yang benar adalah <span class='gd-jp'>天候のいかん</span>.<br>・Di sini <span class='gd-jp'>如何</span> dibaca <b>いかん</b>. Kanji yang sama dibaca いかが di <span class='gd-jp'>如何ですか</span>, jadi jangan tertukar.<br>・Sangat kaku, jadi kalau dipakai ngobrol dengan teman akan terdengar aneh. Dalam percakapan cukup bilang <span class='gd-jp'>どんな理由でも</span> (apa pun alasannya).</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>〜いかんで／いかんによっては</b> (juga N1) artinya justru <b>berlawanan</b>: hasilnya <b>tergantung</b> pada hal di depannya.<br>・<span class='gd-jp'>面接の結果いかんで、採用が決まります。</span>(Diterima atau tidak, tergantung hasil wawancara)<br>・<span class='gd-jp'>面接の結果のいかんにかかわらず、交通費は支給します。</span>(Apa pun hasil wawancaranya, ongkos transportasi tetap kami berikan)</div><div class='gd-sec'><b>〜にかかわらず</b> (N2) adalah \"tidak peduli\" yang lebih umum. Tidak perlu いかん, dan di depannya juga bisa ditaruh kata seperti <span class='gd-jp'>天気</span> atau <span class='gd-jp'>年齢</span>: <span class='gd-jp'>天気にかかわらず、試合は行われます。</span>(Tidak peduli cuacanya, pertandingan tetap berlangsung)<br>Kalau ditambah 「のいかん」, nadanya jadi lebih formal, seperti dokumen resmi.</div><div class='gd-warn'>Trik cepat membedakan: kalau setelah いかん ada 「によらず／にかかわらず／を問わず」, artinya \"tidak peduli\". Kalau diikuti 「で／によっては」, artinya \"tergantung\".</div>","n1-68":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜をもってしても」artinya kira-kira <b>「bahkan dengan ～ pun tetap…」</b>. Di depan kamu taruh sesuatu yang hebat dan seharusnya berguna (teknologi terbaru, kemampuan seseorang), lalu di belakang bilang \"hasilnya tetap tidak bisa / tetap sulit\". Intinya ada di <b>「yang sehebat ini saja tidak bisa」</b>, jadi pola ini dipakai untuk menunjukkan betapa sulitnya sesuatu.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Langsung setelah kata benda: kata benda＋をもってしても<br><span class='gd-pair'><span class='gd-jp'>最新の技術</span> → <span class='gd-jp'>最新の技術をもってしても</span></span>(bahkan dengan teknologi terbaru pun)<br><span class='gd-pair'><span class='gd-jp'>彼の実力</span> → <span class='gd-jp'>彼の実力をもってしても</span></span>(bahkan dengan kemampuannya pun)<br>Di depan juga boleh langsung orangnya, artinya \"bahkan orang sehebat dia\": <span class='gd-jp'>彼をもってしても</span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Teknologi, sains, metode</span>Bahkan cara terbaik yang ada saat ini pun tidak sanggup.</div><div class='gd-ex-line'>・<span class='gd-jp'>今の科学をもってしても、地震を正確に予知することはできない。</span>(Bahkan dengan sains zaman sekarang pun, gempa bumi tidak bisa diprediksi dengan akurat)</div><div class='gd-sec'><span class='gd-tag'>Kemampuan orang</span>Orang yang sangat hebat pun merasa sulit.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の実力をもってしても、優勝は難しいだろう。</span>(Bahkan dengan kemampuannya pun, juara kemungkinan besar sulit diraih)</div><div class='gd-ex-line'>・<span class='gd-jp'>天才と呼ばれた彼をもってしても、この問題は解けなかった。</span>(Bahkan dia yang dijuluki jenius pun tidak bisa memecahkan soal ini)</div><div class='gd-sec'><span class='gd-tag'>Bahasa, ungkapan</span>Ungkapan yang sering muncul dalam pidato atau sambutan, untuk menyatakan perasaan yang begitu kuat sampai tak terkatakan.</div><div class='gd-ex-line'>・<span class='gd-jp'>どんな言葉をもってしても、この感謝の気持ちは伝えきれません。</span>(Dengan kata-kata apa pun, rasa terima kasihku ini tidak akan bisa tersampaikan sepenuhnya)</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Di belakangnya hampir selalu hasil seperti <b>「tidak bisa, sulit, tetap kurang」</b>, misalnya <span class='gd-jp'>できない</span>, <span class='gd-jp'>難しい</span>, <span class='gd-jp'>無理だ</span>. Kalau di belakangnya \"berhasil\", kalimatnya jadi aneh.<br>・Di depan harus ada sesuatu yang <b>awalnya diharapkan sangat berguna</b>. Kalau yang ditaruh hal biasa, misalnya \"pakai pensilku\", tidak ada ketegangan \"yang ini saja tidak bisa\".<br>・Ini ungkapan tulis yang sangat formal, sering muncul di berita, makalah, dan pidato. Dalam percakapan sehari-hari cukup bilang <span class='gd-jp'>最新の技術でも</span> (bahkan teknologi terbaru pun…).<br>・Intinya \"melakukan sesuatu dengan mengandalkan kekuatan ini\", bukan \"dilihat dari sudut ～\". Jangan diartikan \"jika dilihat dari ～\".</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Dengan satu \"teknologi\" yang sama, tiga ungkapan ini hasilnya sama sekali berbeda:<br><b>をもって</b>＝dengan, menggunakan (sekadar menyebut sarana): <span class='gd-jp'>この技術をもって、問題を解決した。</span>(Dengan teknologi ini, masalahnya terselesaikan)<br><b>をもってすれば</b>＝asal punya ～ pasti bisa: <span class='gd-jp'>この技術をもってすれば、問題は解決できる。</span>(Asal ada teknologi ini, masalahnya bisa terselesaikan)<br><b>をもってしても</b>＝meski punya ～ tetap tidak bisa: <span class='gd-jp'>この技術をもってしても、問題は解決できない。</span>(Meski ada teknologi ini, masalahnya tetap tidak bisa diselesaikan)<br>Selain itu, <span class='gd-jp'>をもって</span> juga punya penggunaan \"sebagai batas waktu\", misalnya <span class='gd-jp'>本日をもって閉店します。</span>(Toko ini tutup sampai hari ini). Ini tidak ada hubungannya dengan をもってしても, jadi jangan dicampur.</div><div class='gd-warn'>Trik menilai: lihat bagian kecil di tengah. 「すれば」berarti asal ada itu pasti bisa, 「しても」berarti meski ada itu tetap tidak bisa.</div>","n1-71":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ずにはすまない」artinya kira-kira <b>「kalau tidak ～, rasanya tidak pantas」「kalau tidak ～, urusannya tidak akan beres」</b>. <span class='gd-jp'>すむ</span>(済む) berarti \"urusan selesai, bisa dianggap beres\", jadi <span class='gd-jp'>すまない</span> berarti \"tidak bisa dianggap beres\". Maksud kalimatnya: menurut kepantasan dan situasi saat ini, kalau tidak melakukan hal itu, kamu tidak bisa lepas begitu saja.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Wajib secara moral</span>Setelah berbuat salah atau bikin masalah, tidak minta maaf, tidak mengganti rugi, atau tidak bertanggung jawab itu tidak pantas secara etika.</div><div class='gd-ex-line'>・<span class='gd-jp'>人の車に傷をつけたのだから、弁償せずにはすまない。</span>(Karena sudah menggores mobil orang lain, tidak mengganti rugi itu tidak pantas)</div><div class='gd-sec'><span class='gd-tag'>Terpaksa oleh keadaan</span>Masalahnya sudah membesar, dan kalau tidak ditangani, tidak ada cara untuk menyelesaikannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここまで問題が大きくなれば、社長も記者会見をせずにはすまないだろう。</span>(Masalahnya sudah sebesar ini, direktur utama pun kemungkinan besar mau tidak mau harus mengadakan konferensi pers)</div><div class='gd-sec'>Di bagian depan sering ada alasan lebih dulu, seperti <span class='gd-jp'>〜のだから</span>, <span class='gd-jp'>〜以上</span>, <span class='gd-jp'>〜たら</span>, dan di belakang sering ditambah <span class='gd-jp'>だろう</span>, yang berarti \"melihat keadaannya, sepertinya sulit dihindari\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>ずにはすまない</b>: ubah dulu ke bentuk ない, buang 「ない」, lalu tambahkan 「ずにはすまない」.<br><span class='gd-pair'><span class='gd-jp'>謝る</span> → <span class='gd-jp'>謝らない</span> → <span class='gd-jp'>謝らずにはすまない</span></span><br><span class='gd-pair'><span class='gd-jp'>払う</span> → <span class='gd-jp'>払わない</span> → <span class='gd-jp'>払わずにはすまない</span></span><br><span class='gd-pair'><span class='gd-jp'>認める</span> → <span class='gd-jp'>認めない</span> → <span class='gd-jp'>認めずにはすまない</span></span><br><b>Kelompok 3 harus diingat khusus</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはすまない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはすまない</span>（こずに）</span></div><div class='gd-sec'><b>ないではすまない</b>: bentuk ない langsung ditambah 「ではすまない」, tidak ada yang dibuang. Artinya sama, nadanya sedikit lebih lunak.</div><div class='gd-ex-line'>・<span class='gd-jp'>会議を無断で休んだのだから、部長に説明しないではすまない。</span>(Kamu absen rapat tanpa izin, jadi tidak menjelaskannya kepada kepala bagian itu tidak bisa dibiarkan)</div><div class='gd-sec'>Ada juga <span class='gd-jp'>〜ではすまない</span> yang didahului kata benda atau 「〜だけ」, artinya \"hanya begitu saja tidak cukup untuk menyelesaikannya\":</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談ではすまない。</span>(Ini tidak bisa selesai hanya dengan bilang bercanda)</div><div class='gd-ex-line'>・<span class='gd-jp'>謝るだけではすまない。</span>(Hanya minta maaf saja tidak akan menyelesaikan masalah)</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・する berubah menjadi <b>せずに</b>, bukan 「しずに」. Yang benar: <span class='gd-jp'>説明せずにはすまない</span>.<br>・<span class='gd-jp'>すまない</span> di sini bukan berarti \"maaf\", tetapi \"urusannya tidak bisa dianggap beres\".<br>・Ini ungkapan tulis yang formal, lebih sering muncul di berita, opini, dan situasi resmi. Saat ngobrol dengan teman dan ingin bilang \"sebaiknya minta maaf, deh\", orang Jepang biasanya bilang <span class='gd-jp'>謝らないとまずいよ</span>, atau memakai <span class='gd-jp'>謝らないわけにはいかない</span>.<br>・Intinya: kamu \"dipaksa oleh kepantasan atau keadaan dari luar\", bukan karena kamu sendiri ingin melakukannya, dan bukan karena tidak bisa menahan perasaan.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Untuk hal \"minta maaf\" yang sama, tiga ungkapan yang mirip ini artinya cukup berbeda:<br><b>ずにはすまない</b>＝secara kepantasan, kalau tidak melakukannya itu tidak pantas (dipaksa keadaan)<br>・<span class='gd-jp'>ミスをしたのは私だから、謝らずにはすまない。</span>(Yang berbuat salah itu aku, jadi tidak minta maaf itu tidak pantas)<br><b>ずにはいられない</b>＝tidak bisa menahan perasaan (sudah dipelajari di N2)<br>・<span class='gd-jp'>彼の涙を見て、謝らずにはいられなかった。</span>(Melihat air matanya, aku tidak tahan untuk minta maaf)<br><b>ずにはおかない</b>＝pasti akan dilakukan, tidak akan berhenti sebelum tercapai (tekad yang kuat)<br>・<span class='gd-jp'>今度こそ、彼に謝らせずにはおかない。</span>(Kali ini aku pasti akan membuatnya minta maaf)</div><div class='gd-warn'>Trik menilai: \"kalau tidak dilakukan, tidak pantas\" itu すまない, \"tidak tahan\" itu いられない, \"tidak berhenti sebelum tercapai\" itu おかない.</div>","n1-73":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「ただ～のみ」artinya <b>“hanya ～” atau “tinggal ～ saja”</b>. Ini versi formal dan bergaya tulisan dari 「だけ」. Pemakaian yang paling umum adalah untuk menyatakan tekad: semua yang harus dilakukan sudah dilakukan, dan di depan mata tinggal satu jalan, misalnya <span class='gd-jp'>あとはただ待つのみだ</span> (Sekarang tinggal menunggu). Nadanya tegas, seperti “tidak memikirkan hal lain, fokus saja pada satu hal ini”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Hanya ini</span>Menekankan bahwa cakupannya hanya satu ini, tidak ada yang lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格したのは、ただ一人のみだった。</span>(Yang lulus hanya satu orang)</div><div class='gd-sec'><span class='gd-tag'>Tinggal satu hal yang bisa dilakukan</span>Di akhir kalimat bentuknya jadi 「～のみだ」, artinya tidak perlu memikirkan hal lain, tinggal lakukan hal itu. Sering muncul dalam pidato, pernyataan sebelum pertandingan, dan berita.</div><div class='gd-ex-line'>・<span class='gd-jp'>やるべきことはすべてやった。あとはただ結果を待つのみだ。</span>(Semua yang harus dilakukan sudah dilakukan. Sekarang tinggal menunggu hasilnya)</div><div class='gd-ex-line'>・<span class='gd-jp'>今はただ無事を祈るのみです。</span>(Sekarang kita hanya bisa berdoa agar dia selamat)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata benda</b>: ただ＋kata benda＋のみ　<span class='gd-pair'><span class='gd-jp'>一人</span> → <span class='gd-jp'>ただ一人のみ</span></span><br><b>Kata kerja</b>: ただ＋bentuk kamus＋のみ　<span class='gd-pair'><span class='gd-jp'>前進する</span> → <span class='gd-jp'>ただ前進するのみだ</span></span><br>Kalau mau lebih sopan, ganti だ di akhir dengan です: <span class='gd-jp'>祈るのみです</span>.<br>「ただ」boleh dihilangkan. Hanya dengan「のみ」artinya tetap jalan, dan ただ ditambahkan untuk penekanan.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Kata benda＋あるのみ</span>Untuk mengatakan “tinggal satu hal yang harus dilakukan”, setelah kata benda biasanya ditambah 「ある」. Ini hampir jadi ungkapan baku: <span class='gd-jp'>努力あるのみ</span>, <span class='gd-jp'>前進あるのみ</span>, <span class='gd-jp'>練習あるのみ</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>試合まであと一週間。練習あるのみだ。</span>(Tinggal seminggu lagi sebelum pertandingan. Tidak ada jalan lain selain berlatih keras)</div><div class='gd-sec'><span class='gd-tag'>Papan pengumuman</span>Di jalanan Jepang, kamu sering melihat 「のみ」berdiri sendiri, artinya “khusus ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>この席は会員のみご利用いただけます。</span>(Tempat duduk ini khusus untuk anggota)</div><div class='gd-ex-line'>・<span class='gd-jp'>関係者のみ</span>(Khusus pihak yang berkepentingan)</div><div class='gd-h'>Hal yang sering salah</div><div class='gd-warn'>・Ungkapan ini sangat formal dan penuh semangat. Kalau ngobrol soal makan siang dengan teman lalu bilang 「ただ食べるのみ」, kedengarannya seperti sedang berakting. Dalam percakapan sehari-hari cukup pakai <span class='gd-jp'>だけ</span>: <span class='gd-jp'>あとは待つだけだ</span>.<br>・Kata kerja harus memakai bentuk kamus, tidak boleh bentuk ます. Yang benar <span class='gd-jp'>前進するのみです</span>, bukan 「前進しますのみ」.<br>・<span class='gd-jp'>のみならず</span> mirip, tetapi artinya <b>“tidak hanya ～”</b>, justru kebalikannya: <span class='gd-jp'>ただ日本のみならず、世界中で人気がある。</span> (Tidak hanya di Jepang, tetapi juga populer di seluruh dunia). Kalau setelah のみ masih ada 「ならず」, ganti pemahamanmu jadi “tidak hanya”.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>～のみだ</b> = di depan mata <b>hanya ada satu jalan</b>, fokus saja maju: <span class='gd-jp'>ここまで来たら、ただ前進するのみだ。</span> (Sudah sampai sini, tinggal maju terus)<br><b>～まで（のこと）だ</b> = <b>paling-paling ～</b>, jalan keluar yang sudah disiapkan lebih dulu. Di depannya sering ada 「だめなら」「失敗したら」: <span class='gd-jp'>だめなら、もう一度挑戦するまでだ。</span> (Kalau tidak berhasil, ya paling-paling coba lagi sekali)</div><div class='gd-warn'>Tips menentukan: kalau dalam bahasa Indonesia kamu bisa bilang “tinggal ～ saja / hanya bisa ～”, pakai のみ. Kalau artinya “paling-paling ～” dan di depannya ada “kalau tidak berhasil”, pakai までだ.</div>","n1-74":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ないものでもない」artinya <b>“bukannya tidak ～”</b>. Bayangkan temanmu minta tolong pindahan, lalu kamu menjawab, “Tergantung kamu traktir makan atau enggak ya, bukannya aku nggak mau bantu.” Artinya mungkin saja, tapi tidak terlalu rela, dan juga tidak langsung bilang iya.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk negatif 「ない」, lalu langsung tambahkan <b>ものでもない</b>.<br><span class='gd-pair'><span class='gd-jp'>引き受ける</span> → <span class='gd-jp'>引き受けない</span> → <span class='gd-jp'>引き受けないものでもない</span></span><br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許さない</span> → <span class='gd-jp'>許さないものでもない</span></span><br><span class='gd-pair'><span class='gd-jp'>間に合う</span> → <span class='gd-jp'>間に合わない</span> → <span class='gd-jp'>間に合わないものでもない</span></span><br>Dua negasi (“tidak” lalu “bukannya”) saling meniadakan, dan hasilnya adalah <b>“boleh” yang masih setengah hati</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Setuju dengan syarat</span>Ini pemakaian yang paling umum. Di depannya sering ada 「〜ば」「〜なら」「〜次第では (tergantung ～)」. Kamu menyebut syarat dulu, baru bilang “bukannya tidak bisa”.</div><div class='gd-ex-line'>・<span class='gd-jp'>条件次第では、引き受けないものでもない。</span>(Tergantung syaratnya, bukannya tidak mau menerima)</div><div class='gd-ex-line'>・<span class='gd-jp'>ちゃんと謝るなら、許さないものでもない。</span>(Kalau dia minta maaf dengan benar, bukannya tidak mau memaafkan)</div><div class='gd-sec'><span class='gd-tag'>Masih ada kemungkinan</span>Menilai bahwa sesuatu bukan tanpa harapan sama sekali.</div><div class='gd-ex-line'>・<span class='gd-jp'>あと一週間あれば、間に合わないものでもない。</span>(Kalau ada waktu seminggu lagi, bukannya tidak mungkin keburu)</div><div class='gd-sec'><span class='gd-tag'>Bisa mengerti walau agak berat</span>Menyatakan “agak paham” terhadap pemikiran orang lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の気持ちも分からないものでもない。</span>(Perasaannya pun bukannya tidak bisa kupahami)</div><div class='gd-h'>Hal yang sering salah</div><div class='gd-warn'>・<b>「ない」tidak boleh ketinggalan.</b> Kalau ditulis <span class='gd-jp'>引き受けるものでもない</span>, artinya jadi “itu juga bukan hal yang pantas diterima”, kebalikannya. Kalimat seperti <span class='gd-jp'>お金で買えるものでもない</span> artinya “itu juga bukan sesuatu yang bisa dibeli dengan uang”, dan tidak ada hubungannya dengan pola ini.<br>・Pola ini hanya berarti “<b>mungkin saja</b>”, bukan “pasti”, dan bukan “sangat ingin”. Kalau diterjemahkan menjadi “aku bersedia” atau “tidak masalah”, itu sudah berlebihan.<br>・Nadanya kaku dan bergaya tulisan, sering terdengar agak <b>angkuh, seperti “ya sudah, kuterima dengan terpaksa” atau “akan kupertimbangkan”</b>. Kepada atasan atau pelanggan, mengatakan 「手伝わないものでもないです」 sangat tidak sopan, jadi jangan dipakai saat ingin bersikap santun.<br>・Yang disambung biasanya tindakan atau penilaian diri sendiri, seperti mau menerima atau tidak, mau mempertimbangkan atau tidak, bisa memahami atau tidak. Jarang dipakai untuk membicarakan urusan orang lain.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Ada pola lain yang artinya hampir sama, yaitu <b>ないこともない</b>, <b>ないでもない</b>, dan <b>なくもない</b>. Bedanya ada pada situasi pemakaian:<br><b>ないものでもない</b>: gaya tulisan dan kaku, sering muncul di artikel, negosiasi, dan pernyataan yang cukup formal.<br><span class='gd-jp'>条件が合えば、協力しないものでもない。</span>(Kalau syaratnya cocok, bukannya tidak mau bekerja sama)<br><b>ないこともない／ないでもない</b>: paling sering dipakai dalam percakapan sehari-hari.<br><span class='gd-jp'>時間があれば、行けないこともないよ。</span>(Kalau ada waktu, bukannya nggak bisa pergi, kok)<br><b>なくもない</b>: lebih lisan dan lebih santai.<br><span class='gd-jp'>まあ、分からなくもないけど。</span>(Yah, bukannya nggak ngerti sih)</div><div class='gd-warn'>Tips menentukan: semuanya berarti “bukannya tidak ～”. Untuk ngobrol, pakai 「ないこともない」. Pakai 「ないものでもない」 hanya saat menulis, membahas syarat, atau ingin bersikap agak jual mahal.</div>","n1-79":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「ともすると／ともすれば」artinya kira-kira <b>「sedikit-sedikit jadi ～」「kalau lengah sedikit langsung ～」「sering kali cenderung ～」</b>. Kata ini menggambarkan <b>kecenderungan yang kurang baik</b>: tidak selalu terjadi, tapi kalau kita sedikit saja lengah, kita akan terseret ke arah itu. Rasanya seperti \"kalau lagi senggang, gampang banget main HP sampai tengah malam\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ini adalah <b>kata yang berdiri sendiri</b>, jadi tidak perlu disambung ke kata apa pun. Taruh saja di awal kalimat, atau tepat sebelum \"hal buruk yang mau kamu bicarakan\".<br>Di bagian belakang kalimat, biasanya dipasangkan dengan ungkapan yang berarti \"cenderung ～\". Kalau muncul bersamaan, hasilnya paling natural:<br><span class='gd-tag'>Pasangan yang umum</span><span class='gd-jp'>〜がちだ</span>（sering ～）、<span class='gd-jp'>〜やすい</span>（mudah ～）、<span class='gd-jp'>〜てしまう</span>（tanpa sengaja jadi ～）</div><div class='gd-ex-line'>・<span class='gd-jp'>人はともすると、楽なほうへ流れがちだ。</span>（Manusia sering kali cenderung memilih jalan yang lebih gampang）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、ともすれば食事を抜いてしまう。</span>（Kalau lagi sibuk, sering kali tanpa sadar jadi melewatkan makan）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人暮らしだと、ともすると生活が不規則になりやすい。</span>（Kalau tinggal sendiri, hidup gampang jadi tidak teratur）</div><div class='gd-sec'>「ともすると」dan「ともすれば」artinya sama dan bisa saling menggantikan. Pilih saja yang terasa lebih enak diucapkan.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Ini bukan pola tata bahasa yang menempel di belakang kata lain, jadi tidak boleh ditulis「忙しいともすると」. Pisahkan: <span class='gd-jp'>忙しいと、ともすると〜</span>.<br>・Dipakai untuk <b>kecenderungan yang buruk</b>. Untuk kebiasaan baik, ini tidak dipakai. Misalnya kalau mau bilang \"aku sering tanpa sadar jadi olahraga\", jangan pakai ともすると.<br>・Yang dibicarakan adalah \"kecenderungan yang sering terjadi\", bukan kejadian satu kali. \"Kemarin tanpa sengaja terlambat\" hanya kecelakaan sekali, jadi tidak pakai ともすると. Cukup bilang <span class='gd-jp'>うっかり遅刻した</span>.<br>・Nuansanya cenderung tulisan dan formal, sering muncul di artikel, pidato, dan ulasan. Kalau ngobrol dengan teman, lebih sering pakai <span class='gd-jp'>つい</span> atau <span class='gd-jp'>すぐ</span>, misalnya <span class='gd-jp'>ついスマホを見ちゃう</span>（nggak tahan, jadi terus lihat HP）.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ともすると／ともすれば</b>: berdiri sendiri di dalam kalimat, menyatakan <b>kecenderungan buruk yang mudah terjadi</b>, dan di belakangnya sering ada がち atau やすい.<br><b>ともなると／ともなれば</b>: di depannya ada kata benda (biasanya status, posisi, waktu, atau tingkatan), bisa juga kata kerja bentuk kamus. Artinya <b>「begitu sudah sampai pada status, masa, atau keadaan tertentu, wajar kalau ～」</b>.<br>Sama-sama membahas \"sibuk sampai tidak sempat makan\", coba bandingkan:</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、ともすると食事を抜きがちだ。</span>（Kalau sibuk, gampang melewatkan makan: membahas kebiasaan buruk）</div><div class='gd-ex-line'>・<span class='gd-jp'>年末ともなると、食事をする時間もない。</span>（Kalau sudah akhir tahun, makan pun tidak sempat: membahas hal yang wajar terjadi saat masa itu tiba）</div><div class='gd-sec'>Contoh lain untuk ともなると: <span class='gd-jp'>社長ともなると、なかなか休めない。</span>（Kalau sudah jadi direktur, susah sekali mengambil libur）<br><span class='gd-jp'>海外に住むともなると、準備が大変だ。</span>（Kalau sudah sampai tahap mau tinggal di luar negeri, persiapannya berat sekali）</div><div class='gd-warn'>Trik membedakan: kalau di depannya ada kata benda atau kata kerja dan maknanya \"begitu sampai tahap itu, pasti ～\", itu ともなると. Kalau berdiri sendiri dan maknanya \"sedikit-sedikit jadi ～ (hal buruk)\", itu ともすると.</div><div class='gd-h'>Setelah ini, belajar apa?</div><div class='gd-sec'>Untuk sama-sama membahas \"kecenderungan yang kurang baik\", lanjut lihat <span class='gd-jp'>〜嫌いがある</span>, yang diletakkan di akhir kalimat: <span class='gd-jp'>彼は物事を悲観的に考える嫌いがある。</span>（Dia punya kecenderungan memandang segala hal secara pesimis）. Keduanya juga sering dipakai bersamaan: <span class='gd-jp'>人はともすると、自分に甘くなる嫌いがある。</span>（Manusia sering kali punya kelemahan, yaitu terlalu memaklumi diri sendiri）</div>","n1-82":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜を限りに」artinya <b>「sampai ～ saja, setelah itu tidak ～ lagi」</b>. Seperti kita bilang \"hari ini hari terakhir\" atau \"setelah ini aku berhenti\": ada garis batas, sebelum garis masih ada, sesudahnya sudah tidak ada.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Taruh kata benda yang menunjukkan titik waktu langsung di depannya, lalu tambahkan「を限りに」:<br><span class='gd-pair'><span class='gd-jp'>今日</span> → <span class='gd-jp'>今日を限りに</span></span><span class='gd-pair'><span class='gd-jp'>今回</span> → <span class='gd-jp'>今回を限りに</span></span><span class='gd-pair'><span class='gd-jp'>本日</span> → <span class='gd-jp'>本日を限りに</span></span><br>Yang paling sering muncul adalah kata untuk \"titik waktu sekarang\" seperti <span class='gd-jp'>今日・本日・今回・今月・今年度</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Bertekad tidak mengulangi lagi</span>Memutus hubungan dengan diri kita yang dulu, biasanya disertai tekad.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日を限りに、お酒はやめる。</span>（Minum sampai hari ini saja, setelah ini berhenti）</div><div class='gd-sec'><span class='gd-tag'>Mengumumkan akhir</span>Toko tutup, atlet pensiun, atau aturan dihapus, biasanya dengan nuansa haru.</div><div class='gd-ex-line'>・<span class='gd-jp'>今回の試合を限りに、引退します。</span>（Setelah pertandingan kali ini, aku akan pensiun）</div><div class='gd-ex-line'>・<span class='gd-jp'>この路線は今年度を限りに廃止される。</span>（Rute ini akan dihentikan setelah tahun anggaran ini berakhir）</div><div class='gd-sec'><span class='gd-tag'>Arti lain</span>「<span class='gd-jp'>声を限りに</span>」adalah ungkapan tetap yang artinya \"sekuat tenaga, sekeras-kerasnya\". Tidak ada hubungannya dengan waktu, tapi kamu perlu mengenalinya.</div><div class='gd-ex-line'>・<span class='gd-jp'>声を限りに助けを呼んだ。</span>（Berteriak minta tolong sekeras-kerasnya）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Ini bukan \"tenggat waktu\". Untuk batas waktu mengumpulkan tugas, pakai までに: <span class='gd-jp'>金曜日までに出してください。</span>（Tolong kumpulkan paling lambat hari Jumat）. Tidak boleh bilang「金曜日を限りに出してください」.<br>・Di belakangnya biasanya hal yang berarti <b>berakhir, berhenti, tidak dilakukan lagi</b>, seperti <span class='gd-jp'>やめる・引退する・閉店する・解散する</span>. Kalau cuma mau bilang \"mulai hari ini aku akan berusaha\", bahasa Jepang biasanya pakai <span class='gd-jp'>今日から</span>.<br>・Ini ungkapan yang formal dan cenderung bahasa tulis. Dalam obrolan dengan teman, cukup pakai <span class='gd-jp'>今日でやめる</span> atau <span class='gd-jp'>今日限りでやめる</span>.<br>・Jangan tertukar dengan「kata kerja + 限り」: <span class='gd-jp'>生きている限り</span> artinya \"selama masih hidup\", maknanya benar-benar berbeda.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>をもって</b> juga bisa berarti \"berakhir pada ～\". Dalam pengumuman toko tutup, keduanya bisa dipakai, tapi rasanya berbeda:<br><span class='gd-jp'>本日をもって閉店いたします。</span>（Toko ini beroperasi sampai hari ini）<br>→ Pengumuman resmi yang formal, hanya memberi tahu bahwa \"berakhir pada hari ini\".<br><span class='gd-jp'>本日を限りに閉店いたします。</span>（Hari ini adalah hari terakhir kami buka）<br>→ Fokusnya \"sampai hari ini saja, setelah ini tidak akan ada lagi\", jadi lebih terasa emosional, seperti tirai yang ditutup.<br>Selain itu, <b>をもって</b> juga bisa menyatakan <b>awal</b>: <span class='gd-jp'>4月1日をもって新制度を実施します。</span>（Mulai 1 April, sistem baru diberlakukan）; sedangkan <b>を限りに</b> hanya bisa dipakai untuk \"akhir\", tidak untuk awal.</div><div class='gd-warn'>Trik membedakan: kalau mau menekankan \"yang terakhir kali, setelah ini tidak lagi\", pakai を限りに. Kalau pemberitahuan resmi tentang awal atau akhir pada hari tertentu, pakai をもって.</div><div class='gd-h'>Setelah ini, belajar apa?</div><div class='gd-sec'>Yang maknanya justru berlawanan adalah「<span class='gd-jp'>〜を皮切りに</span>」= diawali dari ～, lalu berlanjut satu demi satu: <span class='gd-jp'>東京公演を皮切りに、全国ツアーが始まる。</span>（Dimulai dari pertunjukan di Tokyo, tur seluruh negeri pun bergulir）</div>","n1-76":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ではあるまいし」kira-kira berarti <b>「Kan bukan ～, (jadi ngapain…／seharusnya…)」</b>. Bayangkan ibumu melihatmu menangis lalu bilang, “Kamu kan bukan anak kecil, kok nangis terus?” Nah, nuansanya persis begitu. Kamu mengajukan dulu sesuatu yang <b>jelas bukan kenyataan</b>, lalu memakainya untuk menegur atau menasihati lawan bicara.</div><div class='gd-h'>Asal-usulnya</div><div class='gd-sec'>Kalau dipecah, jadi gampang dimengerti. <span class='gd-jp'>ではあるまい</span> adalah bentuk yang lebih tulis dari “seharusnya bukan ～ ya”, dan <span class='gd-jp'>し</span> berarti “karena ～”. Digabung jadi “kan bukan ～, jadi…”.<br>Dalam percakapan hampir selalu dipakai <b><span class='gd-jp'>じゃあるまいし</span></b>. <span class='gd-jp'>ではあるまいし</span> lebih sering muncul di tulisan atau situasi yang agak formal.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Nomina</span>langsung disambung: <span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供じゃあるまいし</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>子供じゃあるまいし、自分のことは自分でやりなさい。</span>(Kamu kan bukan anak kecil, urus sendiri urusanmu.)</div><div class='gd-ex-line'>・<span class='gd-jp'>神様じゃあるまいし、明日のことなんて分からないよ。</span>(Aku kan bukan Tuhan, mana tahu besok bakal gimana.)</div><div class='gd-sec'><span class='gd-tag'>Verba</span>harus disisipi dulu <b><span class='gd-jp'>の</span>(dalam percakapan <span class='gd-jp'>ん</span>) atau <span class='gd-jp'>わけ</span></b>, tidak bisa langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>遊びに行く</span> → <span class='gd-jp'>遊びに行くんじゃあるまいし</span></span><br><span class='gd-pair'><span class='gd-jp'>会えない</span> → <span class='gd-jp'>会えないわけじゃあるまいし</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>遊びに行くんじゃあるまいし、もっとちゃんとした服を着ていきなさい。</span>(Kan bukan mau main-main, pakai baju yang lebih rapi dong.)</div><div class='gd-ex-line'>・<span class='gd-jp'>一生会えないわけじゃあるまいし、そんなに泣かないで。</span>(Kan bukan berarti nggak bakal ketemu seumur hidup, jangan nangis sampai segitunya.)</div><div class='gd-h'>Apa yang biasanya muncul setelahnya</div><div class='gd-sec'>Bagian belakang adalah hal yang benar-benar ingin kamu sampaikan. Hampir selalu berupa <b>perintah, larangan, nasihat, kritik, atau penilaian pribadi</b>: “jangan ～ lagi”, “lakukan sendiri”, “hal seperti ini seharusnya tidak terjadi”. Bagian depannya biasanya sesuatu yang berlebihan dan jelas bukan kenyataan, misalnya <span class='gd-jp'>子供</span>, <span class='gd-jp'>神様</span>, atau <span class='gd-jp'>素人</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>素人じゃあるまいし、こんなミスは許されないよ。</span>(Kamu kan bukan amatir, kesalahan seperti ini nggak bisa dimaafkan.)</div><div class='gd-sec'><span class='gd-tag'>Susunan terbalik dalam percakapan</span>Sering juga ditaruh di akhir sebagai tambahan.</div><div class='gd-ex-line'>・<span class='gd-jp'>いちいち説明しなくても分かるよ。子供じゃあるまいし。</span>(Nggak perlu dijelaskan satu-satu, aku ngerti kok. Aku kan bukan anak kecil.)</div><div class='gd-h'>Bagian yang sering keliru</div><div class='gd-warn'>・Di depan verba harus ada <span class='gd-jp'>の／ん／わけ</span>. Yang benar <span class='gd-jp'>死ぬわけじゃあるまいし</span>, bukan 「死ぬじゃあるまいし」. Nomina justru sebaliknya: jangan tambahkan の, jadi tidak ada bentuk 「子供のじゃあるまいし」.<br>・Bagian depan harus berupa hal yang <b>semua orang tahu “jelas bukan”</b>. Kalau cuma menyampaikan alasan biasa, misalnya “aku bukan pelajar, jadi bayar tarif penuh”, memakai pola ini terdengar aneh. Untuk itu cukup pakai <span class='gd-jp'>〜ではないので</span>.<br>・Nuansanya <b>menegur dan nyindir</b>, dengan sedikit rasa tidak sabar. Kalau langsung diucapkan kepada atasan atau pelanggan, itu sangat tidak sopan.<br>・Ini bukan kalimat dugaan seperti “bukan ～ kan?”. Intinya ada pada teguran atau nasihat di bagian belakang.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>〜じゃないんだから</b>: artinya hampir sama, “kan bukan ～”. Tapi lebih sehari-hari dan lebih sering terdengar, jadi learner di bawah N1 pun memakainya.<br>・<span class='gd-jp'>子供じゃないんだから、泣かないで。</span>(Kamu kan bukan anak kecil, jangan nangis.)<br>・<span class='gd-jp'>子供じゃあるまいし、泣かないで。</span>(Sama seperti di atas, tapi terdengar sedikit lebih kuno dan lebih bernada menegur.)</div><div class='gd-sec'><b>〜ではあるまいか</b>: bedanya cuma satu huruf di akhir, tapi artinya sama sekali lain. Ini bentuk tulis untuk “jangan-jangan ～ ya／mungkin ～ ya”, dipakai untuk menduga.<br>・<span class='gd-jp'>子供ではあるまいし、一人で行けるだろう。</span>(Kan bukan anak kecil, pasti bisa pergi sendiri.)<br>・<span class='gd-jp'>彼は何か隠しているのではあるまいか。</span>(Jangan-jangan dia menyembunyikan sesuatu?)</div><div class='gd-warn'>Trik membedakan: kalau di belakang ada 「し」 lalu kalimat yang menegur, artinya “kan bukan ～”. Kalau berakhir dengan 「か」, artinya menebak “jangan-jangan ～”.</div>","n1-78":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「AあってのB」kira-kira berarti <b>「Ada A, baru ada B」「B bergantung sepenuhnya pada A」</b>. A adalah syarat agar B bisa ada. Tanpa A, B tidak akan ada. Pemilik toko sering bilang “pembeli adalah raja”. Dalam bahasa Jepang jadinya: <span class='gd-jp'>お客様あっての商売だ。</span>(Usaha ada karena ada pelanggan.)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Nomina＋あっての＋nomina</b>. Di depan nomina, di belakang pun harus nomina.<br>「あって」 adalah bentuk て dari 「ある」(ada), dan kalau ditambah 「の」 artinya “～ yang ada karena adanya…”.<br><span class='gd-pair'><span class='gd-jp'>お客様</span> → <span class='gd-jp'>お客様あっての商売</span></span>(usaha yang ada karena ada pelanggan)</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>AあってのBだ</span>Menyatakan prinsip atau nilai: B bisa berdiri karena ditopang A.</div><div class='gd-ex-line'>・<span class='gd-jp'>選手はファンあっての存在だ。</span>(Atlet ada karena ada penggemar.)</div><div class='gd-ex-line'>・<span class='gd-jp'>命あっての物種だ。無理はするな。</span>(Selama masih hidup, semuanya masih bisa diraih. Jangan memaksakan diri.)</div><div class='gd-sec'><span class='gd-tag'>〜あってのことだ</span>Nomina di belakang diganti 「こと」, artinya “semua ini bisa terjadi berkat ～”. Paling sering dipakai dalam pidato kemenangan dan ucapan terima kasih.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できたのは、先生のご指導あってのことです。</span>(Saya bisa lulus semuanya berkat bimbingan Bapak/Ibu guru.)</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの応援あっての優勝です。</span>(Juara kali ini ada berkat dukungan kalian semua.)</div><div class='gd-sec'><span class='gd-tag'>あってこその</span>Ditambah 「こそ」 di tengah, nuansanya lebih kuat: <span class='gd-jp'>家族あってこその私です。</span>(Justru karena ada keluarga, aku bisa seperti sekarang.)</div><div class='gd-h'>Bagian yang sering keliru</div><div class='gd-warn'>・Di belakang harus nomina (atau こと). Tidak bisa bilang 「お客様あっての売れる」. Yang benar <span class='gd-jp'>お客様あっての商売</span>.<br>・Bentuknya tetap 「あっての」, jangan ditulis 「あるの」.<br>・Ini bukan sekadar “karena”. Untuk “dibatalkan karena hujan” tidak bisa bilang 「雨あっての中止」. Yang benar <span class='gd-jp'>雨で中止になった</span>. A harus <b>fondasi yang tak tergantikan</b> bagi B, biasanya hal positif dan penting seperti pelanggan, kesehatan, dukungan, atau usaha.<br>・Nuansanya cukup formal dan agak menyentuh perasaan, jadi banyak dipakai di pidato, wawancara, dan tulisan. Kalau ngobrol dengan teman, cukup bilang <span class='gd-jp'>お客さんがいるから</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Satu makna yang sama bisa disampaikan dari sisi positif maupun sisi negatif:<br><b>あっての</b>＝sisi positif, “ada A baru ada B”, diikuti nomina: <span class='gd-jp'>お客様あっての商売だ。</span>(Usaha ada karena ada pelanggan.)<br><b>なくしては</b>＝sisi negatif, “tanpa A, B tidak bisa”, diikuti bentuk negatif: <span class='gd-jp'>お客様なくしては商売は成り立たない。</span>(Tanpa pelanggan, usaha tidak akan berjalan.)<br><b>ばこそ</b>＝“justru karena ～ maka…”, menjelaskan alasan melakukan sesuatu, didahului bentuk ば: <span class='gd-jp'>お客様のことを思えばこそ、品質にこだわるのだ。</span>(Justru karena memikirkan pelanggan, kami sangat memperhatikan kualitas.)</div><div class='gd-warn'>Trik membedakan: untuk “B ada karena A”, pakai あっての dengan nomina di belakang. Untuk “tanpa A, B tidak bisa”, pakai なくしては dengan bentuk negatif di belakang. Untuk “justru karena berpikir atau berbuat begitu”, pakai ばこそ.</div>","n1-83":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'><span class='gd-jp'>めく</span> artinya <b>「mulai terasa seperti ～」「mulai bernuansa ～」</b>. Belum sepenuhnya jadi seperti itu, tapi suasananya sudah terasa. Misalnya di akhir Februari cuaca tiba-tiba menghangat, lalu kamu bilang \"wah, sudah mulai terasa musim semi\". Dalam bahasa Jepang, itu <span class='gd-jp'>春めいてきた</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Pergantian musim perlahan</span>Ini pemakaian yang paling umum, biasanya dipasangkan dengan <span class='gd-jp'>〜めいてきた</span>, artinya \"perlahan mulai terasa ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>一気に春めいてきた。</span>（Tiba-tiba sudah terasa suasana musim semi）</div><div class='gd-ex-line'>・<span class='gd-jp'>風が少し秋めいてきた。</span>（Angin mulai terasa seperti musim gugur）</div><div class='gd-sec'><span class='gd-tag'>Menggambarkan orang atau cara bicara</span>Pakai <span class='gd-jp'>〜めいた</span> di depan kata benda, artinya \"yang agak bernuansa ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女はどこか謎めいた人だ。</span>（Dia orang yang agak misterius）</div><div class='gd-ex-line'>・<span class='gd-jp'>皮肉めいた言い方はやめてよ。</span>（Jangan bicara dengan nada menyindir begitu dong）</div><div class='gd-ex-line'>・<span class='gd-jp'>言い訳めいたことは言いたくない。</span>（Aku tidak mau bicara yang kedengarannya seperti mencari-cari alasan）</div><div class='gd-h'>Cara menyambung dan berubah bentuk</div><div class='gd-sec'>Tambahkan <span class='gd-jp'>めく</span> langsung setelah kata benda, dan jadilah satu verba, yaitu <b>verba kelompok 1 (godan)</b>. Perubahannya sama seperti <span class='gd-jp'>書く</span>.<br>Saat disambung dengan て atau た, く berubah menjadi い:<br><span class='gd-pair'><span class='gd-jp'>春めく</span> → <span class='gd-jp'>春めいて</span></span> → <span class='gd-pair'><span class='gd-jp'>春めいてきた</span></span><br><span class='gd-pair'><span class='gd-jp'>謎めく</span> → <span class='gd-jp'>謎めいた</span></span> → <span class='gd-pair'><span class='gd-jp'>謎めいた事件</span></span>（kasus yang misterius）</div><div class='gd-h'>Yang sering bikin salah</div><div class='gd-warn'>・<b>Tidak semua kata benda bisa dipakai</b>. <span class='gd-jp'>めく</span> hanya cocok dengan sekelompok kecil kata yang sudah tetap. Yang umum, antara lain <span class='gd-jp'>春めく</span>, <span class='gd-jp'>秋めく</span>, <span class='gd-jp'>謎めく</span>, <span class='gd-jp'>皮肉めく</span>, <span class='gd-jp'>冗談めく</span>, <span class='gd-jp'>言い訳めく</span>, <span class='gd-jp'>説教めく</span>. Kalau 「<span class='gd-jp'>学生めく</span>」 atau 「<span class='gd-jp'>先生めく</span>」, itu terdengar tidak natural. Katakan <span class='gd-jp'>学生らしい</span> atau <span class='gd-jp'>学生っぽい</span>.<br>・Di depan kata benda, hampir selalu dipakai <b>めいた</b>: bilang <span class='gd-jp'>謎めいた人</span>, bukan 謎めく人.<br>・Bentuk て-nya <span class='gd-jp'>めいて</span>, bukan めくて, dan bukan juga めきて.<br>・<span class='gd-jp'>春めいてきた</span> artinya \"sudah terasa seperti musim semi\", tidak sama dengan <span class='gd-jp'>春になった</span> (musim semi sudah benar-benar tiba).<br>・Kesannya cenderung tulisan dan sastra, sering muncul di laporan cuaca dan novel. Kalau ngobrol santai dengan teman, biasanya lebih sering pakai <span class='gd-jp'>っぽい</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama bicara soal \"musim semi\":<br><span class='gd-jp'>だんだん春めいてきた。</span>（Perlahan mulai terasa suasana musim semi）: intinya <b>mulai ada tanda-tandanya</b>.<br><span class='gd-jp'>今日は春らしい天気だ。</span>（Hari ini cuacanya khas musim semi banget）: intinya <b>sangat khas, pantas disebut musim semi</b>.<br><span class='gd-jp'>春っぽい服を買った。</span>（Aku beli baju yang kesannya musim semi banget）: <b>bahasa lisan</b>, bilang santai \"mirip-mirip ～\".</div><div class='gd-warn'>Trik cepat: \"mulai terasa nuansa ～, agak bernuansa ～\" pakai めく; \"memang pantas seperti ～ yang seharusnya\" pakai らしい; ngobrol santai \"kesannya ～ banget\" pakai っぽい.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'><span class='gd-jp'>めく</span> punya saudara, yaitu <span class='gd-jp'>めかす</span>, yang artinya \"sengaja membuatnya tampak seperti ～\": <span class='gd-jp'>冗談めかして本音を言った。</span>（Dia mengatakan isi hatinya dengan nada bercanda）</div>","n1-84":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Pola ini artinya <b>「sampai ～ lho」「sebanyak ～」</b>. Di depannya ada angka, dan pembicara ingin menekankan \"angkanya besar banget\", dan <b>mungkin malah lebih dari itu</b>. Misalnya kamu lihat koper seberat 30 kg dan bilang \"ini beratnya sampai 30 kg lho\". Dalam bahasa Jepang, kamu pakai pola ini.</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'>Di depannya pasti <b>angka + satuan</b> (100キロ、1万人、50万円), lalu langsung sambung dengan からある／からする／からの. Mau pilih yang mana, tergantung apa yang dibicarakan.</div><div class='gd-sec'><span class='gd-tag'>からある</span>Berat, panjang, tinggi, jarak, ukuran.<br>Dalam bahasa Jepang, memang lazim bilang 「重さが<b>ある</b>」「長さが<b>ある</b>」, jadi untuk \"seberapa berat, seberapa panjang\" dipakai ある.</div><div class='gd-ex-line'>・<span class='gd-jp'>30キロからある荷物を一人で運んだ。</span>（Aku mengangkut barang seberat 30 kg sendirian）</div><div class='gd-ex-line'>・<span class='gd-jp'>2メートルからある魚が釣れた。</span>（Aku berhasil memancing ikan yang panjangnya sampai dua meter）</div><div class='gd-ex-line'>・<span class='gd-jp'>片道100キロからある道のりを毎日車で通っている。</span>（Dia berangkat kerja naik mobil tiap hari, sekali jalan sampai seratus kilometer）</div><div class='gd-sec'><span class='gd-tag'>からする</span>Harga.<br>Untuk \"harganya sekian\", bahasa Jepang memang memakai する: <span class='gd-jp'>この時計は100万円する。</span>（Jam ini harganya satu juta yen）. Karena itu harga dipasangkan dengan からする.</div><div class='gd-ex-line'>・<span class='gd-jp'>一泊10万円からするホテルに泊まった。</span>（Aku menginap di hotel yang semalamnya sampai seratus ribu yen）</div><div class='gd-ex-line'>・<span class='gd-jp'>あのバッグは50万円からするらしい。</span>（Katanya tas itu harganya sampai lima ratus ribu yen）</div><div class='gd-sec'><span class='gd-tag'>からの</span>Paling sering dipakai untuk jumlah orang, dan di belakangnya <b>harus ada kata benda</b> (の itu seperti \"yang\" atau penanda penghubung). Jumlah uang atau utang juga bisa pakai からの + kata benda.</div><div class='gd-ex-line'>・<span class='gd-jp'>会場には1万人からの人が集まった。</span>（Di lokasi acara berkumpul sampai sepuluh ribu orang）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼には1000万円からの借金がある。</span>（Dia punya utang sampai sepuluh juta yen）</div><div class='gd-h'>Yang sering bikin salah</div><div class='gd-warn'>・Hanya bisa dipakai untuk <b>angka yang besar</b>. <span class='gd-jp'>1キロからある荷物</span> terdengar aneh, karena satu kilo tidak ada yang perlu ditekankan.<br>・からする hanya untuk <b>harga</b>. Untuk berat, katakan <span class='gd-jp'>100キロからある</span>, bukan 100キロからする.<br>・Setelah からの harus ada kata benda: <span class='gd-jp'>1万人からの人</span> boleh, tapi kalimat yang berhenti di 「1万人からの。」 tidak boleh.<br>・Pola ini agak formal dan bernuansa tulisan, sering muncul di berita, laporan, dan artikel. Dalam obrolan dengan teman memang bisa dipakai, tapi cara yang lebih lisan adalah dengan 「も」 (dibahas di bawah).</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>「から」biasa</b> = <b>mulai dari ～</b> (harga terendah dalam kisaran harga):<br><span class='gd-jp'>この店の時計は1万円からあります。</span>（Jam di toko ini ada mulai dari sepuluh ribu yen）<br><b>からする</b> = <b>sampai ～</b> (menekankan mahalnya):<br><span class='gd-jp'>この時計は100万円からする。</span>（Jam ini harganya sampai satu juta yen）<br>Yang pertama membahas \"yang paling murah mulai dari mana\", yang kedua membahas \"barang yang satu ini mahal banget\".</div><div class='gd-sec'><b>Angka + も</b> = versi lisan dari \"ternyata sampai ～\": <span class='gd-jp'>この荷物、30キロもあるよ。</span>（Barang ini ternyata beratnya 30 kg lho）<br><b>からある</b> = lebih bernuansa tulisan, dengan kesan \"paling tidak sebanyak ini, mungkin malah lebih\": <span class='gd-jp'>30キロからある荷物</span>（barang yang beratnya sampai 30 kg）</div><div class='gd-warn'>Trik cepat: kalau toko menulis 「～円から」, itu menyebut harga terendah. Kalau setelah angka ada からある／からする／からの, pembicaranya sedang takjub \"angkanya besar banget\". Berat dan panjang pakai ある, harga pakai する, dan kalau di belakangnya ada kata benda, pakai からの.</div>","n1-85":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ようにも〜ない」artinya <b>「ingin ~ pun tidak bisa ~」</b>, misalnya “ingin kabur pun tidak bisa kabur” atau “ingin melupakan pun tidak bisa lupa”. Kamu benar-benar ingin melakukannya, tapi keadaan menghalangi, jadi <b>sama sekali tidak bisa</b>. Nadanya penuh rasa pasrah.</div><div class='gd-ex-line'>・<span class='gd-jp'>逃げようにも逃げられない状況だった。</span>(Waktu itu keadaannya begitu rupa sampai ingin kabur pun tidak bisa)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Terhalang keadaan di luar dirimu</span>Terluka, tidak ada kendaraan, tidak punya kontak... Bukan kamu tidak mau, tapi kondisinya tidak memungkinkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>終電がなくて、帰ろうにも帰れない。</span>(Kereta terakhir sudah habis, mau pulang pun tidak bisa)</div><div class='gd-ex-line'>・<span class='gd-jp'>足をけがしていて、歩こうにも歩けない。</span>(Kakiku cedera, mau jalan pun tidak bisa)</div><div class='gd-sec'><span class='gd-tag'>Terhalang perasaan</span>Kadang yang menghalangimu adalah emosi atau kenangan.</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れようにも忘れられない思い出だ。</span>(Itu kenangan yang ingin dilupakan pun tidak bisa)</div><div class='gd-ex-line'>・<span class='gd-jp'>状況が深刻すぎて、笑おうにも笑えなかった。</span>(Situasinya terlalu serius, mau tertawa pun tidak bisa)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bentuk volisional verba (「〜う／〜よう」, bentuk yang artinya “ayo ~”) ＋ にも ＋ bentuk “tidak bisa” dari <b>verba yang sama</b> (bentuk potensial negatif).<br>Di tengah sering disisipkan alasannya: <span class='gd-jp'>帰ろうにも、終電がなくて帰れない。</span><br>Bagian belakang juga boleh tidak mengulang verba, langsung menyebut alasan yang menghalangimu:</div><div class='gd-ex-line'>・<span class='gd-jp'>電話しようにも、番号が分からない。</span>(Mau menelepon, tapi tidak tahu nomornya)</div><div class='gd-h'>Cara mengubah bentuk: lihat dulu verbanya termasuk kelompok mana</div><div class='gd-sec'><b>Kelompok 1 (verba godan)</b>: di bagian depan, ganti bunyi terakhir dengan bunyi baris「お」pada baris yang sama, lalu tambah「う」; di bagian belakang, ganti bunyi terakhir dengan bunyi baris「え」pada baris yang sama, lalu tambah「ない」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く diganti こ → <span class='gd-jp'>書こう</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → く diganti け → <span class='gd-jp'>書けない</span></span><br>Digabung: <span class='gd-jp'>書こうにも書けない</span><br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ろうにも帰れない</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話そうにも話せない</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会おうにも会えない</span></span></div><div class='gd-sec'><b>Kelompok 2 (verba ichidan)</b>: di bagian depan, buang「る」lalu tambah「よう」; di bagian belakang, buang「る」lalu tambah「られない」.<br><span class='gd-pair'><span class='gd-jp'>逃げる</span> → <span class='gd-jp'>逃げようにも逃げられない</span></span><br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れようにも忘れられない</span></span></div><div class='gd-sec'><b>Kelompok 3 (hanya dua, hafalkan saja)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようにもできない</span></span>, contoh: <span class='gd-jp'>予約しようにも予約できない</span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようにも来られない</span>(こようにもこられない)</span></div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Bagian depan wajib pakai bentuk volisional: yang benar <span class='gd-jp'>帰ろうにも</span>, bukan 帰るようにも. Pola ini tidak ada hubungannya dengan「〜ように」(supaya ~) yang kamu pelajari di N4. Jangan asal lihat「よう」lalu menyambungnya dengan bentuk kamus.<br>・Bagian belakang harus berarti “<b>tidak bisa</b>”, bukan “tidak mau”: kalau ditulis 帰らない, artinya jadi “akunya sendiri tidak mau pulang”, dan bertabrakan dengan “ingin pulang” di depan.<br>・Syaratnya, orangnya <b>benar-benar ingin melakukannya</b>. Kalau malas atau memang tidak tertarik, pola ini tidak bisa dipakai.<br>・Untuk bentuk “tidak bisa” verba kelompok 2, dalam tulisan resmi dan ujian tulis <span class='gd-jp'>逃げられない</span>; bentuk「逃げれない」yang sering terdengar dalam percakapan sebaiknya dihindari saat menulis.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Sama-sama bicara soal “kabur”, lihat perbedaan tiga pola ini:<br><b>ようにも</b> = ingin melakukan, tapi <b>sama sekali tidak bisa</b>: <span class='gd-jp'>逃げようにも、ドアに鍵がかかっていて逃げられない。</span>(Ingin kabur, tapi pintunya terkunci, jadi tidak bisa)<br><b>たところで</b> = walaupun dilakukan, <b>tetap percuma</b>: <span class='gd-jp'>今さら逃げたところで、すぐに見つかるだろう。</span>(Kabur sekarang pun, pasti segera ketahuan)<br><b>ようと／ようが</b> = <b>bagaimanapun caranya</b>, hasilnya sama saja: <span class='gd-jp'>どこへ逃げようと、必ず見つけ出す。</span>(Ke mana pun kamu kabur, aku pasti akan menemukanmu)</div><div class='gd-warn'>Kiat menentukan: “ingin tapi tidak bisa” pakai ようにも, “dilakukan pun sia-sia” pakai たところで, “bagaimanapun caranya” pakai ようと／ようが.</div>","n1-86":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜とは言い条」artinya <b>“meski dikatakan ~, tapi...” atau “berlabel ~, padahal sebenarnya...”</b>. Di depan kamu mengakui suatu anggapan, lalu di belakang langsung bilang “kenyataannya tidak sesederhana itu”. Artinya hampir sama dengan「とはいえ」, hanya saja lebih kuno dan lebih bergaya tulisan, jadi hampir tidak pernah dipakai dalam percakapan sehari-hari.</div><div class='gd-h'>Pahami dulu kata「言い条」</div><div class='gd-sec'><span class='gd-jp'>言い条</span> dibaca <b>いいじょう</b>, arti aslinya “cara bicara, dalih”. Jadi 「Aとは言い条」kalau diartikan harfiah: “dibilang A, itu memang katanya begitu”. Maksud tersiratnya: <b>memang begitu katanya, tapi kenyataannya lain</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Nomina langsung disambung: <span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロとは言い条</span></span><br>Verba dan adjektiva disambung dengan bentuk biasa (bentuk tanpa ます atau です): <span class='gd-pair'><span class='gd-jp'>分かっている</span> → <span class='gd-jp'>分かっているとは言い条</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとは言い条</span></span><br>Yang paling sering muncul adalah <b>nomina yang langsung disambung</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Nama tak sesuai kenyataan</span>Bagian depan berisi sebutan atau nama yang diakui banyak orang, lalu bagian belakang menunjukkan bahwa kenyataannya tidak begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>春とは言い条、朝晩はまだ冷える。</span>(Meski katanya sudah musim semi, pagi dan malam masih dingin)</div><div class='gd-ex-line'>・<span class='gd-jp'>自由とは言い条、実際には多くの制約がある。</span>(Katanya bebas, tapi kenyataannya banyak sekali batasan)</div><div class='gd-sec'><span class='gd-tag'>Paham tapi tidak bisa melakukannya</span>Kamu mengakui hal di depan itu benar, tetapi hasilnya tetap tidak ideal.</div><div class='gd-ex-line'>・<span class='gd-jp'>頭では分かっているとは言い条、なかなか実行に移せない。</span>(Meski di kepala sudah paham, sulit sekali dipraktikkan)</div><div class='gd-ex-line'>・<span class='gd-jp'>プロとは言い条、ミスを犯すこともある。</span>(Meski profesional, sesekali tetap bisa berbuat kesalahan)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Cara bacanya <b>いいじょう</b>. 「条」dibaca じょう (vokal panjang), jangan dibaca「いうじょう」atau「じょ」yang pendek.<br>・Pola ini diletakkan di <b>tengah kalimat</b>, dan setelahnya harus ada kalimat bernada “tapi...”. Tidak bisa ditaruh sendirian di akhir kalimat.<br>・Ini bahasa tulis yang sangat kaku, dipakai dalam ulasan, novel, dan artikel. Kalau kamu bilang「春とは言い条」saat ngobrol dengan teman, kedengarannya seperti membaca buku kuno; dalam percakapan cukup「<span class='gd-jp'>春だけど</span>」.<br>・Kalau menemukannya di ujian, cukup kenali artinya “meski dikatakan ~ tapi...”. Saat menulis sendiri, pakai「とはいえ」lebih aman dan tidak terasa janggal.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Ketiganya berarti “meski dikatakan ~ tapi...”, bedanya ada pada <b>seberapa formal dan seberapa kuno</b>. Bandingkan dalam situasi yang sama:<br><b>とはいうものの</b>: bahasa tulis, dan dalam situasi formal juga dipakai saat berbicara.<br></div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいうものの、まだ寒い。</span>(Meski katanya musim semi, masih dingin)</div><div class='gd-sec'><b>とはいえ</b>: terutama bahasa tulis, sering muncul di berita dan artikel, dan dalam percakapan yang agak formal pun kadang terdengar.</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいえ、まだ寒い。</span>(Meski katanya musim semi, masih dingin)</div><div class='gd-sec'><b>とは言い条</b>: yang paling kuno, di zaman sekarang hampir hanya ditemukan di artikel dan karya sastra.</div><div class='gd-ex-line'>・<span class='gd-jp'>春とは言い条、まだ寒い。</span>(Meski katanya musim semi, masih dingin)</div><div class='gd-warn'>Kiat menentukan: artinya sama-sama “meski dikatakan ~ tapi...”. Yang paling terasa seperti buku kuno dan berbunga-bunga adalah「とは言い条」; kalau menulis karangan, memilih「とはいえ」paling aman.</div>","n1-90":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜にかこつけて」artinya <b>「berdalih ～」「menjadikan ～ sebagai alasan」</b>. Di permukaan alasannya A, padahal yang benar-benar ingin dilakukan adalah B. Misalnya kamu bilang 「aku dinas luar kota」, tapi sebagian besar waktunya dipakai jalan-jalan belanja dan wisata kuliner. Nah, perasaan \"berkedok dinas\" seperti itulah yang diwakili pola ini.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋にかこつけて, lalu diikuti hal yang sebenarnya ingin dilakukan.<br><span class='gd-pair'><span class='gd-jp'>出張</span> → <span class='gd-jp'>出張にかこつけて</span></span>（berdalih dinas luar kota）<br><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事にかこつけて</span></span>（menjadikan pekerjaan sebagai alasan）<br>Bagian depan berisi \"alasan resmi yang enak diucapkan\", sedangkan bagian belakang adalah \"hal yang sebenarnya ingin dilakukan\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menyindir orang lain</span>Ini pemakaian yang paling umum. Kamu merasa sebal karena seseorang memakai alasan yang masuk akal sebagai kedok, dan nadanya agak mengkritik.</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は視察にかこつけて、毎年ハワイに行っている。</span>（Kepala bagian setiap tahun pergi ke Hawaii dengan dalih inspeksi）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は仕事にかこつけて、毎晩飲みに行っている。</span>（Dia berdalih pekerjaan, lalu setiap malam pergi minum-minum）</div><div class='gd-sec'><span class='gd-tag'>Menyindir diri sendiri</span>Boleh juga dipakai untuk diri sendiri. Artinya kamu mengaku, \"sebenarnya aku memang pengin melakukan itu.\" Nadanya agak malu-malu dan sedikit lucu.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの誕生日にかこつけて、自分が食べたいケーキを買った。</span>（Berdalih ulang tahun anak, aku membeli kue yang sebenarnya aku sendiri ingin makan）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨にかこつけて、ジムをサボった。</span>（Dengan alasan hujan, aku bolos ke gym）</div><div class='gd-h'>Hal yang sering keliru</div><div class='gd-warn'>・Partikelnya adalah <b>に</b>, bukan を. Ungkapan sehari-hari yang artinya mirip, 「〜を口実に」, memang memakai を. Jangan dicampur ya. Menulis 「出張をかこつけて」 itu salah.<br>・Pola ini selalu membawa kesan <b>「alasan di permukaan berbeda dari tujuan sebenarnya」</b>. Kalau kamu memang benar-benar dinas dan hanya sambil menikmati pemandangan, memakai pola ini malah terdengar seperti kamu mengaku \"dinas bohongan, senang-senang beneran\".<br>・Karena nadanya mengkritik atau menyindir diri sendiri, pola ini tidak cocok untuk menjelaskan jadwalmu dalam situasi formal. Misalnya, kalau kamu bilang 「出張にかこつけて…」 saat melapor ke atasan, sama saja kamu mengaku sedang bermalas-malasan.<br>・Biasanya ditulis dengan hiragana. Versi kanjinya 「託けて」, tapi jarang terlihat, jadi cukup dikenali saja.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Situasi yang sama: kamu pergi berwisata ke Kyoto saat dinas.<br><b>がてら</b>＝<b>sekalian</b>. Kedua hal itu sama-sama nyata dan dilakukan secara terang-terangan:<br><span class='gd-jp'>出張がてら、京都を観光した。</span>（Sekalian dinas, aku berwisata di Kyoto）<br><b>かたがた</b>＝juga berarti \"sekalian, sambil\", tetapi lebih formal. Sering dipakai saat berkunjung atau mengucapkan terima kasih:<br><span class='gd-jp'>お礼かたがた、先生のお宅に伺った。</span>（Aku berkunjung ke rumah guru sekaligus menyampaikan terima kasih）<br><b>にかこつけて</b>＝alasan di depan hanyalah <b>kedok</b>, dan tujuan sebenarnya adalah hal di belakang:<br><span class='gd-jp'>出張にかこつけて、京都を観光した。</span>（Berdalih dinas, padahal sebenarnya pergi jalan-jalan ke Kyoto）</div><div class='gd-warn'>Trik cepat membedakan: kalau kedua hal itu memang sungguh-sungguh ingin dilakukan, pakai 「がてら」, dan untuk situasi formal pakai 「かたがた」. Kalau alasan di depan hanya dalih dan yang sebenarnya diinginkan adalah hal di belakang, pakai 「にかこつけて」.</div><div class='gd-h'>Setelah ini, belajar yang berikut</div><div class='gd-sec'>Dalam percakapan sehari-hari, 「〜を口実に」 lebih sering terdengar. Artinya hampir sama, tetapi nadanya lebih langsung: <span class='gd-jp'>風邪を口実に、会社を休んだ。</span>（Aku memakai alasan flu untuk izin tidak masuk kantor）</div>","n1-92":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「AとBが相まって」artinya <b>「dua faktor, A dan B, bergabung sehingga efeknya berlipat」</b>. Seperti kalimat \"sudah lelah, ditambah kurang tidur\" atau \"cuacanya bagus, ditambah lokasinya strategis\": satu faktor saja mungkin masih biasa, tapi kalau dua-duanya bertumpuk, hasilnya jadi terasa sekali. Bisa dipakai untuk hal baik maupun buruk, dan sering muncul di berita, ulasan, dan artikel.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya dipasang <b>kata benda</b>. Ada tiga bentuk yang umum:<br><span class='gd-tag'>AはBと相まって</span>Tokoh utama A bergabung dengan faktor lain B.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の才能は努力と相まって、大きな成果を生んだ。</span>（Bakatnya, ditambah kerja keras, menghasilkan pencapaian yang besar）</div><div class='gd-sec'><span class='gd-tag'>AとBが相まって</span>Dua faktor diletakkan berdampingan, dan bersama-sama menimbulkan hasil di belakangnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は料理の味と雰囲気の良さが相まって、いつも予約でいっぱいだ。</span>（Di restoran ini makanannya enak dan suasananya juga bagus, jadi reservasinya selalu penuh）</div><div class='gd-sec'><span class='gd-tag'>Bも相まって</span>Ini yang paling sering muncul di berita. Dengan 「も」 kamu menyampaikan bahwa \"sebenarnya sudah ada penyebab lain, dan <b>ditambah</b> B\".</div><div class='gd-ex-line'>・<span class='gd-jp'>円安も相まって、外国人観光客が急増している。</span>（Ditambah yen yang melemah, wisatawan asing meningkat tajam）</div><div class='gd-sec'>Kalau di depannya berupa kalimat utuh, tambahkan 「こと」 dulu agar menjadi kata benda:<br><span class='gd-pair'><span class='gd-jp'>駅から近い</span> → <span class='gd-jp'>駅から近いことも相まって</span></span>（ditambah dekat dari stasiun）</div><div class='gd-h'>Hal yang sering keliru</div><div class='gd-warn'>・Bacanya <b>あいまって</b>, bukan 「そうまって」.<br>・Harus ada <b>dua faktor atau lebih</b>. Kalau penyebabnya hanya satu, pola ini tidak bisa dipakai. Kalau pertandingan dibatalkan karena hujan, cukup bilang <span class='gd-jp'>雨で試合が中止になった</span>. Kamu tidak boleh bilang 「雨と相まって中止になった」.<br>・Pola ini tidak hanya untuk hal baik. Untuk hal buruk pun bisa: <span class='gd-jp'>寝不足と疲れが相まって、熱を出してしまった。</span>（Kurang tidur ditambah kelelahan, akhirnya aku demam）Jadi jangan samakan dengan \"saling melengkapi\" dalam bahasa Indonesia, yang hanya dipakai untuk hal baik.<br>・Ini ungkapan yang cenderung formal dan bernuansa tulisan. Saat ngobrol dengan teman, <span class='gd-jp'>〜もあって</span> dan <span class='gd-jp'>〜も重なって</span> terdengar lebih natural.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'><b>に加えて</b>＝sekadar \"selain A, ada juga B\", hanya mendaftar hal satu per satu:<br><span class='gd-jp'>円安に加えて、物価も上がっている。</span>（Selain yen melemah, harga-harga juga naik）<br><b>と相まって</b>＝dua faktor <b>bekerja bersama</b> dan menimbulkan suatu hasil:<br><span class='gd-jp'>円安と物価高が相まって、生活が苦しくなっている。</span>（Yen yang melemah ditambah harga yang melambung membuat hidup jadi susah）</div><div class='gd-sec'><b>とあって</b>（bedanya hanya satu huruf, jadi gampang salah baca）＝\"karena sedang dalam situasi khusus ～, maka…\", dengan hanya satu penyebab:<br><span class='gd-jp'>連休とあって、どこも混んでいる。</span>（Karena libur panjang, di mana-mana ramai）<br><b>と相まって</b>＝dua penyebab bertumpuk:<br><span class='gd-jp'>連休と好天が相まって、どこも混んでいる。</span>（Libur panjang ditambah cuaca cerah, di mana-mana ramai）</div><div class='gd-warn'>Trik cepat membedakan: kalau hanya \"ada ～ juga\", pakai に加えて. Kalau \"karena sedang ～\", pakai とあって. Pakai と相まって hanya kalau \"dua faktor bertumpuk dan efeknya berlipat\".</div>","n1-87":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜かれ〜かれ」kurang lebih sama dengan <b>“cepat atau lambat”, “lebih atau kurang”, “baik atau buruk”</b> dalam bahasa Indonesia. Ini bukan pola yang bisa kamu isi kata apa saja, melainkan <b>tiga ungkapan tetap</b>. Hafalkan saja satu per satu sebagai satu paket.</div><div class='gd-h'>Dari mana asalnya</div><div class='gd-sec'>「かれ」adalah bentuk perintah dalam bahasa Jepang klasik, kira-kira berarti “entah ~ atau tidak, sama saja”.<br><span class='gd-jp'>多かれ少なかれ</span>awalnya mirip dengan “banyak ya sudah, sedikit ya sudah”, lalu berkembang menjadi “mau banyak atau sedikit, pokoknya ada”.<br>Kamu tidak perlu belajar bahasa klasik. Cukup tahu bahwa ini adalah dua kata sifat yang <b>artinya berlawanan</b> dan diletakkan berdampingan, untuk menyatakan “mau pilih sisi yang mana pun, hasilnya tetap sama”.</div><div class='gd-h'>Tiga pasangan yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>遅かれ早かれ</span>dibaca「おそかれはやかれ」, artinya cepat atau lambat. Biasanya diikuti hal yang pasti akan terjadi, dengan kesan “tidak bisa dihindari”. Ungkapan ini juga sering dipakai dalam percakapan sehari-hari.</div><div class='gd-ex-line'>・<span class='gd-jp'>嘘は遅かれ早かればれるよ。</span>(Cepat atau lambat, kebohongan pasti ketahuan)</div><div class='gd-ex-line'>・<span class='gd-jp'>遅かれ早かれ、決めなきゃいけないことだ。</span>(Cepat atau lambat, ini hal yang memang harus diputuskan)</div><div class='gd-sec'><span class='gd-tag'>多かれ少なかれ</span>dibaca「おおかれすくなかれ」, artinya lebih atau kurang. Sering diikuti「誰でも」「みんな」, untuk menyatakan bahwa semua orang mengalaminya, hanya saja tingkatnya berbeda.</div><div class='gd-ex-line'>・<span class='gd-jp'>多かれ少なかれ、誰にでも悩みはある。</span>(Setiap orang pasti punya masalah, entah besar atau kecil)</div><div class='gd-sec'><span class='gd-tag'>善かれ悪しかれ</span>dibaca「よかれあしかれ」, artinya baik atau buruk. Lebih formal daripada dua pasangan sebelumnya dan lebih sering muncul di tulisan atau ulasan.</div><div class='gd-ex-line'>・<span class='gd-jp'>善かれ悪しかれ、スマホは私たちの生活を大きく変えた。</span>(Entah baik atau buruk, ponsel pintar telah mengubah hidup kita secara besar-besaran)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Tidak boleh bikin sendiri</b>: jangan tergoda untuk memasukkan <span class='gd-jp'>高い</span>, <span class='gd-jp'>大きい</span> ke pola「kata sifat＋かれ」. Itu tidak bisa. Yang ada hanya tiga pasangan ini.<br>・Yang benar <b>悪しかれ</b>, bukan「悪かれ」. Yang dipakai di sini adalah「悪し」dari bahasa klasik, bukan「悪い」yang modern.<br>・Urutannya tetap: katakan <span class='gd-jp'>遅かれ早かれ</span> dan <span class='gd-jp'>多かれ少なかれ</span>, jangan dibalik.<br>・<span class='gd-jp'>よかれと思って</span> yang berdiri sendiri adalah ungkapan lain, artinya “dengan niat baik, mengira itu baik untuk lawan bicara”. Tidak ada hubungannya dengan “baik atau buruk”.<br>　<span class='gd-jp'>よかれと思って言ったのに、怒られた。</span>(Aku bilang begitu dengan niat baik, tapi malah dimarahi)</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama berarti “entah A atau B”, tetapi <span class='gd-jp'>〜にせよ〜にせよ</span> dan <span class='gd-jp'>〜であれ〜であれ</span> bisa diisi kata apa saja, sedangkan <span class='gd-jp'>〜かれ〜かれ</span> tidak.</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにせよ行かないにせよ、早めに連絡してね。</span>(Mau pergi atau tidak, kabari aku lebih awal ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>雨であれ雪であれ、試合は行われる。</span>(Entah hujan atau salju, pertandingan tetap diadakan)</div><div class='gd-ex-line'>・<span class='gd-jp'>遅かれ早かれ、ばれるよ。</span>(Cepat atau lambat, pasti ketahuan)</div><div class='gd-sec'>Sebaliknya, “cepat atau lambat” juga tidak diucapkan sebagai <span class='gd-jp'>遅いにせよ早いにせよ</span>. Secara tata bahasa memang tidak salah, tetapi terdengar seperti membahas dua kemungkinan “lambat atau cepat”, bukan ungkapan tetap “cepat atau lambat”. Orang Jepang pasti bilang <span class='gd-jp'>遅かれ早かれ</span>.<br>Satu lagi: <span class='gd-jp'>であれ</span> disambung dengan kata benda atau kata sifat-な, <b>tidak dengan kata sifat-い</b>. Jadi「遅いであれ」sendiri sudah salah.</div><div class='gd-warn'>Tips menentukan: kalau mau bilang “cepat atau lambat / lebih atau kurang / baik atau buruk”, langsung pakai tiga pasangan かれ. Untuk “entah A atau B” yang lain, pakai にせよ atau であれ.</div>","n1-88":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜始末だ」kurang lebih berarti <b>“sampai-sampai akhirnya malah ~”, “berakhir dengan nasib ~”</b>. Kamu menyebutkan serangkaian hal yang keterlaluan, lalu menutupnya dengan akhir yang lebih parah lagi. Nadanya penuh <b>rasa tak habis pikir, jengkel, dan menyindir</b>. Seperti saat kamu curhat ke teman: “Dia sudah telat, barangnya lupa dibawa juga, terus gimana? Ujung-ujungnya malah kena marah atasan.”</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menyindir orang lain</span>Ini pemakaian yang paling khas. Kamu menceritakan seseorang yang makin lama makin kelewatan, sampai akhirnya berada di titik yang parah.</div><div class='gd-ex-line'>・<span class='gd-jp'>息子は毎晩ゲームばかりして、ついには学校を休む始末だ。</span>(Anakku tiap malam main game terus, sampai akhirnya malah bolos sekolah)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は何度注意しても聞かず、最近は返事もしない始末だ。</span>(Sudah berkali-kali diperingatkan dia tidak mau dengar, belakangan ini bahkan tidak menjawab sama sekali)</div><div class='gd-sec'><span class='gd-tag'>Menertawakan diri sendiri</span>Boleh juga dipakai untuk diri sendiri, dengan nada menyindir diri: “duh, parah banget aku ini”.</div><div class='gd-ex-line'>・<span class='gd-jp'>寝坊して駅まで走ったのに、財布を家に忘れる始末だ。</span>(Sudah kesiangan, lari-lari sampai stasiun, eh dompetnya malah ketinggalan di rumah)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja bentuk kamus＋始末だ: <span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休む始末だ</span></span><br>Kata kerja bentuk ない＋始末だ: <span class='gd-pair'><span class='gd-jp'>しない</span> → <span class='gd-jp'>返事もしない始末だ</span></span><br>Kata tunjuk＋始末だ: <span class='gd-jp'>この始末だ</span>、<span class='gd-jp'>あの始末だ</span> (“jadi begini / jadi begitu parahnya”)</div><div class='gd-ex-line'>・<span class='gd-jp'>あれほど言ったのに、この始末だ。</span>(Sudah kubilangin sampai segitunya, tapi tetap jadi begini)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Di bagian depan, sering dipasang kata yang berarti “pada akhirnya” untuk membangun kesan “makin lama makin parah”: <span class='gd-jp'>ついには</span>、<span class='gd-jp'>とうとう</span>、<span class='gd-jp'>最後には</span>、<span class='gd-jp'>挙句の果てには</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>借金を重ね、挙句の果てには夜逃げする始末だ。</span>(Utangnya terus menumpuk, dan pada akhirnya malah kabur diam-diam di malam hari)</div><div class='gd-sec'>Untuk hal yang sudah lewat, bagian depan tetap memakai bentuk kamus, dan akhir kalimat bisa memakai <span class='gd-jp'>始末だった</span>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Bagian depan memakai <b>bentuk kamus atau bentuk ない</b>, jangan bentuk た: yang benar <span class='gd-jp'>叱られる始末だ</span>, bukan 叱られた始末だ.<br>・<b>Hanya untuk hasil yang buruk</b>. Untuk “belajar giat dan akhirnya lulus”, tidak bisa pakai 始末だ.<br>・Perlu ada <b>pembukaan di depan</b>. Kalau hanya melempar satu kalimat seperti “dia terlambat, 始末だ”, terdengar aneh. Jelaskan dulu bagaimana keadaannya memburuk selangkah demi selangkah.<br>・Nadanya <b>menyindir dan mengeluh</b>. Mengatakan ini tentang atasan atau tamu di depan mereka sangat tidak sopan. Pola ini lebih sering muncul dalam keluhan, tulisan, atau ulasan.<br>・<span class='gd-jp'>始末</span> yang berdiri sendiri juga berarti “membereskan, menangani”, seperti <span class='gd-jp'>後始末</span> (beres-beres setelahnya) dan <span class='gd-jp'>始末書</span> (surat pernyataan penyesalan). Itu hal yang berbeda dari pola ini.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Untuk mengatakan “akhirnya jadi ~”, ada juga 「末に」dan「羽目になる」yang sudah kamu pelajari di N2. Bedanya ada pada <b>hasilnya baik atau tidak, siapa yang dibicarakan, dan perasaan pembicara</b>.<br><b>末に</b> = kesimpulan setelah melalui suatu proses, <b>netral</b>, hasil baik pun boleh:<br><span class='gd-jp'>何度も話し合った末に、ゲームは一日一時間と決めた。</span>(Setelah berdiskusi berkali-kali, akhirnya diputuskan main game cuma satu jam sehari)<br><b>羽目になる</b> = <b>diri sendiri</b> terpaksa harus melakukan sesuatu yang merepotkan, dengan nada menyesal:<br><span class='gd-jp'>息子のゲームの課金を、私が払う羽目になった。</span>(Tagihan top-up game anakku, ujung-ujungnya aku yang harus bayar)<br><b>始末だ</b> = pembicara <b>tak habis pikir dan menyindir</b> seseorang yang “sampai bisa separah ini”:<br><span class='gd-jp'>息子はゲームに夢中で、ついには学校を休む始末だ。</span>(Anakku keasyikan main game, sampai akhirnya malah bolos sekolah)</div><div class='gd-warn'>Tips menentukan: untuk “akhirnya memutuskan ~” yang netral, pakai 末に. Untuk “gara-gara itu aku terpaksa ~”, pakai 羽目になる. Kalau kamu ingin menggerakkan mata sambil bilang “ujung-ujungnya malah ~”, pakai 始末だ.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Sering muncul bersama「〜あげく」: <span class='gd-jp'>さんざん迷ったあげく、何も買わずに帰ってくる始末だ。</span>(Sudah bingung lama sekali, ujung-ujungnya pulang tanpa membeli apa-apa)</div>","n1-17":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜そばから」setara dengan <b>“baru saja ～, eh langsung ～ lagi”</b>. Kamu baru selesai mengerjakan sesuatu, tapi hasilnya langsung dirusak lagi, dan <b>setiap kali selalu begitu</b>, jadi sama saja kerja sia-sia. Bayangkan kamu baru selesai mengepel, lalu anak langsung menginjaknya dengan sandal. Dipel, diinjak, dipel, diinjak lagi. Rasa tak berdaya itulah そばから.</div><div class='gd-h'>Cara menyambungkan</div><div class='gd-sec'>Bentuk kamus atau bentuk た dari kata kerja, lalu langsung tambahkan そばから.<br><span class='gd-pair'><span class='gd-jp'>片付ける</span> → <span class='gd-jp'>片付けるそばから</span></span>（baru saja dirapikan）<br><span class='gd-pair'><span class='gd-jp'>覚えた</span> → <span class='gd-jp'>覚えたそばから</span></span>（baru saja dihafal）<br>Kedua bentuk artinya hampir sama. Kalau dipaksa dibedakan, bentuk kamus terasa seperti “sambil dikerjakan, sambil dirusak”, sedangkan bentuk た terasa seperti “baru selesai dikerjakan, langsung dirusak”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Usaha jadi sia-sia</span>Kamu sudah melakukan sesuatu, tapi hasilnya langsung kembali seperti semula.</div><div class='gd-ex-line'>・<span class='gd-jp'>覚えたそばから忘れてしまう。</span>（Baru saja dihafal, sudah lupa lagi）</div><div class='gd-ex-line'>・<span class='gd-jp'>雪かきしたそばから、また積もっていく。</span>（Baru saja salju disekop, sudah menumpuk lagi）</div><div class='gd-sec'><span class='gd-tag'>Masuk lalu langsung keluar</span>Sesuatu baru datang, tapi langsung hilang, tidak bisa ditahan.</div><div class='gd-ex-line'>・<span class='gd-jp'>稼ぐそばから使ってしまうので、全然貯金できない。</span>（Uang baru masuk langsung habis, jadi sama sekali tidak bisa menabung）</div><div class='gd-ex-line'>・<span class='gd-jp'>掃除するそばから、犬が毛を落としていく。</span>（Aku baru menyapu, anjing langsung merontokkan bulunya lagi）</div><div class='gd-sec'>Bagian belakang kalimat sering dipasangkan dengan <span class='gd-jp'>〜てしまう</span>, <span class='gd-jp'>〜ていく</span>, atau bentuk pasif <span class='gd-jp'>〜される</span> (contoh: <span class='gd-jp'>子供に散らかされる</span>), untuk mengungkapkan perasaan “semuanya di luar kendali dan aku tak bisa berbuat apa-apa”.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・そばから membicarakan hal yang <b>terjadi berulang kali</b>. Untuk hal yang hanya terjadi sekali, tidak bisa dipakai. Misalnya “Begitu aku sampai rumah, hujan turun” tidak bisa dikatakan 「家に着いたそばから雨が降り出した」. Untuk kasus seperti itu, pakai <span class='gd-jp'>とたん</span> atau <span class='gd-jp'>や否や</span>.<br>・Hampir selalu dipakai dalam situasi <b>mengeluh, pasrah, atau usaha yang sia-sia</b>. Untuk hal baik yang terus berdatangan, biasanya tidak dipakai そばから.<br>・Bagian belakang kalimat menggambarkan “kenyataannya memang begitu”, jadi tidak bisa diikuti ungkapan kemauan atau perintah seperti “aku akan ～” atau “tolong ～”.<br>・そば di sini bukan 「蕎麦」 (mi soba), tapi artinya “samping”. Bayangkan saja: “baru dikerjakan, di sampingnya langsung ～”.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><span class='gd-jp'>〜が早いか</span> dan <span class='gd-jp'>〜や否や</span> juga berarti “begitu ～ langsung ～”, tetapi keduanya membicarakan kejadian di <b>satu kali saja</b>, dua hal terjadi berurutan dengan cepat, dan tidak ada arti “sia-sia”.<br>Contoh yang sama, tentang gaji:<br><b>そばから</b>: <span class='gd-jp'>給料が入るそばから使ってしまう。</span>（Gaji baru masuk langsung habis terpakai, setiap bulan begitu）<br><b>や否や</b>: <span class='gd-jp'>給料が入るや否や、新しいスマホを買った。</span>（Begitu gaji masuk waktu itu, aku langsung membeli ponsel baru）</div><div class='gd-warn'>Tips memilih: “setiap kali selalu begitu, dikerjakan pun sia-sia” pakai そばから; “pada satu kejadian itu, begitu hal pertama terjadi, hal berikutnya langsung menyusul” pakai が早いか atau や否や.</div>","n1-21":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜んがため（に）」artinya <b>「demi ～, rela melakukan apa saja」</b>. Artinya sama dengan 「ために」, yaitu \"untuk/demi\", tapi nadanya jauh lebih kuat, ada semangat \"pokoknya harus tercapai\". Pola ini terasa kuno, hampir tidak pernah dipakai dalam obrolan sehari-hari, dan lebih sering muncul di novel, pidato, atau artikel opini.</div><div class='gd-h'>Apa sih 「ん」 ini?</div><div class='gd-sec'>「ん」di sini <b>bukan negasi</b>. Ini kata bahasa Jepang klasik yang berarti \"ingin ～, bermaksud ～\", maknanya dekat dengan 「〜う／〜よう」 di bahasa modern. Sedangkan 「が」 setara dengan 「の」. Jadi <span class='gd-jp'>勝たんがため</span> kira-kira berarti \"tujuan untuk ingin menang\", alias \"demi menang\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ない, lalu <b>buang ない</b>, dan tambahkan 「んがため（に）」.</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>：<br><span class='gd-pair'><span class='gd-jp'>勝つ</span> → <span class='gd-jp'>勝たない</span> → <span class='gd-jp'>勝たんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>守る</span> → <span class='gd-jp'>守らんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>売る</span> → <span class='gd-jp'>売らんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わんがため</span></span>（yang berakhiran う berubah jadi わ, sama seperti bentuk ない）</div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>：<br><span class='gd-pair'><span class='gd-jp'>生きる</span> → <span class='gd-jp'>生きない</span> → <span class='gd-jp'>生きんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>逃れる</span> → <span class='gd-jp'>逃れんがため</span></span></div><div class='gd-sec'><b>Golongan 3</b>：<span class='gd-jp'>する</span> berubah menjadi <b>せ</b>, bukan し.<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>優勝する</span> → <span class='gd-jp'>優勝せんがため</span></span><br>「来る」hampir tidak pernah muncul di pola ini, jadi tidak perlu dihafalkan khusus.</div><div class='gd-h'>Bentuk yang paling sering kamu temui</div><div class='gd-sec'><span class='gd-tag'>んがために</span> ditaruh di bagian awal kalimat, lalu di belakangnya disebutkan \"apa yang dilakukan untuk itu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>勝たんがために、彼は必死に練習した。</span>（Demi menang, dia berlatih mati-matian）</div><div class='gd-ex-line'>・<span class='gd-jp'>生きんがために、どんな仕事でもした。</span>（Demi bertahan hidup, dia mengerjakan pekerjaan apa saja）</div><div class='gd-sec'><span class='gd-tag'>んがための＋kata benda</span> menerangkan kata benda di belakangnya. <span class='gd-jp'>売らんがため</span> sering bernuansa negatif, yaitu \"hanya memikirkan cara menjual demi uang\".</div><div class='gd-ex-line'>・<span class='gd-jp'>売らんがための広告には、もううんざりだ。</span>（Aku sudah muak dengan iklan yang cuma mau jualan）</div><div class='gd-sec'><span class='gd-tag'>んがためだ</span> ditaruh di akhir kalimat untuk menjelaskan \"melakukan itu demi ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が嘘をついたのは、自分を守らんがためだった。</span>（Dia berbohong demi melindungi dirinya sendiri）</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Untuk する bentuknya <b>せんがため</b>. Menulis 「しんがため」 itu salah.<br>・「ん」bukan negasi: <span class='gd-jp'>勝たんがため</span> artinya \"demi menang\", bukan \"demi tidak menang\".<br>・Bagian belakang harus berupa <b>tindakan yang sengaja dilakukan seseorang</b>, dan biasanya tujuan yang ingin dicapai orang yang sama. Tidak bisa dipakai untuk cuaca atau fenomena alam.<br>・Bagian belakang tidak boleh berupa ajakan atau perintah seperti 「tolong ～」 atau 「lakukan ～」: <span class='gd-jp'>合格せんがため、勉強しなさい</span> terdengar tidak wajar, yang benar <span class='gd-jp'>合格するために、勉強しなさい</span>.<br>・Kalau dipakai untuk hal sepele, jadinya berlebihan dan lucu: kalau mau beli roti ke minimarket, cukup bilang <span class='gd-jp'>パンを買うために</span>.</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'>Situasi yang sama, \"demi lulus ujian, belajar sampai larut malam setiap hari\":<br><b>ために</b>＝\"demi/untuk\" yang umum, bisa dipakai di situasi apa pun: <span class='gd-jp'>合格するために、毎晩遅くまで勉強した。</span><br><b>べく</b>＝\"demi/untuk\" ragam tulis, langsung disambung dengan bentuk kamus, dan する bisa jadi <span class='gd-jp'>すべく</span>: <span class='gd-jp'>合格すべく、毎晩遅くまで勉強した。</span><br><b>んがため</b>＝lebih kuno, dengan kesan \"mati-matian pun harus tercapai\": <span class='gd-jp'>合格せんがため、毎晩遅くまで勉強した。</span></div><div class='gd-sec'>Satu lagi yang perlu diwaspadai adalah <b>んばかりに</b>. Cara menyambungnya persis sama, tapi artinya sama sekali berbeda, yaitu \"hampir saja ～ (tampak seperti mau ～)\":<br><span class='gd-jp'>泣かんばかりに頼んだ。</span>（Dia memohon sampai nyaris menangis）</div><div class='gd-warn'>Trik membedakan: kalau 「ん」 diikuti <b>がため</b> artinya \"demi\", kalau diikuti <b>ばかり</b> artinya \"hampir saja\". Untuk mengungkapkan \"demi\": dalam keseharian pakai ために, dalam tulisan pakai べく, dan pakai んがため hanya kalau kamu ingin menampilkan kesan \"rela melakukan apa saja\".</div>"});
